#[test]
fn compile_recursive_iterator_iterator_array_surface_to_native_binary() {
    let root = temp_dir("ptn-native-recursive-iterator-iterator-array-surface");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("recursive-iterator-iterator-array-surface.php");
    let output = root.join("recursive-iterator-iterator-array-surface-bin");
    fs::write(
        &input,
        r#"<?php
error_reporting(E_ERROR);

class FruitPublic {
    public $title;
    public function __construct($title) { $this->title = $title; }
    public function __toString() { return $this->title; }
}

class FruitProtected {
    protected $title;
    public function __construct($title) { $this->title = $title; }
    public function __toString() { return $this->title; }
}

$nested = [1, 2 => [21, 22 => [221, 222], 23 => [231]], 3];
foreach (new RecursiveIteratorIterator(new RecursiveArrayIterator($nested), RecursiveIteratorIterator::LEAVES_ONLY) as $value) {
    echo "leaf:$value\n";
}

$duplicateKeys = [1 => [1 => [1 => "apple"], 2 => [1 => "grape"]]];
foreach (new RecursiveIteratorIterator(new RecursiveArrayIterator($duplicateKeys)) as $key => $value) {
    echo "dup:$key=$value\n";
}

$objects = [new FruitPublic("apple"), new FruitProtected("grape")];
foreach (new RecursiveIteratorIterator(new RecursiveArrayIterator($objects)) as $key => $value) {
    echo "object:$key=$value\n";
}
foreach (new RecursiveIteratorIterator(new RecursiveArrayIterator($objects, RecursiveArrayIterator::CHILD_ARRAYS_ONLY)) as $key => $value) {
    echo "child-arrays-only:$key=$value\n";
}

$nestedObjects = [1 => [1 => new FruitPublic("apple")], 2 => [1 => new FruitProtected("grape")]];
foreach (new RecursiveIteratorIterator(new RecursiveArrayIterator($nestedObjects, RecursiveArrayIterator::CHILD_ARRAYS_ONLY)) as $key => $value) {
    echo "nested-child-arrays-only:$key=$value\n";
}

$data = new stdClass();
$data->props = ["hello" => 5, "props" => ["keyme" => ["test" => 5]]];
foreach (new RecursiveIteratorIterator(new RecursiveArrayIterator($data), RecursiveIteratorIterator::SELF_FIRST) as $key => $value) {
    echo "self:$key\n";
}

$rc = new ReflectionClass(RecursiveIteratorIterator::class);
$it = $rc->newInstanceWithoutConstructor();
try {
    foreach ($it as $value) {
    }
} catch (Error $e) {
    echo $e->getMessage(), "\n";
}
"#,
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "leaf:1\n",
            "leaf:21\n",
            "leaf:221\n",
            "leaf:222\n",
            "leaf:231\n",
            "leaf:3\n",
            "dup:1=apple\n",
            "dup:1=grape\n",
            "object:title=apple\n",
            "child-arrays-only:0=apple\n",
            "child-arrays-only:1=grape\n",
            "nested-child-arrays-only:1=apple\n",
            "nested-child-arrays-only:1=grape\n",
            "self:props\n",
            "self:hello\n",
            "self:props\n",
            "self:keyme\n",
            "self:test\n",
            "Object is not initialized\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_datetime_timezone_semantics_to_native_binary() {
    let root = temp_dir("ptn-native-datetime-timezone-semantics");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("datetime-timezone-semantics.php");
    let output = root.join("datetime-timezone-semantics-bin");
    fs::write(
        &input,
        r#"<?php
date_default_timezone_set('UTC');
error_reporting(E_ALL & ~E_DEPRECATED);

$dt = date_create('2006-12-12');
$tz = date_timezone_get($dt);
var_dump($tz->getName());
var_dump(timezone_offset_get($tz, $dt));

$ny = timezone_open('America/New_York');
var_dump($ny->getName());

$la = new DateTimeZone('America/Los_Angeles');
var_dump($la->getOffset($dt));

$abbr = timezone_abbreviations_list();
var_dump($abbr['utc'][0]['timezone_id']);
var_dump(timezone_name_from_abbr('CET'));

var_dump(in_array('Europe/London', timezone_identifiers_list()));
var_dump(in_array('UTC', DateTimeZone::listIdentifiers(DateTimeZone::EUROPE | DateTimeZone::UTC)));

$dto = new DateTime();
$old = $dto->getTimezone();
$dto->setTimezone(new DateTimeZone('US/Eastern'));
var_dump($dto->getTimezone()->getName());
var_dump($old->getName());

class DateTimeZoneExt extends DateTimeZone {
    public function __toString() {
        return parent::getName();
    }
}
echo new DateTimeZoneExt('Europe/Kyiv'), "\n";

$offsetTz = date_create('2012-01-01 10:00 +1:00')->getTimezone();
echo $offsetTz->getName(), "\n";
echo unserialize(serialize($offsetTz))->getName(), "\n";
eval('$restored = ' . var_export(new DateTimeZone('America/New_York'), true) . ';');
echo $restored->getName(), "\n";

date_default_timezone_set('Etc/GMT+1');
$rfcZone = new DateTime('Fri, 07 Dec 2007 19:05:14 +1000');
echo $rfcZone->getTimezone()->getName(), "\n";

date_default_timezone_set('UTC');
$boise = new DateTime('@1604219400');
$boise->setTimezone(new DateTimeZone('America/Boise'));
echo $boise->format('Y-m-d H:i:s T'), "\n";
echo "{$boise->format('Y-m-d H:i:s T')} | {$boise->getTimestamp()}", "\n";
$sunInfo = date_sun_info(strtotime('2006-12-12'), 31.7667, 35.2333);
echo $sunInfo['sunrise'], '/', $sunInfo['sunset'], '/', $sunInfo['transit'], '/', $sunInfo['civil_twilight_begin'], '/', $sunInfo['astronomical_twilight_end'], "\n";

$transitions = timezone_transitions_get(new DateTimeZone('Europe/London'), -306972000, -37241999);
var_dump(count($transitions));
var_dump($transitions[6]['abbr']);
$oslo = timezone_location_get(new DateTimeZone('Europe/Oslo'));
var_dump($oslo['country_code']);
var_dump($oslo['latitude']);
var_dump($oslo['longitude']);
var_dump($oslo['comments']);

date_default_timezone_set('America/Chicago');
echo date_sunrise(mktime(8, 8, 8, 8, 11, 2008), 1, 41.85, -87.65, 90, -5), "\n";

date_default_timezone_set('America/New_York');
$spring = new DateTime('2010-03-14 03:00:00');
echo $spring->sub(new DateInterval('PT1S'))->format('Y-m-d H:i:s T e'), "\n";
$fallStart = new DateTime('2010-11-07 01:59:59');
$fallEnd = new DateTime('2010-11-07 01:00:00 EST');
$fallEnd->setTimezone(new DateTimeZone('America/New_York'));
echo $fallStart->diff($fallEnd)->format('P%dDT%hH%iM%sS'), "\n";
"#,
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "string(3) \"UTC\"\n",
            "int(0)\n",
            "string(16) \"America/New_York\"\n",
            "int(-28800)\n",
            "string(13) \"Etc/Universal\"\n",
            "string(13) \"Europe/Berlin\"\n",
            "bool(true)\n",
            "bool(true)\n",
            "string(10) \"US/Eastern\"\n",
            "string(3) \"UTC\"\n",
            "Europe/Kyiv\n",
            "+01:00\n",
            "+01:00\n",
            "America/New_York\n",
            "+10:00\n",
            "2020-11-01 01:30:00 MST\n",
            "2020-11-01 01:30:00 MST | 1604219400\n",
            "1165897761/1165934160/1165915961/1165896156/1165939371\n",
            "int(18)\n",
            "string(3) \"BST\"\n",
            "string(2) \"NO\"\n",
            "float(59.91666)\n",
            "float(10.75)\n",
            "string(0) \"\"\n",
            "05:58\n",
            "2010-03-14 01:59:59 EST America/New_York\n",
            "P0DT0H0M1S\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

