#[test]
fn parser_accepts_precedence_aware_binary_expressions() {
    let program = parser::parse("<?php echo \"sum \" . 20 - 3 * 4 + 8 / 2 % 3 . \"\\n\";").unwrap();
    let Statement::Echo { expressions, .. } = &program.statements[0] else {
        panic!("expected echo statement");
    };
    let Expr::Binary {
        op: BinaryOp::Concat,
        left,
        right,
        ..
    } = &expressions[0]
    else {
        panic!("expected outer concat");
    };
    assert!(matches!(right.as_ref(), Expr::String(_, _)));

    let Expr::Binary {
        op: BinaryOp::Concat,
        right,
        ..
    } = left.as_ref()
    else {
        panic!("expected left concat");
    };
    assert!(matches!(
        right.as_ref(),
        Expr::Binary {
            op: BinaryOp::Add,
            ..
        }
    ));

    let Expr::Binary {
        op: BinaryOp::Add,
        right,
        ..
    } = right.as_ref()
    else {
        panic!("expected nested addition");
    };
    assert!(matches!(
        right.as_ref(),
        Expr::Binary {
            op: BinaryOp::Modulo,
            ..
        }
    ));
}

#[test]
fn parser_accepts_power_as_right_associative_above_unary() {
    let program = parser::parse("<?php echo -3 ** 2, 2 ** 3 ** 2;").unwrap();
    let Statement::Echo { expressions, .. } = &program.statements[0] else {
        panic!("expected echo statement");
    };

    let Expr::Unary {
        op: UnaryOp::Negate,
        expr,
        ..
    } = &expressions[0]
    else {
        panic!("expected unary negation around power expression");
    };
    assert!(matches!(
        expr.as_ref(),
        Expr::Binary {
            op: BinaryOp::Power,
            ..
        }
    ));

    let Expr::Binary {
        op: BinaryOp::Power,
        right,
        ..
    } = &expressions[1]
    else {
        panic!("expected outer power expression");
    };
    assert!(matches!(
        right.as_ref(),
        Expr::Binary {
            op: BinaryOp::Power,
            ..
        }
    ));
}

#[test]
fn parser_accepts_assignment_operands_under_prefix_operators() {
    let program = parser::parse(
        "<?php if (!$link = connect()) {} echo -$value + 1; echo (int)$raw = value();",
    )
    .unwrap();
    assert_eq!(program.statements.len(), 3);

    let Statement::If { condition, .. } = &program.statements[0] else {
        panic!("expected if statement");
    };
    let Expr::Unary {
        op: UnaryOp::Not,
        expr,
        ..
    } = condition
    else {
        panic!("expected not expression around assignment");
    };
    assert!(matches!(
        expr.as_ref(),
        Expr::Assign {
            target: AssignmentTarget::Variable { name, .. },
            ..
        } if name == "link"
    ));

    let Statement::Echo { expressions, .. } = &program.statements[1] else {
        panic!("expected echo statement");
    };
    let Expr::Binary {
        op: BinaryOp::Add,
        left,
        ..
    } = &expressions[0]
    else {
        panic!("expected addition outside unary negation");
    };
    assert!(matches!(
        left.as_ref(),
        Expr::Unary {
            op: UnaryOp::Negate,
            expr,
            ..
        } if matches!(expr.as_ref(), Expr::Variable(name, _) if name == "value")
    ));

    let Statement::Echo { expressions, .. } = &program.statements[2] else {
        panic!("expected cast echo statement");
    };
    let Expr::Cast {
        kind: CastKind::Int,
        expr,
        ..
    } = &expressions[0]
    else {
        panic!("expected int cast around assignment");
    };
    assert!(matches!(
        expr.as_ref(),
        Expr::Assign {
            target: AssignmentTarget::Variable { name, .. },
            ..
        } if name == "raw"
    ));
}

