#[test]
fn parser_accepts_union_parameter_and_return_type_hints() {
    let program = parser::parse(
        "<?php namespace App; use Vendor\\Type as Imported; \
         function test(int|float $number, null|Imported $maybe): string|\\Vendor\\Type { return $maybe; } \
         $callback = fn(int|float ...$values): int|float => $values[0];",
    )
    .unwrap();

    let function = &program.functions[0];
    assert_eq!(
        function.parameters[0].type_hint,
        Some(TypeHint::Union(vec![TypeHint::Int, TypeHint::Float]))
    );
    assert_eq!(
        function.parameters[1].type_hint,
        Some(TypeHint::Union(vec![
            TypeHint::Null,
            TypeHint::Class("Vendor\\Type".to_string())
        ]))
    );
    assert_eq!(
        function.return_type,
        Some(TypeHint::Union(vec![
            TypeHint::String,
            TypeHint::Class("Vendor\\Type".to_string())
        ]))
    );

    let Statement::Assign { value, .. } = &program.statements[0] else {
        panic!("expected closure assignment");
    };
    let Expr::AnonymousFunction(closure) = value else {
        panic!("expected anonymous function expression");
    };
    assert_eq!(
        closure.parameters[0].type_hint,
        Some(TypeHint::Union(vec![TypeHint::Int, TypeHint::Float]))
    );
    assert!(closure.parameters[0].is_variadic);
    assert_eq!(
        closure.return_type,
        Some(TypeHint::Union(vec![TypeHint::Int, TypeHint::Float]))
    );
}

#[test]
fn parser_validates_closure_use_lists() {
    let program = parser::parse("<?php $b = 'test'; $fn = function () use ($b, &$a,) {};").unwrap();
    let Statement::Assign { value, .. } = &program.statements[1] else {
        panic!("expected closure assignment");
    };
    let Expr::AnonymousFunction(closure) = value else {
        panic!("expected anonymous function expression");
    };
    assert_eq!(
        closure
            .captures
            .iter()
            .map(|capture| (capture.name.as_str(), capture.by_ref))
            .collect::<Vec<_>>(),
        vec![("b", false), ("a", true)]
    );

    let cases = [
        (
            "<?php $fn = function() use ($a, &$a) {};",
            "Cannot use variable $a twice",
        ),
        (
            "<?php $fn = function() use ($GLOBALS) {};",
            "Cannot use auto-global as lexical variable",
        ),
        (
            "<?php $fn = function() use ($this) {};",
            "Cannot use $this as lexical variable",
        ),
        (
            "<?php $fn = function($a) use ($a) {};",
            "Cannot use lexical variable $a as a parameter name",
        ),
        (
            "<?php $a = null; $fn = function () use (&$a) { if (true) { static $a; } };",
            "Duplicate declaration of static variable $a",
        ),
    ];

    for (source, message) in cases {
        let error = parser::parse(source).unwrap_err();
        assert_eq!(error.kind, DiagnosticKind::Fatal, "{source}");
        assert_eq!(error.message, message, "{source}");
    }
}

#[test]
fn parser_accepts_static_anonymous_functions() {
    let program = parser::parse(
        "<?php $fn = static function () { return isset($this); }; \
         $arrow = static fn() => isset($this);",
    )
    .unwrap();

    let Statement::Assign { value, .. } = &program.statements[0] else {
        panic!("expected static closure assignment");
    };
    let Expr::AnonymousFunction(closure) = value else {
        panic!("expected anonymous function expression");
    };
    assert!(closure.is_static);
    assert!(!closure.is_arrow);

    let Statement::Assign { value, .. } = &program.statements[1] else {
        panic!("expected static arrow assignment");
    };
    let Expr::AnonymousFunction(closure) = value else {
        panic!("expected arrow function to lower to anonymous function");
    };
    assert!(closure.is_static);
    assert!(closure.is_arrow);
}

#[test]
fn parser_accepts_arrow_functions_as_implicit_capture_closures() {
    let program = parser::parse(
        "<?php $outer = 1; \
         $callback = fn(int $x, string &...$rest): array => [$x, $rest, $outer];",
    )
    .unwrap();

    let Statement::Assign { value, .. } = &program.statements[1] else {
        panic!("expected arrow function assignment");
    };
    let Expr::AnonymousFunction(closure) = value else {
        panic!("expected arrow function to lower to anonymous function");
    };

    assert_eq!(closure.return_type, Some(TypeHint::Array));
    assert!(!closure.return_by_ref);
    assert!(!closure.is_static);
    assert_eq!(closure.parameters.len(), 2);
    assert_eq!(closure.parameters[0].type_hint, Some(TypeHint::Int));
    assert_eq!(closure.parameters[1].type_hint, Some(TypeHint::String));
    assert!(closure.parameters[1].by_ref);
    assert!(closure.parameters[1].is_variadic);
    assert_eq!(closure.captures.len(), 1);
    assert_eq!(closure.captures[0].name, "outer");
    assert!(!closure.captures[0].by_ref);
    assert!(!closure.captures[0].warn_if_missing);
    assert!(matches!(
        &closure.body[..],
        [Statement::Return {
            value: Some(Expr::Array { .. }),
            ..
        }]
    ));
}

#[test]
fn parser_propagates_nested_arrow_captures_to_outer_arrow_scope() {
    let program =
        parser::parse("<?php $outer = 1; $callback = fn($x) => fn() => $x + $outer;").unwrap();

    let Statement::Assign { value, .. } = &program.statements[1] else {
        panic!("expected arrow function assignment");
    };
    let Expr::AnonymousFunction(outer) = value else {
        panic!("expected outer arrow closure");
    };
    assert_eq!(
        outer
            .captures
            .iter()
            .map(|capture| capture.name.as_str())
            .collect::<Vec<_>>(),
        vec!["outer"]
    );

    let [Statement::Return {
        value: Some(Expr::AnonymousFunction(inner)),
        ..
    }] = &outer.body[..]
    else {
        panic!("expected nested arrow closure return");
    };
    assert_eq!(
        inner
            .captures
            .iter()
            .map(|capture| capture.name.as_str())
            .collect::<Vec<_>>(),
        vec!["x", "outer"]
    );
}

