#[test]
fn parser_rejects_void_cast_expression_context_with_parse_error_kind() {
    let error = parser::parse("<?php $tmp = (void)$dummy;").unwrap_err();
    assert_eq!(error.message, "syntax error, unexpected token \"(void)\"");
    assert_eq!(error.kind, DiagnosticKind::ParseError);
    assert_eq!(error.span.unwrap().line, 1);
}

#[test]
fn parser_accepts_void_cast_statement_form() {
    let program = parser::parse("<?php (void)$dummy; (void)mark();").unwrap();
    assert_eq!(program.statements.len(), 2);
    let Statement::Expression { expression, .. } = &program.statements[0] else {
        panic!("expected expression statement");
    };
    assert!(matches!(expression, Expr::Variable(name, _) if name == "dummy"));
    let Statement::Expression { expression, .. } = &program.statements[1] else {
        panic!("expected expression statement");
    };
    assert!(matches!(expression, Expr::Call { name, .. } if name == "mark"));
}

#[test]
fn parser_rejects_unterminated_block_comment_with_parse_error_kind() {
    let error = parser::parse("<?php\n/* Foo\nBar").unwrap_err();
    assert_eq!(error.message, "Unterminated comment starting line 2");
    assert_eq!(error.kind, DiagnosticKind::ParseError);
    assert_eq!(error.span.unwrap().line, 2);
}

#[test]
fn parser_preserves_parenthesized_expression_grouping() {
    let program = parser::parse("<?php echo (1), ($name), (1 + 2), ((\"a\" . \"b\"));").unwrap();
    let Statement::Echo { expressions, .. } = &program.statements[0] else {
        panic!("expected echo statement");
    };

    assert!(matches!(
        &expressions[0],
        Expr::Grouped { expr, .. } if matches!(expr.as_ref(), Expr::Int(1, _))
    ));
    assert!(matches!(
        &expressions[1],
        Expr::Grouped { expr, .. } if matches!(expr.as_ref(), Expr::Variable(name, _) if name == "name")
    ));
    assert!(matches!(
        &expressions[2],
        Expr::Grouped { expr, .. } if matches!(expr.as_ref(), Expr::Binary { op: BinaryOp::Add, .. })
    ));

    let Expr::Grouped { expr, .. } = &expressions[3] else {
        panic!("expected outer grouping");
    };
    assert!(matches!(
        expr.as_ref(),
        Expr::Grouped { expr, .. } if matches!(expr.as_ref(), Expr::Binary { op: BinaryOp::Concat, .. })
    ));
}

#[test]
fn parser_accepts_comparison_boolean_and_grouping_expressions() {
    let program = parser::parse("<?php echo 1 + 2 <= \"3\" && (false || 4 >= 4);").unwrap();
    let Statement::Echo { expressions, .. } = &program.statements[0] else {
        panic!("expected echo statement");
    };
    let Expr::Binary {
        op: BinaryOp::And,
        left,
        right,
        ..
    } = &expressions[0]
    else {
        panic!("expected outer boolean and");
    };
    assert!(matches!(
        left.as_ref(),
        Expr::Binary {
            op: BinaryOp::LessEqual,
            ..
        }
    ));
    let Expr::Grouped { expr, .. } = right.as_ref() else {
        panic!("expected grouped boolean or");
    };
    assert!(matches!(
        expr.as_ref(),
        Expr::Binary {
            op: BinaryOp::Or,
            ..
        }
    ));
}

#[test]
fn parser_accepts_clone_expressions_with_assignment_operands() {
    let program = parser::parse("<?php $copy = clone $source = new stdClass;").unwrap();
    let Statement::Assign { value, .. } = &program.statements[0] else {
        panic!("expected assignment statement");
    };
    let Expr::Clone { expr, .. } = value else {
        panic!("expected clone expression");
    };
    assert!(matches!(
        expr.as_ref(),
        Expr::Assign {
            target: AssignmentTarget::Variable { name, .. },
            value,
            ..
        } if name == "source" && matches!(value.as_ref(), Expr::NewObject { class_name, .. } if class_name == "stdClass")
    ));
}

#[test]
fn parser_accepts_clone_with_property_updates() {
    let program = parser::parse("<?php $copy = clone($source, ['foo' => $bar]);").unwrap();
    let Statement::Assign { value, .. } = &program.statements[0] else {
        panic!("expected assignment statement");
    };
    let Expr::Call {
        name,
        arguments,
        argument_names,
        argument_unpacks,
        ..
    } = value
    else {
        panic!("expected clone call");
    };
    assert_eq!(name, "clone");
    assert_eq!(arguments.len(), 2);
    assert!(argument_names.iter().all(Option::is_none));
    assert!(argument_unpacks.iter().all(|unpack| !*unpack));
    assert!(matches!(&arguments[0], Expr::Variable(name, _) if name == "source"));
    assert!(matches!(
        &arguments[1],
        Expr::Array { elements, .. }
            if elements.len() == 1
                && matches!(&elements[0].value, ArrayElementValue::Value(value) if matches!(value, Expr::Variable(name, _) if name == "bar"))
    ));
}

#[test]
fn parser_accepts_clone_parenthesized_new_object_postfix_operand() {
    let program =
        parser::parse("<?php $property = clone (new Foo)->bar; $method = clone (new Foo)->bar();")
            .unwrap();

    let Statement::Assign { value, .. } = &program.statements[0] else {
        panic!("expected property assignment statement");
    };
    let Expr::Clone {
        expr,
        with_properties,
        ..
    } = value
    else {
        panic!("expected property clone expression");
    };
    assert!(with_properties.is_none());
    assert!(matches!(
        expr.as_ref(),
        Expr::PropertyFetch { receiver, name, .. }
            if name == "bar"
                && matches!(
                    receiver.as_ref(),
                    Expr::Grouped { expr, .. }
                        if matches!(expr.as_ref(), Expr::NewObject { class_name, .. } if class_name == "Foo")
                )
    ));

    let Statement::Assign { value, .. } = &program.statements[1] else {
        panic!("expected method assignment statement");
    };
    let Expr::Clone {
        expr,
        with_properties,
        ..
    } = value
    else {
        panic!("expected method clone expression");
    };
    assert!(with_properties.is_none());
    assert!(matches!(
        expr.as_ref(),
        Expr::MethodCall {
            receiver, name, ..
        } if name == "bar"
            && matches!(
                receiver.as_ref(),
                Expr::Grouped { expr, .. }
                    if matches!(expr.as_ref(), Expr::NewObject { class_name, .. } if class_name == "Foo")
            )
    ));
}

#[test]
fn parser_accepts_keyword_boolean_precedence() {
    let program = parser::parse(
        "<?php echo true || false and false, false or true && false, true xor false || false;",
    )
    .unwrap();
    let Statement::Echo { expressions, .. } = &program.statements[0] else {
        panic!("expected echo statement");
    };

    let Expr::Binary {
        op: BinaryOp::And,
        left,
        ..
    } = &expressions[0]
    else {
        panic!("expected outer keyword and");
    };
    assert!(matches!(
        left.as_ref(),
        Expr::Binary {
            op: BinaryOp::Or,
            ..
        }
    ));

    let Expr::Binary {
        op: BinaryOp::Or,
        right,
        ..
    } = &expressions[1]
    else {
        panic!("expected outer keyword or");
    };
    assert!(matches!(
        right.as_ref(),
        Expr::Binary {
            op: BinaryOp::And,
            ..
        }
    ));

    let Expr::Binary {
        op: BinaryOp::Xor,
        right,
        ..
    } = &expressions[2]
    else {
        panic!("expected outer keyword xor");
    };
    assert!(matches!(
        right.as_ref(),
        Expr::Binary {
            op: BinaryOp::Or,
            ..
        }
    ));
}

#[test]
fn parser_accepts_keyword_boolean_tail_after_direct_assignment_statement() {
    let program = parser::parse("<?php $result = true and false;").unwrap();
    let Statement::Expression { expression, .. } = &program.statements[0] else {
        panic!("expected expression statement");
    };
    let Expr::Binary {
        op: BinaryOp::And,
        left,
        ..
    } = expression
    else {
        panic!("expected keyword boolean tail");
    };
    assert!(matches!(
        left.as_ref(),
        Expr::Assign {
            op: AssignmentOp::Assign,
            ..
        }
    ));

    let compound = parser::parse("<?php $result += true xor false;").unwrap();
    let Statement::Expression { expression, .. } = &compound.statements[0] else {
        panic!("expected expression statement");
    };
    let Expr::Binary {
        op: BinaryOp::Xor,
        left,
        ..
    } = expression
    else {
        panic!("expected keyword boolean tail");
    };
    assert!(matches!(
        left.as_ref(),
        Expr::Assign {
            op: AssignmentOp::AddAssign,
            ..
        }
    ));

    parser::parse("<?php $result = (true and false);").unwrap();
}

