#[test]
fn parser_accepts_property_root_array_assignment_expressions() {
    let program =
        parser::parse("<?php $this->children[$name] = $value; $this->counts[$name] += 2;").unwrap();
    assert_eq!(program.statements.len(), 2);

    let Statement::Expression { expression, .. } = &program.statements[0] else {
        panic!("expected assignment expression statement");
    };
    let Expr::Assign { target, op, .. } = expression else {
        panic!("expected property array assignment expression");
    };
    let AssignmentTarget::PropertyArrayDim {
        receiver,
        name,
        dimensions,
        ..
    } = target
    else {
        panic!("expected property array assignment target");
    };
    assert_eq!(name, "children");
    assert!(matches!(receiver.as_ref(), Expr::Variable(name, _) if name == "this"));
    assert_eq!(dimensions.len(), 1);
    assert!(matches!(dimensions[0].as_ref(), Some(Expr::Variable(name, _)) if name == "name"));
    assert_eq!(*op, AssignmentOp::Assign);

    let Statement::Expression { expression, .. } = &program.statements[1] else {
        panic!("expected compound assignment expression statement");
    };
    let Expr::Assign { target, op, .. } = expression else {
        panic!("expected property array compound assignment expression");
    };
    assert!(matches!(
        target,
        AssignmentTarget::PropertyArrayDim { name, .. } if name == "counts"
    ));
    assert_eq!(*op, AssignmentOp::AddAssign);
}

#[test]
fn parser_models_final_class_and_modifier_diagnostics() {
    let program = parser::parse("<?php final class Base {}").unwrap();
    assert!(program.classes[0].is_final);

    let err = parser::parse("<?php final class Base {} class Child extends Base {}").unwrap_err();
    assert!(err
        .message
        .contains("Class Child cannot extend final class Base"));

    let err = parser::parse("<?php enum MyEnum {} class Child extends MyEnum {}").unwrap_err();
    assert!(err
        .message
        .contains("Class Child cannot extend enum MyEnum"));

    let err = parser::parse("<?php final final class Bad {}").unwrap_err();
    assert!(err
        .message
        .contains("Multiple final modifiers are not allowed"));

    let err = parser::parse("<?php final abstract class Bad {}").unwrap_err();
    assert!(err
        .message
        .contains("Cannot use the final modifier on an abstract class"));

    let err = parser::parse("<?php interface Bad { final function run(); }").unwrap_err();
    assert_eq!(err.message, "Interface method Bad::run() must not be final");

    let err = parser::parse(
        "<?php class Base { final public function run() {} } class Child extends Base { public function run() {} }",
    )
    .unwrap_err();
    assert_eq!(err.message, "Cannot override final method Base::run()");

    let err = parser::parse("<?php class Bad { abstract abstract function run() {} }").unwrap_err();
    assert!(err
        .message
        .contains("Multiple abstract modifiers are not allowed"));

    let err = parser::parse("<?php class Bad { public public function run() {} }").unwrap_err();
    assert!(err
        .message
        .contains("Multiple access type modifiers are not allowed"));
}

#[test]
fn parser_accepts_array_offset_compound_assignment_expressions() {
    let program = parser::parse(
        "<?php\n\
echo $items[\"count\"] += 2;\n\
($items[] .= \"x\");\n",
    )
    .unwrap();
    assert_eq!(program.statements.len(), 2);

    let Statement::Echo { expressions, .. } = &program.statements[0] else {
        panic!("expected echo statement");
    };
    assert!(matches!(
        &expressions[0],
        Expr::Assign {
            target: AssignmentTarget::ArrayDim(target),
            op: AssignmentOp::AddAssign,
            ..
        } if target.array == "items"
            && matches!(target.dimensions[0].as_ref(), Some(Expr::String(value, _)) if value == "count")
    ));

    let Statement::Expression { expression, .. } = &program.statements[1] else {
        panic!("expected grouped expression statement");
    };
    assert!(matches!(
        expression,
        Expr::Grouped { expr, .. }
            if matches!(
                expr.as_ref(),
                Expr::Assign {
                    target: AssignmentTarget::ArrayDim(target),
                    op: AssignmentOp::ConcatAssign,
                    ..
                } if target.array == "items" && target.dimensions == vec![None]
        )
    ));
}

#[test]
fn parser_accepts_append_array_call_arguments() {
    let program = parser::parse(
        "<?php\n\
function takes_ref(&$value) {}\n\
takes_ref($items[]);\n\
takes_ref(($items[0][]));\n",
    )
    .unwrap();
    assert_eq!(program.statements.len(), 2);

    let Statement::Call { arguments, .. } = &program.statements[0] else {
        panic!("expected first call statement");
    };
    assert!(matches!(
        &arguments[0],
        Expr::ArrayAccess { index: None, .. }
    ));

    let Statement::Call { arguments, .. } = &program.statements[1] else {
        panic!("expected grouped nested append call statement");
    };
    assert!(matches!(
        &arguments[0],
        Expr::Grouped { expr, .. }
            if matches!(
                expr.as_ref(),
                Expr::ArrayAccess { index: None, .. }
            )
    ));
}

#[test]
fn parser_rejects_unsupported_reference_forms_with_explicit_diagnostics() {
    parser::parse("<?php function &factory() { return null; }").unwrap();

    let yield_from_by_ref =
        parser::parse("<?php function &gen() { yield from other(); }").unwrap_err();
    assert_eq!(
        yield_from_by_ref.message,
        "Cannot use \"yield from\" inside a by-reference generator"
    );

    parser::parse("<?php function gen() { yield from other(); }").unwrap();

    let temporary_assignment = parser::parse("<?php $alias =& 1;").unwrap_err();
    assert_eq!(
        temporary_assignment.message,
        "unsupported by-reference assignment target"
    );

    let class_constant_assignment =
        parser::parse("<?php class A { const C = 1; } $alias =& A::C;").unwrap_err();
    assert_eq!(
        class_constant_assignment.message,
        "Cannot use temporary expression in write context"
    );
    assert_eq!(class_constant_assignment.kind, DiagnosticKind::ParseError);

    let builtin_result_assignment = parser::parse("<?php $alias =& strlen('x');").unwrap_err();
    assert_eq!(
        builtin_result_assignment.message,
        "Cannot use result of built-in function in write context"
    );
    parser::parse("<?php $alias =& array_shift($array);").unwrap();

    parser::parse("<?php function &factory(&$value) { $fn = 'id'; return $fn($value); }").unwrap();

    let recursive_return =
        parser::parse("<?php function &factory(&$value) { return factory($value); }").unwrap_err();
    assert_eq!(
        recursive_return.message,
        "recursive by-reference returns are unsupported"
    );

    parser::parse("<?php $array = []; $array[] =& $array;").unwrap();
    parser::parse("<?php $array = [1]; $array[] =& $array[0];").unwrap();
    parser::parse("<?php $array = [1, 2]; $array[0] =& $array[1];").unwrap();

    parser::parse("<?php $array = [&$array];").unwrap();
    parser::parse("<?php $array = ['self' => &$array];").unwrap();
    parser::parse("<?php $array = [[&$array]];").unwrap();

    let recursive_array_element_literal =
        parser::parse("<?php $array = []; $array[] = [&$array];").unwrap_err();
    assert_eq!(
        recursive_array_element_literal.message,
        "recursive array references are unsupported"
    );

    let same_array_element_literal = parser::parse("<?php $array = [&$array[0]];").unwrap_err();
    assert_eq!(
        same_array_element_literal.message,
        "same-array element references are unsupported"
    );

    let same_array_element_append_literal =
        parser::parse("<?php $array = []; $array[] = [&$array[0]];").unwrap_err();
    assert_eq!(
        same_array_element_append_literal.message,
        "same-array element references are unsupported"
    );

    parser::parse("<?php $array[0][1] =& $value;").unwrap();
    parser::parse("<?php $alias =& $array[0][1];").unwrap();
    parser::parse("<?php $alias =& ($array[0][1]);").unwrap();
    parser::parse("<?php $alias =& ($array[0])[1];").unwrap();
    parser::parse("<?php $alias =& (($array)[0])[1];").unwrap();
    parser::parse("<?php $refs = [&$array[0][1]];").unwrap();
    parser::parse("<?php $refs = ['k' => &$array[0][1]];").unwrap();
    parser::parse("<?php $refs = [&($array[0])[1]];").unwrap();

    let temporary_offset_forms = [
        ("<?php $alias =& factory()[0];", "factory()[0]"),
        ("<?php $alias =& [1][0];", "[1][0]"),
        ("<?php $alias =& ($value + 1)[0];", "($value + 1)[0]"),
        ("<?php $refs = [&factory()[0]];", "factory()[0]"),
        ("<?php $refs = [&[1][0]];", "[1][0]"),
    ];
    for (source, target) in temporary_offset_forms {
        assert_reference_lvalue_diagnostic(
            source,
            "temporary array offset references are unsupported",
            target,
        );
    }
}

#[test]
fn parser_rejects_class_constant_assignment_as_parse_error() {
    let class_constant_write =
        parser::parse("<?php class A { const C = 1; } A::C = 2;").unwrap_err();
    assert_eq!(
        class_constant_write.message,
        "syntax error, unexpected token \"=\""
    );
    assert_eq!(class_constant_write.kind, DiagnosticKind::ParseError);
}

fn assert_reference_lvalue_diagnostic(source: &str, message: &str, target: &str) {
    let error = parser::parse(source).unwrap_err();
    assert_eq!(error.kind, DiagnosticKind::Fatal);
    assert_eq!(error.message, message);
    let span = error
        .span
        .expect("reference diagnostic should be source-spanned");
    let byte_start = source
        .find(target)
        .unwrap_or_else(|| panic!("test source should contain target {target}"));
    let byte_end = byte_start + target.len();
    assert_eq!(span.byte_start, byte_start);
    assert_eq!(span.byte_end, byte_end);
    assert_eq!(&source[span.byte_start..span.byte_end], target);
    assert_eq!(
        span.line,
        source[..byte_start]
            .bytes()
            .filter(|byte| *byte == b'\n')
            .count()
            + 1
    );
    assert_eq!(
        span.column,
        source[..byte_start]
            .rsplit('\n')
            .next()
            .expect("source prefix should have a final line")
            .chars()
            .count()
            + 1
    );
}

#[test]
fn parser_accepts_grouped_direct_and_single_dim_reference_targets() {
    let program =
        parser::parse("<?php $alias =& ($value); $slot =& ($items)[0]; $same =& ($items[1]);")
            .unwrap();

    assert!(matches!(
        &program.statements[0],
        Statement::AssignRef { name, .. } if name == "alias"
    ));
    assert!(matches!(
        &program.statements[1],
        Statement::AssignRef { name, .. } if name == "slot"
    ));
    assert!(matches!(
        &program.statements[2],
        Statement::AssignRef { name, .. } if name == "same"
    ));
}

#[test]
fn parser_accepts_property_reference_assignment_targets() {
    let program = parser::parse("<?php $box->value =& $value; $alias =& $box->value;").unwrap();
    assert_eq!(program.statements.len(), 2);

    let Statement::Expression { expression, .. } = &program.statements[0] else {
        panic!("expected property assignment expression");
    };
    assert!(matches!(
        expression,
        Expr::AssignRef {
            target: AssignmentTarget::Property { name, .. },
            source,
            ..
        } if name == "value" && matches!(source.as_ref(), Expr::Variable(value, _) if value == "value")
    ));

    let Statement::AssignRef { name, source, .. } = &program.statements[1] else {
        panic!("expected variable reference assignment");
    };
    assert_eq!(name, "alias");
    assert!(matches!(source, Expr::PropertyFetch { name, .. } if name == "value"));
}

#[test]
fn parser_accepts_by_reference_return_call_assignment_sources() {
    let program = parser::parse(
        "<?php function &id(&$value) { return $value; } $alias =& id($value); $value_alias =& factory(); var_dump($items[0] =& returnsVal());",
    )
    .unwrap();
    assert!(program.functions[0].return_by_ref);
    let Statement::AssignRef { name, source, .. } = &program.statements[0] else {
        panic!("expected by-reference assignment");
    };
    assert_eq!(name, "alias");
    assert!(matches!(source, Expr::Call { name, .. } if name == "id"));

    let Statement::AssignRef { name, source, .. } = &program.statements[1] else {
        panic!("expected value-returning call by-reference assignment");
    };
    assert_eq!(name, "value_alias");
    assert!(matches!(source, Expr::Call { name, .. } if name == "factory"));

    let Statement::Call {
        name, arguments, ..
    } = &program.statements[2]
    else {
        panic!("expected var_dump call");
    };
    assert_eq!(name, "var_dump");
    assert!(matches!(
        &arguments[0],
        Expr::AssignRef {
            target: AssignmentTarget::ArrayDim(target),
            source,
            ..
        } if target.array == "items"
            && matches!(source.as_ref(), Expr::Call { name, .. } if name == "returnsval")
    ));
}

#[test]
fn parser_accepts_by_reference_assignment_expression_tails() {
    let program =
        parser::parse("<?php $a = 2; $x =& $a == 1; $a[] =& $a == $a =& $b > gc_collect_cycles();")
            .unwrap();

    let Statement::Expression { expression, .. } = &program.statements[1] else {
        panic!("expected by-reference assignment comparison expression");
    };
    assert!(matches!(
        expression,
        Expr::Binary {
            op: BinaryOp::Equal,
            left,
            ..
        } if matches!(left.as_ref(), Expr::AssignRef { target: AssignmentTarget::Variable { name, .. }, .. } if name == "x")
    ));

    let Statement::Expression { expression, .. } = &program.statements[2] else {
        panic!("expected array by-reference assignment comparison expression");
    };
    assert!(matches!(
        expression,
        Expr::Binary {
            op: BinaryOp::Equal,
            left,
            right,
            ..
        } if matches!(left.as_ref(), Expr::AssignRef { target: AssignmentTarget::ArrayDim(_), .. })
            && matches!(right.as_ref(), Expr::Binary { op: BinaryOp::Greater, .. })
    ));
}

#[test]
fn parser_accepts_by_reference_return_call_result_chains() {
    let program = parser::parse(
        "<?php function &id(&$value) { return $value; } function &chain(&$value) { return id($value); } function &fallback() { return make_value(); }",
    )
    .unwrap();

    assert_eq!(program.functions.len(), 3);
    assert!(program
        .functions
        .iter()
        .all(|function| function.return_by_ref));

    let Statement::Return {
        value: Some(Expr::Call { name, .. }),
        ..
    } = &program.functions[1].body[0]
    else {
        panic!("expected chained call return");
    };
    assert_eq!(name, "id");

    let Statement::Return {
        value: Some(Expr::Call { name, .. }),
        ..
    } = &program.functions[2].body[0]
    else {
        panic!("expected value call return");
    };
    assert_eq!(name, "make_value");
}

#[test]
fn parser_accepts_reference_array_literal_values() {
    let program = parser::parse("<?php $items = [&$value, 'k' => &$source[0]];").unwrap();
    let Statement::Assign { value, .. } = &program.statements[0] else {
        panic!("expected assignment statement");
    };
    let Expr::Array { elements, .. } = value else {
        panic!("expected array literal");
    };
    assert_eq!(elements.len(), 2);
    assert!(matches!(
        &elements[0].value,
        ArrayElementValue::Reference(ReferenceTarget::Variable { name, .. }) if name == "value"
    ));
    assert!(matches!(
        &elements[1].value,
        ArrayElementValue::Reference(ReferenceTarget::ArrayDim(target))
            if target.array == "source" && target.dimensions.len() == 1
    ));
}

#[test]
fn parser_accepts_whitespace_prelude_and_reference_array_entries() {
    let program = parser::parse("\n\t <?php $items = [&$a, \"k\" => &$b];").unwrap();
    let Statement::Assign {
        name,
        value: Expr::Array { elements, .. },
        ..
    } = &program.statements[0]
    else {
        panic!("expected array assignment");
    };

    assert_eq!(name, "items");
    assert_eq!(elements.len(), 2);
    assert!(matches!(
        &elements[0].value,
        ArrayElementValue::Reference(ReferenceTarget::Variable { name, .. }) if name == "a"
    ));
    assert!(matches!(&elements[1].key, Some(Expr::String(key, _)) if key == "k"));
    assert!(matches!(
        &elements[1].value,
        ArrayElementValue::Reference(ReferenceTarget::Variable { name, .. }) if name == "b"
    ));
}

#[test]
fn parser_accepts_long_array_literals_and_isset_empty_constructs() {
    let program = parser::parse(
        "<?php var_dump(isset($items[0], array('k' => 1)['k']), empty($items['missing']));",
    )
    .unwrap();
    let Statement::Call {
        name, arguments, ..
    } = &program.statements[0]
    else {
        panic!("expected var_dump statement");
    };
    assert_eq!(name, "var_dump");
    assert_eq!(arguments.len(), 2);
    assert!(matches!(
        &arguments[0],
        Expr::Isset { targets, .. } if targets.len() == 2
            && matches!(&targets[1], Expr::ArrayAccess { array, .. } if matches!(array.as_ref(), Expr::Array { .. }))
    ));
    assert!(matches!(&arguments[1], Expr::Empty { .. }));
}

#[test]
fn parser_treats_standalone_language_constructs_as_expressions() {
    let program = parser::parse(
        "<?php isset($items[(string)'0']); empty($items[(string)'1']); array(call_side_effect());",
    )
    .unwrap();
    assert_eq!(program.statements.len(), 3);

    assert!(matches!(
        &program.statements[0],
        Statement::Expression {
            expression: Expr::Isset { targets, .. },
            ..
        } if targets.len() == 1
            && matches!(
                &targets[0],
                Expr::ArrayAccess { index: Some(index), .. }
                    if matches!(index.as_ref(), Expr::Cast { kind: CastKind::String, .. })
            )
    ));
    assert!(matches!(
        &program.statements[1],
        Statement::Expression {
            expression: Expr::Empty { target, .. },
            ..
        } if matches!(
            target.as_ref(),
            Expr::ArrayAccess { index: Some(index), .. }
                if matches!(index.as_ref(), Expr::Cast { kind: CastKind::String, .. })
        )
    ));
    assert!(matches!(
        &program.statements[2],
        Statement::Expression {
            expression: Expr::Array { .. },
            ..
        }
    ));
}

#[test]
fn parser_accepts_null_coalescing_as_right_associative_expression() {
    let program = parser::parse("<?php echo $a ?? $b ?? \"fallback\";").unwrap();
    let Statement::Echo { expressions, .. } = &program.statements[0] else {
        panic!("expected echo statement");
    };
    let Expr::Binary {
        op: BinaryOp::Coalesce,
        left,
        right,
        ..
    } = &expressions[0]
    else {
        panic!("expected null coalescing expression");
    };
    assert!(matches!(left.as_ref(), Expr::Variable(name, _) if name == "a"));
    assert!(matches!(
        right.as_ref(),
        Expr::Binary {
            op: BinaryOp::Coalesce,
            left,
            right,
            ..
        } if matches!(left.as_ref(), Expr::Variable(name, _) if name == "b")
            && matches!(right.as_ref(), Expr::String(value, _) if value == "fallback")
    ));
}

#[test]
fn parser_accepts_bitwise_scalar_expressions() {
    let program = parser::parse("<?php echo \"a\" & \"b\" ^ \"d\" | \"c\" && 1 == 1;").unwrap();
    let Statement::Echo { expressions, .. } = &program.statements[0] else {
        panic!("expected echo statement");
    };

    let Expr::Binary {
        op: BinaryOp::And,
        left,
        ..
    } = &expressions[0]
    else {
        panic!("expected outer boolean and");
    };
    let Expr::Binary {
        op: BinaryOp::BitwiseOr,
        left,
        ..
    } = left.as_ref()
    else {
        panic!("expected bitwise or below boolean and");
    };
    let Expr::Binary {
        op: BinaryOp::BitwiseXor,
        left,
        ..
    } = left.as_ref()
    else {
        panic!("expected bitwise xor below bitwise or");
    };
    assert!(matches!(
        left.as_ref(),
        Expr::Binary {
            op: BinaryOp::BitwiseAnd,
            ..
        }
    ));
}

#[test]
fn parser_accepts_unary_bitwise_not_expressions() {
    let program = parser::parse("<?php echo ~6 & 3, ~(\"some\");").unwrap();
    let Statement::Echo { expressions, .. } = &program.statements[0] else {
        panic!("expected echo statement");
    };
    let Expr::Binary {
        op: BinaryOp::BitwiseAnd,
        left,
        ..
    } = &expressions[0]
    else {
        panic!("expected bitwise and expression");
    };
    assert!(matches!(
        left.as_ref(),
        Expr::Unary {
            op: UnaryOp::BitwiseNot,
            ..
        }
    ));
    assert!(matches!(
        &expressions[1],
        Expr::Unary {
            op: UnaryOp::BitwiseNot,
            ..
        }
    ));
}

#[test]
fn parser_accepts_shift_expressions_and_bare_constants() {
    let program = parser::parse(
        "<?php error_reporting(\\E_ERROR); var_dump(\"34\" << \"1\", \"56\" >> \"2\", \\PHP_EOL);",
    )
    .unwrap();

    let Statement::Call {
        name, arguments, ..
    } = &program.statements[0]
    else {
        panic!("expected error_reporting call");
    };
    assert_eq!(name, "error_reporting");
    assert!(matches!(
        &arguments[0],
        Expr::Constant(constant, _) if constant == "E_ERROR"
    ));

    let Statement::Call { arguments, .. } = &program.statements[1] else {
        panic!("expected var_dump call");
    };
    assert!(matches!(
        &arguments[0],
        Expr::Binary {
            op: BinaryOp::ShiftLeft,
            ..
        }
    ));
    assert!(matches!(
        &arguments[1],
        Expr::Binary {
            op: BinaryOp::ShiftRight,
            ..
        }
    ));
    assert!(matches!(
        &arguments[2],
        Expr::Constant(constant, _) if constant == "PHP_EOL"
    ));
}

#[test]
fn parser_accepts_global_const_declarations() {
    let program = parser::parse(
        "<?php const C = 0 && __NAMESPACE__, D = PHP_EOL, A = [\"x\" => 1], B = [\"bar\" => 3][\"bar\"]; var_dump(C, defined(\"D\"));",
    )
    .unwrap();

    let Statement::Const { declarations, .. } = &program.statements[0] else {
        panic!("expected const declaration");
    };
    assert_eq!(declarations.len(), 4);
    assert_eq!(declarations[0].name, "C");
    assert!(matches!(
        &declarations[0].value,
        Expr::Binary {
            op: BinaryOp::And,
            ..
        }
    ));
    assert!(matches!(
        &declarations[1].value,
        Expr::Constant(name, _) if name == "PHP_EOL"
    ));
    assert!(matches!(
        &declarations[2].value,
        Expr::Array { elements, .. } if elements.len() == 1
    ));
    assert!(matches!(
        &declarations[3].value,
        Expr::ArrayAccess { array, index: Some(index), .. }
            if matches!(array.as_ref(), Expr::Array { .. })
                && matches!(index.as_ref(), Expr::String(key, _) if key == "bar")
    ));
}

#[test]
fn parser_accepts_class_constant_metadata_and_fetches() {
    let program = parser::parse(
        "<?php
class Sample {
    const A = 1, B = [\"x\" => 2], C = [\"bar\" => 3][\"bar\"];
    public const Label = \"ok\";

    public static function value() { return self::A; }
}
$haystack = [Sample::A];
$map = [Sample::A => Sample::B];
echo \\Sample::Label;",
    )
    .unwrap();

    assert_eq!(program.classes.len(), 1);
    assert_eq!(program.classes[0].constants.len(), 4);
    assert_eq!(program.classes[0].constants[0].name, "A");
    assert_eq!(
        program.classes[0].constants[0].visibility,
        PropertyVisibility::Public
    );
    assert!(matches!(
        program.classes[0].constants[0].value,
        Expr::Int(1, _)
    ));
    assert!(matches!(
        program.classes[0].constants[1].value,
        Expr::Array { ref elements, .. } if elements.len() == 1
    ));
    assert!(matches!(
        program.classes[0].constants[2].value,
        Expr::ArrayAccess { ref array, index: Some(ref index), .. }
            if matches!(array.as_ref(), Expr::Array { .. })
                && matches!(index.as_ref(), Expr::String(key, _) if key == "bar")
    ));
    assert!(matches!(
        program.classes[0].methods[0].body[0],
        Statement::Return {
            value:
                Some(Expr::ClassConstantFetch {
                    ref class_name,
                    ref name,
                    ..
                }),
            ..
        } if class_name == "self" && name == "A"
    ));
    assert!(matches!(
        &program.statements[0],
        Statement::Assign {
            value:
                Expr::Array {
                    elements,
                    ..
                },
            ..
        } if matches!(
            &elements[0].value,
            ArrayElementValue::Value(Expr::ClassConstantFetch { class_name, name, .. })
                if class_name == "Sample" && name == "A"
        )
    ));
    assert!(matches!(
        &program.statements[2],
        Statement::Echo { expressions, .. }
            if matches!(
                &expressions[0],
                Expr::ClassConstantFetch { class_name, name, .. }
                    if class_name == "Sample" && name == "Label"
            )
    ));
}

#[test]
fn parser_accepts_typed_class_constants_and_reports_literal_type_mismatches() {
    let program = parser::parse(
        "<?php
class Sample {
    public const int A = 1, B = 2;
    protected const float C = 3;
    private const string|null D = null;
}",
    )
    .unwrap();

    let constants = &program.classes[0].constants;
    assert_eq!(constants.len(), 4);
    assert!(matches!(constants[0].type_hint, Some(TypeHint::Int)));
    assert!(matches!(constants[1].type_hint, Some(TypeHint::Int)));
    assert!(matches!(constants[2].type_hint, Some(TypeHint::Float)));
    assert!(matches!(
        constants[3].type_hint,
        Some(TypeHint::Union(ref members))
            if matches!(members.as_slice(), [TypeHint::String, TypeHint::Null])
    ));

    let error = parser::parse("<?php class Sample { public const string A = 1; }").unwrap_err();
    assert_eq!(
        error.message,
        "Cannot use int as value for class constant Sample::A of type string"
    );
    assert_eq!(error.kind, DiagnosticKind::Fatal);

    for (type_name, expected) in [
        (
            "callable",
            "Class constant Sample::A cannot have type callable",
        ),
        ("void", "Class constant Sample::A cannot have type void"),
        ("never", "Class constant Sample::A cannot have type never"),
    ] {
        let error = parser::parse(&format!(
            "<?php class Sample {{ public const {type_name} A = 1; }}"
        ))
        .unwrap_err();
        assert_eq!(error.message, expected);
        assert_eq!(error.kind, DiagnosticKind::Fatal);
    }
}

#[test]
fn parser_validates_typed_class_constant_inheritance_and_composition() {
    let error = parser::parse(
        "<?php
class A {
    public const int VALUE = 1;
}
class B extends A {
    public const string VALUE = 'b';
}",
    )
    .unwrap_err();
    assert_eq!(
        error.message,
        "Type of B::VALUE must be compatible with A::VALUE of type int"
    );
    assert_eq!(error.kind, DiagnosticKind::Fatal);

    let error = parser::parse(
        "<?php
interface I {
    public const string VALUE = 'i';
}
class C implements I {
    public const VALUE = 'c';
}",
    )
    .unwrap_err();
    assert_eq!(
        error.message,
        "Type of C::VALUE must be compatible with I::VALUE of type string"
    );
    assert_eq!(error.kind, DiagnosticKind::Fatal);

    let program = parser::parse(
        "<?php
trait T {
    public const ?array VALUE = [];
}
class UsesTrait {
    use T;
    public const array VALUE = [];
}",
    )
    .unwrap();
    assert_eq!(
        program.classes[0].declaration_fatals[0].message,
        "UsesTrait and T define the same constant (VALUE) in the composition of UsesTrait. However, the definition differs and is considered incompatible. Class was composed"
    );

    let program = parser::parse(
        "<?php
class ParentConstant {
    public const iterable VALUE = [];
}
class ChildConstant extends ParentConstant {
    public const array VALUE = [];
}",
    )
    .unwrap();
    assert_eq!(program.classes.len(), 2);
}

#[test]
fn parser_accepts_dynamic_class_name_fetch_syntax() {
    let program =
        parser::parse("<?php $e = new Exception; echo $e::class; echo (new stdClass)::CLASS;")
            .unwrap();

    assert!(matches!(
        &program.statements[1],
        Statement::Echo { expressions, .. }
            if matches!(
                &expressions[0],
                Expr::DynamicClassNameFetch { receiver, .. }
                    if matches!(receiver.as_ref(), Expr::Variable(name, _) if name == "e")
            )
    ));
    assert!(matches!(
        &program.statements[2],
        Statement::Echo { expressions, .. }
            if matches!(
                &expressions[0],
                Expr::DynamicClassNameFetch { receiver, .. }
                    if matches!(receiver.as_ref(), Expr::Grouped { expr, .. } if matches!(
                        expr.as_ref(),
                        Expr::NewObject { class_name, .. } if class_name == "stdClass"
                    ))
            )
    ));
}

#[test]
fn parser_accepts_dynamic_class_constant_fetch_syntax() {
    let program = parser::parse(
        "<?php
class Sample { const VALUE = 'value'; const NAME = 'VALUE'; }
$name = 'VALUE';
$class = Sample::class;
echo Sample::{$name};
echo $class::VALUE;
echo $class::{$name};
echo Sample::{Sample::NAME};",
    )
    .unwrap();

    assert!(matches!(
        &program.statements[2],
        Statement::Echo { expressions, .. }
            if matches!(
                &expressions[0],
                Expr::DynamicClassConstantFetch {
                    class_name: Some(class_name),
                    receiver: None,
                    name,
                    ..
                } if class_name == "Sample"
                    && matches!(name.as_ref(), Expr::Variable(name, _) if name == "name")
            )
    ));
    assert!(matches!(
        &program.statements[3],
        Statement::Echo { expressions, .. }
            if matches!(
                &expressions[0],
                Expr::DynamicClassConstantFetch {
                    class_name: None,
                    receiver: Some(receiver),
                    name,
                    ..
                } if matches!(receiver.as_ref(), Expr::Variable(name, _) if name == "class")
                    && matches!(name.as_ref(), Expr::String(name, _) if name == "VALUE")
            )
    ));
    assert!(matches!(
        &program.statements[4],
        Statement::Echo { expressions, .. }
            if matches!(
                &expressions[0],
                Expr::DynamicClassConstantFetch {
                    class_name: None,
                    receiver: Some(receiver),
                    name,
                    ..
                } if matches!(receiver.as_ref(), Expr::Variable(name, _) if name == "class")
                    && matches!(name.as_ref(), Expr::Variable(name, _) if name == "name")
            )
    ));
    assert!(matches!(
        &program.statements[5],
        Statement::Echo { expressions, .. }
            if matches!(
                &expressions[0],
                Expr::DynamicClassConstantFetch {
                    class_name: Some(class_name),
                    receiver: None,
                    name,
                    ..
                } if class_name == "Sample"
                    && matches!(
                        name.as_ref(),
                        Expr::ClassConstantFetch { class_name, name, .. }
                            if class_name == "Sample" && name == "NAME"
                    )
            )
    ));
}

