#[test]
fn compile_error_handler_stack_and_trigger_error_to_native_binary() {
    let root = temp_dir("ptn-native-error-handler-stack-trigger");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("error-handler-stack-trigger.php");
    let output = root.join("error-handler-stack-trigger-bin");
    fs::write(
        &input,
        "<?php
set_error_handler(function ($errno, $errstr) {
    echo 'first:', $errno, ':', $errstr, \"\\n\";
    return true;
});
set_error_handler(function ($errno, $errstr) {
    echo 'second:', $errno, ':', $errstr, \"\\n\";
    return true;
});
trigger_error('alpha');
restore_error_handler();
trigger_error('beta');
set_error_handler(null);
trigger_error('gamma');
restore_error_handler();
trigger_error('delta');
",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    let stdout = String::from_utf8(execution.stdout).unwrap();
    assert!(stdout.contains("second:1024:alpha\n"), "{stdout}");
    assert!(stdout.contains("first:1024:beta\n"), "{stdout}");
    assert!(stdout.contains("Notice: gamma in ptn on line"), "{stdout}");
    assert!(stdout.contains("first:1024:delta\n"), "{stdout}");
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_trigger_error_user_error_emits_deprecated_then_direct_fatal() {
    let root = temp_dir("ptn-native-trigger-error-user-error");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("trigger-error-user-error.php");
    let output = root.join("trigger-error-user-error-bin");
    fs::write(
        &input,
        r#"<?php
$anonymous = new class {};
trigger_error(get_class($anonymous) . " ...now you don't!", E_USER_ERROR);
echo "unreachable\n";
"#,
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(!execution.status.success());
    let stdout = String::from_utf8(execution.stdout).unwrap();
    assert!(
        stdout.contains(
            "Deprecated: Passing E_USER_ERROR to trigger_error() is deprecated since 8.4, throw an exception or call exit with a string message instead"
        ),
        "{stdout}"
    );
    assert!(!stdout.contains("unreachable"), "{stdout}");
    let stderr = String::from_utf8(execution.stderr).unwrap();
    assert!(stderr.contains("Fatal error: class@anonymous"), "{stderr}");
    assert!(stderr.contains(" ...now you don't!"), "{stderr}");
    assert!(!stderr.contains("Uncaught Error"), "{stderr}");
}

