#[test]
fn compile_shutdown_function_forward_static_call_no_active_file_to_native_binary() {
    let root = temp_dir("ptn-native-shutdown-forward-static-no-active-file");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("shutdown-forward-static-no-active-file.php");
    let output = root.join("shutdown-forward-static-no-active-file-bin");
    fs::write(
        &input,
        "<?php
register_shutdown_function('forward_static_call', 'hash_hkdf');
?>
Done
",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(!execution.status.success());
    assert_eq!(String::from_utf8(execution.stdout).unwrap(), "Done\n");
    let stderr = String::from_utf8(execution.stderr).unwrap();
    assert!(stderr.contains(
        "Fatal error: Uncaught Error: Cannot call forward_static_call() when no class scope is active in [no active file]:0\n"
    ));
    assert!(stderr.contains("#0 [internal function]: forward_static_call('hash_hkdf')\n"));
    assert!(stderr.contains("#1 {main}\n"));
    assert!(stderr.contains("  thrown in [no active file] on line 0\n"));
    assert!(!stderr.contains("shutdown-forward-static-no-active-file.php:0"));
}

#[test]
fn parser_rejects_unmatched_override_attributes() {
    let cases = [
        (
            "<?php class C { #[\\Override] public function c() {} }",
            "C::c() has #[\\Override] attribute, but no matching parent method exists",
        ),
        (
            "<?php class P { private mixed $p; } class C extends P { #[\\Override] public mixed $p; }",
            "C::$p has #[\\Override] attribute, but no matching parent property exists",
        ),
        (
            "<?php trait T { public function t() {} } class C { use T; #[\\Override] public function t() {} }",
            "C::t() has #[\\Override] attribute, but no matching parent method exists",
        ),
        (
            "<?php class C { public string $p { #[\\Override] get => $this->p; set => $value; } }",
            "C::$p::get() has #[\\Override] attribute, but no matching parent method exists",
        ),
        (
            "<?php class C { public string $p { get => $this->p; #[\\Override] set => $value; } }",
            "C::$p::set() has #[\\Override] attribute, but no matching parent method exists",
        ),
    ];

    for (source, message) in cases {
        let error = parser::parse(source).unwrap_err();
        assert_eq!(error.message, message, "{source}");
    }
}

#[test]
fn parser_ignores_override_identifier_inside_non_override_attribute_arguments() {
    let program =
        parser::parse("<?php class C { #[Example(Override::class)] public function c() {} }")
            .unwrap();

    assert!(!program.classes[0].methods[0].has_override_attribute);
}

#[test]
fn parser_accepts_readonly_property_metadata() {
    let program = parser::parse(
        "<?php
class Book {
    public readonly string $title;
    private readonly int $year;
    public private(set) readonly int $id;
}
",
    )
    .unwrap();

    assert!(program.classes[0].properties[0].is_readonly);
    let title_type = program.classes[0].properties[0].type_hint.as_ref().unwrap();
    assert_eq!(title_type.text, "string");
    assert!(matches!(&title_type.kind, PropertyTypeKind::String));
    assert!(!title_type.allows_null);
    assert_eq!(
        program.classes[0].properties[0].visibility,
        PropertyVisibility::Public
    );
    assert_eq!(
        program.classes[0].properties[0].set_visibility,
        PropertyVisibility::Protected
    );
    assert!(program.classes[0].properties[1].is_readonly);
    let year_type = program.classes[0].properties[1].type_hint.as_ref().unwrap();
    assert_eq!(year_type.text, "int");
    assert!(matches!(&year_type.kind, PropertyTypeKind::Int));
    assert!(!year_type.allows_null);
    assert_eq!(
        program.classes[0].properties[1].visibility,
        PropertyVisibility::Private
    );
    assert_eq!(
        program.classes[0].properties[1].set_visibility,
        PropertyVisibility::Private
    );
    assert!(program.classes[0].properties[2].is_readonly);
    let id_type = program.classes[0].properties[2].type_hint.as_ref().unwrap();
    assert_eq!(id_type.text, "int");
    assert!(matches!(&id_type.kind, PropertyTypeKind::Int));
    assert!(!id_type.allows_null);
    assert_eq!(
        program.classes[0].properties[2].set_visibility,
        PropertyVisibility::Private
    );
}

