#[test]
fn parser_rejects_asymmetric_virtual_property_hooks() {
    parser::parse("<?php class Foo { public private(set) int $bar { get => 42; set {} } }")
        .unwrap();
    parser::parse("<?php class Foo { public int $bar = 42 { set {} } }").unwrap();

    let error = parser::parse("<?php class Foo { public private(set) int $bar { get => 42; } }")
        .unwrap_err();
    assert_eq!(
        error.message,
        "get-only virtual property Foo::$bar must not specify asymmetric visibility"
    );

    let error =
        parser::parse("<?php class Foo { public private(set) int $bar { set {} } }").unwrap_err();
    assert_eq!(
        error.message,
        "set-only virtual property Foo::$bar must not specify asymmetric visibility"
    );
}

#[test]
fn parser_rejects_default_on_explicit_virtual_property_hooks() {
    let error =
        parser::parse("<?php class Test { public $prop = 0 { get {} set {} } }").unwrap_err();
    assert_eq!(
        error.message,
        "Cannot specify default value for virtual hooked property Test::$prop"
    );

    let error = parser::parse(
        "<?php
class A { public $prop { get {} set {} } }
class B extends A { public $prop = 0 { get {} set {} } }
",
    )
    .unwrap_err();
    assert_eq!(
        error.message,
        "Cannot specify default value for virtual hooked property B::$prop"
    );

    parser::parse("<?php class Test { public $prop = 0 { get { return $this->prop; } set {} } }")
        .unwrap();
    parser::parse("<?php class Test { public $prop = 0 { get { return 42; } } }").unwrap();
}

