#[test]
fn parser_accepts_instance_class_methods_and_object_callables() {
    let program = parser::parse(
        "<?php
class Worker {
    public function run($value) { return $value + 1; }
}
$worker = new Worker();
echo $worker->run(3);
call_user_func([$worker, \"run\"], 4);",
    )
    .unwrap();
    assert_eq!(program.classes.len(), 1);
    assert_eq!(program.classes[0].methods.len(), 1);
    assert_eq!(program.classes[0].methods[0].name, "run");
    assert!(!program.classes[0].methods[0].is_static);
    assert_eq!(program.statements.len(), 3);
    assert!(matches!(
        &program.statements[0],
        Statement::Assign {
            value: Expr::NewObject { class_name, .. },
            ..
        } if class_name == "Worker"
    ));
    assert!(matches!(
        &program.statements[1],
        Statement::Echo { expressions, .. }
            if matches!(&expressions[0], Expr::MethodCall { name, .. } if name == "run")
    ));
    assert!(matches!(
        &program.statements[2],
        Statement::Call { name, arguments, .. }
            if name == "call_user_func" && arguments.len() == 2
    ));
}

#[test]
fn parser_distinguishes_constructed_new_from_bare_new_access() {
    let program = parser::parse(
        "<?php
class A {
    const C = 'constant';
    public static $prop = B::class;
}
class B {}

echo new (trim(' A '))()::C;
var_dump(new A::$prop);
",
    )
    .unwrap();

    let echo_statement = program
        .statements
        .iter()
        .find(|statement| matches!(*statement, Statement::Echo { .. }))
        .expect("expected echo statement");
    let Statement::Echo { expressions, .. } = echo_statement else {
        panic!("expected echo statement");
    };
    assert!(matches!(
        &expressions[0],
        Expr::DynamicClassConstantFetch {
            receiver: Some(receiver),
            ..
        } if matches!(
            receiver.as_ref(),
            Expr::DynamicNewObject {
                constructor_parentheses: true,
                ..
            }
        )
    ));

    let call_statement = program
        .statements
        .iter()
        .find(|statement| matches!(*statement, Statement::Call { .. }))
        .expect("expected var_dump call");
    let Statement::Call { arguments, .. } = call_statement else {
        panic!("expected var_dump call");
    };
    assert!(matches!(
        &arguments[0],
        Expr::DynamicNewObject {
            class_name,
            constructor_parentheses: false,
            ..
        } if matches!(
            class_name.as_ref(),
            Expr::StaticPropertyFetch {
                class_name,
                name,
                ..
            } if class_name == "A" && name == "prop"
        )
    ));

    let method = parser::parse("<?php class A { function test() {} } new A->test();").unwrap_err();
    assert_eq!(method.kind, DiagnosticKind::ParseError);
    assert_eq!(method.message, "syntax error, unexpected token \"->\"");

    let property = parser::parse("<?php class A { public $prop; } echo new A->prop;").unwrap_err();
    assert_eq!(property.kind, DiagnosticKind::ParseError);
    assert_eq!(
        property.message,
        "syntax error, unexpected token \"->\", expecting \",\" or \";\""
    );

    let assignment = parser::parse("<?php new ArrayObject() = 1;").unwrap_err();
    assert_eq!(assignment.kind, DiagnosticKind::ParseError);
    assert_eq!(assignment.message, "syntax error, unexpected token \"=\"");
}

#[test]
fn parser_accepts_simple_class_inheritance_metadata() {
    let program = parser::parse(
        "<?php
class Base {
    public function label($value) { return $value; }
}

class Child extends Base {
    public function own($value) { return $this->label($value); }
}",
    )
    .unwrap();

    assert_eq!(program.classes.len(), 2);
    assert_eq!(program.classes[0].name, "Base");
    assert_eq!(program.classes[0].parent_name, None);
    assert_eq!(program.classes[1].name, "Child");
    assert_eq!(program.classes[1].parent_name.as_deref(), Some("Base"));
    assert_eq!(program.classes[1].methods.len(), 1);
}

#[test]
fn parser_accepts_anonymous_class_metadata_and_instanceof() {
    let program = parser::parse(
        "<?php
interface Contract {
    public function run();
}

class Base {
    public function label($value) { return $value; }
}

$worker = new class(\"native\") extends Base implements Contract {
    public $name;

    public function __construct($name) {
        $this->name = $name;
    }

    public function run() {
        return $this->label($this->name);
    }
};

var_dump($worker instanceof Base, $worker instanceof Contract);
",
    )
    .unwrap();

    assert_eq!(program.classes.len(), 3);
    assert_eq!(program.classes[2].name, "Base@anonymous");
    assert!(program.classes[2].is_anonymous);
    assert_eq!(program.classes[2].parent_name.as_deref(), Some("Base"));
    assert_eq!(program.classes[2].interfaces, vec!["Contract"]);
    assert_eq!(program.classes[2].properties[0].name, "name");
    assert_eq!(program.classes[2].methods.len(), 2);

    let Statement::Assign { value, .. } = &program.statements[0] else {
        panic!("expected anonymous class assignment");
    };
    assert!(matches!(
        value,
        Expr::NewObject { class_name, .. } if class_name == "Base@anonymous"
    ));

    let Statement::Call { arguments, .. } = &program.statements[1] else {
        panic!("expected var_dump statement");
    };
    assert!(matches!(
        &arguments[0],
        Expr::InstanceOf {
            target: InstanceOfTarget::ClassName { name, .. },
            ..
        } if name == "Base"
    ));
    assert!(matches!(
        &arguments[1],
        Expr::InstanceOf {
            target: InstanceOfTarget::ClassName { name, .. },
            ..
        } if name == "Contract"
    ));
}

#[test]
fn parser_accepts_unit_and_backed_enum_declarations() {
    let program = parser::parse(
        "<?php
enum Sample {
    case A;
    const Alias = self::A;
    public function label() { return __METHOD__; }
}
enum Code: int {
    case Ok = 200;
}",
    )
    .unwrap();

    assert_eq!(program.classes.len(), 2);
    assert!(program.classes[0].is_enum);
    assert_eq!(program.classes[0].enum_backing_type, None);
    assert_eq!(program.classes[0].constants.len(), 2);
    assert!(program.classes[0].constants[0].is_enum_case);
    assert!(program.classes[0].constants[0].enum_case_value.is_none());
    assert!(!program.classes[0].constants[1].is_enum_case);
    assert_eq!(program.classes[0].methods.len(), 1);

    assert!(program.classes[1].is_enum);
    assert_eq!(
        program.classes[1].enum_backing_type,
        Some(ptn::ast::EnumBackingType::Int)
    );
    assert!(program.classes[1].constants[0].is_enum_case);
    assert!(program.classes[1].constants[0].enum_case_value.is_some());
}

