#[test]
fn compile_trait_adaptation_across_separate_use_blocks_to_native_binary() {
    let root = temp_dir("ptn-native-trait-adaptation-separate-use-blocks");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("trait-adaptation-separate-use-blocks.php");
    let output = root.join("trait-adaptation-separate-use-blocks-bin");
    fs::write(
        &input,
        "<?php
trait TraitA {
    public static function catch() { echo __METHOD__, \"\\n\"; }
}
trait TraitB {
    protected static function try() { echo __METHOD__, \"\\n\"; }
}
class Foo {
    use TraitA {
        TraitA::catch insteadof TraitB;
    }
    use TraitB {
        try as public attempt;
    }
}
Foo::attempt();
",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        "TraitB::try\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn parser_enforces_trait_imported_abstract_methods_in_concrete_class() {
    let program = parser::parse(
        "<?php
trait TraitWithAbstract {
    abstract public function fromTrait();
}
class TraitWorks {
    use TraitWithAbstract;
}",
    )
    .unwrap();
    assert!(program.classes[0]
        .methods
        .iter()
        .any(|method| method.name == "fromTrait" && method.trait_name.is_some()));

    let error = parser::parse(
        "<?php
trait TraitWithAbstract {
    abstract public function fromTrait();
}
class TraitWorks {
    use TraitWithAbstract {
        TraitWithAbstract::fromTrait as renamedRequirement;
    }
}",
    )
    .unwrap_err();
    assert_eq!(
        error.message,
        "Class TraitWorks contains 1 abstract method and must therefore be declared abstract or implement the remaining method (TraitWorks::renamedRequirement)"
    );

    let program = parser::parse(
        "<?php
trait TraitWithAbstract {
    abstract public function fromTrait();
}
class TraitWorks {
    use TraitWithAbstract;
    public function fromTrait() {}
}
abstract class Base {
    abstract public function directAbstract();
}",
    )
    .unwrap();

    assert!(program.classes[0]
        .methods
        .iter()
        .any(|method| method.name == "fromTrait" && method.trait_name.is_none()));

    let error = parser::parse(
        "<?php
class NotAbstract {
    abstract public function directAbstract();
}",
    )
    .unwrap_err();
    assert_eq!(
        error.message,
        "Class NotAbstract declares abstract method directAbstract() and must therefore be declared abstract"
    );
}

