#[test]
fn compile_autoload_variance_class_order_to_native_binary() {
    let cases = [
        (
            "autoload-variance-outstanding-dependency",
            r#"<?php
spl_autoload_register(function ($class) {
    if ($class == 'A') {
        class A {
            function m(): B {}
        }
    } elseif ($class == 'B') {
        class B extends A {
            function m(): X {}
        }
    } else {
        class C extends B {}
    }
});

new B;
"#,
            "",
            "Could not check compatibility between B::m(): X and A::m(): B, because class X is not available",
            "Class \"B\" not found",
        ),
        (
            "autoload-variance-no-extra-candidate",
            r#"<?php
spl_autoload_register(function ($class) {
    if ($class == 'A') {
        class A {
            function m(): B {}
            function m2(): B {}
        }
        var_dump(new A);
    } elseif ($class == 'B') {
        class B extends A {
            function m(): X {}
            function m2(): Y {}
        }
        var_dump(new B);
    } elseif ($class == 'X') {
        class X extends B {}
        var_dump(new X);
    } else {
        class Y extends A {}
        var_dump(new Y);
    }
});

new B;
"#,
            "object(A)#",
            "Declaration of B::m2(): Y must be compatible with A::m2(): B",
            "object(X)#",
        ),
        (
            "autoload-variance-current-class-target-no-compatible-candidate-autoload",
            r#"<?php
spl_autoload_register(function ($class) {
    if ($class == 'A') {
        class A
        {
            function m(): B {}
            function m2(): B {}
        }
        var_dump(new A);
    } elseif ($class == 'B') {
        class B extends A
        {
            function m(): X {}
            function m2(): Y {}
        }
        var_dump(new B);
    } elseif ($class == 'X') {
        class X extends A {}
        var_dump(new X);
    } else {
        class Y extends B {}
        var_dump(new Y);
    }
});

new B;
"#,
            "object(X)#",
            "Declaration of B::m(): X must be compatible with A::m(): B",
            "object(Y)#",
        ),
        (
            "autoload-variance-current-class-candidate-fatal",
            r#"<?php
spl_autoload_register(function($class) {
    if ($class === 'A') {
        class A {
            public function method() : C {}
        }
    } else if ($class == 'B') {
        class B extends A {
            public function method() : B {}
        }
    } else {
        class C extends B {
        }
    }
});

$b = new B;
"#,
            "",
            "Declaration of B::method(): B must be compatible with A::method(): C",
            "Class \"C\" not found",
        ),
        (
            "autoload-variance-linking-candidate-fatal-before-parent",
            r#"<?php
interface I {}
spl_autoload_register(function() {
    class X {
        function test(): I {}
    }
    class Y extends X {
        function test(): C {}
    }
});
class C extends Z implements C {}
"#,
            "",
            "Declaration of Y::test(): C must be compatible with X::test(): I",
            "Class \"Z\" not found",
        ),
        (
            "autoload-variance-loading-exception-parent",
            r#"<?php
spl_autoload_register(function($class) {
    throw new Exception("Class $class does not exist");
});

for ($i = 0; $i < 2; $i++) {
    try {
        class B extends A {}
    } catch (Exception $e) {
        echo $e->getMessage(), "\n";
    }
}

interface I {}

spl_autoload_register(function($class) {
    class X {
        public function test(): I {}
    }
    class Y extends X {
        public function test(): B {}
    }
}, true, true);

try {
    class B extends A implements I {}
} catch (Exception $e) {
    echo $e->getMessage(), "\n";
}
"#,
            "Class A does not exist\nClass A does not exist",
            "During inheritance of B with variance dependencies: Uncaught Exception: Class A does not exist",
            "Declaration of Y::test(): B must be compatible with X::test(): I",
        ),
        (
            "autoload-variance-loading-exception-interface",
            r#"<?php
spl_autoload_register(function($class) {
    throw new Exception("Class $class does not exist");
});

class A {}

for ($i = 0; $i < 2; $i++) {
    try {
        class B extends A implements I {}
    } catch (Exception $e) {
        echo $e->getMessage(), "\n";
    }
}

interface J {}

spl_autoload_register(function($class) {
    class X {
        public function test(): J {}
    }
    class Y extends X {
        public function test(): B {}
    }
}, true, true);

try {
    class B extends A implements I, J {}
} catch (Exception $e) {
    echo $e->getMessage(), "\n";
}
"#,
            "Class I does not exist\nClass I does not exist",
            "During inheritance of B with variance dependencies: Uncaught Exception: Class I does not exist",
            "Declaration of Y::test(): B must be compatible with X::test(): J",
        ),
    ];

    for (name, source, required_stdout, required_stderr, forbidden_output) in cases {
        let root_name = format!("ptn-native-{name}");
        let root = temp_dir(&root_name);
        fs::create_dir_all(&root).unwrap();
        let input = root.join(format!("{name}.php"));
        let output = root.join(format!("{name}-bin"));
        fs::write(&input, source).unwrap();

        compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

        let execution = Command::new(&output).output().unwrap();
        assert!(!execution.status.success(), "{name}");
        assert_eq!(execution.status.code(), Some(255), "{name}");

        let stdout = String::from_utf8(execution.stdout).unwrap();
        let stderr = String::from_utf8(execution.stderr).unwrap();
        assert!(stdout.contains(required_stdout), "{name}: {stdout}");
        assert!(stderr.contains(required_stderr), "{name}: {stderr}");
        assert!(
            !stdout.contains(forbidden_output) && !stderr.contains(forbidden_output),
            "{name}: stdout={stdout} stderr={stderr}"
        );
        if name == "autoload-variance-no-extra-candidate" {
            assert!(stdout.contains("object(Y)#"), "{stdout}");
        }
        if name.starts_with("autoload-variance-loading-exception-") {
            assert!(
                stderr.contains(&format!("#0 {}(", input.display()))
                    && stderr.contains(": {closure:"),
                "{name}: {stderr}"
            );
            assert!(
                !stderr.contains("#0 [internal function]: {closure:"),
                "{name}: {stderr}"
            );
        }
    }
}

fn assert_ordered_contains(haystack: &str, needles: &[&str]) {
    let mut offset = 0;
    for needle in needles {
        let relative = haystack[offset..]
            .find(needle)
            .unwrap_or_else(|| panic!("missing {needle:?} after byte {offset} in {haystack:?}"));
        offset += relative + needle.len();
    }
}

