#[test]
fn parser_tracks_constructor_final_and_abstract_prototype_contracts() {
    let error = parser::parse(
        "<?php
abstract class A {
    abstract function __construct(X $x);
}
class B extends A {
    function __construct(X $x) {}
}
class C extends B {
    function __construct() {}
}",
    )
    .unwrap_err();
    assert_eq!(
        error.message,
        "Declaration of C::__construct() must be compatible with A::__construct(X $x)"
    );

    let error = parser::parse(
        "<?php
class Base {
    private final function __construct() {}
}
class Extended extends Base {
    public function __construct() {}
}",
    )
    .unwrap_err();
    assert_eq!(
        error.message,
        "Cannot override final method Base::__construct()"
    );

    let error = parser::parse(
        "<?php
class MyPhpToken extends PhpToken {
    public function __construct() {}
}",
    )
    .unwrap_err();
    assert_eq!(
        error.message,
        "Cannot override final method PhpToken::__construct()"
    );

    let program = parser::parse(
        "<?php
class A {
    final private function hidden() {}
}
class B extends A {
    final private function hidden() {}
}",
    )
    .unwrap();
    assert_eq!(program.compile_warnings.len(), 2);
    assert!(program.compile_warnings.iter().all(|warning| {
        warning.kind == CompileWarningKind::Warning
            && warning.message
                == "Private methods cannot be final as they are never overridden by other classes"
    }));
}

#[test]
fn parser_allows_private_abstract_methods_in_traits_only() {
    parser::parse(
        "<?php
trait T {
    abstract private function method(self $x): self;
}
class C {
    use T;

    private function method(self $x): self {
        return $this;
    }
}",
    )
    .unwrap();

    let error = parser::parse(
        "<?php
class C {
    abstract private function method();
}",
    )
    .unwrap_err();
    assert_eq!(
        error.message,
        "Abstract function C::method() cannot be declared private"
    );
}

#[test]
fn parser_accepts_interface_declarations_and_implements_metadata() {
    let program = parser::parse(
        "<?php
interface Contract {
    public function run(): mixed;
}
abstract class Base {
    abstract protected function hidden();
}
class Worker extends Base implements Contract {
    public function run(): mixed { return 1; }
    protected function hidden() {}
}",
    )
    .unwrap();

    assert_eq!(program.classes.len(), 3);
    assert!(program.classes[0].is_interface);
    assert_eq!(program.classes[0].methods.len(), 1);
    assert!(program.classes[0].methods[0].is_abstract);
    assert!(program.classes[1].is_abstract);
    assert!(program.classes[1].methods[0].is_abstract);
    assert_eq!(program.classes[2].interfaces, vec!["Contract"]);
    assert!(!program.classes[2].is_abstract);
    assert_eq!(program.classes[2].methods.len(), 2);
}

