#[test]
fn compile_echo_program_to_native_binary() {
    let root = temp_dir("ptn-native-echo");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("hello.php");
    let output = root.join("hello-bin");
    fs::write(&input, "<?php echo \"Hello \", 42, \"\\n\";").unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();
    assert!(compiled.binary.exists());
    assert!(compiled.c_source.unwrap().exists());

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(String::from_utf8(execution.stdout).unwrap(), "Hello 42\n");
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_scalar_echo_keeps_direct_output_path_to_native_binary() {
    let root = temp_dir("ptn-native-scalar-echo-direct-output");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("scalar-echo.php");
    let output = root.join("scalar-echo-bin");
    fs::write(
        &input,
        "<?php $word = \"runtime\"; echo \"literal \", $word, \" \", 123, \" \", 1.25, \" \", true, false, null, \"\\n\";",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        "literal runtime 123 1.25 1\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    let echo_body = generated_c_static_function_body(
        &c_source,
        "static PTN_UNUSED void ptn_echo(PtnRuntime *runtime, PtnValue value, size_t line)",
    );
    assert!(!echo_body.contains("ptn_value_to_string"));
    assert!(!c_source.contains("ptn_internal_var_dump"));
    assert!(!c_source.contains("ptn_call_internal"));
    assert!(echo_body.contains("ptn_output_write"));
    assert!(echo_body.contains("case PTN_NULL:"));
    assert!(echo_body.contains("case PTN_BOOL:"));
    assert!(echo_body.contains("case PTN_INT:"));
    assert!(echo_body.contains("case PTN_FLOAT:"));
    assert!(echo_body.contains("case PTN_STRING:"));
}

#[test]
fn compile_dynamic_precision_ini_formats_scalars_to_native_binary() {
    let root = temp_dir("ptn-native-dynamic-precision-formatting");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("dynamic-precision-formatting.php");
    let output = root.join("dynamic-precision-formatting-bin");
    fs::write(
        &input,
        r#"<?php
$v = array(123456789.012345678901234567890, 10/3, 987e100, 10.0000001);
ini_set('precision', 9);
ini_set('serialize_precision', 17);
echo ini_get('precision'), '/', ini_get('serialize_precision'), "\n";
echo join(' ', $v), "\n";
echo serialize($v), "\n";
echo var_export($v, true), "\n";
ini_set('precision', 100);
ini_set('serialize_precision', 0);
echo join(' ', array(3.0, 123456789.0)), "\n";
echo serialize(array(3.0, 123456789.0)), "\n";
echo var_export(array(3.0, 123456789.0), true), "\n";
"#,
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        "9/17\n\
123456789 3.33333333 9.87E+102 10.0000001\n\
a:4:{i:0;d:123456789.01234567;i:1;d:3.3333333333333335;i:2;d:9.8700000000000007E+102;i:3;d:10.000000099999999;}\n\
array (\n  0 => 123456789.01234567,\n  1 => 3.3333333333333335,\n  2 => 9.8700000000000007E+102,\n  3 => 10.000000099999999,\n)\n\
3 123456789\n\
a:2:{i:0;d:3.0E+0;i:1;d:1.0E+8;}\n\
array (\n  0 => 3.0,\n  1 => 1.0E+8,\n)\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

