#[test]
fn compile_object_to_string_conversion_to_native_binary() {
    let root = temp_dir("ptn-native-object-to-string-conversion");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("object-to-string-conversion.php");
    let output = root.join("object-to-string-conversion-bin");
    fs::write(
        &input,
        "<?php
class StringCapable {
    public function __toString() {
        return \"Hello, world\";
    }
}
class PlainObject {}
class ReturnsInt {
    public function __toString() {
        return 123;
    }
}
class ReturnsFalse {
    public function __toString() {
        return false;
    }
}
class ReturnsArray {
    public function __toString() {
        return [];
    }
}
class ReturnsNull {
    public function __toString() {
        return null;
    }
}
class ReturnsNone {
    public function __toString() {
    }
}
class ReturnedObject {}
class ReturnsObject {
    public function __toString() {
        return new ReturnedObject();
    }
}

$value = new StringCapable();
var_dump(strlen($value));
var_dump(strlen(\"$value\"));
echo $value, \"\\n\";
echo \"prefix:$value\\n\";
try {
    var_dump((string) new stdClass());
} catch (Error $e) {
    echo $e->getMessage(), \"\\n\";
}
try {
    var_dump((string) new PlainObject());
} catch (Error $e) {
    echo $e->getMessage(), \"\\n\";
}
echo (string) new ReturnsInt(), \"\\n\";
echo \"[\", (string) new ReturnsFalse(), \"]\\n\";
foreach ([new ReturnsArray(), new ReturnsNull(), new ReturnsNone(), new ReturnsObject()] as $bad) {
    try {
        echo (string) $bad;
    } catch (TypeError $e) {
        echo $e->getMessage(), \"\\n\";
    }
}
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "int(12)\n",
            "int(12)\n",
            "Hello, world\n",
            "prefix:Hello, world\n",
            "Object of class stdClass could not be converted to string\n",
            "Object of class PlainObject could not be converted to string\n",
            "123\n",
            "[]\n",
            "ReturnsArray::__toString(): Return value must be of type string, array returned\n",
            "ReturnsNull::__toString(): Return value must be of type string, null returned\n",
            "ReturnsNone::__toString(): Return value must be of type string, none returned\n",
            "ReturnsObject::__toString(): Return value must be of type string, ReturnedObject returned\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("runtime.method_dispatch = ptn_call_declared_method;"));
    assert!(c_source.contains("ptn_value_to_string_operand_with_runtime"));
}

