#[test]
fn compile_weak_map_to_native_binary() {
    let root = temp_dir("ptn-native-weak-map");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("weak-map.php");
    let output = root.join("weak-map-bin");
    fs::write(
        &input,
        "<?php
$a = (object)['name' => 'a'];
$b = (object)['name' => 'b'];
$map = new WeakMap;
$map[$a] = 1;
$map[$b] = 2;

var_dump(
    $map instanceof WeakMap,
    $map instanceof ArrayAccess,
    $map instanceof Countable,
    $map instanceof Iterator,
    count($map),
    isset($map[$a]),
    $map[$a]
);

foreach ($map as $key => $value) {
    echo $key->name, '=', $value, \"\\n\";
}
unset($key);

foreach ($map as &$value) {
    $value += 10;
}
unset($value);

var_dump($map[$a], $map->offsetGet($b));
$clone = clone $map;
unset($a);
gc_collect_cycles();
var_dump(count($map), count($clone), isset($map[$b]));
unset($b);
gc_collect_cycles();
var_dump(count($map), count($clone));
",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "int(2)\n",
            "bool(true)\n",
            "int(1)\n",
            "a=1\n",
            "b=2\n",
            "int(11)\n",
            "int(12)\n",
            "int(1)\n",
            "int(1)\n",
            "bool(true)\n",
            "int(0)\n",
            "int(0)\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

