#[test]
fn compile_array_object_invalid_offset_diagnostics_to_native_binary() {
    let root = temp_dir("ptn-native-array-object-invalid-offset");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("array-object-invalid-offset.php");
    let output = root.join("array-object-invalid-offset-bin");
    fs::write(
        &input,
        r#"<?php
$arrayObject = new ArrayObject([1, 2, 3]);
try {
    var_dump($arrayObject[[]]);
} catch (TypeError $e) {
    echo $e->getMessage(), "\n";
}
try {
    $arrayObject[[]] = new stdClass;
} catch (TypeError $e) {
    echo $e->getMessage(), "\n";
}
try {
    $ref =& $arrayObject[[]];
} catch (TypeError $e) {
    echo $e->getMessage(), "\n";
}
try {
    var_dump(isset($arrayObject[[]]));
} catch (TypeError $e) {
    echo $e->getMessage(), "\n";
}
try {
    unset($arrayObject[[]]);
} catch (TypeError $e) {
    echo $e->getMessage(), "\n";
}
try {
    $arrayObject[[]] += 1;
} catch (TypeError $e) {
    echo $e->getMessage(), "\n";
}

$nullKey = null;
$arrayObject[$nullKey] += 20;
var_dump($arrayObject);
"#,
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    let stdout = String::from_utf8(execution.stdout).unwrap();
    let input_path = input.display().to_string();
    assert_eq!(
        stdout,
        format!(
            concat!(
                "Cannot access offset of type array on ArrayObject\n",
                "Cannot access offset of type array on ArrayObject\n",
                "Cannot access offset of type array on ArrayObject\n",
                "Cannot access offset of type array in isset or empty\n",
                "Cannot unset offset of type array on ArrayObject\n",
                "Cannot access offset of type array on ArrayObject\n",
                "\n",
                "Deprecated: Using null as an array offset is deprecated, use an empty string instead in {} on line 35\n",
                "\n",
                "Warning: Undefined array key \"\" in {} on line 35\n",
                "object(ArrayObject)#1 (1) {{\n",
                "  [\"storage\":\"ArrayObject\":private]=>\n",
                "  array(4) {{\n",
                "    [0]=>\n",
                "    int(1)\n",
                "    [1]=>\n",
                "    int(2)\n",
                "    [2]=>\n",
                "    int(3)\n",
                "    [3]=>\n",
                "    int(20)\n",
                "  }}\n",
                "}}\n",
            ),
            input_path,
            input_path
        )
    );
    assert_eq!(
        stdout
            .matches("Using null as an array offset is deprecated")
            .count(),
        1,
        "{stdout}"
    );
    assert_eq!(
        stdout
            .matches("Cannot access offset of type array on ArrayObject")
            .count(),
        4,
        "{stdout}"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_array_object_offset_get_only_isset_uses_storage_to_native_binary() {
    let root = temp_dir("ptn-native-array-object-offset-get-only-isset");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("array-object-offset-get-only-isset.php");
    let output = root.join("array-object-offset-get-only-isset-bin");
    fs::write(
        &input,
        r#"<?php
class OffsetGetOnly extends ArrayObject
{
    public function offsetGet($offset): mixed
    {
        echo "get:", $offset, "\n";
        return parent::offsetGet($offset);
    }
}

class OffsetGetSet extends ArrayObject
{
    public function offsetGet($offset): mixed
    {
        echo "get-set:", $offset, "\n";
        return parent::offsetGet(str_rot13($offset));
    }

    public function offsetSet($offset, $value): void
    {
        parent::offsetSet(str_rot13($offset), $value);
    }
}

$object = new OffsetGetOnly(['foo' => '', 'bar' => null, 'baz' => 42]);
var_dump($object->offsetExists('foo'), isset($object['foo']), empty($object['foo']));
var_dump($object->offsetExists('bar'), isset($object['bar']), empty($object['bar']));
var_dump($object->offsetExists('baz'), isset($object['baz']), empty($object['baz']));
var_dump($object->offsetExists('qux'), isset($object['qux']), empty($object['qux']));

$mapped = new OffsetGetSet();
$mapped['foo'] = 42;
var_dump(
    $mapped->offsetExists('foo'),
    $mapped->offsetExists('sbb'),
    isset($mapped['foo']),
    isset($mapped['sbb'])
);
"#,
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "get:foo\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "get:bar\n",
            "bool(true)\n",
            "bool(false)\n",
            "bool(true)\n",
            "get:baz\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(false)\n",
            "bool(false)\n",
            "bool(false)\n",
            "bool(true)\n",
            "bool(false)\n",
            "bool(true)\n",
            "bool(false)\n",
            "bool(true)\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_internal_array_object_offset_isset_quiet"));
}

