#[test]
fn compile_generator_abort_through_nested_finally_to_native_binary() {
    let root = temp_dir("ptn-native-generator-abort-nested-finally");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("generator-abort-nested-finally.php");
    let output = root.join("generator-abort-nested-finally-bin");
    fs::write(
        &input,
        r#"<?php
function gen_one() {
    try {
        try {
            yield;
        } finally {
            print "INNER\n";
        }
    } catch (Exception $e) {
        print "EX\n";
    } finally {
        print "OUTER\n";
    }
    print "NOTREACHED\n";
}

function gen_cleanup() {
    try {
        throw new Exception("suppressed");
    } finally {
        yield;
    }
}

function gen_two() {
    try {
        throw new Exception(1);
    } finally {
        try {
            throw new Exception(2);
        } finally {
            try {
                yield;
            } finally {
            }
        }
    }
}

function gen_three() {
    try {
        throw new Exception(1);
    } finally {
        try {
            yield;
        } finally {
            try {
                throw new Exception(2);
            } finally {
            }
        }
    }
}

gen_one()->current();
echo "--\n";
gen_cleanup()->rewind();
echo "cleanup\n";
echo "--\n";
try {
    gen_two()->rewind();
} catch (Exception $e) {
    echo $e, "\n";
}
echo "--\n";
try {
    gen_three()->rewind();
} catch (Exception $e) {
    echo $e, "\n";
}
"#,
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    let stdout = String::from_utf8(execution.stdout).unwrap();
    let path = input.display().to_string();
    assert!(!stdout.contains("NOTREACHED"));
    assert!(stdout.starts_with("INNER\nOUTER\n--\ncleanup\n--\n"));
    assert!(!stdout.contains("suppressed"));
    assert!(stdout.contains("Exception: 1 in "));
    assert!(stdout.contains("\n\nNext Exception: 2 in "));
    assert!(stdout.contains("Stack trace:\n#0 [internal function]: gen_two()\n#1 "));
    assert!(stdout.contains(": Generator->rewind()\n#2 {main}\n\nNext Exception: 2"));
    let gen_two_section = stdout.split("--\n").nth(2).expect("gen_two output section");
    assert!(
        gen_two_section.contains("\nNext Exception: 2 in ")
            && gen_two_section.contains("Stack trace:\n#0 [internal function]: gen_two()\n#1 "),
        "{stdout}"
    );
    assert!(stdout.contains("Stack trace:\n#0 [internal function]: gen_three()\n#1 "));
    assert!(stdout.contains(&format!("#0 {path}(")));
    assert!(stdout.contains(": gen_three()\n#1 {main}\n"));
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_generator_yield_from_exception_releases_protocol_iterator_to_native_binary() {
    let root = temp_dir("ptn-native-generator-yield-from-exception-release");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("generator-yield-from-exception-release.php");
    let output = root.join("generator-yield-from-exception-release-bin");
    fs::write(
        &input,
        r#"<?php
class FooBar implements Iterator {
    function __construct()   { echo "Constructing new FooBar\n"; }
    function __destruct()    { echo "Destructing FooBar\n"; }
    function current(): mixed { throw new Exception; }
    function key(): int { return 0; }
    function next(): void {}
    function rewind(): void {}
    function valid(): bool { return true; }
}

function foo() {
    try {
        $f = new FooBar;
        yield from $f;
    } catch (Exception $e) {
        echo "[foo()] Caught Exception\n";
    }
}

function bar() {
    echo "Starting bar()\n";
    $x = foo();
    var_dump($x->current());
    echo "Unsetting \$x\n";
    unset($x);
    echo "Finishing bar()\n";
}

bar();
"#,
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        "Starting bar()\nConstructing new FooBar\n[foo()] Caught Exception\nDestructing FooBar\nNULL\nUnsetting $x\nFinishing bar()\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_by_reference_generator_foreach_to_native_binary() {
    let root = temp_dir("ptn-native-generator-by-ref-foreach");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("generator-by-ref-foreach.php");
    let output = root.join("generator-by-ref-foreach-bin");
    fs::write(
        &input,
        r#"<?php
function &walk(array &$array) {
    foreach ($array as $key => &$value) {
        yield $key => $value;
    }
}
$persisted = [1, 2, 3];
$generator = walk($persisted);
foreach ($generator as &$value) {
    $value *= -1;
}
var_dump($persisted);

$items = [1, 2];
foreach (walk($items) as &$value) {
    $value *= -1;
}
var_dump($items);

function gen_non_ref() {
    yield 1;
}
try {
    foreach (gen_non_ref() as &$value) {}
} catch (Exception $e) {
    echo $e->getMessage(), "\n";
}

function &notice_gen() {
    yield $v = 0;
    yield $v = 1;
}
foreach (notice_gen() as $v) {
    var_dump($v);
}
"#,
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        "array(3) {\n  [0]=>\n  int(-1)\n  [1]=>\n  int(-2)\n  [2]=>\n  &int(-3)\n}\narray(2) {\n  [0]=>\n  int(-1)\n  [1]=>\n  &int(-2)\n}\nYou can only iterate a generator by-reference if it declared that it yields by-reference\n\nNotice: Only variable references should be yielded by reference in ptn on line 30\nint(0)\n\nNotice: Only variable references should be yielded by reference in ptn on line 31\nint(1)\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

