#[test]
fn compile_string_token_compare_and_similarity_helpers_to_native_binary() {
    let root = temp_dir("ptn-native-string-token-compare-similarity");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("string-token-compare-similarity.php");
    let output = root.join("string-token-compare-similarity-bin");
    fs::write(
        &input,
        "<?php\n\
$string = \"This testcase test strtok() function.\";\n\
$token = \" ().\";\n\
var_dump(strtok($string, $token));\n\
for ($i = 0; $i < 5; $i++) { var_dump(strtok($token)); }\n\
function ptn_next_token($token) { return strtok($token); }\n\
var_dump(strtok(\"a,b,c\", \",\"));\n\
var_dump(ptn_next_token(\",\"));\n\
var_dump(substr_compare(\"abcde\", \"df\", -2) < 0);\n\
var_dump(substr_compare(\"abcde\", \"bcg\", 1, 2));\n\
var_dump(substr_compare(\"abcde\", \"BC\", 1, 2, true));\n\
var_dump(substr_compare(\"abcde\", \"abcdef\", -10, 10) < 0);\n\
var_dump(substr_compare(\"Hello,\" . chr(0) . \"world\", \"Hello,world\", 0, 12, true));\n\
try { substr_compare(\"abcde\", \"abc\", 0, -1); } catch (\\ValueError $e) { echo $e->getMessage(), \"\\n\"; }\n\
try { substr_compare(\"abcde\", \"abc\", 99); } catch (\\ValueError $e) { echo $e->getMessage(), \"\\n\"; }\n\
$percent = 0;\n\
var_dump(similar_text(\"abcdefgh\", \"efg\", $percent));\n\
var_dump($percent);\n\
var_dump(function_exists(\"strtok\"), function_exists(\"SUBSTR_COMPARE\"), function_exists(\"similar_text\"));",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        "string(4) \"This\"\n\
string(8) \"testcase\"\n\
string(4) \"test\"\n\
string(6) \"strtok\"\n\
string(8) \"function\"\n\
bool(false)\n\
string(1) \"a\"\n\
string(1) \"b\"\n\
bool(true)\n\
int(0)\n\
int(0)\n\
bool(true)\n\
int(-119)\n\
substr_compare(): Argument #4 ($length) must be greater than or equal to 0\n\
substr_compare(): Argument #3 ($offset) must be contained in argument #1 ($haystack)\n\
int(3)\n\
float(54.54545454545455)\n\
bool(true)\n\
bool(true)\n\
bool(true)\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_trim_ltrim_rtrim_phpt_shapes_to_native_binary() {
    let root = temp_dir("ptn-native-trim-ltrim-rtrim-phpt-shapes");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("trim-ltrim-rtrim.php");
    let output = root.join("trim-ltrim-rtrim-bin");
    fs::write(
        &input,
        "<?php\n\
echo \"*** Testing trim/ltrim/rtrim() : basic functionality ***\\n\";\n\
$text = \"  \\t\\r\\n\\0\\x0B  ---These are a few words---  \\t\\r\\n\\0\\x0B  \";\n\
$left = \" \\t\\r\\n\\0\\x0B ---These are a few words---  \";\n\
$right = \"---These are a few words---  \\t\\r\\n\\0\\x0B  \";\n\
$hello = \"!===Hello World===!\";\n\
$alpha_left = \"ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789\";\n\
$alpha_right = \"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ\";\n\
\n\
var_dump(trim($text));\n\
var_dump(ltrim($left));\n\
var_dump(rtrim($right));\n\
var_dump(trim($hello, \"=!\"));\n\
var_dump(ltrim($hello, \"!oleH=\"));\n\
var_dump(rtrim($hello, \"!dlWro=\"));\n\
var_dump(ltrim($alpha_left, \"A..Z\"));\n\
var_dump(rtrim($alpha_right, \"A..Z\"));\n\
var_dump(\"ABC\\x50\\xC1\" === trim(\"ABC\\x50\\xC1\\x60\\x90\", \"\\x51..\\xC0\"));\n\
var_dump(\"ABC\" === trim(\"ABC\\x50\\xC1\\x60\\x90\", \"\\x50..\\xC1\"));\n\
var_dump(\" \\0\\t\\nABC \\0\\t\\n\" === trim(\" \\0\\t\\nABC \\0\\t\\n\", \"\"));\n\
var_dump(\"ABC\" === trim(\"\\fABC\\f\"));\n\
var_dump(\"ABC\" === ltrim(\"\\fABC\"));\n\
var_dump(\"ABC\" === rtrim(\"ABC\\f\"));\n\
var_dump(function_exists(\"trim\"), function_exists(\"LTRIM\"), function_exists(\"rtrim\"));\n",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        "*** Testing trim/ltrim/rtrim() : basic functionality ***\n\
string(27) \"---These are a few words---\"\n\
string(29) \"---These are a few words---  \"\n\
string(27) \"---These are a few words---\"\n\
string(11) \"Hello World\"\n\
string(10) \" World===!\"\n\
string(10) \"!===Hello \"\n\
string(10) \"0123456789\"\n\
string(10) \"0123456789\"\n\
bool(true)\n\
bool(true)\n\
bool(true)\n\
bool(true)\n\
bool(true)\n\
bool(true)\n\
bool(true)\n\
bool(true)\n\
bool(true)\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

