#[test]
fn compile_date_interval_and_period_malformed_string_exceptions_to_native_binary() {
    let root = temp_dir("ptn-native-date-interval-period-malformed-exceptions");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("date-interval-period-malformed-exceptions.php");
    let output = root.join("date-interval-period-malformed-exceptions-bin");
    fs::write(
        &input,
        "<?php\n\
try {\n\
    new DateInterval('P3\"D');\n\
} catch (Exception $e) {\n\
    echo get_class($e), ': ', $e->getMessage(), \"\\n\";\n\
}\n\
try {\n\
    DatePeriod::createFromISO8601String('P3\"D');\n\
} catch (Exception $e) {\n\
    echo get_class($e), ': ', $e->getMessage(), \"\\n\";\n\
}\n\
try {\n\
    DatePeriod::createFromISO8601String('2008-03-01T12:00:00Z1');\n\
} catch (Exception $e) {\n\
    echo get_class($e), ': ', $e->getMessage(), \"\\n\";\n\
}\n",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "DateMalformedIntervalStringException: Unknown or bad format (P3\"D)\n",
            "DateMalformedPeriodStringException: Unknown or bad format (P3\"D)\n",
            "DateMalformedPeriodStringException: Unknown or bad format (2008-03-01T12:00:00Z1)\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_incomplete_datetime_comparison_errors_to_native_binary() {
    let root = temp_dir("ptn-native-incomplete-datetime-comparison");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("incomplete-datetime-comparison.php");
    let output = root.join("incomplete-datetime-comparison-bin");
    fs::write(
        &input,
        "<?php\n\
class MyDateTime extends DateTime { public function __construct() {} }\n\
$dt = new DateTime('2023-01-16 17:09:08');\n\
$dti = new DateTimeImmutable('2023-01-16 17:09:08');\n\
$bad = new MyDateTime();\n\
var_dump($dt < $dti);\n\
foreach ([[$dt, $bad], [$bad, $dt], [$dti, $bad], [$bad, $dti]] as $pair) {\n\
    try {\n\
        var_dump($pair[0] < $pair[1]);\n\
    } catch (DateObjectError $e) {\n\
        echo $e::class, ': ', $e->getMessage(), \"\\n\";\n\
    }\n\
}\n",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "bool(false)\n",
            "DateObjectError: Trying to compare an incomplete DateTime or DateTimeImmutable object\n",
            "DateObjectError: Trying to compare an incomplete DateTime or DateTimeImmutable object\n",
            "DateObjectError: Trying to compare an incomplete DateTime or DateTimeImmutable object\n",
            "DateObjectError: Trying to compare an incomplete DateTime or DateTimeImmutable object\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_dateinterval_comparison_warnings_to_native_binary() {
    let root = temp_dir("ptn-native-dateinterval-comparison-warnings");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("dateinterval-comparison-warnings.php");
    let output = root.join("dateinterval-comparison-warnings-bin");
    fs::write(
        &input,
        "<?php\n\
$i1 = new DateInterval('P1D');\n\
$i2 = new DateInterval('PT1H');\n\
var_dump($i1 == $i2);\n\
var_dump($i1 < $i2);\n\
var_dump($i1 > $i2);\n",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    let stdout = String::from_utf8(execution.stdout).unwrap();
    assert_eq!(
        stdout
            .matches("Cannot compare DateInterval objects")
            .count(),
        3
    );
    assert_eq!(stdout.matches("bool(false)").count(), 3);
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_date_diff_function_to_native_binary() {
    let root = temp_dir("ptn-native-date-diff-function");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("date-diff-function.php");
    let output = root.join("date-diff-function-bin");
    fs::write(
        &input,
        "<?php
date_default_timezone_set('UTC');
$dt1 = new DateTime('2010-10-20');
$dti1 = new DateTimeImmutable('2010-10-25');
$dti2 = new DateTimeImmutable('2010-10-28');

$diff1 = $dt1->diff($dti1);
echo $diff1->y, ' ', $diff1->m, ' ', $diff1->d, ' ',
     $diff1->h, ' ', $diff1->i, ' ', $diff1->s, \"\\n\";

$diff2 = $dti1->diff($dti2);
echo $diff2->y, ' ', $diff2->m, ' ', $diff2->d, ' ',
     $diff2->h, ' ', $diff2->i, ' ', $diff2->s, \"\\n\";

$diff3 = date_diff($dt1, $dti2);
echo $diff3->y, ' ', $diff3->m, ' ', $diff3->d, ' ',
     $diff3->h, ' ', $diff3->i, ' ', $diff3->s, \"\\n\";

date_default_timezone_set('Europe/London');
$london1 = new DateTime('2010-10-20');
$london2 = new DateTimeImmutable('2010-10-25');
$london3 = new DateTimeImmutable('2010-10-28');
echo $london1->diff($london2)->format('%y %m %d %h %i %s'), \"\\n\";
echo $london2->diff($london3)->format('%y %m %d %h %i %s'), \"\\n\";
echo date_diff($london1, $london3)->format('%y %m %d %h %i %s'), \"\\n\";

date_default_timezone_set('Europe/Berlin');
$berlinStart = date_create('2012-06-01');
$berlinEnd = date_create('2012-12-01');
echo date_diff($berlinStart, $berlinEnd)->format('%mM / %dD %hH %iM'), \"\\n\";

date_default_timezone_set('Asia/Tehran');
$tehran1 = new DateTime('2019-09-24 11:47:24');
$tehran2 = new DateTime('2019-08-21 12:47:24');
$tehranDiff = $tehran1->diff($tehran2);
echo $tehranDiff->y, ' ', $tehranDiff->m, ' ', $tehranDiff->d, ' ',
     $tehranDiff->h, ' ', $tehranDiff->i, ' ', $tehranDiff->s, ' ',
     $tehranDiff->invert, ' ', $tehranDiff->days, \"\\n\";

$chicagoStart = new DateTimeImmutable(
    '2000-11-01 09:29:22.907606',
    new DateTimeZone('America/Chicago')
);
$newYorkEnd = new DateTimeImmutable(
    '2022-06-06 11:00:00.000000',
    new DateTimeZone('America/New_York')
);
$cityDiff = $chicagoStart->diff($newYorkEnd);
var_dump($cityDiff->y);
echo $cityDiff->format('%R %Y %M %D (%a) %H %I %S %F'), \"\\n\";

$sydney = new DateTime('2000-01-01 00:00:00.000000', new DateTimeZone('Australia/Sydney'));
$losAngeles = new DateTime('2000-01-01 00:00:00.000000', new DateTimeZone('America/Los_Angeles'));
echo $sydney->diff($losAngeles)->h, \"\\n\";
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        "0 0 5 0 0 0\n\
0 0 3 0 0 0\n\
0 0 8 0 0 0\n\
0 0 5 0 0 0\n\
0 0 3 0 0 0\n\
0 0 8 0 0 0\n\
6M / 0D 0H 0M\n\
0 1 2 23 0 0 1 33\n\
int(21)\n\
+ 21 07 04 (7886) 23 30 37 092394\n\
19\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("{ \"date_diff\", 2, 3, ptn_internal_date_diff }"));
}

#[test]
fn compile_timelib_timestamp_and_negative_year_rows_to_native_binary() {
    let root = temp_dir("ptn-native-timelib-timestamp-negative-year-rows");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("timelib-timestamp-negative-year-rows.php");
    let output = root.join("timelib-timestamp-negative-year-rows-bin");
    fs::write(
        &input,
        r#"<?php
date_default_timezone_set('UTC');
echo date('Y-m-d o-W-N', -62167046400 - (((99 * 365) + 25) * 86400) + (6 * 86400)), "\n";

date_default_timezone_set('Europe/London');
$empty = new DateTime('');
echo $empty->getTimezone()->getName(), "\n";

$m = new DateTime('2022-12-20 14:30:25', new DateTimeZone('Europe/Paris'));
$m->modify('@1234567890');
var_dump($m->getTimestamp());
echo $m->format(DateTime::ATOM), "\n";

$a = new DateTime('2022-11-01 13:30:00', new DateTimeZone('America/Lima'));
echo $a->format(DateTime::ATOM), "\n";
$a->modify('@' . $a->getTimestamp());
echo $a->format(DateTime::ATOM), "\n";
"#,
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        "-0099-01-08 -99-02-2\n\
Europe/London\n\
int(1234567890)\n\
2009-02-13T23:31:30+00:00\n\
2022-11-01T13:30:00-05:00\n\
2022-11-01T18:30:00+00:00\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("{ \"date\", 1, 2, ptn_internal_date }"));
    assert!(c_source.contains("static PTN_UNUSED PtnValue ptn_datetime_new("));
}

#[test]
fn compile_conditional_datetimeinterface_implementation_fatals_to_native_binary() {
    let root = temp_dir("ptn-native-conditional-datetimeinterface-fatal");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("conditional-datetimeinterface-fatal.php");
    let output = root.join("conditional-datetimeinterface-fatal-bin");
    fs::write(
        &input,
        "<?php
echo \"before\\n\";
if (true) {
    class cdt1 extends DateTime implements DateTimeInterface {}
}
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(!execution.status.success());
    assert_eq!(String::from_utf8(execution.stdout).unwrap(), "before\n");
    assert_eq!(
        String::from_utf8(execution.stderr).unwrap(),
        format!(
            "\nFatal error: DateTimeInterface can't be implemented by user classes in {} on line 4\n",
            input.display()
        )
    );

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("DateTimeInterface can't be implemented by user classes"));
}

#[test]
fn compile_date_object_aliases_and_round_trips_to_native_binary() {
    let root = temp_dir("ptn-native-date-object-aliases-round-trips");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("date-object-aliases-round-trips.php");
    let output = root.join("date-object-aliases-round-trips-bin");
    fs::write(
        &input,
        r#"<?php
date_default_timezone_set('UTC');

$mutable = date_create('2020-01-02 03:04:05');
echo date_format($mutable, 'Y-m-d H:i:s T e'), "\n";
date_modify($mutable, '+2 day');
echo $mutable->format('Y-m-d'), "\n";

$interval = new DateInterval('P1DT2H3M4S');
date_add($mutable, $interval);
echo date_format($mutable, 'Y-m-d H:i:s'), "\n";
date_sub($mutable, new DateInterval('PT4S'));
echo $mutable->format('Y-m-d H:i:s'), "\n";
echo date_interval_format($interval, '%D %H:%I:%S'), "\n";

$immutable = date_create_immutable('2020-01-01 00:00:00');
$next = $immutable->add(new DateInterval('P1D'));
echo $immutable->format('Y-m-d'), '/', $next->format('Y-m-d'), "\n";

$fromMutable = DateTimeImmutable::createFromMutable($mutable);
$fromImmutable = DateTime::createFromImmutable($fromMutable);
var_dump($fromMutable instanceof DateTimeImmutable, $fromImmutable instanceof DateTime);

$payload = serialize($mutable);
$roundTrip = unserialize($payload);
echo $roundTrip->format('Y-m-d H:i:s T e'), "\n";

$tz = new DateTimeZone('Europe/Berlin');
$tzRoundTrip = unserialize(serialize($tz));
$tzPayload = $tzRoundTrip->__serialize();
var_dump($tzRoundTrip->getName(), $tzPayload['timezone']);
"#,
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "2020-01-02 03:04:05 UTC UTC\n",
            "2020-01-04\n",
            "2020-01-05 05:07:09\n",
            "2020-01-05 05:07:05\n",
            "01 02:03:04\n",
            "2020-01-01/2020-01-02\n",
            "bool(true)\n",
            "bool(true)\n",
            "2020-01-05 05:07:05 UTC UTC\n",
            "string(13) \"Europe/Berlin\"\n",
            "string(13) \"Europe/Berlin\"\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_internal_date_create_immutable"));
    assert!(c_source.contains("ptn_internal_date_interval_format"));
    assert!(c_source.contains("createFromMutable"));
}

#[test]
fn compile_datetime_timestamp_microseconds_and_offsets_to_native_binary() {
    let root = temp_dir("ptn-native-datetime-timestamp-microseconds-offsets");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("datetime-timestamp-microseconds-offsets.php");
    let output = root.join("datetime-timestamp-microseconds-offsets-bin");
    fs::write(
        &input,
        r#"<?php
date_default_timezone_set('UTC');

$at = new DateTime('@1217184864');
echo $at->format('Y-m-d H:i:s.u e p'), "\n";

$factory = DateTimeImmutable::createFromTimestamp(0.123456);
echo $factory->format('U.u e p'), "\n";
class MyDateTime extends DateTime {}
echo get_class(MyDateTime::createFromTimestamp(0)), "\n";
class MyDateTimeImmutable extends DateTimeImmutable {}
echo get_class(MyDateTimeImmutable::createFromMutable(new DateTime('2020-01-01 00:00:00'))), "\n";
try {
    DateTime::createFromTimestamp(NAN);
} catch (Throwable $e) {
    echo get_class($e), "\n";
}

$clone = clone $at;
$clone->setTime(1, 2, 3, 456789);
echo $at->format('H:i:s.u'), '/', $clone->format('H:i:s.u'), "\n";

$immutable = new DateTimeImmutable('2020-03-10T12:13:14.987654Z');
$changed = $immutable->setTime(5, 6, 7, 890);
echo $immutable->format('H:i:s.u e p'), '/', $changed->format('H:i:s.u e p'), "\n";

$chicago = new DateTime('2020-03-10 12:00:00 America/Chicago');
echo date_offset_get($chicago), ' ', $chicago->format('T P p'), "\n";

date_default_timezone_set('America/Chicago');
$spring = new DateTime('2020-03-08 01:30:00');
echo $spring->setTime(2, 0)->format('Y-m-d H:i:s T/e - U'), "\n";
$spring = new DateTime('2020-03-08 01:30:00');
echo $spring->setTime(2, 30)->format('Y-m-d H:i:s T/e - U'), "\n";
$spring = new DateTime('2020-03-08 01:30:00');
echo $spring->setTime(3, 0)->format('Y-m-d H:i:s T/e - U'), "\n";
$spring = new DateTime('2020-03-08 01:30:00');
echo $spring->setTime(1, 59, 59)->format('Y-m-d H:i:s T/e - U'), "\n";
date_default_timezone_set('UTC');

echo gmdate('Y-m-d H:i:s', strtotime('1 Jul 06 14:27:30 +0200')), "\n";
$parsed = date_parse('2009-02-27 10:00:00.5');
echo $parsed['year'], ' ', $parsed['month'], ' ', $parsed['day'], ' ', $parsed['hour'], ' ', $parsed['fraction'], "\n";
var_dump(date_get_last_errors());

$set = new DateTime('2009-01-30 19:34:10', new DateTimeZone('Europe/London'));
date_date_set($set, 2008, 2, 1);
echo $set->format(DateTime::RFC2822), "\n";
date_isodate_set($set, 2009, 30, 3);
echo $set->format('D M j'), "\n";

echo date(DATE_ISO8601, strtotime('2006-1-6T0:0:0-8:0')), "\n";
$rfc = date_create('Sun, 22 May 1955 02:00:00 +0200');
echo $rfc->format(DATE_ISO8601), "\n";
echo $rfc->format('U e'), "\n";
$rfc->setTimeZone(new DateTimeZone('Europe/Budapest'));
echo $rfc->format(DATE_ISO8601), "\n";
echo $rfc->format('U e'), "\n";
echo DateTime::createFromFormat('Y-m-d|', '2011-02-02')->format('Y-m-d H:i:s e'), "\n";
echo DateTime::createFromFormat('Y-m-d!', '2011-02-02')->format('Y-m-d H:i:s e'), "\n";
$offsetCases = [['O', 'GMT+0800'], ['P', 'GMT-08:00'], ['[O]', '[+0800]']];
foreach ($offsetCases as $case) {
    $dt = DateTime::createFromFormat($case[0], $case[1]);
    echo $dt ? $dt->getOffset() : 'false', "\n";
}
var_dump(DateTime::createFromFormat('O', 'invalid'));
"#,
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "2008-07-27 18:54:24.000000 +00:00 +00:00\n",
            "0.123456 +00:00 +00:00\n",
            "MyDateTime\n",
            "MyDateTimeImmutable\n",
            "DateRangeError\n",
            "18:54:24.000000/01:02:03.456789\n",
            "12:13:14.987654 Z Z/05:06:07.000890 Z Z\n",
            "-18000 CDT -05:00 -05:00\n",
            "2020-03-08 03:00:00 CDT/America/Chicago - 1583654400\n",
            "2020-03-08 03:30:00 CDT/America/Chicago - 1583656200\n",
            "2020-03-08 03:00:00 CDT/America/Chicago - 1583654400\n",
            "2020-03-08 01:59:59 CST/America/Chicago - 1583654399\n",
            "2006-07-01 12:27:30\n",
            "2009 2 27 10 0.5\n",
            "bool(false)\n",
            "Fri, 01 Feb 2008 19:34:10 +0000\n",
            "Wed Jul 22\n",
            "2006-01-06T08:00:00+0000\n",
            "1955-05-22T02:00:00+0200\n",
            "-461203200 +02:00\n",
            "1955-05-22T01:00:00+0100\n",
            "-461203200 Europe/Budapest\n",
            "2011-02-02 00:00:00 UTC\n",
            "1970-01-01 00:00:00 UTC\n",
            "28800\n",
            "-28800\n",
            "28800\n",
            "bool(false)\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("createFromTimestamp"));
    assert!(c_source.contains("ptn_internal_date_offset_get"));
    assert!(c_source.contains("ptn_internal_strtotime"));
    assert!(c_source.contains("ptn_internal_date_parse"));
}

#[test]
fn compile_datetime_noon_and_fractional_interval_to_native_binary() {
    let root = temp_dir("ptn-native-datetime-noon-fractional-interval");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("datetime-noon-fractional-interval.php");
    let output = root.join("datetime-noon-fractional-interval-bin");
    fs::write(
        &input,
        "<?php\n\
date_default_timezone_set('UTC');\n\
echo date(DATE_ISO8601, strtotime('2005-12-22 noon')), \"\\n\";\n\
$dt = new DateTimeImmutable('2016-10-03 12:47:18.081921');\n\
echo $dt->modify('yesterday')->format('Y-m-d H:i:s.u'), \"\\n\";\n\
echo $dt->modify('noon')->format('Y-m-d H:i:s.u'), \"\\n\";\n\
echo $dt->modify('10 weekday')->format('Y-m-d H:i:s.u'), \"\\n\";\n\
$actual = new DateTimeImmutable('2022-07-21 15:00:10');\n\
$delta = new DateInterval('PT0S');\n\
$delta->f = -0.9;\n\
$lower = $actual->sub($delta);\n\
$upper = $actual->add($delta);\n\
echo $lower->format('H:i:s.u U'), \"\\n\";\n\
echo $upper->format('H:i:s.u U'), \"\\n\";\n\
var_dump($actual < $lower, $actual > $upper);\n",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "2005-12-22T12:00:00+0000\n",
            "2016-10-02 00:00:00.000000\n",
            "2016-10-03 12:00:00.000000\n",
            "2016-10-17 12:47:18.081921\n",
            "15:00:10.900000 1658415610\n",
            "15:00:09.100000 1658415609\n",
            "bool(true)\n",
            "bool(true)\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_datetime_tokyo_textual_clone_lifecycle_to_native_binary() {
    let root = temp_dir("ptn-native-datetime-tokyo-textual-clone");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("datetime-tokyo-textual-clone.php");
    let output = root.join("datetime-tokyo-textual-clone-bin");
    fs::write(
        &input,
        r#"<?php
date_default_timezone_set('Europe/London');

$tokyo = new DateTimeZone('Asia/Tokyo');
var_dump($tokyo->getName());

$immutable = new DateTimeImmutable('2012-12-27 16:24:08');
$changed = $immutable->setTimezone($tokyo);
echo $immutable->format('Y-m-d H:i:s e'), "\n";
echo $changed->format('Y-m-d H:i:s e'), "\n";

$fromFormat = DateTime::createFromFormat('D., M# j, Y g:iA', 'Thu., Nov. 29, 2012 5:00PM');
echo $fromFormat->format('D., M. j, Y g:iA'), "\n";

class NativeDateTimeChild extends DateTime {
    public function __clone() {
        echo "NativeDateTimeChild::__clone\n";
    }
}
class NativeDateTimeZoneChild extends DateTimeZone {}

$date = new NativeDateTimeChild('1pm Aug 1 GMT 2007');
$copy = clone $date;
$date->modify('1 hour');
$copy->modify('1 second ago');
echo $date->format(DateTime::RFC822), "\n";
echo $copy->format(DateTime::RFC822), "\n";

$zone = new NativeDateTimeZoneChild('Asia/Tokyo');
$zoneCopy = clone $zone;
echo $zoneCopy->getName(), "\n";
"#,
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "string(10) \"Asia/Tokyo\"\n",
            "2012-12-27 16:24:08 Europe/London\n",
            "2012-12-28 01:24:08 Asia/Tokyo\n",
            "Thu., Nov. 29, 2012 5:00PM\n",
            "NativeDateTimeChild::__clone\n",
            "Wed, 01 Aug 07 14:00:00 +0000\n",
            "Wed, 01 Aug 07 12:59:59 +0000\n",
            "Asia/Tokyo\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("Asia/Tokyo"));
    assert!(c_source.contains("ptn_datetime_parse_meridian_time_token"));
    assert!(c_source.contains("ptn_datetime_parse_create_from_format"));
}

