fn compile_tempnam_open_basedir_fallback_to_native_binary() {
    let root = temp_dir("ptn-native-tempnam-open-basedir-fallback");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("tempnam-open-basedir-fallback.php");
    let output = root.join("tempnam-open-basedir-fallback-bin");
    fs::write(
        &input,
        "<?php\n\
ini_set('open_basedir', '.');\n\
echo tempnam('directory_that_not_exists', 'prefix_');\n",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).current_dir(&root).output().unwrap();
    assert!(execution.status.success());
    let stdout = String::from_utf8(execution.stdout).unwrap();
    assert!(
        stdout.contains("Notice: tempnam(): file created in the system's temporary directory"),
        "{stdout}"
    );
    assert!(
        stdout.contains("Warning: tempnam(): open_basedir restriction in effect. File("),
        "{stdout}"
    );
    assert!(
        stdout.contains("is not within the allowed path(s): (.)"),
        "{stdout}"
    );
    assert!(stdout.ends_with(" on line 3\n"), "{stdout}");
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_stream_read_and_csv_internals_to_native_binary() {
    let root = temp_dir("ptn-native-stream-read-csv-internals");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("stream-read-csv.php");
    let output = root.join("stream-read-csv-bin");
    fs::write(
        &input,
        "<?php\n\
$path = __DIR__ . '/stream.csv';\n\
file_put_contents($path, \"a,b\\nc,d\\nlast\");\n\
$fp = fopen($path, 'rb');\n\
var_dump(ftell($fp));\n\
var_dump(fgetc($fp));\n\
var_dump(ftell($fp));\n\
var_dump(rewind($fp));\n\
var_dump(fgets($fp, 4));\n\
var_dump(rewind($fp));\n\
var_dump(fread($fp, 3));\n\
var_dump(feof($fp));\n\
fclose($fp);\n\
$fp = fopen($path, 'rb');\n\
var_dump(fgetcsv($fp, escape: '\\\\'));\n\
var_dump(fgetcsv($fp, escape: '\\\\'));\n\
fclose($fp);\n\
$out = __DIR__ . '/written.csv';\n\
$fp = fopen($out, 'wb');\n\
var_dump(fputcsv($fp, ['x,y', 'z'], escape: '\\\\'));\n\
fclose($fp);\n\
var_dump(file($out));\n\
$fp = fopen($path, 'rb');\n\
var_dump(fseek($fp, 2));\n\
var_dump(ftell($fp));\n\
$stat = fstat($fp);\n\
var_dump($stat['size']);\n\
fclose($fp);\n\
$tmp = tmpfile();\n\
fwrite($tmp, '12345');\n\
var_dump(stream_get_contents($tmp, 2, 3));\n\
var_dump(stream_get_contents($tmp, 2, -1));\n\
$copy = __DIR__ . '/copy.txt';\n\
$src = fopen($path, 'rb');\n\
$dest = fopen($copy, 'wb');\n\
var_dump(stream_copy_to_stream($src, $dest, 4));\n\
fclose($src);\n\
fclose($dest);\n\
var_dump(file_get_contents($copy));\n\
var_dump(readfile($copy));\n\
$truncate = __DIR__ . '/truncate.txt';\n\
file_put_contents($truncate, 'abcdef');\n\
$fp = fopen($truncate, 'r+');\n\
var_dump(ftruncate($fp, 3));\n\
fclose($fp);\n\
var_dump(file_get_contents($truncate));\n\
$line = __DIR__ . '/line.txt';\n\
file_put_contents($line, 'foo<br>bar');\n\
$fp = fopen($line, 'rb');\n\
var_dump(stream_get_line($fp, 0, '<br>'));\n\
var_dump(stream_get_line($fp, 0, '<br>'));\n\
fclose($fp);\n\
$dir = opendir(__DIR__);\n\
var_dump(is_string(readdir($dir)));\n\
rewinddir($dir);\n\
var_dump(is_string(readdir($dir)));\n\
var_dump(fstat($dir));\n\
closedir($dir);\n\
var_dump(is_resource(stream_context_create()));\n\
@unlink($path);\n\
@unlink($out);\n\
@unlink($copy);\n\
@unlink($truncate);\n\
@unlink($line);\n",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        "int(0)\n\
string(1) \"a\"\n\
int(1)\n\
bool(true)\n\
string(3) \"a,b\"\n\
bool(true)\n\
string(3) \"a,b\"\n\
bool(false)\n\
array(2) {\n  [0]=>\n  string(1) \"a\"\n  [1]=>\n  string(1) \"b\"\n}\n\
array(2) {\n  [0]=>\n  string(1) \"c\"\n  [1]=>\n  string(1) \"d\"\n}\n\
int(8)\n\
array(1) {\n  [0]=>\n  string(8) \"\"x,y\",z\n\"\n}\n\
int(0)\n\
int(2)\n\
int(12)\n\
string(2) \"45\"\n\
string(0) \"\"\n\
int(4)\n\
string(4) \"a,b\n\"\n\
a,b\n\
int(4)\n\
bool(true)\n\
string(3) \"abc\"\n\
string(3) \"foo\"\n\
string(3) \"bar\"\n\
bool(true)\n\
bool(true)\n\
bool(false)\n\
bool(true)\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_zlib_wrapper_copy_and_socket_stream_copy_to_native_binary() {
    let root = temp_dir("ptn-native-zlib-wrapper-socket-copy");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("zlib-wrapper-socket-copy.php");
    let output = root.join("zlib-wrapper-socket-copy-bin");
    fs::write(
        &input,
        r#"<?php
$sockets = stream_socket_pair(STREAM_PF_UNIX, STREAM_SOCK_STREAM, 0);
$tmp = tmpfile();
fwrite($sockets[0], "a");
stream_socket_shutdown($sockets[0], STREAM_SHUT_WR);
stream_copy_to_stream($sockets[1], $tmp);
fseek($tmp, 0, SEEK_SET);
var_dump(stream_get_contents($tmp));
stream_copy_to_stream($sockets[1], $tmp);
fseek($tmp, 0, SEEK_SET);
var_dump(stream_get_contents($tmp));

$source = __DIR__ . "/zlib-source.txt";
$compressed = __DIR__ . "/zlib-copy.gz";
$plain = __DIR__ . "/zlib-copy.txt";
$round = __DIR__ . "/zlib-round.gz";
$data = "hello zlib\nline two";
file_put_contents($source, $data);
copy($source, "compress.zlib://$compressed");
$h = gzopen($compressed, "r");
var_dump(gzread($h, 4096));
gzclose($h);
$h = fopen($compressed, "r");
var_dump(bin2hex(fread($h, 2)));
fclose($h);
copy("compress.zlib://$compressed", $plain);
var_dump(file_get_contents($plain));
$fileUri = "file://$compressed";
$h = fopen("compress.zlib://$fileUri", "r");
var_dump(stream_get_contents($h));
fclose($h);
copy("compress.zlib://$compressed", "compress.zlib://$round");
$h = gzopen($round, "r");
var_dump(gzread($h, 4096));
gzclose($h);
$put = __DIR__ . "/zlib-put.gz";
var_dump(file_put_contents("compress.zlib://$put", $data));
var_dump(file_put_contents("compress.zlib://$put", "\nappended", FILE_APPEND));
$h = gzopen($put, "r");
var_dump(gzread($h, 4096));
gzclose($h);

$levelData = str_repeat(file_get_contents(__FILE__), 10);
function ptn_zlib_level_size(string $path, string $data, int $level): int {
    $ctx = stream_context_create(["zlib" => ["level" => $level]]);
    $stream = fopen("compress.zlib://$path", "w", false, $ctx);
    fwrite($stream, $data);
    fclose($stream);
    return filesize($path);
}
$level1 = __DIR__ . "/zlib-level-1.gz";
$level9 = __DIR__ . "/zlib-level-9.gz";
var_dump(ptn_zlib_level_size($level9, $levelData, 9) < ptn_zlib_level_size($level1, $levelData, 1));

@unlink($source);
@unlink($compressed);
@unlink($plain);
@unlink($round);
@unlink($put);
@unlink($level1);
@unlink($level9);
"#,
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        "string(1) \"a\"\n\
string(1) \"a\"\n\
string(19) \"hello zlib\n\
line two\"\n\
string(4) \"1f8b\"\n\
string(19) \"hello zlib\n\
line two\"\n\
string(19) \"hello zlib\n\
line two\"\n\
string(19) \"hello zlib\n\
line two\"\n\
int(19)\n\
int(9)\n\
string(28) \"hello zlib\n\
line two\n\
appended\"\n\
bool(true)\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_internal_stream_socket_pair"));
    assert!(c_source.contains("ptn_internal_stream_socket_shutdown"));
    assert!(c_source.contains("ptn_try_open_compress_zlib_stream"));
    assert!(c_source.contains("ptn_zlib_write_path_bytes"));
}

#[test]
fn compile_zlib_functions_filters_and_constants_to_native_binary() {
    let root = temp_dir("ptn-native-zlib-functions-filters");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("zlib-functions-filters.php");
    let output = root.join("zlib-functions-filters-bin");
    fs::write(
        &input,
        r#"<?php
$data = "alpha beta gamma";
$path = __DIR__ . "/zlib-surface.gz";
$filtered = __DIR__ . "/zlib-filter.gz";
$truncated = __DIR__ . "/zlib-truncate.gz";

$constants = get_defined_constants(true);
var_dump(ZLIB_ENCODING_DEFLATE, FORCE_GZIP, $constants["zlib"]["ZLIB_ENCODING_GZIP"]);
var_dump(bin2hex(substr(gzencode("abc"), 0, 2)));
$packed = gzcompress("abc");
var_dump(bin2hex(substr(gzencode("abc", -1, ZLIB_ENCODING_DEFLATE), 0, 2)));
var_dump(bin2hex(substr(gzencode("abc", -1, ZLIB_ENCODING_RAW), 0, 2)));
var_dump(bin2hex(substr($packed, 0, 2)));
$gzcompressed = gzcompress($data);
var_dump(gzuncompress($gzcompressed) === $data);
var_dump(strlen(gzuncompress($gzcompressed, strlen($data))));
var_dump(gzuncompress($packed));
var_dump(gzuncompress($packed, 3));
var_dump(gzuncompress($packed, 2));
try { gzuncompress($packed, -1); } catch (ValueError $e) { echo "max-error\n"; }
var_dump(gzuncompress(gzcompress("roundtrip")));
$deflate = deflate_init(ZLIB_ENCODING_DEFLATE);
var_dump(gzuncompress(deflate_add($deflate, "stream", ZLIB_FINISH)));
try { deflate_add(fopen("php://memory", "r+"), "bad"); } catch (TypeError $e) { echo "deflate-type\n"; }
try { deflate_add($deflate, "bad", 6789); } catch (ValueError $e) { echo "deflate-flush\n"; }

$chain = __DIR__ . "/zlib-chain.gz.gz";
file_put_contents($chain, gzencode(gzencode(str_repeat("x", 10000))));
$chainStream = fopen($chain, "rb");
stream_filter_append($chainStream, "zlib.inflate", STREAM_FILTER_READ, ["window" => 30]);
stream_filter_append($chainStream, "zlib.inflate", STREAM_FILTER_READ, ["window" => 30]);
$total = 0;
while (!feof($chainStream)) {
    $total += strlen(fread($chainStream, 4096));
}
fclose($chainStream);
var_dump($total);

$h = gzopen($path, "w");
var_dump(gzwrite($h, "ignored", 0));
var_dump(gzwrite($h, "ignored", -1));
var_dump(gzwrite($h, $data));
gzclose($h);

$write_only = gzopen(__DIR__ . "/zlib-write-only.gz", "w");
var_dump(gzread($write_only, 1));
gzclose($write_only);

$h = gzopen($path, "r", false);
var_dump(gzread($h, 5));
var_dump(gzseek($h, 6));
var_dump(gzread($h, 4));
var_dump(gzseek($h, 0, SEEK_END));
var_dump(gztell($h));
gzrewind($h);
var_dump(gzread($h, 5));
gzclose($h);

var_dump(gzopen($path, "w+"));

$h = gzopen($path, "r");
$count = gzpassthru($h);
echo "\n";
var_dump($count);
gzclose($h);

$count = readgzfile($path);
echo "\n";
var_dump($count);

$stream = fopen($filtered, "w+");
$filter = stream_filter_append($stream, "zlib.deflate", STREAM_FILTER_WRITE, ["window" => FORCE_GZIP]);
var_dump($filter !== false);
var_dump(fwrite($stream, $data));
stream_filter_remove($filter);
fflush($stream);
fseek($stream, 0, SEEK_SET);
var_dump(bin2hex(fread($stream, 2)));
fclose($stream);

$z = fopen("compress.zlib://$truncated", "w");
var_dump(ftruncate($z, 0));
fclose($z);

$plain = "The quick brown fox jumps over the lazy dog.";
$encoded = gzencode($plain);
$truncated_gzip = substr($encoded, 0, strlen($encoded) - 20);
$mem = fopen("php://temp", "w+");
fwrite($mem, $truncated_gzip);
rewind($mem);
stream_filter_append($mem, "zlib.inflate", STREAM_FILTER_READ, ["window" => 15 + 16]);
var_dump(fread($mem, 100));
fclose($mem);

$encoded[strlen($encoded) - 5] = "X";
$mem = fopen("php://temp", "w+");
fwrite($mem, $encoded);
rewind($mem);
stream_filter_append($mem, "zlib.inflate", STREAM_FILTER_READ, ["window" => 15 + 16]);
$old_reporting = error_reporting(0);
var_dump(fread($mem, 100));
error_reporting($old_reporting);
fclose($mem);

$encoded = zlib_encode("Hello world.", ZLIB_ENCODING_DEFLATE);
$ctx = inflate_init(ZLIB_ENCODING_DEFLATE);
$inflated = "";
for ($i = 0; inflate_get_status($ctx) === ZLIB_OK; $i++) {
    $inflated .= inflate_add($ctx, substr($encoded, $i, 1));
}
echo "inflate:", $inflated, ":", inflate_get_status($ctx), "\n";
inflate_add($ctx, substr($encoded, 0, 4));
echo "reset-status:", inflate_get_status($ctx), "\n";

try { inflate_init(42); } catch (ValueError $e) { echo "inflate-error\n"; }
try { inflate_init(ZLIB_ENCODING_DEFLATE, ["window" => []]); } catch (TypeError $e) { echo "window-option\n"; }
try { gzdeflate("x", 99); } catch (ValueError $e) { echo "level-error\n"; }
try { deflate_init(ZLIB_ENCODING_DEFLATE, ["level" => 42]); } catch (ValueError $e) { echo $e->getMessage(), "\n"; }
try { deflate_init(ZLIB_ENCODING_DEFLATE, ["level" => -2]); } catch (ValueError $e) { echo $e->getMessage(), "\n"; }
try { deflate_init(ZLIB_ENCODING_DEFLATE, ["memory" => 0]); } catch (ValueError $e) { echo $e->getMessage(), "\n"; }
try { deflate_init(ZLIB_ENCODING_DEFLATE, ["memory" => 10]); } catch (ValueError $e) { echo $e->getMessage(), "\n"; }
try { gzencode("abc", -1, 99); } catch (ValueError $e) { echo "gzencode-encoding-error\n"; }
try { deflate_init(ZLIB_ENCODING_DEFLATE, ["level" => "bad"]); } catch (TypeError $e) { echo "option-error\n"; }

@unlink($path);
@unlink($filtered);
@unlink($truncated);
@unlink(__DIR__ . "/zlib-write-only.gz");
@unlink($chain);
"#,
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    let stdout = String::from_utf8(execution.stdout).unwrap();
    assert!(stdout.contains("Warning: ftruncate(): Can't truncate this stream!"));
    assert!(stdout.contains(
        "Warning: gzopen(): Cannot open a zlib stream for reading and writing at the same time!"
    ));
    assert!(stdout.contains("Warning: gzseek(): SEEK_END is not supported"));
    let stdout_without_warnings = stdout
        .lines()
        .filter(|line| !line.is_empty() && !line.starts_with("Warning:"))
        .collect::<Vec<_>>()
        .join("\n")
        + "\n";
    assert_eq!(
        stdout_without_warnings,
        "int(15)\n\
int(31)\n\
int(31)\n\
string(4) \"1f8b\"\n\
string(4) \"789c\"\n\
string(4) \"4b4c\"\n\
string(4) \"789c\"\n\
bool(true)\n\
int(16)\n\
string(3) \"abc\"\n\
string(3) \"abc\"\n\
bool(false)\n\
max-error\n\
string(9) \"roundtrip\"\n\
string(6) \"stream\"\n\
deflate-type\n\
deflate-flush\n\
int(10000)\n\
int(0)\n\
int(0)\n\
int(16)\n\
bool(false)\n\
string(5) \"alpha\"\n\
int(0)\n\
string(4) \"beta\"\n\
int(-1)\n\
int(10)\n\
string(5) \"alpha\"\n\
bool(false)\n\
alpha beta gamma\n\
int(16)\n\
alpha beta gamma\n\
int(16)\n\
bool(true)\n\
int(16)\n\
string(4) \"1f8b\"\n\
bool(false)\n\
string(32) \"The quick brown fox jumps over t\"\n\
bool(false)\n\
inflate:Hello world.:1\n\
reset-status:0\n\
inflate-error\n\
window-option\n\
level-error\n\
deflate_init(): \"level\" option must be between -1 and 9\n\
deflate_init(): \"level\" option must be between -1 and 9\n\
deflate_init(): \"memory\" option must be between 1 and 9\n\
deflate_init(): \"memory\" option must be between 1 and 9\n\
gzencode-encoding-error\n\
option-error\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_internal_gzuncompress"));
    assert!(c_source.contains("ptn_internal_gzwrite"));
    assert!(c_source.contains("ptn_internal_gzuncompress"));
    assert!(c_source.contains("ptn_internal_deflate_add"));
    assert!(c_source.contains("ptn_internal_gzseek"));
    assert!(c_source.contains("ptn_internal_zlib_encode"));
    assert!(c_source.contains("ptn_internal_inflate_get_status"));
    assert!(c_source.contains("ptn_internal_stream_filter_remove"));
    assert!(c_source.contains("ptn_defined_constants_zlib_table"));
}

#[test]
fn compile_zlib_row_pack_frontier_semantics_to_native_binary() {
    let root = temp_dir("ptn-native-zlib-row-pack-frontier");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("zlib-row-pack-frontier.php");
    let output = root.join("zlib-row-pack-frontier-bin");
    fs::write(
        &input,
        r#"<?php
$original = str_repeat("hallo php", 32);
$packed = gzcompress($original);
var_dump(gzuncompress($packed) === $original);
var_dump(gzuncompress($packed, 3));

$deflated = gzdeflate("aaaaaaaaaaaaaaa");
var_dump(gzinflate($deflated, 150));
var_dump(gzinflate($deflated, 1));

$path = __DIR__ . "/lines.gz";
$h = gzopen($path, "w");
gzwrite($h, "first\nsecond\n");
gzclose($h);
$h = gzopen($path, "r");
var_dump(gzgets($h));
var_dump(gzeof($h));
gzread($h, 4096);
var_dump(gzeof($h));
gzrewind($h);
var_dump(gztell($h), gzgets($h));
gzclose($h);

mkdir(__DIR__ . "/inc1");
mkdir(__DIR__ . "/inc2");
mkdir(__DIR__ . "/work");
$name = "sample.gz";
$h = gzopen(__DIR__ . "/inc2/" . $name, "w");
gzwrite($h, "from inc2");
gzclose($h);
chdir(__DIR__ . "/work");
set_include_path(__DIR__ . "/inc1:" . __DIR__ . "/inc2:");
$lines = gzfile($name, true);
echo $lines[0], "\n";
$h = gzopen(__DIR__ . "/inc1/" . $name, "w");
gzwrite($h, "from inc1");
gzclose($h);
$h = gzopen($name, "w");
gzwrite($h, "from cwd");
gzclose($h);
$lines = gzfile($name, true);
echo $lines[0], "\n";
chdir(__DIR__);

$dictionary = "abc";
$deflate = deflate_init(ZLIB_ENCODING_RAW, ["dictionary" => $dictionary]);
$compressed = deflate_add($deflate, "abcabc", ZLIB_FINISH);
$inflate = inflate_init(ZLIB_ENCODING_RAW, ["dictionary" => $dictionary]);
var_dump(inflate_add($inflate, $compressed) === "abcabc");

$sync = deflate_init(ZLIB_ENCODING_RAW);
$syncChunk = deflate_add($sync, str_repeat("x", 128), ZLIB_SYNC_FLUSH);
var_dump(bin2hex(substr($syncChunk, -4)));

$stream = fopen("php://temp", "w+");
stream_filter_append($stream, "zlib.deflate", STREAM_FILTER_WRITE);
stream_filter_append($stream, "convert.base64-encode", STREAM_FILTER_WRITE);
fwrite($stream, "filter text");
rewind($stream);
$encoded = stream_get_contents($stream);
var_dump(gzinflate(base64_decode($encoded)));

try { deflate_init(ZLIB_ENCODING_DEFLATE, ["dictionary" => [" ", ""]]); } catch (ValueError $e) { echo $e->getMessage(), "\n"; }
try { deflate_init(ZLIB_ENCODING_DEFLATE, ["dictionary" => ["hello", "wor\0ld"]]); } catch (ValueError $e) { echo $e->getMessage(), "\n"; }
try { deflate_init(ZLIB_ENCODING_DEFLATE, ["dictionary" => [" ", new stdClass]]); } catch (Error $e) { echo $e->getMessage(), "\n"; }

var_dump(zlib_get_coding_type());
var_dump(ZLIB_VERSION, ZLIB_VERNUM >= 0x1240);
"#,
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    let stdout = String::from_utf8(execution.stdout).unwrap();
    assert!(stdout.contains("Warning: gzuncompress(): insufficient memory"));
    assert!(stdout.contains("Warning: gzinflate(): insufficient memory"));
    let stdout_without_warnings = stdout
        .lines()
        .filter(|line| !line.is_empty() && !line.starts_with("Warning:"))
        .collect::<Vec<_>>()
        .join("\n")
        + "\n";
    assert_eq!(
        stdout_without_warnings,
        "bool(true)\n\
bool(false)\n\
string(15) \"aaaaaaaaaaaaaaa\"\n\
bool(false)\n\
string(6) \"first\n\
\"\n\
bool(false)\n\
bool(true)\n\
int(0)\n\
string(6) \"first\n\
\"\n\
from inc2\n\
from inc1\n\
bool(true)\n\
string(8) \"0000ffff\"\n\
string(11) \"filter text\"\n\
deflate_init(): Argument #2 ($options) must not contain empty strings\n\
deflate_init(): Argument #2 ($options) must not contain strings with null bytes\n\
Object of class stdClass could not be converted to string\n\
bool(false)\n\
string(5) \"1.3.1\"\n\
bool(true)\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_internal_gzcompress"));
    assert!(c_source.contains("ptn_internal_gzgets"));
    assert!(c_source.contains("ptn_internal_deflate_add"));
    assert!(c_source.contains("PTN_STREAM_FILTER_CONVERT_BASE64_ENCODE"));
}

#[test]
fn compile_zlib_phar_wrapper_ops_to_native_binary() {
    let root = temp_dir("ptn-native-zlib-phar-wrapper-ops");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("zlib-phar-wrapper-ops.php");
    let output = root.join("zlib-phar-wrapper-ops-bin");
    fs::write(
        &input,
        r#"<?php
$base = __DIR__ . '/readgz';
$dir1 = $base . '/dir1';
$dir2 = $base . '/dir2';
$dir3 = $base . '/dir3';
$work = $base . '/work';
mkdir($base);
mkdir($dir1);
mkdir($dir2);
mkdir($dir3);
mkdir($work);
$name = 'payload.gz';

$h = gzopen($dir2 . '/' . $name, 'w');
gzwrite($h, 'dir2');
gzclose($h);
chdir($work);
set_include_path($dir1 . ':' . $dir2 . ':' . $dir3 . ':');
echo 'read:';
readgzfile($name, true);
echo "\n";

$h = gzopen($dir1 . '/' . $name, 'w');
gzwrite($h, 'dir1');
gzclose($h);
$h = gzopen($name, 'w');
gzwrite($h, 'work');
gzclose($h);
echo 'read:';
readgzfile($name, true);
echo "\n";

unlink($dir1 . '/' . $name);
unlink($dir2 . '/' . $name);
echo 'read:';
readgzfile($name, true);
echo "\n";

$h = gzopen(__DIR__ . '/' . $name, 'w');
gzwrite($h, 'script');
gzclose($h);
echo 'read:';
readgzfile($name, true);
echo "\n";
chdir(__DIR__);

$big = '';
for ($i = 0; $i < 30000; $i++) {
    $big .= $i . ' ';
}
$deflated = gzdeflate($big, 9);
var_dump(strlen($deflated) > 65535);
var_dump(gzinflate(substr($deflated, 0, 65535)));

$file = __DIR__ . '/seek.zlib';
$fp = fopen($file, 'w');
stream_filter_append($fp, 'zlib.deflate', STREAM_FILTER_WRITE);
fwrite($fp, 'abcdefghij');
fclose($fp);

$fp = fopen($file, 'r');
stream_filter_append($fp, 'zlib.inflate', STREAM_FILTER_READ);
echo fread($fp, 3), "\n";
var_dump(fseek($fp, 0, SEEK_SET));
var_dump(ftell($fp));
var_dump(stream_get_contents($fp));
var_dump(fseek($fp, 4, SEEK_SET));
fclose($fp);

var_dump(gzopen('php://output', 14));

unlink($work . '/' . $name);
unlink(__DIR__ . '/' . $name);
unlink($file);
rmdir($work);
rmdir($dir1);
rmdir($dir2);
rmdir($dir3);
rmdir($base);
"#,
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    let stdout = String::from_utf8(execution.stdout).unwrap();
    assert!(stdout.contains("Warning: gzinflate(): data error"));
    assert!(stdout.contains(
        "Warning: fseek(): Stream filter zlib.inflate is seekable only to start position"
    ));
    assert!(
        stdout.contains("Warning: gzopen(php://output): could not make seekable - php://output")
    );
    let stdout_without_warnings = stdout
        .lines()
        .filter(|line| !line.is_empty() && !line.contains("Warning: "))
        .collect::<Vec<_>>()
        .join("\n")
        + "\n";
    assert_eq!(
        stdout_without_warnings,
        "read:dir2\n\
read:dir1\n\
read:work\n\
read:script\n\
bool(true)\n\
bool(false)\n\
abc\n\
int(0)\n\
int(0)\n\
string(10) \"abcdefghij\"\n\
int(-1)\n\
bool(false)\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_resolve_zlib_include_path"));
    assert!(c_source.contains("ptn_stream_filter_chain_has_zlib_inflate"));
}

#[test]
fn compile_zlib_alias_encode_incremental_inflate_and_wrappers_to_native_binary() {
    let root = temp_dir("ptn-native-zlib-alias-inflate-wrappers");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("zlib-alias-inflate-wrappers.php");
    let output = root.join("zlib-alias-inflate-wrappers-bin");
    fs::write(
        &input,
        r#"<?php
$data = implode(range("a", "z"));
$packed = zlib_encode($data, ZLIB_ENCODING_GZIP);
$ctx = inflate_init(ZLIB_ENCODING_GZIP);
$out = "";
for ($i = 0; $i < strlen($packed); $i++) {
    $out .= inflate_add($ctx, $packed[$i]);
}
$out .= inflate_add($ctx, "", ZLIB_FINISH);
var_dump($out === $data);

$out = "";
for ($i = 0; $i < strlen($packed); $i++) {
    $out .= inflate_add($ctx, $packed[$i]);
}
$out .= inflate_add($ctx, "", ZLIB_FINISH);
var_dump($out === $data);

$path = __DIR__ . "/gzputs.gz";
$h = gzopen($path, "w");
var_dump(gzputs($h, "abcdef", 3));
gzclose($h);
$h = gzopen($path, "r");
var_dump(gzread($h, 10));
gzclose($h);
unlink($path);

$wrappers = stream_get_wrappers();
var_dump(in_array("phar", $wrappers, true), in_array("compress.zlib", $wrappers, true));
"#,
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        "bool(true)\nbool(true)\nint(3)\nstring(3) \"abc\"\nbool(true)\nbool(true)\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_internal_zlib_encode"));
    assert!(c_source.contains("ptn_zlib_context_inflate_with_zlib"));
    assert!(c_source.contains("ptn_internal_stream_get_wrappers"));
}

