#[test]
fn compile_stream_process_zlib_residuals_to_native_binary() {
    let root = temp_dir("ptn-native-stream-process-zlib-residuals");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("stream-process-zlib-residuals.php");
    let output = root.join("stream-process-zlib-residuals-bin");
    let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    let port = listener.local_addr().unwrap().port();
    drop(listener);
    let php = r#"<?php
$port = __PORT__;
try {
    popen("abc.txt", "x");
} catch (ValueError $e) {
    echo $e->getMessage(), "\n";
}

$plain = __DIR__ . "/gzopen-plain.txt";
file_put_contents($plain, "Here is some plain\ntext");
$gz = gzopen($plain, "r");
var_dump(is_resource($gz));
gzpassthru($gz);
gzclose($gz);
echo "\n";
unlink($plain);

$server = stream_socket_server("tcp://127.0.0.1:$port");
var_dump(is_resource($server));
$client = fsockopen("tcp://127.0.0.1:$port");
var_dump(is_resource($client));
fclose($client);
try {
    var_dump(stream_set_timeout($client, 10));
} catch (TypeError $e) {
    echo $e->getMessage(), "\n";
}
$file = fopen(__FILE__, "r");
var_dump(stream_set_timeout($file, 10));
fclose($file);
fclose($server);
"#
    .replace("__PORT__", &port.to_string());
    fs::write(&input, php).unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        "popen(): Argument #2 ($mode) must be one of \"r\", \"rb\", \"w\", or \"wb\"\n\
bool(true)\n\
Here is some plain\n\
text\n\
bool(true)\n\
bool(true)\n\
stream_set_timeout(): Argument #1 ($stream) must be an open stream resource\n\
bool(false)\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_internal_popen"));
    assert!(c_source.contains("ptn_internal_fsockopen"));
    assert!(c_source.contains("ptn_internal_stream_set_timeout"));
    assert!(c_source.contains("ptn_try_open_plain_gz_read_stream"));
}

#[test]
fn compile_stream_convert_filters_and_dechunk_to_native_binary() {
    let root = temp_dir("ptn-native-stream-convert-filters-dechunk");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("stream-convert-filters-dechunk.php");
    let output = root.join("stream-convert-filters-dechunk-bin");
    fs::write(
        &input,
        "<?php\n\
$fp = tmpfile();\n\
fwrite($fp, 'Long text that will be wrapped');\n\
rewind($fp);\n\
stream_filter_prepend($fp, 'convert.base64-encode', STREAM_FILTER_READ, ['line-length' => 20, 'line-break-chars' => \"\\n\"]);\n\
echo str_replace(\"\\n\", '|', stream_get_contents($fp)), \"\\n\";\n\
fclose($fp);\n\
\n\
$qp = tmpfile();\n\
fwrite($qp, \"Line1\\r\\nLine2\");\n\
rewind($qp);\n\
stream_filter_prepend($qp, 'convert.quoted-printable-encode', STREAM_FILTER_READ);\n\
echo stream_get_contents($qp), \"\\n\";\n\
fclose($qp);\n\
\n\
$qpd = tmpfile();\n\
fwrite($qpd, 'Text=09=0D=0A');\n\
rewind($qpd);\n\
stream_filter_prepend($qpd, 'convert.quoted-printable-decode', STREAM_FILTER_READ);\n\
echo bin2hex(stream_get_contents($qpd)), \"\\n\";\n\
fclose($qpd);\n\
\n\
$buffer = fopen('php://temp', 'w+');\n\
stream_filter_append($buffer, 'dechunk', STREAM_FILTER_WRITE);\n\
fwrite($buffer, \"5\\r\\nHello\\r\\n\");\n\
var_dump(stream_get_contents($buffer, -1, 0));\n\
fwrite($buffer, \"7\\r\\n, World\\r\\n\");\n\
var_dump(stream_get_contents($buffer, -1, 0));\n\
fwrite($buffer, \"0\\r\\n\\r\\n\");\n\
var_dump(stream_get_contents($buffer, -1, 0));\n\
fclose($buffer);\n",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        "TG9uZyB0ZXh0IHRoYXQg|d2lsbCBiZSB3cmFwcGVk\n\
Line1=0D=0ALine2\n\
54657874090d0a\n\
string(5) \"Hello\"\n\
string(12) \"Hello, World\"\n\
string(12) \"Hello, World\"\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("PTN_STREAM_FILTER_CONVERT_BASE64_ENCODE"));
    assert!(c_source.contains("PTN_STREAM_FILTER_CONVERT_QUOTED_PRINTABLE_ENCODE"));
    assert!(c_source.contains("PTN_STREAM_FILTER_CONVERT_QUOTED_PRINTABLE_DECODE"));
    assert!(c_source.contains("PTN_STREAM_FILTER_DECHUNK"));
}

#[test]
fn compile_stream_convert_filters_and_write_seek_modes_to_native_binary() {
    let root = temp_dir("ptn-native-stream-convert-filter-seek-modes");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("stream-convert-filter-seek-modes.php");
    let output = root.join("stream-convert-filter-seek-modes-bin");
    fs::write(
        &input,
        "<?php\n\
$encoded = \"Sauvegarder=C3=A9ussi(e) n=C3=A3o N=C3=83O\\n\";\n\
$encoded .= \"Sauvegarder=c3=a9ussi(e) n=c3=a3o N=c3=83O\\n\";\n\
$fp = fopen('php://temp', 'w+');\n\
stream_filter_append($fp, 'convert.quoted-printable-decode', STREAM_FILTER_WRITE);\n\
fwrite($fp, $encoded);\n\
rewind($fp);\n\
fpassthru($fp);\n\
fclose($fp);\n\
\n\
foreach (['convert.base64-encode', 'convert.quoted-printable-encode'] as $name) {\n\
    $fp = fopen('php://memory', 'w+');\n\
    stream_filter_append($fp, $name, STREAM_FILTER_WRITE, ['write_seek_mode' => 'preserve']);\n\
    fwrite($fp, 'Hello');\n\
    var_dump(fseek($fp, 0, SEEK_SET) === 0);\n\
    var_dump(fseek($fp, 100, SEEK_SET) === 0);\n\
    fclose($fp);\n\
\n\
    $fp = fopen('php://memory', 'w+');\n\
    stream_filter_append($fp, $name, STREAM_FILTER_WRITE, ['write_seek_mode' => 'strict']);\n\
    fwrite($fp, 'Hello');\n\
    var_dump(fseek($fp, 0, SEEK_SET) === -1);\n\
    fclose($fp);\n\
}\n\
\n\
$fp = fopen('php://memory', 'w+');\n\
stream_filter_append($fp, 'zlib.deflate', STREAM_FILTER_WRITE, ['write_seek_mode' => 'reset']);\n\
fwrite($fp, 'Hello');\n\
var_dump(fseek($fp, 0, SEEK_SET) === 0);\n\
var_dump(fseek($fp, 5, SEEK_SET) === -1);\n\
fclose($fp);\n\
\n\
$fp = fopen('php://memory', 'w+');\n\
stream_filter_append($fp, 'convert.base64-encode', STREAM_FILTER_WRITE, ['write_seek_mode' => 42]);\n\
fclose($fp);\n",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    let stdout = String::from_utf8(execution.stdout).unwrap();
    assert!(stdout.starts_with(
        "Sauvegarderéussi(e) não NÃO\n\
Sauvegarderéussi(e) não NÃO\n\
bool(true)\n\
bool(true)\n\
bool(true)\n\
bool(true)\n\
bool(true)\n\
bool(true)\n"
    ));
    assert!(
        stdout.contains("fseek(): Stream filter zlib.deflate is seekable only to start position")
    );
    assert!(stdout.contains(
        "stream_filter_append(): \"write_seek_mode\" filter parameter must be one of \"preserve\", \"reset\", or \"strict\""
    ));
    assert!(stdout.contains(
        "stream_filter_append(): Unable to create or locate filter \"convert.base64-encode\""
    ));
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("PTN_STREAM_FILTER_CONVERT_QUOTED_PRINTABLE_DECODE"));
    assert!(c_source.contains("ptn_stream_filter_write_seek_mode"));
}

