#[test]
fn compile_preg_match_all_named_and_split_to_native_binary() {
    let root = temp_dir("ptn-native-preg-match-all-named-and-split");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("preg-match-all-named-and-split.php");
    let output = root.join("preg-match-all-named-and-split-bin");
    fs::write(
        &input,
        "<?php\n\
preg_match('~(?P<word>\\\\w+)-(\\\\d+)~x', 'abc-12', $m);\n\
var_dump($m['word'], $m[1], $m[2]);\n\
var_dump(preg_match_all('~(?P<word>\\\\w+)-(\\\\d+)~', 'abc-12 def-34', $all, PREG_PATTERN_ORDER));\n\
var_dump($all['word'][1], $all[2][0]);\n\
var_dump(preg_match_all('/(\\\\w+)-(\\\\d+)/', 'abc-12 def-34', $sets, PREG_SET_ORDER | PREG_OFFSET_CAPTURE));\n\
var_dump($sets[1][2][0], $sets[1][2][1]);\n\
var_dump(preg_match_all('/(?:\\\\([^)]+\\\\))?(&?)([\\\\w>.()-]+(?:\\\\[\\\\w+\\\\])?)\\\\s*,?((?:\\\\)*\\\\s*=)?)/S', '&a, b, &c', $vars, PREG_SET_ORDER));\n\
var_dump($vars[2][1], $vars[2][2]);\n\
var_dump(preg_split('/PHP_(?:NAMED_)?(?:FUNCTION|METHOD)\\\\s*\\\\((\\\\w+(?:,\\\\s*\\\\w+)?)\\\\)/S', \"PHP_FUNCTION(s, preg_match)\\n{\\nlalala\", -1, PREG_SPLIT_DELIM_CAPTURE | PREG_SPLIT_OFFSET_CAPTURE));\n\
try { preg_match_all('//', '', $dummy, 0xdead); } catch (ValueError $e) { echo $e->getMessage(), \"\\n\"; }\n",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "string(3) \"abc\"\n",
            "string(3) \"abc\"\n",
            "string(2) \"12\"\n",
            "int(2)\n",
            "string(3) \"def\"\n",
            "string(2) \"12\"\n",
            "int(2)\n",
            "string(2) \"34\"\n",
            "int(11)\n",
            "int(3)\n",
            "string(1) \"&\"\n",
            "string(1) \"c\"\n",
            "array(3) {\n",
            "  [0]=>\n",
            "  array(2) {\n",
            "    [0]=>\n",
            "    string(0) \"\"\n",
            "    [1]=>\n",
            "    int(0)\n",
            "  }\n",
            "  [1]=>\n",
            "  array(2) {\n",
            "    [0]=>\n",
            "    string(13) \"s, preg_match\"\n",
            "    [1]=>\n",
            "    int(13)\n",
            "  }\n",
            "  [2]=>\n",
            "  array(2) {\n",
            "    [0]=>\n",
            "    string(9) \"\n",
            "{\n",
            "lalala\"\n",
            "    [1]=>\n",
            "    int(27)\n",
            "  }\n",
            "}\n",
            "preg_match_all(): Argument #4 ($flags) must be a PREG_* constant\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_preg_uses_pcre2_runtime_boundary_to_native_binary() {
    let Some(pcre2_library) = discover_pcre2_library() else {
        eprintln!("skipping PCRE2 runtime-boundary test: libpcre2-8 was not found");
        return;
    };

    let root = temp_dir("ptn-native-preg-pcre2-boundary");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("preg-pcre2-boundary.php");
    let output = root.join("preg-pcre2-boundary-bin");
    fs::write(
        &input,
        "<?php\n\
var_dump(preg_match('/(?<word>\\\\p{L}+)/u', '1 café', $m, PREG_OFFSET_CAPTURE));\n\
var_dump($m['word'][0], $m['word'][1]);\n\
var_dump(preg_match('/(?<=foo)\\\\d+/', 'foo123', $look));\n\
var_dump($look[0]);\n\
var_dump(preg_match('/(*UCP)^\\\\w+$/u', 'é'));\n\
var_dump(preg_match('/^\\\\w+$/u', 'é'));\n\
var_dump(preg_match('/k/iu', \"\\u{212A}\"));\n\
var_dump(preg_match('/k/iur', \"\\u{212A}\"));\n\
var_dump(preg_match('/./u', \"\\xFC\"));\n\
var_dump(preg_last_error());\n\
var_dump(preg_replace('/./u', 'x', \"\\xFC\"));\n\
var_dump(preg_last_error());\n\
var_dump(preg_match('/./u', 'é', $bad_offset, 0, 1));\n\
var_dump(preg_last_error());\n\
$count = 0;\n\
var_dump(preg_replace(['/([\\\\p{L}]+)/u', '/(?<=#)\\\\d+/'], ['[$0]', 'num:$0'], 'café #123', -1, $count));\n\
var_dump($count);\n\
preg_match('/.(.)./n', 'abc', $non_capture);\n\
var_dump($non_capture);\n\
preg_match('/.(?P<test>.)./n', 'abc', $named_capture);\n\
var_dump($named_capture);\n\
var_dump(preg_match('/(?U)<.*>/', '<aa> <bb> <cc>', $ungreedy));\n\
var_dump($ungreedy[0]);\n\
preg_match('/(?J)(?<chr>[ac])(?<num>\\\\d)|(?<chr>[b])/', 'b', $duplicate_names);\n\
var_dump($duplicate_names['chr'], $duplicate_names[1], $duplicate_names[3]);\n\
preg_match('/(?J)(?:(?<g>foo)|(?<g>bar))/', 'foo', $duplicate_tail);\n\
var_dump($duplicate_tail);\n\
preg_match('/(?J)(?:(?<g>foo)|(?<g>bar))/', 'foo', $duplicate_tail_null, PREG_UNMATCHED_AS_NULL);\n\
var_dump($duplicate_tail_null);\n\
var_dump(preg_split('/(?<=\\\\p{L})(?=\\\\d)/u', 'é2 a3'));\n",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output)
        .env("PTN_PCRE2_LIBRARY", &pcre2_library)
        .output()
        .unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstdout:\n{}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stdout),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "int(1)\n",
            "string(5) \"café\"\n",
            "int(2)\n",
            "int(1)\n",
            "string(3) \"123\"\n",
            "int(1)\n",
            "int(1)\n",
            "int(1)\n",
            "int(0)\n",
            "bool(false)\n",
            "int(4)\n",
            "NULL\n",
            "int(4)\n",
            "bool(false)\n",
            "int(5)\n",
            "string(16) \"[café] #num:123\"\n",
            "int(2)\n",
            "array(1) {\n",
            "  [0]=>\n",
            "  string(3) \"abc\"\n",
            "}\n",
            "array(3) {\n",
            "  [0]=>\n",
            "  string(3) \"abc\"\n",
            "  [\"test\"]=>\n",
            "  string(1) \"b\"\n",
            "  [1]=>\n",
            "  string(1) \"b\"\n",
            "}\n",
            "int(1)\n",
            "string(4) \"<aa>\"\n",
            "string(1) \"b\"\n",
            "string(0) \"\"\n",
            "string(1) \"b\"\n",
            "array(3) {\n",
            "  [0]=>\n",
            "  string(3) \"foo\"\n",
            "  [\"g\"]=>\n",
            "  string(3) \"foo\"\n",
            "  [1]=>\n",
            "  string(3) \"foo\"\n",
            "}\n",
            "array(4) {\n",
            "  [0]=>\n",
            "  string(3) \"foo\"\n",
            "  [\"g\"]=>\n",
            "  string(3) \"foo\"\n",
            "  [1]=>\n",
            "  string(3) \"foo\"\n",
            "  [2]=>\n",
            "  NULL\n",
            "}\n",
            "array(3) {\n",
            "  [0]=>\n",
            "  string(2) \"é\"\n",
            "  [1]=>\n",
            "  string(3) \"2 a\"\n",
            "  [2]=>\n",
            "  string(1) \"3\"\n",
            "}\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("PtnPregProgram"));
    assert!(c_source.contains("ptn_preg_compile_pcre2"));
    assert!(c_source.contains("PTN_PCRE2_LIBRARY"));
}

#[test]
fn compile_preg_pcre2_version_and_utf8_offset_cache_to_native_binary() {
    let Some(pcre2_library) = discover_pcre2_library() else {
        eprintln!("skipping PCRE2 UTF-8 cache test: libpcre2-8 was not found");
        return;
    };

    let root = temp_dir("ptn-native-preg-pcre2-version-utf8-cache");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("preg-pcre2-version-utf8-cache.php");
    let output = root.join("preg-pcre2-version-utf8-cache-bin");
    fs::write(
        &input,
        "<?php\n\
$constants = get_defined_constants(true);\n\
var_dump(PCRE_VERSION_MAJOR === 10);\n\
var_dump(PCRE_VERSION_MINOR >= 38);\n\
var_dump(isset($constants['pcre']['PCRE_VERSION']));\n\
var_dump($constants['pcre']['PCRE_VERSION_MAJOR'] === PCRE_VERSION_MAJOR);\n\
$input_size = 64 * 1024;\n\
$str = str_repeat('a', $input_size);\n\
$start = microtime(true);\n\
$pos = 0;\n\
while (preg_match('/\\G\\w/u', $str, $m, 0, $pos)) ++$pos;\n\
$elapsed = microtime(true) - $start;\n\
var_dump($pos === $input_size);\n\
var_dump($elapsed < 0.5);\n\
var_dump(preg_match('/./u', \"a\\xFF\", $bad, 0, 1));\n\
var_dump(preg_last_error() === PREG_BAD_UTF8_ERROR);\n\
var_dump(preg_match('/(*NO_JIT)^(A{1,2}B)+$$/', str_repeat('AB', 128)));\n\
var_dump(preg_match('~(*NO_JIT)(a)*~', str_repeat('a', 20), $nojit));\n\
$text = \"VA\\xFF\"; $text .= \"LID\";\n\
var_dump(preg_match('/\\\\b/u', $text, $word, 0, 4));\n\
var_dump(preg_last_error() === PREG_NO_ERROR);\n",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output)
        .env("PTN_PCRE2_LIBRARY", &pcre2_library)
        .output()
        .unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstdout:\n{}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stdout),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(false)\n",
            "bool(true)\n",
            "int(1)\n",
            "int(1)\n",
            "int(1)\n",
            "bool(true)\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("PTN_PCRE2_NO_UTF_CHECK"));
    assert!(c_source.contains("pcre_utf8_cache_data"));
    assert!(c_source.contains("ptn_direct_preg_match_contiguous_word_variable_matches"));
}

