#[test]
fn compile_mb_ereg_pcre2_semantics_to_native_binary() {
    let root = temp_dir("ptn-native-mb-ereg-pcre2-semantics");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("mb-ereg-pcre2-semantics.php");
    let output = root.join("mb-ereg-pcre2-semantics-bin");
    fs::write(
        &input,
        "<?php\n\
error_reporting(E_ALL & ~E_DEPRECATED);\n\
try {\n\
    mb_ereg_search_regs();\n\
} catch (Error $e) {\n\
    echo $e->getMessage(), \"\\n\";\n\
}\n\
$str = \"\\x80\";\n\
var_dump(false === mb_eregi('.', $str, $matches));\n\
var_dump($matches);\n\
var_dump(NULL === mb_ereg_replace('.', \"\\\\0\", $str));\n\
mb_regex_encoding('UTF-8');\n\
var_dump(mb_ereg('a', 'a'));\n\
mb_ereg('(?<wsp>\\s*)(?<word>\\w+)', 'x', $emptyCapture);\n\
var_dump($emptyCapture);\n\
echo mb_ereg_replace('123', 'def\\\\1ghi', 'abc123'), \"\\n\";\n\
var_dump(mb_ereg_replace('(%)', '\\\\\\\\1', 'a%c'));\n\
mb_ereg_search_init('');\n\
var_dump(mb_ereg_search(''));\n\
var_dump(mb_ereg_search_getregs());\n\
$pattern = '\\\\w+((?<punct>？)|(?<punct>！))';\n\
mb_ereg($pattern, '中？', $m);\n\
var_dump($m);\n\
mb_ereg($pattern, '中！', $m);\n\
var_dump($m);\n\
echo mb_ereg_replace('1(2*)3', '\\\\1def\\\\1', 'abc122222222223'), \"\\n\";\n\
$subject = 'foo';\n\
mb_ereg_search_init($subject);\n\
mb_ereg_search('\\\\A');\n\
var_dump(mb_ereg_search_getpos());\n\
var_dump(mb_ereg_search_getregs());\n\
mb_ereg_search('\\\\w+');\n\
var_dump(mb_ereg_search_getpos());\n\
var_dump(mb_ereg_search_getregs());\n",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "No pattern was provided\n",
            "bool(true)\n",
            "array(0) {\n",
            "}\n",
            "bool(true)\n",
            "bool(true)\n",
            "array(5) {\n",
            "  [0]=>\n",
            "  string(1) \"x\"\n",
            "  [1]=>\n",
            "  bool(false)\n",
            "  [2]=>\n",
            "  string(1) \"x\"\n",
            "  [\"wsp\"]=>\n",
            "  bool(false)\n",
            "  [\"word\"]=>\n",
            "  string(1) \"x\"\n",
            "}\n",
            "abcdef\\1ghi\n",
            "string(4) \"a\\%c\"\n",
            "bool(true)\n",
            "array(1) {\n",
            "  [0]=>\n",
            "  string(0) \"\"\n",
            "}\n",
            "array(4) {\n",
            "  [0]=>\n",
            "  string(6) \"中？\"\n",
            "  [1]=>\n",
            "  string(3) \"？\"\n",
            "  [2]=>\n",
            "  bool(false)\n",
            "  [\"punct\"]=>\n",
            "  string(3) \"？\"\n",
            "}\n",
            "array(4) {\n",
            "  [0]=>\n",
            "  string(6) \"中！\"\n",
            "  [1]=>\n",
            "  bool(false)\n",
            "  [2]=>\n",
            "  string(3) \"！\"\n",
            "  [\"punct\"]=>\n",
            "  string(3) \"！\"\n",
            "}\n",
            "abc2222222222def2222222222\n",
            "int(0)\n",
            "array(1) {\n",
            "  [0]=>\n",
            "  string(0) \"\"\n",
            "}\n",
            "int(3)\n",
            "array(1) {\n",
            "  [0]=>\n",
            "  string(3) \"foo\"\n",
            "}\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_mb_compile_regex_program"));
    assert!(c_source.contains("PTN_PCRE2_DUPNAMES"));
}

#[test]
fn compile_mbstring_embedded_nul_encoding_lists_to_native_binary() {
    let root = temp_dir("ptn-native-mb-embedded-nul-encodings");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("mb-embedded-nul-encodings.php");
    let output = root.join("mb-embedded-nul-encodings-bin");
    fs::write(
        &input,
        "<?php\n\
$encoding = \"UTF-8\\0AAAAAAAA\";\n\
$alias = \"binary\\0AAAAAAAA\";\n\
$var = 'foo';\n\
function dump_exception(callable $callback) {\n\
    try {\n\
        $callback();\n\
    } catch (Throwable $e) {\n\
        echo get_class($e), ': ', $e->getMessage(), \"\\n\";\n\
    }\n\
}\n\
dump_exception(fn() => mb_convert_encoding('foo', $encoding, $encoding));\n\
dump_exception(fn() => mb_convert_encoding('foo', $alias, $alias));\n\
dump_exception(fn() => mb_detect_encoding('foo', $encoding));\n\
dump_exception(fn() => mb_detect_encoding('foo', $alias));\n\
dump_exception(fn() => mb_convert_variables($encoding, $alias, $var));\n\
dump_exception(fn() => mb_detect_order($encoding));\n\
dump_exception(fn() => mb_detect_order($alias));\n",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "ValueError: mb_convert_encoding(): Argument #3 ($from_encoding) contains invalid encoding \"UTF-8\"\n",
            "ValueError: mb_convert_encoding(): Argument #3 ($from_encoding) contains invalid encoding \"binary\"\n",
            "ValueError: mb_detect_encoding(): Argument #2 ($encodings) contains invalid encoding \"UTF-8\"\n",
            "ValueError: mb_detect_encoding(): Argument #2 ($encodings) contains invalid encoding \"binary\"\n",
            "ValueError: mb_convert_variables(): Argument #2 ($from_encoding) contains invalid encoding \"binary\"\n",
            "ValueError: mb_detect_order(): Argument #1 ($encoding) contains invalid encoding \"UTF-8\"\n",
            "ValueError: mb_detect_order(): Argument #1 ($encoding) contains invalid encoding \"binary\"\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_mbstring_detect_order_validation_to_native_binary() {
    let root = temp_dir("ptn-native-mb-detect-order-validation");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("mb-detect-order-validation.php");
    let output = root.join("mb-detect-order-validation-bin");
    fs::write(
        &input,
        "<?php\n\
function dump_error(callable $callback) {\n\
    try {\n\
        $callback();\n\
    } catch (Throwable $e) {\n\
        echo $e->getMessage(), \"\\n\";\n\
    }\n\
}\n\
function dump_order() {\n\
    echo implode(', ', mb_detect_order()), \"\\n\";\n\
}\n\
dump_error(fn() => mb_detect_order(''));\n\
dump_error(fn() => mb_detect_order([]));\n\
mb_language('Japanese');\n\
var_dump(mb_detect_order('auto'));\n\
dump_order();\n\
var_dump(mb_detect_order('SJIS,EUC-JP,JIS,UTF-8'));\n\
dump_order();\n\
dump_error(fn() => mb_detect_order('BAD_NAME'));\n\
dump_error(fn() => mb_detect_order(['ASCII', 'BAD_NAME']));\n\
$value = 'text';\n\
dump_error(fn() => mb_convert_variables('UTF-8', [], $value));\n\
ini_set('mbstring.detect_order', 'UTF-8, ISO-8859-1, ASCII');\n\
dump_order();\n\
ini_set('mbstring.detect_order', 'UTF-8');\n\
dump_order();\n\
ini_set('mbstring.detect_order', '');\n\
dump_order();\n",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "mb_detect_order(): Argument #1 ($encoding) must specify at least one encoding\n",
            "mb_detect_order(): Argument #1 ($encoding) must specify at least one encoding\n",
            "bool(true)\n",
            "ASCII, JIS, UTF-8, EUC-JP, SJIS\n",
            "bool(true)\n",
            "SJIS, EUC-JP, JIS, UTF-8\n",
            "mb_detect_order(): Argument #1 ($encoding) contains invalid encoding \"BAD_NAME\"\n",
            "mb_detect_order(): Argument #1 ($encoding) contains invalid encoding \"BAD_NAME\"\n",
            "mb_convert_variables(): Argument #2 ($from_encoding) must specify at least one encoding\n",
            "UTF-8, ISO-8859-1, ASCII\n",
            "UTF-8\n",
            "UTF-8\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn phpc_mbstring_residual_state_and_diagnostics_edges() {
    let root = temp_dir("ptn-phpc-mbstring-residual-edges");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("mbstring-residual-edges.php");
    fs::write(
        &input,
        "<?php\n\
echo mb_convert_case(\"People's issues versus people’s issues\", MB_CASE_TITLE, 'UTF-8'), \"\\n\";\n\
try {\n\
    var_dump(mb_convert_encoding(\"\", \"UTF-8\", [0]));\n\
} catch (ValueError $e) {\n\
    echo $e->getMessage(), \"\\n\";\n\
}\n\
try {\n\
    var_dump(mb_convert_encoding('foo', 'UTF-8', [['bar'], ['baz']]));\n\
} catch (ValueError $e) {\n\
    echo $e->getMessage(), \"\\n\";\n\
}\n\
var_dump(mb_internal_encoding());\n\
var_dump(mb_strlen(\"\\xc3\\xb6\"));\n\
ini_set('mbstring.internal_encoding', 'utf-8');\n\
var_dump(mb_internal_encoding());\n\
var_dump(mb_strlen(\"\\xc3\\xb6\"));\n\
ini_set('internal_encoding', 'iso-8859-2');\n\
var_dump(mb_internal_encoding());\n\
var_dump(mb_strlen(\"\\xc3\\xb6\"));\n\
ini_set('mbstring.internal_encoding', '');\n\
var_dump(mb_internal_encoding());\n\
var_dump(mb_strlen(\"\\xc3\\xb6\"));\n\
mb_internal_encoding('utf-8');\n\
var_dump(mb_internal_encoding());\n\
var_dump(mb_strlen(\"\\xc3\\xb6\"));\n\
ini_set('internal_encoding', 'iso-8859-3');\n\
var_dump(mb_internal_encoding());\n\
var_dump(mb_strlen(\"\\xc3\\xb6\"));\n\
ini_set('mbstring.internal_encoding', '');\n\
var_dump(mb_internal_encoding());\n\
var_dump(mb_strlen(\"\\xc3\\xb6\"));\n\
var_dump(mb_strimwidth('some string', 1, -2, '...', 'ASCII'));\n",
    )
    .unwrap();

    let execution = Command::new(env!("CARGO_BIN_EXE_phpc"))
        .arg("-d")
        .arg("error_reporting=32767")
        .arg("-d")
        .arg("internal_encoding=iso-8859-1")
        .arg("-f")
        .arg(&input)
        .output()
        .unwrap();
    assert!(execution.status.success());
    let stdout = String::from_utf8(execution.stdout).unwrap();
    assert!(
        stdout.contains("People's Issues Versus People’s Issues\n"),
        "{stdout}"
    );
    assert!(
        stdout.contains(
            "mb_convert_encoding(): Argument #3 ($from_encoding) contains invalid encoding \"0\"\n"
        ),
        "{stdout}"
    );
    assert!(
        stdout.contains("\nWarning: Array to string conversion in ptn on line "),
        "{stdout}"
    );
    assert!(
        stdout.contains("mb_convert_encoding(): Argument #3 ($from_encoding) contains invalid encoding \"Array\"\n"),
        "{stdout}"
    );
    assert_eq!(
        stdout
            .matches("Deprecated: ini_set(): Use of mbstring.internal_encoding is deprecated")
            .count(),
        3,
        "{stdout}"
    );
    assert!(
        stdout.contains("string(10) \"ISO-8859-1\"\nint(2)\n"),
        "{stdout}"
    );
    assert!(
        stdout.contains("string(5) \"UTF-8\"\nint(1)\nstring(5) \"UTF-8\"\nint(1)\n"),
        "{stdout}"
    );
    assert!(
        stdout.contains("string(10) \"ISO-8859-2\"\nint(2)\n"),
        "{stdout}"
    );
    assert!(
        stdout.contains("string(10) \"ISO-8859-3\"\nint(2)\n"),
        "{stdout}"
    );
    assert!(
        stdout.contains("Deprecated: mb_strimwidth(): passing a negative integer to argument #3 ($width) is deprecated"),
        "{stdout}"
    );
    assert!(stdout.contains("string(8) \"ome s...\"\n"), "{stdout}");
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

