#[test]
fn compile_preg_replace_callback_array_and_match_debug_refcounts_to_native_binary() {
    let root = temp_dir("ptn-native-preg-replace-callback-array-debug");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("preg-replace-callback-array-debug.php");
    let output = root.join("preg-replace-callback-array-debug-bin");
    fs::write(
        &input,
        "<?php
var_dump(function_exists('preg_replace_callback_array'));
var_dump(preg_replace_callback('/(.)(.)(.)/', static function ($matches) {
    debug_zval_dump($matches);
    return '';
}, 'abc'));
$count = 0;
var_dump(preg_replace_callback_array([
    '/a/' => static function ($matches) { return 'A'; },
    '/b/' => static function ($matches) { return 'B'; },
], 'abc', -1, $count));
var_dump($count);
var_dump(preg_replace_callback_array(['/(.)(.)(.)/' => static function ($matches) {
    debug_zval_dump($matches);
    return '';
}], 'abc'));
",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    let stdout = String::from_utf8(execution.stdout).unwrap();
    assert!(stdout.starts_with("bool(true)\n"), "{stdout:?}");
    assert_eq!(stdout.matches("array(4) packed refcount(2){").count(), 2);
    assert_eq!(stdout.matches("string(1) \"a\" interned").count(), 2);
    assert_eq!(stdout.matches("string(1) \"b\" interned").count(), 2);
    assert_eq!(stdout.matches("string(1) \"c\" interned").count(), 2);
    assert!(stdout.contains("string(3) \"ABc\"\nint(2)\n"), "{stdout:?}");
    assert_eq!(stdout.matches("string(0) \"\"").count(), 2);
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_preg_replace_callback_array_pattern_errors_to_native_binary() {
    let root = temp_dir("ptn-native-preg-replace-callback-array-pattern-errors");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("preg-replace-callback-array-pattern-errors.php");
    let output = root.join("preg-replace-callback-array-pattern-errors-bin");
    fs::write(
        &input,
        "<?php
class TrampolineTarget {
    public function __call(string $name, array $arguments): string {
        echo 'callback ', $name, PHP_EOL;
        return 'X';
    }
}
$target = new TrampolineTarget();

function report($callback) {
    try {
        var_dump($callback());
    } catch (Throwable $e) {
        echo $e::class, ': ', $e->getMessage(), PHP_EOL;
    }
}

report(fn() => preg_replace_callback([new stdClass()], [$target, 'trampoline'], 'a'));
report(fn() => preg_replace_callback('/a/', function ($matches) {
    throw new Exception('boom');
}, ['a', ['b']]));
report(fn() => preg_replace_callback_array([
    '/a/' => [$target, 'trampoline'],
    '/X/' => new stdClass(),
], 'a'));
",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    let stdout = String::from_utf8(execution.stdout).unwrap();
    assert!(stdout.contains("Error: Object of class stdClass could not be converted to string\n"));
    assert!(stdout.contains("Warning: Array to string conversion"));
    assert!(stdout.contains("Exception: boom\n"));
    assert!(
        stdout.find("Warning: Array to string conversion").unwrap()
            < stdout.find("Exception: boom\n").unwrap(),
        "{stdout:?}"
    );
    assert!(stdout.contains(
        "callback trampoline\nTypeError: preg_replace_callback_array(): Argument #1 ($pattern) must contain only valid callbacks\n"
    ));
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

