    fs::write(
        &input,
        "<?php
class B {
    public function __destruct() {
        echo \"B\\n\";
    }
}

class A {
    public static $b;
    public static $new;
    public static $max = 4;

    public function __destruct() {
        if (self::$max-- <= 0) {
            return;
        }
        echo \"A\\n\";
        self::$b = new B;
        self::$new[] = new A;
    }
}

new A;
",
    )
