#[test]
fn parser_reports_late_static_class_name_row_diagnostics() {
    for source in [
        "<?php class static {}",
        "<?php interface static {}",
        "<?php trait static {}",
    ] {
        let error = parser::parse(source).unwrap_err();
        assert_eq!(
            error.message, "syntax error, unexpected token \"static\", expecting T_STRING",
            "{source}"
        );
        assert_eq!(error.kind, DiagnosticKind::ParseError, "{source}");
    }

    let invalid_class = parser::parse("<?php []::X::X;").unwrap_err();
    assert_eq!(invalid_class.message, "Illegal class name");
    assert_eq!(invalid_class.kind, DiagnosticKind::Fatal);
}

#[test]
fn compile_declared_class_metadata_intrinsics_to_native_binary() {
    let root = temp_dir("ptn-native-declared-class-metadata-intrinsics");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("declared-class-metadata-intrinsics.php");
    let output = root.join("declared-class-metadata-intrinsics-bin");
    fs::write(
        &input,
        "<?php
interface Contract {
    const MARK = \"contract\";
}

const LOOKUP_CONST = \"value\";

function lookup_func() {
    return null;
}

class BaseWorker {
}

class Worker extends BaseWorker implements Contract {
    public function Run($value) {
        return $value;
    }

    public static function StaticWork() {
    }
}

$worker = new Worker();
$callback = function () { return null; };
var_dump(class_exists(\"Worker\"));
var_dump(class_exists(\"worker\"));
var_dump(class_exists(\"\\\\Worker\"));
var_dump(class_exists(\"Missing\", false));
var_dump(class_exists(\"stdClass\"));
var_dump(interface_exists(\"Contract\"));
var_dump(interface_exists(\"\\\\Contract\"));
var_dump(interface_exists(\"Missing\"));
var_dump(interface_exists(\"ArrayAccess\"));
var_dump(interface_exists(\"SplObserver\"));
var_dump(interface_exists(\"\\\\SplSubject\"));
var_dump(method_exists(\"Worker\", \"run\"));
var_dump(method_exists($worker, \"RUN\"));
var_dump(method_exists(\"Worker\", \"staticwork\"));
var_dump(method_exists(\"Worker\", \"missing\"));
var_dump(method_exists(\"stdClass\", \"anything\"));
var_dump(get_class($worker));
var_dump(get_class(new stdClass));
var_dump(get_class($callback));
var_dump(get_parent_class($worker));
var_dump(get_parent_class(\"worker\"));
var_dump(get_parent_class(\"Contract\"));
var_dump(get_parent_class(new stdClass));
try {
    get_class(42);
} catch (TypeError $e) {
    echo get_class($e), \": \", $e->getMessage(), \"\\n\";
}
try {
    get_parent_class([]);
} catch (TypeError $e) {
    echo get_class($e), \": \", $e->getMessage(), \"\\n\";
}
var_dump(function_exists(\"get_class\"));
var_dump(function_exists(\"interface_exists\"));
var_dump(function_exists(\"\\\\lookup_func\"));
var_dump(defined(\"\\\\LOOKUP_CONST\"));
var_dump(constant(\"\\\\LOOKUP_CONST\"));
var_dump(defined(\"Worker::MARK\"));
var_dump(constant(\"Worker::MARK\"));
spl_autoload_register(function($name) {
    echo \"lookup:\", $name, \"\\n\";
});
var_dump(is_a(\"AutoloadMissing\", \"Worker\", true));
var_dump(is_subclass_of(\"AutoloadMissing2\", \"Worker\"));
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(false)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(false)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(false)\n",
            "bool(false)\n",
            "string(6) \"Worker\"\n",
            "string(8) \"stdClass\"\n",
            "string(7) \"Closure\"\n",
            "string(10) \"BaseWorker\"\n",
            "string(10) \"BaseWorker\"\n",
            "bool(false)\n",
            "bool(false)\n",
            "TypeError: get_class(): Argument #1 ($object) must be of type object, int given\n",
            "TypeError: get_parent_class(): Argument #1 ($object_or_class) must be an object or a valid class name, array given\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "string(5) \"value\"\n",
            "bool(true)\n",
            "string(8) \"contract\"\n",
            "lookup:AutoloadMissing\n",
            "bool(false)\n",
            "lookup:AutoloadMissing2\n",
            "bool(false)\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("static int ptn_declared_class_exists("));
    assert!(c_source.contains("static int ptn_declared_interface_exists("));
    assert!(c_source.contains("static int ptn_declared_class_method_exists("));
    assert!(c_source.contains("static PTN_UNUSED const char *ptn_declared_class_parent_name("));
    assert!(c_source.contains("ptn_internal_class_exists"));
    assert!(c_source.contains("ptn_internal_get_class"));
    assert!(c_source.contains("ptn_internal_get_parent_class"));
    assert!(c_source.contains("ptn_internal_interface_exists"));
    assert!(c_source.contains("ptn_internal_method_exists"));
}

