#[test]
fn compile_class_object_metadata_lists_to_native_binary() {
    let root = temp_dir("ptn-native-class-object-metadata-lists");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("class-object-metadata-lists.php");
    let output = root.join("class-object-metadata-lists-bin");
    fs::write(
        &input,
        "<?php
interface Contract {
    public function pubI();
}

trait ListedTrait {
}

class BaseList {
    private function privBase() {}
    protected function protBase() {}
    public function pubBase() {}
}

class WorkerList extends BaseList implements Contract {
    use ListedTrait;

    public function pubI() {}
    private function privWorker() {}
    protected function protWorker() {}
    public function pubWorker() {}

    public static function fromWorker() {
        dump_methods(get_class_methods(\"WorkerList\"));
        dump_methods(get_class_methods(\"BaseList\"));
    }
}

class PeerList {
    public static function fromPeer() {
        dump_methods(get_class_methods(\"WorkerList\"));
    }
}

class StringBox {
    public function __toString() {
        return \"box\";
    }
}

interface IOrder1 {}
interface IOrder2 {}
interface IOrder3 {}
interface IOrder4 extends IOrder3 {}
interface IOrder5 extends IOrder4 {}
interface IOrder6 extends IOrder5, IOrder1, IOrder2 {}
interface IOrder7 extends IOrder6 {}
class InterfaceOrderSubject implements IOrder7 {}

function dump_methods($methods) {
    foreach ($methods as $method) {
        echo $method, \"|\";
    }
    echo \"\\n\";
}

function dump_assoc($items) {
    foreach ($items as $key => $value) {
        echo $key, \"=\", $value, \"|\";
    }
    echo \"\\n\";
}

dump_methods(get_class_methods(\"WorkerList\"));
WorkerList::fromWorker();
PeerList::fromPeer();
dump_assoc(class_parents(\"WorkerList\"));
dump_assoc(class_parents(new WorkerList()));
dump_assoc(class_implements(\"WorkerList\"));
dump_assoc(class_implements(new WorkerList()));
dump_assoc(class_uses(\"WorkerList\"));
dump_assoc(class_uses(new WorkerList()));
dump_assoc(class_uses(\"BaseList\"));
dump_assoc(class_implements(new StringBox()));
dump_assoc((new ReflectionClass(\"StringBox\"))->getInterfaceNames());
dump_assoc((new ReflectionClass(\"IOrder7\"))->getInterfaceNames());
dump_assoc((new ReflectionClass(\"InterfaceOrderSubject\"))->getInterfaceNames());
var_dump(in_array(\"WorkerList\", get_declared_classes()));
var_dump(in_array(\"Contract\", get_declared_interfaces()));
var_dump(in_array(\"ListedTrait\", get_declared_traits()));
var_dump(in_array(\"Contract\", get_declared_classes()));
var_dump(in_array(\"WorkerList\", get_declared_interfaces()));
var_dump(in_array(\"WorkerList\", get_declared_traits()));
var_dump(is_a(new WorkerList(), \"BaseList\"));
var_dump(is_a(\"WorkerList\", \"BaseList\"));
var_dump(is_a(\"WorkerList\", \"BaseList\", true));
var_dump(is_a(\"WorkerList\", \"Contract\", true));
var_dump(is_a(\"WorkerList\", \"WorkerList\", true));
var_dump(is_a(\"Missing\", \"Missing\", true));
var_dump(method_exists(\"WorkerList\", \"privBase\"));
var_dump(method_exists(new WorkerList(), \"privBase\"));
var_dump(method_exists(\"WorkerList\", \"privWorker\"));
try {
    get_class_methods(\"MissingList\");
} catch (TypeError $e) {
    echo get_class($e), \": \", $e->getMessage(), \"\\n\";
}
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "pubI|pubWorker|fromWorker|pubBase|\n",
            "pubI|privWorker|protWorker|pubWorker|fromWorker|protBase|pubBase|\n",
            "protBase|pubBase|\n",
            "pubI|pubWorker|fromWorker|pubBase|\n",
            "BaseList=BaseList|\n",
            "BaseList=BaseList|\n",
            "Contract=Contract|\n",
            "Contract=Contract|\n",
            "ListedTrait=ListedTrait|\n",
            "ListedTrait=ListedTrait|\n",
            "\n",
            "Stringable=Stringable|\n",
            "0=Stringable|\n",
            "0=IOrder6|1=IOrder4|2=IOrder3|3=IOrder2|4=IOrder1|5=IOrder5|\n",
            "0=IOrder7|1=IOrder5|2=IOrder1|3=IOrder2|4=IOrder3|5=IOrder4|6=IOrder6|\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(false)\n",
            "bool(false)\n",
            "bool(false)\n",
            "bool(true)\n",
            "bool(false)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(false)\n",
            "bool(false)\n",
            "bool(true)\n",
            "bool(true)\n",
            "TypeError: get_class_methods(): Argument #1 ($object_or_class) must be an object or a valid class name, string given\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_declared_class_method_names"));
    assert!(c_source.contains("ptn_declared_class_method_exists_from_class_name"));
    assert!(c_source.contains("ptn_declared_class_parent_names"));
    assert!(c_source.contains("ptn_declared_class_interface_names"));
    assert!(c_source.contains("ptn_declared_class_trait_names"));
    assert!(c_source.contains("ptn_internal_get_declared_classes"));
    assert!(c_source.contains("ptn_internal_is_a"));
}

#[test]
fn compile_reflection_class_trait_metadata_to_native_binary() {
    let root = temp_dir("ptn-native-reflection-class-trait-metadata");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("reflection-class-trait-metadata.php");
    let output = root.join("reflection-class-trait-metadata-bin");
    fs::write(
        &input,
        "<?php
trait T1 {
    public function m1() {}
    public function m2() {}
}
trait T2 {
    public function run() {}
    public function say() {}
}
trait T3 {
    public function run() {}
    public function say() {}
}

class NoTraits {}
class OneTrait {
    use T1;
}
class OneAlias {
    use T1 {
        m1 as a1;
    }
}
class TwoAliases {
    use T1 {
        m1 as a1;
        m2 as a2;
    }
}
class MultiTrait {
    use T2, T3 {
        T2::run as execute;
        T2::say insteadof T3;
        T3::run insteadof T2;
        T3::say as talk;
    }
}

function dump_list($items) {
    foreach ($items as $key => $value) {
        echo $key, '=', $value, '|';
    }
    echo \"\\n\";
}

function dump_trait_objects($class) {
    foreach ((new ReflectionClass($class))->getTraits() as $name => $reflection) {
        echo $name, '=', $reflection->getName(), ':', get_class($reflection), '|';
    }
    echo \"\\n\";
}

dump_list((new ReflectionClass('NoTraits'))->getTraitNames());
dump_list((new ReflectionClass('OneTrait'))->getTraitNames());
dump_list((new ReflectionClass('NoTraits'))->getTraitAliases());
dump_list((new ReflectionClass('OneAlias'))->getTraitAliases());
dump_list((new ReflectionClass('TwoAliases'))->getTraitAliases());
dump_list((new ReflectionClass('MultiTrait'))->getTraitAliases());
dump_trait_objects('MultiTrait');
var_dump((new ReflectionClass('T1'))->isTrait());
var_dump((new ReflectionClass('TwoAliases'))->isTrait());
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "\n",
            "0=T1|\n",
            "\n",
            "a1=T1::m1|\n",
            "a1=T1::m1|a2=T1::m2|\n",
            "execute=T2::run|talk=T3::say|\n",
            "T2=T2:ReflectionClass|T3=T3:ReflectionClass|\n",
            "bool(true)\n",
            "bool(false)\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_declared_class_reflection_trait_aliases"));
    assert!(c_source.contains("ptn_declared_class_reflection_traits"));
    assert!(c_source.contains("ptn_reflection_class_call_method"));
}

