fn compile_conditional_class_metadata_visibility_to_native_binary() {
    let root = temp_dir("ptn-native-conditional-class-metadata-visibility");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("conditional-class-metadata-visibility.php");
    let output = root.join("conditional-class-metadata-visibility-bin");
    fs::write(
        &input,
        "<?php
function declare_local_class() {
    var_dump(class_exists('FunctionLocalClass', false));
    class FunctionLocalClass {
        public static function value() {
            return 'fn';
        }
    }
    var_dump(class_exists('FunctionLocalClass', false));
}

$closure = function () {
    interface ClosureLocalContract {}
    class ClosureLocalClass implements ClosureLocalContract {}
};

var_dump(class_exists('FunctionLocalClass', false));
var_dump(in_array('FunctionLocalClass', get_declared_classes()));
declare_local_class();
var_dump(in_array('FunctionLocalClass', get_declared_classes()));
var_dump(FunctionLocalClass::value());
var_dump(interface_exists('ClosureLocalContract', false));
var_dump(in_array('ClosureLocalContract', get_declared_interfaces()));
$closure();
var_dump(interface_exists('ClosureLocalContract', false));
var_dump(class_exists('ClosureLocalClass', false));
var_dump(in_array('ClosureLocalContract', get_declared_interfaces()));
var_dump(in_array('ClosureLocalClass', get_declared_classes()));
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "bool(false)\n",
            "bool(false)\n",
            "bool(false)\n",
            "bool(true)\n",
            "bool(true)\n",
            "string(2) \"fn\"\n",
            "bool(false)\n",
            "bool(false)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_declared_class_exists"));
    assert!(c_source.contains("ptn_declared_runtime_interface_exists"));
    assert!(c_source.contains("ptn_declared_user_classes"));
}

#[test]
fn compile_autoload_declares_function_local_enum_to_native_binary() {
    let root = temp_dir("ptn-native-autoload-function-local-enum");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("autoload-function-local-enum.php");
    let output = root.join("autoload-function-local-enum-bin");
    fs::write(
        &input,
        "<?php
enum Foo {
    case Bar;
}

class Baz {}

spl_autoload_register(function ($className) {
    echo \"Triggered autoloader with class $className\\n\";

    if ($className === 'Quux') {
        enum Quux {}
    }
});

var_dump(enum_exists(Foo::class));
var_dump(enum_exists(Foo::Bar::class));
var_dump(enum_exists(Baz::class));
var_dump(enum_exists(Qux::class));
var_dump(enum_exists(Quux::class, false));
var_dump(enum_exists(Quux::class, true));
var_dump(enum_exists(Quuz::class, false));
var_dump(enum_exists(Quuz::class, true));
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "bool(true)\n",
            "bool(true)\n",
            "bool(false)\n",
            "Triggered autoloader with class Qux\n",
            "bool(false)\n",
            "bool(false)\n",
            "Triggered autoloader with class Quux\n",
            "bool(true)\n",
            "bool(false)\n",
            "Triggered autoloader with class Quuz\n",
            "bool(false)\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_internal_enum_exists"));
    assert!(c_source.contains("ptn_declared_runtime_class_exists"));
}

#[test]
fn compile_reflection_enum_to_string_metadata_to_native_binary() {
    let root = temp_dir("ptn-native-reflection-enum-to-string-metadata");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("reflection-enum-to-string-metadata.php");
    let output = root.join("reflection-enum-to-string-metadata-bin");
    fs::write(
        &input,
        "<?php
interface MyStringable {
    public function toString(): string;
}

enum Suit: string implements MyStringable {
    case Hearts = 'H';
    case Spades = 'S';

    public function toString(): string {
        return $this->name;
    }
}

enum EmptySuit {}

echo new ReflectionClass(Suit::class);
echo \"---\\n\";
echo new ReflectionEnum(Suit::class);
$empty = new ReflectionClass(EmptySuit::class);
echo \"===empty===\\n\";
echo $empty;
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    let stdout = String::from_utf8(execution.stdout).unwrap();
    let reflection_outputs = stdout.split("---\n").collect::<Vec<_>>();
    assert_eq!(reflection_outputs.len(), 2, "{stdout}");
    assert!(
        reflection_outputs[0].contains("  - Enum cases [2] {"),
        "{stdout}"
    );
    assert!(
        reflection_outputs[1].contains("  - Enum cases [2] {"),
        "{stdout}"
    );
    assert_eq!(
        stdout.matches("  - Enum cases [2] {").count(),
        2,
        "{stdout}"
    );
    assert_eq!(stdout.matches("Case Hearts = H").count(), 2, "{stdout}");
    assert_eq!(stdout.matches("Case Spades = S").count(), 2, "{stdout}");
    assert!(
        stdout.contains("Enum [ <user> enum EmptySuit implements UnitEnum ]"),
        "{stdout}"
    );
    let empty_tail = stdout
        .split("===empty===\n")
        .nth(1)
        .unwrap_or_else(|| panic!("missing empty enum reflection marker in {stdout}"));
    assert!(!empty_tail.contains("  - Enum cases [0] {"), "{stdout}");
    assert!(empty_tail.contains("  - Constants [0] {"), "{stdout}");
    assert_eq!(
        stdout
            .matches("Method [ <user, prototype MyStringable> public method toString ]")
            .count(),
        2,
        "{stdout}"
    );
    assert_eq!(
        stdout
            .matches("      - Parameters [0] {\n      }\n      - Return [ string ]")
            .count(),
        2,
        "{stdout}"
    );
    assert!(
        stdout.contains("reflection-enum-to-string-metadata.php 10 - 12"),
        "{stdout}"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_declared_class_is_enum(class_name)"));
    assert!(c_source.contains("prototype MyStringable"));
}

