#[test]
fn parser_rejects_resolved_trait_property_default_mismatch() {
    let program = parser::parse(
        "<?php
const VALUE = true;
trait FooMismatch {
    public $var = VALUE;
}
trait BarMismatch {
    public $var = false;
}
class BazMismatch {
    use FooMismatch, BarMismatch;
}
",
    )
    .unwrap();

    let fatal = &program.classes[0].declaration_fatals[0];
    assert!(fatal
        .message
        .contains("FooMismatch and BarMismatch define the same property ($var)"));
}

#[test]
fn compile_get_class_legacy_scope_edges_to_native_binary() {
    let root = temp_dir("ptn-native-get-class-legacy-scope-edges");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("get-class-legacy-scope-edges.php");
    let output = root.join("get-class-legacy-scope-edges-bin");
    fs::write(
        &input,
        "<?php
class Ancestor {
}
class Base extends Ancestor {
    public function legacy() {
        var_dump(get_class());
        var_dump(get_parent_class());
        $name = \"get_class\";
        var_dump($name());
        var_dump(call_user_func(\"get_parent_class\"));
    }
}
class Child extends Base {
    public static function staticScope() {
        var_dump(get_class());
        var_dump(get_parent_class());
    }
    public function closureScope() {
        $fn = function () {
            var_dump(get_class());
            var_dump(get_parent_class());
        };
        $fn();
    }
}
(new Child())->legacy();
Child::staticScope();
(new Child())->closureScope();
try {
    var_dump(get_class());
} catch (Error $e) {
    echo get_class($e), \": \", $e->getMessage(), \"\\n\";
}
var_dump(get_parent_class());
try {
    get_parent_class(\"missing\");
} catch (TypeError $e) {
    echo get_class($e), \": \", $e->getMessage(), \"\\n\";
}
try {
    get_class(new stdClass, 1);
} catch (ArgumentCountError $e) {
    echo get_class($e), \": \", $e->getMessage(), \"\\n\";
}
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "\nDeprecated: Calling get_class() without arguments is deprecated in ptn on line 6\n",
            "string(4) \"Base\"\n",
            "\nDeprecated: Calling get_parent_class() without arguments is deprecated in ptn on line 7\n",
            "string(8) \"Ancestor\"\n",
            "\nDeprecated: Calling get_class() without arguments is deprecated in ptn on line 9\n",
            "string(4) \"Base\"\n",
            "\nDeprecated: Calling get_parent_class() without arguments is deprecated in ptn on line 10\n",
            "string(8) \"Ancestor\"\n",
            "\nDeprecated: Calling get_class() without arguments is deprecated in ptn on line 15\n",
            "string(5) \"Child\"\n",
            "\nDeprecated: Calling get_parent_class() without arguments is deprecated in ptn on line 16\n",
            "string(4) \"Base\"\n",
            "\nDeprecated: Calling get_class() without arguments is deprecated in ptn on line 20\n",
            "string(5) \"Child\"\n",
            "\nDeprecated: Calling get_parent_class() without arguments is deprecated in ptn on line 21\n",
            "string(4) \"Base\"\n",
            "Error: get_class() without arguments must be called from within a class\n",
            "bool(false)\n",
            "TypeError: get_parent_class(): Argument #1 ($object_or_class) must be an object or a valid class name, string given\n",
            "ArgumentCountError: get_class() expects at most 1 argument, 2 given\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("runtime.current_class_name"));
    assert!(c_source.contains("ptn_internal_get_class"));
    assert!(c_source.contains("ptn_internal_get_parent_class"));
}

#[test]
fn compile_spl_object_identity_intrinsics_to_native_binary() {
    let root = temp_dir("ptn-native-spl-object-identity-intrinsics");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("spl-object-identity-intrinsics.php");
    let output = root.join("spl-object-identity-intrinsics-bin");
    fs::write(
        &input,
        "<?php
class Worker {}

$worker = new Worker();
$std = new stdClass();
$closure = function () { return null; };
var_dump(spl_object_id($worker));
var_dump(spl_object_id($std));
var_dump(spl_object_id($closure));
var_dump(spl_object_id($worker));
var_dump(spl_object_hash($worker));
var_dump(spl_object_hash($std));
var_dump(function_exists(\"spl_object_id\"), function_exists(\"SPL_OBJECT_HASH\"));
try {
    spl_object_id(42);
} catch (TypeError $e) {
    var_dump(is_object($e));
    var_dump(spl_object_id($e));
    echo get_class($e), \": \", $e->getMessage(), \"\\n\";
}
try {
    spl_object_hash(null);
} catch (TypeError $e) {
    echo get_class($e), \": \", $e->getMessage(), \"\\n\";
}
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "int(1)\n",
            "int(2)\n",
            "int(3)\n",
            "int(1)\n",
            "string(32) \"00000000000000010000000000000000\"\n",
            "string(32) \"00000000000000020000000000000000\"\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "int(4)\n",
            "TypeError: spl_object_id(): Argument #1 ($object) must be of type object, int given\n",
            "TypeError: spl_object_hash(): Argument #1 ($object) must be of type object, null given\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_internal_spl_object_id"));
    assert!(c_source.contains("ptn_internal_spl_object_hash"));
    assert!(c_source.contains("ptn_runtime_alloc_object_id"));
}

