#[test]
fn compile_reflection_internal_subclasses_to_native_binary() {
    let root = temp_dir("ptn-native-reflection-internal-subclasses");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("reflection-internal-subclasses.php");
    let output = root.join("reflection-internal-subclasses-bin");
    fs::write(
        &input,
        "<?php
class ReflectionClassEx extends ReflectionClass
{
    public $bla;

    function getMethodNames()
    {
        $res = array();
        foreach ($this->getMethods() as $m) {
            $res[] = $m->class . '::' . $m->name;
        }
        sort($res);
        return $res;
    }
}

$rc = new ReflectionClassEx('ReflectionClassEx');
$props = array_keys(get_class_vars('ReflectionClassEx'));
sort($props);
var_dump($props);
var_dump($rc->name);
var_dump($rc->getName());
var_dump(in_array('ReflectionClassEx::getMethodNames', $rc->getMethodNames(), true));

#[AllowDynamicProperties]
class ReflectionMethodEx extends ReflectionMethod
{
    public $foo = 'xyz';

    function __construct($c, $m)
    {
        echo __METHOD__ . \"\\n\";
        parent::__construct($c, $m);
    }
}

$rm = new ReflectionMethodEx('ReflectionMethodEx', 'getName');
var_dump($rm->class);
var_dump($rm->name);
var_dump($rm->foo);
var_dump($rm->bar ?? null);

try {
    $rm->class = 'bullshit';
} catch (ReflectionException $e) {
    echo $e->getMessage() . \"\\n\";
}

try {
    $rm->name = 'bullshit';
} catch (ReflectionException $e) {
    echo $e->getMessage() . \"\\n\";
}

$rm->foo = 'bar';
$rm->bar = 'baz';

var_dump($rm->class);
var_dump($rm->name);
var_dump($rm->foo);
var_dump($rm->bar);
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "array(2) {\n",
            "  [0]=>\n",
            "  string(3) \"bla\"\n",
            "  [1]=>\n",
            "  string(4) \"name\"\n",
            "}\n",
            "string(17) \"ReflectionClassEx\"\n",
            "string(17) \"ReflectionClassEx\"\n",
            "bool(true)\n",
            "ReflectionMethodEx::__construct\n",
            "string(26) \"ReflectionFunctionAbstract\"\n",
            "string(7) \"getName\"\n",
            "string(3) \"xyz\"\n",
            "NULL\n",
            "Cannot set read-only property ReflectionMethodEx::$class\n",
            "Cannot set read-only property ReflectionMethodEx::$name\n",
            "string(26) \"ReflectionFunctionAbstract\"\n",
            "string(7) \"getName\"\n",
            "string(3) \"bar\"\n",
            "string(3) \"baz\"\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_adopt_internal_parent_object_state"));
    assert!(c_source.contains("ReflectionFunctionAbstract"));
}

#[test]
fn compile_reflection_method_metadata_to_native_binary() {
    let root = temp_dir("ptn-native-reflection-method-metadata");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("reflection-method-metadata.php");
    let output = root.join("reflection-method-metadata-bin");
    fs::write(
        &input,
        "<?php
class ReflectBaseMethod {
    protected function inherited() {}
    public function overridden() {}
}

class ReflectMethodSubject extends ReflectBaseMethod {
    public static function stat() {}
    public function fresh() {}
    public function overridden() {}
    private function hidden() {}
    public function __construct() {}
}

trait ReflectMethodTrait {
    public function traitMethod() {}
}

class ReflectMethodFactoryEx extends ReflectionMethod {}

class ReflectMethodFactoryOverride extends ReflectionMethod {
    public static function createFromMethodName($method) {
        return \"override:\" . $method;
    }
}

enum ReflectMethodEnum {
    case A;

    public function enumMethod() {}
}

interface ReflectPrototypeInterfaceA {
    function viaInterface();
    function inheritedViaInterface();
}

interface ReflectPrototypeInterfaceB {
    function viaInterface();
}

class ReflectPrototypeParent {
    public function inheritedViaInterface() {}
}

class ReflectPrototypeChild extends ReflectPrototypeParent implements ReflectPrototypeInterfaceA, ReflectPrototypeInterfaceB {
    public function viaInterface() {}
}

class ReflectPlainParent {
    public function plainInherited() {}
}

class ReflectPlainChild extends ReflectPlainParent {}

class ReflectParentPrototypeA {
    public function f() {}
}

class ReflectParentPrototypeB extends ReflectParentPrototypeA {
    public function f() {}
}

class ReflectParentPrototypeC extends ReflectParentPrototypeB {}

$inherited = new ReflectionMethod(\"ReflectMethodSubject\", \"inherited\");
var_dump($inherited->getName());
var_dump($inherited->getDeclaringClass()->getName());
var_dump($inherited->isProtected());
var_dump($inherited->isStatic());
var_dump($inherited->isUserDefined());

$overridden = new ReflectionMethod(\"ReflectMethodSubject\", \"overridden\");
$prototype = $overridden->getPrototype();
var_dump($overridden->hasPrototype());
var_dump($prototype->class);
var_dump($prototype->name);

$fresh = new ReflectionMethod(\"ReflectMethodSubject\", \"fresh\");
var_dump($fresh->hasPrototype());

$static = ReflectionMethod::createFromMethodName(\"ReflectMethodSubject::stat\");
var_dump($static->getName());
var_dump($static->isPublic());
var_dump($static->isStatic());
var_dump($static->isConstructor());

$factory = ReflectMethodFactoryEx::createFromMethodName(\"ReflectMethodSubject::fresh\");
var_dump(get_class($factory));
var_dump($factory->class);
var_dump($factory->name);
var_dump(ReflectMethodFactoryOverride::createFromMethodName(\"ReflectMethodSubject::fresh\"));

$trait = new ReflectionMethod(\"ReflectMethodTrait\", \"traitMethod\");
var_dump($trait->class);
var_dump($trait->name);

$private = new ReflectionMethod(\"ReflectMethodSubject\", \"hidden\");
var_dump($private->isPrivate());
var_dump($private->getModifiers());
var_dump(Reflection::getModifierNames($private->getModifiers()));
var_dump(Reflection::getModifierNames(ReflectionMethod::IS_FINAL | ReflectionMethod::IS_PROTECTED));
var_dump(method_exists(\"Reflection\", \"getModifierNames\"));

$ctor = new ReflectionMethod(\"ReflectMethodSubject\", \"__construct\");
var_dump($ctor->isConstructor());
var_dump($ctor->isDestructor());

$internal = new ReflectionMethod(\"ReflectionProperty\", \"__construct\");
var_dump($internal->isInternal());
var_dump($internal->isUserDefined());
var_dump(method_exists(\"ReflectionMethod\", \"isPublic\"));

$enumMethod = new ReflectionMethod(\"ReflectMethodEnum\", \"enumMethod\");
var_dump($enumMethod->class);
var_dump(get_class($enumMethod->getDeclaringClass()));
var_dump($enumMethod->getDeclaringClass()->getName());
$enumFactory = ReflectionMethod::createFromMethodName(\"ReflectMethodEnum::enumMethod\");
var_dump(get_class($enumFactory->getDeclaringClass()));

$directInterfacePrototype = (new ReflectionMethod(\"ReflectPrototypeChild\", \"viaInterface\"))->getPrototype();
var_dump($directInterfacePrototype->class);
$inheritedInterfacePrototype = (new ReflectionMethod(\"ReflectPrototypeChild\", \"inheritedViaInterface\"))->getPrototype();
var_dump($inheritedInterfacePrototype->class);
$plainInherited = new ReflectionMethod(\"ReflectPlainChild\", \"plainInherited\");
var_dump($plainInherited->hasPrototype());
try {
    $plainInherited->getPrototype();
} catch (ReflectionException $e) {
    echo $e->getMessage(), \"\\n\";
}
$inheritedParentPrototype = (new ReflectionMethod(\"ReflectParentPrototypeC\", \"f\"))->getPrototype();
var_dump($inheritedParentPrototype->class);
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "string(9) \"inherited\"\n",
            "string(17) \"ReflectBaseMethod\"\n",
            "bool(true)\n",
            "bool(false)\n",
            "bool(true)\n",
            "bool(true)\n",
            "string(17) \"ReflectBaseMethod\"\n",
            "string(10) \"overridden\"\n",
            "bool(false)\n",
            "string(4) \"stat\"\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(false)\n",
            "string(22) \"ReflectMethodFactoryEx\"\n",
            "string(20) \"ReflectMethodSubject\"\n",
            "string(5) \"fresh\"\n",
            "string(36) \"override:ReflectMethodSubject::fresh\"\n",
            "string(18) \"ReflectMethodTrait\"\n",
            "string(11) \"traitMethod\"\n",
            "bool(true)\n",
            "int(4)\n",
            "array(1) {\n",
            "  [0]=>\n",
            "  string(7) \"private\"\n",
            "}\n",
            "array(2) {\n",
            "  [0]=>\n",
            "  string(5) \"final\"\n",
            "  [1]=>\n",
            "  string(9) \"protected\"\n",
            "}\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(false)\n",
            "bool(true)\n",
            "bool(false)\n",
            "bool(true)\n",
            "string(17) \"ReflectMethodEnum\"\n",
            "string(14) \"ReflectionEnum\"\n",
            "string(17) \"ReflectMethodEnum\"\n",
            "string(14) \"ReflectionEnum\"\n",
            "string(26) \"ReflectPrototypeInterfaceB\"\n",
            "string(26) \"ReflectPrototypeInterfaceA\"\n",
            "bool(false)\n",
            "Method ReflectPlainChild::plainInherited does not have a prototype\n",
            "string(23) \"ReflectParentPrototypeA\"\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_reflection_method_new"));
    assert!(c_source.contains("ptn_declared_class_reflection_method_metadata"));
    assert!(c_source.contains("ptn_declared_class_reflection_method_prototype"));
    assert!(c_source.contains("ptn_internal_reflection_method_create_from_method_name"));
    assert!(c_source.contains("ptn_declared_trait_exists"));
}

#[test]
fn compile_reflection_method_tentative_returns_and_static_variables_to_native_binary() {
    let root = temp_dir("ptn-native-reflection-method-tentative-static-vars");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("reflection-method-tentative-static-vars.php");
    let output = root.join("reflection-method-tentative-static-vars-bin");
    fs::write(
        &input,
        "<?php
function reflection_static_default() {
    echo \"test() called\\n\";
    return 42;
}

function static_reflection_target() {
    $function = new ReflectionFunction(__FUNCTION__);
    $before = $function->getStaticVariables()['a'];
    static $a = reflection_static_default();
    var_dump($a);
    $live = &$function->getStaticVariables()['a'];
    $live = $before;
}

static_reflection_target();
static_reflection_target();

class MyDateTimeZone extends DateTimeZone
{
    #[ReturnTypeWillChange]
    public static function listIdentifiers(int $timezoneGroup = DateTimeZone::ALL, ?string $countryCode = null): string
    {
        return '';
    }
}

function show_tentative(ReflectionMethod $method) {
    var_dump($method->hasReturnType());
    var_dump($method->hasTentativeReturnType());
    var_dump((string) $method->getReturnType());
    var_dump((string) $method->getTentativeReturnType());
    echo $method, \"--\\n\";
}

show_tentative(new ReflectionMethod(DateTimeZone::class, 'listIdentifiers'));
show_tentative(new ReflectionMethod(MyDateTimeZone::class, 'listIdentifiers'));
show_tentative(new ReflectionMethod(FileSystemIterator::class, 'current'));
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    let stdout = String::from_utf8(execution.stdout).unwrap();
    assert!(
        stdout.starts_with("test() called\nint(42)\nNULL\n"),
        "{stdout}"
    );
    assert!(
        stdout.contains("bool(false)\nbool(true)\nstring(0) \"\"\nstring(5) \"array\"\n"),
        "{stdout}"
    );
    assert!(
        stdout.contains("static public method listIdentifiers")
            && stdout.contains("  - Tentative return [ array ]\n"),
        "{stdout}"
    );
    assert!(
        stdout.contains("bool(true)\nbool(false)\nstring(6) \"string\"\nstring(0) \"\"\n"),
        "{stdout}"
    );
    assert!(
        stdout.contains("overwrites DateTimeZone, prototype DateTimeZone"),
        "{stdout}"
    );
    assert!(stdout.contains("DateTimeZone::ALL"), "{stdout}");
    assert!(!stdout.contains("\\DateTimeZone::ALL"), "{stdout}");
    assert!(
        stdout.contains("string(37) \"SplFileInfo|FilesystemIterator|string\"")
            && stdout.contains("overwrites DirectoryIterator, prototype Iterator")
            && stdout.contains("  - Parameters [0] {\n  }\n")
            && stdout.contains("  - Tentative return [ SplFileInfo|FilesystemIterator|string ]\n"),
        "{stdout}"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_function_metadata_with_tentative_return"));
    assert!(c_source.contains("ptn_runtime_static_local_values"));
}

#[test]
fn compile_reflection_method_class_scoped_defaults_to_native_binary() {
    let root = temp_dir("ptn-native-reflection-method-scoped-defaults");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("reflection-method-scoped-defaults.php");
    let output = root.join("reflection-method-scoped-defaults-bin");
    fs::write(
        &input,
        r#"<?php
class F {
    public function bar($x = self::class) {}
}

trait T {
    public function bar($x = self::class) {}
}

class B {
    use T;
}

class Baz {
    const B = 3;
}

class Foo {
    const X = 1;
    public function x($a = self::X, $b = Baz::B, $c = 99) {}
}

class Bar extends Foo {
    const Y = 2;
    public function y($a = self::Y, $b = Baz::B, $c = 99) {}
}

class DefaultParent {
    const Y = 20;
}

class DefaultChild extends DefaultParent {
    const X = 12;
    public function x($x = 1, $y = [self::X], $z = parent::Y) {}
}

function arrayDefaults(
    array $x = ['a', 'b'],
    array $y = ['x' => 'y'],
    array $z = [0 => 0, 2 => -2],
    array $a = [[], [1], [2, 3]],
) {}

$cases = [
    [F::class, 'Parameter #0 [ <optional> $x = \'F\' ]'],
    [T::class, 'Parameter #0 [ <optional> $x = self::class ]'],
    [B::class, 'Parameter #0 [ <optional> $x = self::class ]'],
];

foreach ($cases as [$className, $needle]) {
    $method = new ReflectionMethod($className, 'bar');
    echo $className, str_contains((string) $method, $needle) ? ":string\n" : ":missing\n";
}

foreach ([F::class, B::class] as $className) {
    $method = new ReflectionMethod($className, 'bar');
    echo $className, ":", $method->getParameters()[0]->getDefaultValue(), "\n";
}

foreach ((new ReflectionClass('Bar'))->getMethods() as $method) {
    foreach ($method->getParameters() as $param) {
        if ($param->isDefaultValueAvailable()) {
            echo $method->getDeclaringClass()->getName(), '::', $method->getName(), '($', $param->getName(), ' = ', $param->getDefaultValue(), ")\n";
        }
    }
}

$method = (new ReflectionClass('DefaultChild'))->getMethod('x');
foreach ($method->getParameters() as $param) {
    if ($param->isDefaultValueAvailable()) {
        echo $param->getName(), ':', var_export($param->getDefaultValue(), true), "\n";
    }
}

$arrayDefaults = (string) new ReflectionFunction('arrayDefaults');
echo str_contains($arrayDefaults, 'array $x = [\'a\', \'b\']') ? "array-x:string\n" : "array-x:missing\n";
echo str_contains($arrayDefaults, 'array $y = [\'x\' => \'y\']') ? "array-y:string\n" : "array-y:missing\n";
echo str_contains($arrayDefaults, 'array $z = [0 => 0, 2 => -2]') ? "array-z:string\n" : "array-z:missing\n";
echo str_contains($arrayDefaults, 'array $a = [[], [1], [2, 3]]') ? "array-a:string\n" : "array-a:missing\n";
"#,
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "F:string\n",
            "T:string\n",
            "B:string\n",
            "F:F\n",
            "B:B\n",
            "Bar::y($a = 2)\n",
            "Bar::y($b = 3)\n",
            "Bar::y($c = 99)\n",
            "Foo::x($a = 1)\n",
            "Foo::x($b = 3)\n",
            "Foo::x($c = 99)\n",
            "x:1\n",
            "y:array (\n",
            "  0 => 12,\n",
            ")\n",
            "z:20\n",
            "array-x:string\n",
            "array-y:string\n",
            "array-z:string\n",
            "array-a:string\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_reflection_parameter_default_values_to_native_binary() {
    let root = temp_dir("ptn-native-reflection-parameter-default-values");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("reflection-parameter-default-values.php");
    let output = root.join("reflection-parameter-default-values-bin");
    fs::write(
        &input,
        "<?php
class OtherDefaultBox {
    const B = 3;
}

class ParentDefaultBox {
    const P = 20;
}

class DefaultBox extends ParentDefaultBox {
    const X = 12;

    public function method($literal = [123], $selfArray = [self::X], $self = self::X, $other = OtherDefaultBox::B, $parent = parent::P) {}
}

$method = new ReflectionMethod(DefaultBox::class, 'method');
foreach ($method->getParameters() as $parameter) {
    $value = $parameter->getDefaultValue();
    echo $parameter->getName(), ':', is_array($value) ? implode(',', $value) : $value, \"\\n\";
}
",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "literal:123\n",
            "selfArray:12\n",
            "self:12\n",
            "other:3\n",
            "parent:20\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_reflection_method_invoke_to_native_binary() {
    let root = temp_dir("ptn-native-reflection-method-invoke");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("reflection-method-invoke.php");
    let output = root.join("reflection-method-invoke-bin");
    fs::write(
        &input,
        "<?php
class ReflectInvokeBase {
    protected function inherited($value) {
        echo \"base:$value\\n\";
        return \"base\";
    }
}

class ReflectInvokeSubject extends ReflectInvokeBase {
    public $prop = \"prop\";

    public function read($value) {
        echo $this->prop . \":$value\\n\";
        return \"read\";
    }

    private function hidden($value) {
        echo \"hidden:$value\\n\";
    }

    public static function stat($value) {
        echo \"stat:$value\\n\";
        return \"stat-ret\";
    }
}

class ReflectInvokeLateBase {
    const WHAT = \"A\";

    public static function late() {
        return static::WHAT;
    }
}

class ReflectInvokeLateChild extends ReflectInvokeLateBase {
    const WHAT = \"B\";
}

$subject = new ReflectInvokeSubject();

$read = new ReflectionMethod(\"ReflectInvokeSubject\", \"read\");
var_dump($read->invoke($subject, \"arg\"));

$hidden = new ReflectionMethod(\"ReflectInvokeSubject\", \"hidden\");
var_dump($hidden->invokeArgs($subject, array(\"secret\")));

$inherited = new ReflectionMethod(\"ReflectInvokeBase\", \"inherited\");
var_dump($inherited->invoke($subject, \"b\"));

$static = ReflectionMethod::createFromMethodName(\"ReflectInvokeSubject::stat\");
var_dump($static->invoke(null, \"s\"));

$late = ReflectionMethod::createFromMethodName(\"ReflectInvokeLateChild::late\");
echo $late->invoke(null), $late->invokeArgs(null, array()), \"\\n\";

$lateBase = ReflectionMethod::createFromMethodName(\"ReflectInvokeLateBase::late\");
echo $lateBase->invoke(null), $lateBase->invokeArgs(null, array()), \"\\n\";

try {
    $read->invoke(new stdClass());
} catch (ReflectionException $e) {
    echo $e->getMessage(), \"\\n\";
}

try {
    $read->invoke(true);
} catch (TypeError $e) {
    echo $e->getMessage(), \"\\n\";
}

var_dump(method_exists(\"ReflectionMethod\", \"invokeArgs\"));
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "prop:arg\n",
            "string(4) \"read\"\n",
            "hidden:secret\n",
            "NULL\n",
            "base:b\n",
            "string(4) \"base\"\n",
            "stat:s\n",
            "string(8) \"stat-ret\"\n",
            "BB\n",
            "AA\n",
            "Given object is not an instance of the class this method was declared in\n",
            "ReflectionMethod::invoke(): Argument #1 ($object) must be of type ?object, true given\n",
            "bool(true)\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("runtime.reflected_method_dispatch"));
    assert!(c_source.contains("ptn_reflection_method_dispatch_invoke"));
}

#[test]
fn compile_reflection_method_invoke_arity_errors_to_native_binary() {
    let root = temp_dir("ptn-native-reflection-method-invoke-arity-errors");
    fs::create_dir_all(&root).unwrap();

    let cases = [
        (
            "invoke",
            "<?php
class ReflectArityTarget {
    public function needsTwo($a, $b) {}
}

echo \"invoke\\n\";
$method = new ReflectionMethod(ReflectArityTarget::class, 'needsTwo');
$method->invoke(new ReflectArityTarget());
",
            "ReflectionMethod->invoke(Object(ReflectArityTarget))",
        ),
        (
            "invokeArgs",
            "<?php
class ReflectArityTarget {
    public function needsTwo($a, $b) {}
}

echo \"invokeArgs\\n\";
$method = new ReflectionMethod(ReflectArityTarget::class, 'needsTwo');
$method->invokeArgs(new ReflectArityTarget(), []);
",
            "ReflectionMethod->invokeArgs(Object(ReflectArityTarget), Array)",
        ),
    ];

    for (name, source, reflection_frame) in cases {
        let input = root.join(format!("{name}.php"));
        let output = root.join(format!("{name}-bin"));
        fs::write(&input, source).unwrap();
        compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

        let execution = Command::new(&output).output().unwrap();
        assert!(!execution.status.success());
        assert_eq!(
            String::from_utf8(execution.stdout).unwrap(),
            format!("{name}\n")
        );
        let stderr = String::from_utf8(execution.stderr).unwrap();
        assert!(
            stderr.contains("Fatal error: Uncaught ArgumentCountError: Too few arguments to function ReflectArityTarget::needsTwo(), 0 passed and exactly 2 expected"),
            "{stderr}"
        );
        assert!(
            stderr.contains("[internal function]: ReflectArityTarget->needsTwo()"),
            "{stderr}"
        );
        assert!(stderr.contains(reflection_frame), "{stderr}");
    }
}

#[test]
fn compile_reflection_method_invoke_exception_trace_to_native_binary() {
    let root = temp_dir("ptn-native-reflection-method-invoke-exception-trace");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("reflection-method-invoke-exception-trace.php");
    let output = root.join("reflection-method-invoke-exception-trace-bin");
    fs::write(
        &input,
        "<?php
class ErrorHandler {
    public static function handle(int $errno, string $errstr, string $errfile, int $errline) {
        throw new RuntimeException;
    }
}

class Target {
    public function run() {
        $source = &$this->missing();
    }

    public function missing() {
        return null;
    }
}

set_error_handler([ErrorHandler::class, 'handle'], E_ALL);

$method = new ReflectionMethod(Target::class, 'run');
$method->invoke(new Target());
",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(!execution.status.success());
    assert_eq!(String::from_utf8(execution.stdout).unwrap(), "");
    let stderr = String::from_utf8(execution.stderr).unwrap();
    assert!(
        stderr.contains("Fatal error: Uncaught RuntimeException"),
        "{stderr}"
    );
    assert!(
        stderr.contains(": ErrorHandler::handle(8, 'Only variables ...'"),
        "{stderr}"
    );
    assert!(
        stderr.contains("[internal function]: Target->run()"),
        "{stderr}"
    );
    assert!(
        stderr.contains(": ReflectionMethod->invoke(Object(Target))"),
        "{stderr}"
    );
}

#[test]
fn compile_reflection_method_invoke_argument_count_trace_to_native_binary() {
    let root = temp_dir("ptn-native-reflection-method-invoke-argument-count-trace");
    fs::create_dir_all(&root).unwrap();

    for &(name, call, reflection_frame) in &[
        (
            "invoke",
            "$method->invoke(new Target());",
            ": ReflectionMethod->invoke(Object(Target))",
        ),
        (
            "invokeArgs",
            "$method->invokeArgs(new Target(), array());",
            ": ReflectionMethod->invokeArgs(Object(Target), Array)",
        ),
    ] {
        let input = root.join(format!("reflection-method-{name}-argument-count-trace.php"));
        let output = root.join(format!("reflection-method-{name}-argument-count-trace-bin"));
        fs::write(
            &input,
            format!(
                "<?php
class Target {{
    public function run($a, $b) {{}}
}}

$method = new ReflectionMethod(Target::class, 'run');
{call}
"
            ),
        )
        .unwrap();

        compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

        let execution = Command::new(&output).output().unwrap();
        assert!(!execution.status.success());
        assert_eq!(String::from_utf8(execution.stdout).unwrap(), "");
        let stderr = String::from_utf8(execution.stderr).unwrap();
        assert!(
            stderr.contains(
                "Fatal error: Uncaught ArgumentCountError: Too few arguments to function Target::run(), 0 passed and exactly 2 expected in "
            ),
            "{stderr}"
        );
        assert!(
            stderr.contains(&format!(
                "reflection-method-{name}-argument-count-trace.php:3"
            )),
            "{stderr}"
        );
        assert!(
            stderr.contains("[internal function]: Target->run()"),
            "{stderr}"
        );
        assert!(stderr.contains(reflection_frame), "{stderr}");
        assert!(stderr.contains("thrown in "), "{stderr}");
    }
}

#[test]
fn compile_reflection_class_constants_to_native_binary() {
    let root = temp_dir("ptn-native-reflection-class-constants");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("reflection-class-constants.php");
    let output = root.join("reflection-class-constants-bin");
    fs::write(
        &input,
        "<?php
class ConstBase {
    const a = \"base\";
    const b = 7;
}

class ConstChild extends ConstBase {
    const a = \"child\";
}

$base = new ReflectionClass(\"ConstBase\");
var_dump($base->getConstant(\"a\"));
var_dump($base->getConstants());

$child = new ReflectionClass(\"ConstChild\");
var_dump($child->getConstant(\"a\"));
var_dump($child->getConstant(\"b\"));
var_dump($child->hasConstant(\"b\"));

$constant = $child->getReflectionConstant(\"a\");
var_dump(gettype($constant));
var_dump($constant->getName());
var_dump($constant->getDeclaringClass()->getName());
var_dump($constant->getValue());

$internal = new ReflectionClass(\"ReflectionClass\");
var_dump($internal->hasConstant(\"IS_FINAL\"));
var_dump(gettype($internal->getReflectionConstant(\"IS_IMPLICIT_ABSTRACT\")));
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "string(4) \"base\"\n",
            "array(2) {\n",
            "  [\"a\"]=>\n",
            "  string(4) \"base\"\n",
            "  [\"b\"]=>\n",
            "  int(7)\n",
            "}\n",
            "string(5) \"child\"\n",
            "int(7)\n",
            "bool(true)\n",
            "string(6) \"object\"\n",
            "string(1) \"a\"\n",
            "string(10) \"ConstChild\"\n",
            "string(5) \"child\"\n",
            "bool(true)\n",
            "string(6) \"object\"\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_declared_class_constants"));
    assert!(c_source.contains("ptn_reflection_class_constant_call_method"));
}

#[test]
fn compile_reflection_class_name_arguments_type_errors_to_native_binary() {
    let root = temp_dir("ptn-native-reflection-class-name-argument-type-errors");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("reflection-class-name-argument-type-errors.php");
    let output = root.join("reflection-class-name-argument-type-errors-bin");
    fs::write(
        &input,
        "<?php
class RefNameBox {
    public const VALUE = 1;
    public $prop = 1;
    public function run() {}
}

$rc = new ReflectionClass(RefNameBox::class);
$bad = [[1], new RefNameBox()];

foreach ($bad as $arg) {
    try { $rc->getMethod($arg); } catch (TypeError $e) { echo $e->getMessage(), \"\\n\"; }
}
foreach ($bad as $arg) {
    try { $rc->hasMethod($arg); } catch (TypeError $e) { echo $e->getMessage(), \"\\n\"; }
}
foreach ($bad as $arg) {
    try { $rc->hasProperty($arg); } catch (TypeError $e) { echo $e->getMessage(), \"\\n\"; }
}
foreach ($bad as $arg) {
    try { $rc->getConstant($arg); } catch (TypeError $e) { echo $e->getMessage(), \"\\n\"; }
}
foreach ($bad as $arg) {
    try { $rc->getReflectionConstant($arg); } catch (TypeError $e) { echo $e->getMessage(), \"\\n\"; }
}
foreach ($bad as $arg) {
    try { $rc->hasConstant($arg); } catch (TypeError $e) { echo $e->getMessage(), \"\\n\"; }
}
",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "ReflectionClass::getMethod(): Argument #1 ($name) must be of type string, array given\n",
            "ReflectionClass::getMethod(): Argument #1 ($name) must be of type string, RefNameBox given\n",
            "ReflectionClass::hasMethod(): Argument #1 ($name) must be of type string, array given\n",
            "ReflectionClass::hasMethod(): Argument #1 ($name) must be of type string, RefNameBox given\n",
            "ReflectionClass::hasProperty(): Argument #1 ($name) must be of type string, array given\n",
            "ReflectionClass::hasProperty(): Argument #1 ($name) must be of type string, RefNameBox given\n",
            "ReflectionClass::getConstant(): Argument #1 ($name) must be of type string, array given\n",
            "ReflectionClass::getConstant(): Argument #1 ($name) must be of type string, RefNameBox given\n",
            "ReflectionClass::getReflectionConstant(): Argument #1 ($name) must be of type string, array given\n",
            "ReflectionClass::getReflectionConstant(): Argument #1 ($name) must be of type string, RefNameBox given\n",
            "ReflectionClass::hasConstant(): Argument #1 ($name) must be of type string, array given\n",
            "ReflectionClass::hasConstant(): Argument #1 ($name) must be of type string, RefNameBox given\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_reflection_class_without_constants_emits_quiet_helpers_to_native_binary() {
    let root = temp_dir("ptn-native-reflection-class-no-constants");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("reflection-class-no-constants.php");
    let output = root.join("reflection-class-no-constants-bin");
    fs::write(
        &input,
        "<?php
class NoConstantBox {
    public function read() {
        return 1;
    }
}

$reflection = new ReflectionClass(NoConstantBox::class);
var_dump($reflection->getConstants());
var_dump($reflection->getReflectionConstants());
var_dump($reflection->hasConstant(\"MISSING\"));
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "array(0) {\n",
            "}\n",
            "array(0) {\n",
            "}\n",
            "bool(false)\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    let constants_body = generated_c_static_function_body(
        &c_source,
        "static PTN_UNUSED PtnValue ptn_declared_class_constants(",
    );
    assert!(constants_body.contains("(void)runtime;"));
    assert!(constants_body.contains("(void)filter_present;"));
    assert!(constants_body.contains("(void)filter;"));
    let reflection_constants_body = generated_c_static_function_body(
        &c_source,
        "static PTN_UNUSED PtnValue ptn_declared_class_reflection_constants(",
    );
    assert!(reflection_constants_body.contains("(void)runtime;"));
    assert!(reflection_constants_body.contains("(void)filter_present;"));
    assert!(reflection_constants_body.contains("(void)filter;"));
    assert!(reflection_constants_body.contains("(void)index;"));
    let modifiers_body = generated_c_static_function_body(
        &c_source,
        "static PTN_UNUSED int ptn_declared_class_reflection_constant_modifiers(",
    );
    assert!(modifiers_body.contains("(void)constant_name;"));
    let deprecation_body = generated_c_static_function_body(
        &c_source,
        "static PTN_UNUSED int ptn_declared_class_reflection_constant_is_deprecated(",
    );
    assert!(deprecation_body.contains("(void)constant_name;"));
}

#[test]
fn compile_reflection_class_constant_visibility_filters_to_native_binary() {
    let root = temp_dir("ptn-native-reflection-class-constant-visibility");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("reflection-class-constant-visibility.php");
    let output = root.join("reflection-class-constant-visibility-bin");
    fs::write(
        &input,
        "<?php
class ConstantVisBase {
    public const PUB = \"base-pub\";
    final public const FINAL_PUB = \"base-final\";
    protected const PROT = \"base-prot\";
    private const PRIV = \"base-priv\";
}

class ConstantVisChild extends ConstantVisBase {
    public const OWN = \"child-own\";
    private const CHILD_PRIV = \"child-priv\";
}

class DeprecatedConstantBox {
    #[Deprecated]
    public const OLD = \"old\";
}

$base = new ReflectionClass(ConstantVisBase::class);
var_dump($base->getConstants(ReflectionClassConstant::IS_PUBLIC));
var_dump($base->getConstants(ReflectionClassConstant::IS_FINAL));
var_dump($base->getConstants(ReflectionClassConstant::IS_PROTECTED));
var_dump($base->getConstants(ReflectionClassConstant::IS_PRIVATE));

$child = new ReflectionClass(ConstantVisChild::class);
var_dump($child->getConstants(ReflectionClassConstant::IS_PRIVATE));

foreach ($base->getReflectionConstants(ReflectionClassConstant::IS_PROTECTED) as $constant) {
    echo $constant->getDeclaringClass()->getName(), \"::\", $constant->getName(), \"\\n\";
    var_dump($constant->isProtected(), $constant->getModifiers(), $constant->getValue());
}

$private = $base->getReflectionConstant(\"PRIV\");
var_dump($private->isPublic(), $private->isProtected(), $private->isPrivate(), $private->getModifiers());
$final = $base->getReflectionConstant(\"FINAL_PUB\");
var_dump($final->isFinal(), $final->getModifiers());
$direct = new ReflectionClassConstant(ConstantVisChild::class, \"FINAL_PUB\");
echo $direct->getDeclaringClass()->getName(), \"::\", $direct->getName(), \"\\n\";
var_dump($direct->isFinal(), $direct->getValue(), $direct->isDeprecated());
echo $direct;
$deprecated = new ReflectionClassConstant(DeprecatedConstantBox::class, \"OLD\");
var_dump($deprecated->isDeprecated());
var_dump(ReflectionClassConstant::IS_PUBLIC, ReflectionClassConstant::IS_PROTECTED, ReflectionClassConstant::IS_PRIVATE, ReflectionClassConstant::IS_FINAL);
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "array(2) {\n",
            "  [\"PUB\"]=>\n",
            "  string(8) \"base-pub\"\n",
            "  [\"FINAL_PUB\"]=>\n",
            "  string(10) \"base-final\"\n",
            "}\n",
            "array(1) {\n",
            "  [\"FINAL_PUB\"]=>\n",
            "  string(10) \"base-final\"\n",
            "}\n",
            "array(1) {\n",
            "  [\"PROT\"]=>\n",
            "  string(9) \"base-prot\"\n",
            "}\n",
            "array(1) {\n",
            "  [\"PRIV\"]=>\n",
            "  string(9) \"base-priv\"\n",
            "}\n",
            "array(1) {\n",
            "  [\"CHILD_PRIV\"]=>\n",
            "  string(10) \"child-priv\"\n",
            "}\n",
            "ConstantVisBase::PROT\n",
            "bool(true)\n",
            "int(2)\n",
            "string(9) \"base-prot\"\n",
            "bool(false)\n",
            "bool(false)\n",
            "bool(true)\n",
            "int(4)\n",
            "bool(true)\n",
            "int(33)\n",
            "ConstantVisBase::FINAL_PUB\n",
            "bool(true)\n",
            "string(10) \"base-final\"\n",
            "bool(false)\n",
            "Constant [ final public string FINAL_PUB ] { base-final }\n",
            "bool(true)\n",
            "int(1)\n",
            "int(2)\n",
            "int(4)\n",
            "int(32)\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_declared_class_reflection_constants"));
    assert!(c_source.contains("ptn_declared_class_reflection_constant_modifiers"));
    assert!(c_source.contains("ptn_declared_class_reflection_constant_is_deprecated"));
}

#[test]
fn compile_inherited_private_class_constants_are_not_child_constants_to_native_binary() {
    let root = temp_dir("ptn-native-private-class-constant-inheritance");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("private-class-constant-inheritance.php");
    let output = root.join("private-class-constant-inheritance-bin");
    fs::write(
        &input,
        "<?php
class ConstantPrivateBase {
    public const PUB = 1;
    protected const PROT = 2;
    private const PRIV = 3;

    public static function baseDefined() {
        var_dump(defined(\"ConstantPrivateBase::PRIV\"));
    }
}

class ConstantPrivateChild extends ConstantPrivateBase {
    public static function childDefined() {
        var_dump(defined(\"ConstantPrivateChild::PUB\"));
        var_dump(defined(\"ConstantPrivateChild::PROT\"));
        var_dump(defined(\"ConstantPrivateChild::PRIV\"));
        var_dump(defined(\"ConstantPrivateBase::PRIV\"));
    }

    public static function checkConstants() {
        var_dump(self::PUB);
        var_dump(self::PROT);
        try {
            var_dump(self::PRIV);
        } catch (Error $e) {
            echo $e->getMessage(), \"\\n\";
        }
    }
}

var_dump(defined(\"ConstantPrivateBase::PUB\"));
var_dump(defined(\"ConstantPrivateBase::PROT\"));
var_dump(defined(\"ConstantPrivateBase::PRIV\"));
ConstantPrivateBase::baseDefined();
ConstantPrivateChild::childDefined();
ConstantPrivateChild::checkConstants();

try {
    var_dump(ConstantPrivateChild::PRIV);
} catch (Error $e) {
    echo $e->getMessage(), \"\\n\";
}

try {
    var_dump(ConstantPrivateBase::PRIV);
} catch (Error $e) {
    echo $e->getMessage(), \"\\n\";
}
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "bool(true)\n",
            "bool(false)\n",
            "bool(false)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(false)\n",
            "bool(false)\n",
            "int(1)\n",
            "int(2)\n",
            "Undefined constant ConstantPrivateChild::PRIV\n",
            "Undefined constant ConstantPrivateChild::PRIV\n",
            "Cannot access private constant ConstantPrivateBase::PRIV\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_runtime_read_class_constant_with_scope"));
    assert!(c_source.contains("ptn_runtime_constant_is_defined"));
}

#[test]
fn compile_enum_reflection_metadata_to_native_binary() {
    let root = temp_dir("ptn-native-enum-reflection-metadata");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("enum-reflection-metadata.php");
    let output = root.join("enum-reflection-metadata-bin");
    fs::write(
        &input,
        "<?php
enum Status {
    #[Deprecated(\"use Status::Ok instead\")]
    case Old;
    case Ok;
    const Alias = self::Ok;
}

class PlainConstantBox {
    const VALUE = 1;
}

var_dump((new ReflectionClass(PlainConstantBox::class))->isEnum());
var_dump((new ReflectionClass(Status::class))->isEnum());
var_dump((new ReflectionClassConstant(Status::class, 'Old'))->isEnumCase());
var_dump((new ReflectionClassConstant(Status::class, 'Alias'))->isEnumCase());
var_dump((new ReflectionClassConstant(PlainConstantBox::class, 'VALUE'))->isEnumCase());
Status::Old;

try {
    new ArrayObject(Status::Ok);
} catch (InvalidArgumentException $e) {
    echo $e->getMessage(), \"\\n\";
}
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    let stdout = String::from_utf8(execution.stdout).unwrap();
    assert!(stdout.contains("bool(false)\nbool(true)\nbool(true)\nbool(false)\nbool(false)\n"));
    assert!(
        stdout.contains("Deprecated: Enum case Status::Old is deprecated, use Status::Ok instead"),
        "{stdout}"
    );
    assert!(
        stdout.contains("Deprecated: ArrayObject::__construct(): Using an object as a backing array for ArrayObject is deprecated"),
        "{stdout}"
    );
    assert!(
        stdout.contains("Enums are not compatible with ArrayObject"),
        "{stdout}"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_declared_class_is_enum"));
    assert!(c_source.contains("ptn_declared_class_reflection_constant_is_enum_case"));
    assert!(c_source.contains("Enum case Status::Old is deprecated"));
}

#[test]
fn compile_enum_case_var_export_to_native_binary() {
    let root = temp_dir("ptn-native-enum-case-var-export");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("enum-case-var-export.php");
    let output = root.join("enum-case-var-export-bin");
    fs::write(
        &input,
        "<?php
namespace {
    enum Foo { case BAR; }
}

namespace A {
    enum Foo { case BAR; }
}

namespace A\\B {
    enum Foo { case BAR; }
}

namespace Test {
    echo var_export(\\Foo::BAR, true), \"\\n\";
    echo var_export(\\A\\Foo::BAR, true), \"\\n\";
    echo var_export(\\A\\B\\Foo::BAR, true), \"\\n\";
}
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstdout:\n{}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stdout),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        "\\Foo::BAR\n\\A\\Foo::BAR\n\\A\\B\\Foo::BAR\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    let helper = generated_c_static_function_body(&c_source, "ptn_compact_append_var_export");
    assert!(helper.contains("enum_case_name"));
}

