#[test]
fn compile_reflection_attribute_first_class_callable_arguments_to_native_binary() {
    let root = temp_dir("ptn-native-attribute-first-class-callable-args");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("attribute-first-class-callable-args.php");
    let output = root.join("attribute-first-class-callable-args-bin");
    fs::write(
        &input,
        "<?php
#[Attribute(Attribute::TARGET_CLASS | Attribute::IS_REPEATABLE)]
class CallbackAttr {
    public function __construct(public Closure $value) {}
}

class P {
    public static function foreign(string $value): string {
        return \"p:$value\";
    }
}

class Q extends P {}

#[CallbackAttr(strrev(...))]
#[CallbackAttr(strlen(...))]
#[CallbackAttr(Q::foreign(...))]
#[CallbackAttr(self::secret(...))]
#[CallbackAttr(Subject::secret(...))]
class Subject {
    private static function secret(string $value): string {
        return \"secret:$value\";
    }
}

foreach ((new ReflectionClass(Subject::class))->getAttributes() as $attribute) {
    $fn = $attribute->newInstance()->value;
    $reflection = new ReflectionFunction($fn);
    $called = $reflection->getClosureCalledClass();
    $scope = $reflection->getClosureScopeClass();
    var_dump($called ? $called->getName() : null);
    var_dump($scope ? $scope->getName() : null);
    echo $fn(\"abc\"), \"\\n\";
}
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "NULL\n",
            "NULL\n",
            "cba\n",
            "NULL\n",
            "NULL\n",
            "3\n",
            "string(1) \"Q\"\n",
            "string(1) \"P\"\n",
            "p:abc\n",
            "string(7) \"Subject\"\n",
            "string(7) \"Subject\"\n",
            "secret:abc\n",
            "string(7) \"Subject\"\n",
            "string(7) \"Subject\"\n",
            "secret:abc\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_first_class_callable_create(runtime"));
    assert!(c_source.contains("Subject::secret"));
}

#[test]
fn compile_reflection_function_attributes_follow_method_first_class_callable_origin() {
    let root = temp_dir("ptn-native-reflection-function-method-callable-attributes");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("reflection-function-method-callable-attributes.php");
    let output = root.join("reflection-function-method-callable-attributes-bin");
    fs::write(
        &input,
        "<?php
#[Attribute(Attribute::TARGET_FUNCTION)]
class FunctionOnly {}

#[Attribute(Attribute::TARGET_METHOD)]
class MethodOnly {}

class CallableAttributeTarget {
    #[FunctionOnly]
    #[MethodOnly]
    public function run() {}
}

#[FunctionOnly]
#[MethodOnly]
function callable_attribute_target() {}

function showCallableAttribute(string $attributeClass, Closure $callable): void {
    try {
        $attribute = (new ReflectionFunction($callable))->getAttributes($attributeClass)[0];
        echo get_class($attribute->newInstance()), \"\\n\";
    } catch (Error $e) {
        echo $e->getMessage(), \"\\n\";
    }
}

$function = callable_attribute_target(...);
$method = [new CallableAttributeTarget(), 'run'](...);

showCallableAttribute(FunctionOnly::class, $function);
showCallableAttribute(MethodOnly::class, $function);
showCallableAttribute(FunctionOnly::class, $method);
showCallableAttribute(MethodOnly::class, $method);
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "FunctionOnly\n",
            "Attribute \"MethodOnly\" cannot target function (allowed targets: method)\n",
            "Attribute \"FunctionOnly\" cannot target method (allowed targets: function)\n",
            "MethodOnly\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_reflection_function_method_metadata_attributes"));
}

