#[test]
fn compile_iterable_object_and_composite_type_hints_to_native_binary() {
    let root = temp_dir("ptn-native-composite-user-type-hints");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("composite-user-type-hints.php");
    let output = root.join("composite-user-type-hints-bin");
    fs::write(
        &input,
        "<?php
interface LeftMarker {}
interface RightMarker {}
class BothMarkers implements LeftMarker, RightMarker {}

function accept_iterable(iterable $value): iterable {
    foreach ($value as $item) {
        echo $item;
    }
    echo \"\\n\";
    return $value;
}
function accept_object(object $value): object { return $value; }
function accept_union(array|stdClass $value): array|stdClass { return $value; }
function accept_intersection(LeftMarker&RightMarker $value): LeftMarker&RightMarker { return $value; }
function invalid_return(): iterable { return 1; }

accept_iterable([1, 2]);
accept_iterable(new ArrayIterator([3, 4]));
var_dump(accept_object(new stdClass) instanceof stdClass);
var_dump(accept_union(new stdClass) instanceof stdClass);
var_dump(accept_union([\"x\"]));
var_dump(accept_intersection(new BothMarkers) instanceof BothMarkers);

try { accept_iterable(1); } catch (TypeError $e) { echo \"iterable error: \", $e->getMessage(), \"\\n\"; }
try { accept_object([]); } catch (TypeError $e) { echo \"object error: \", $e->getMessage(), \"\\n\"; }
try { accept_intersection(new stdClass); } catch (TypeError $e) { echo \"intersection error: \", $e->getMessage(), \"\\n\"; }
try { invalid_return(); } catch (TypeError $e) { echo \"return error: \", $e->getMessage(), \"\\n\"; }
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    let stdout = String::from_utf8(execution.stdout).unwrap();
    assert!(stdout.contains(
        "12\n34\nbool(true)\nbool(true)\narray(1) {\n  [0]=>\n  string(1) \"x\"\n}\nbool(true)\n"
    ));
    assert!(stdout.contains(
        "iterable error: accept_iterable(): Argument #1 ($value) must be of type Traversable|array, int given, called in "
    ));
    assert!(stdout.contains(
        "object error: accept_object(): Argument #1 ($value) must be of type object, array given, called in "
    ));
    assert!(stdout.contains(
        "intersection error: accept_intersection(): Argument #1 ($value) must be of type LeftMarker&RightMarker, stdClass given, called in "
    ));
    assert!(stdout.contains(
        "return error: invalid_return(): Return value must be of type Traversable|array, int returned\n"
    ));
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_value_satisfies_iterable_type_hint"));
    assert!(c_source.contains("ptn_value_satisfies_object_type_hint"));
    assert!(c_source.contains("ptn_throw_user_return_type_error"));
}

#[test]
fn compile_composite_reflection_types_to_native_binary() {
    let root = temp_dir("ptn-native-composite-reflection-types");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("composite-reflection-types.php");
    let output = root.join("composite-reflection-types-bin");
    fs::write(
        &input,
        "<?php
interface X {}
interface Y {}
class C {}
class Box {
    public (X&Y)|null $dnf;
    public iterable $items;
    public ?iterable $maybe;
    public string|null $nullableText { set => $value; }
    public function make(): static { return $this; }
}
function f_union(): X|Y|int|null {}
function f_dnf(): (X&Y)|C|null {}
function f_implicit(X&Y $value = null) {}
function f_iterable(iterable $value): iterable { return $value; }
function show(ReflectionType $type) {
    echo $type::class, ' ', (string) $type, ' null=', ($type->allowsNull() ? '1' : '0'), \"\\n\";
    if ($type instanceof ReflectionUnionType || $type instanceof ReflectionIntersectionType) {
        foreach ($type->getTypes() as $inner) {
            echo '  ', $inner::class, ' ', (string) $inner;
            if ($inner instanceof ReflectionNamedType) {
                echo ' name=', $inner->getName(), ' builtin=', ($inner->isBuiltin() ? '1' : '0');
            }
            echo ' null=', ($inner->allowsNull() ? '1' : '0'), \"\\n\";
        }
    } else if ($type instanceof ReflectionNamedType) {
        echo '  name=', $type->getName(), ' builtin=', ($type->isBuiltin() ? '1' : '0'), \"\\n\";
    }
}
show((new ReflectionFunction('f_union'))->getReturnType());
show((new ReflectionFunction('f_dnf'))->getReturnType());
show((new ReflectionFunction('f_implicit'))->getParameters()[0]->getType());
show((new ReflectionFunction('f_iterable'))->getReturnType());
show((new ReflectionClass(Box::class))->getProperty('dnf')->getType());
show((new ReflectionClass(Box::class))->getProperty('items')->getType());
show((new ReflectionClass(Box::class))->getProperty('maybe')->getType());
$nullableText = (new ReflectionClass(Box::class))->getProperty('nullableText');
show($nullableText->getType());
show($nullableText->getSettableType());
show((new ReflectionMethod(Box::class, 'make'))->getReturnType());
",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "\nDeprecated: f_implicit(): Implicitly marking parameter $value as nullable is deprecated, the explicit nullable type must be used instead in ptn on line 14\n",
            "ReflectionUnionType X|Y|int|null null=1\n",
            "  ReflectionNamedType X name=X builtin=0 null=0\n",
            "  ReflectionNamedType Y name=Y builtin=0 null=0\n",
            "  ReflectionNamedType int name=int builtin=1 null=0\n",
            "  ReflectionNamedType null name=null builtin=1 null=1\n",
            "ReflectionUnionType (X&Y)|C|null null=1\n",
            "  ReflectionIntersectionType X&Y null=0\n",
            "  ReflectionNamedType C name=C builtin=0 null=0\n",
            "  ReflectionNamedType null name=null builtin=1 null=1\n",
            "ReflectionUnionType (X&Y)|null null=1\n",
            "  ReflectionIntersectionType X&Y null=0\n",
            "  ReflectionNamedType null name=null builtin=1 null=1\n",
            "ReflectionNamedType iterable null=0\n",
            "  name=iterable builtin=1\n",
            "ReflectionUnionType (X&Y)|null null=1\n",
            "  ReflectionIntersectionType X&Y null=0\n",
            "  ReflectionNamedType null name=null builtin=1 null=1\n",
            "ReflectionNamedType iterable null=0\n",
            "  name=iterable builtin=1\n",
            "ReflectionNamedType ?iterable null=1\n",
            "  name=iterable builtin=1\n",
            "ReflectionNamedType ?string null=1\n",
            "  name=string builtin=1\n",
            "ReflectionNamedType ?string null=1\n",
            "  name=string builtin=1\n",
            "ReflectionNamedType static null=0\n",
            "  name=static builtin=0\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_union_typed_user_function_parameters_to_native_binary() {
    let root = temp_dir("ptn-native-user-function-union-type");
    fs::create_dir_all(&root).unwrap();

    let input = root.join("user-function-union-type.php");
    let output = root.join("user-function-union-type-bin");
    fs::write(
        &input,
        "<?php\n\
function safe_to_string(int|float $number): string { return (string)$number; }\n\
function choose_number(bool $float): int|float { return $float ? 1.5 : 2; }\n\
function collect(int|float ...$numbers): array { return $numbers; }\n\
echo safe_to_string(2), \"\\n\";\n\
echo safe_to_string(3.5), \"\\n\";\n\
var_dump(choose_number(false));\n\
var_dump(choose_number(true));\n\
var_dump(collect(1, 2.5));",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        "2\n3.5\nint(2)\nfloat(1.5)\narray(2) {\n  [0]=>\n  int(1)\n  [1]=>\n  float(2.5)\n}\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let error_input = root.join("user-function-union-type-error.php");
    let error_output = root.join("user-function-union-type-error-bin");
    fs::write(
        &error_input,
        "<?php function safe_to_string(int|float $number): string { return (string)$number; } safe_to_string([]);",
    )
    .unwrap();
    compile_file(
        &error_input,
        &error_output,
        CompileOptions { emit_c: false },
    )
    .unwrap();
    let error_execution = Command::new(&error_output).output().unwrap();
    assert!(!error_execution.status.success());
    assert_eq!(error_execution.status.code(), Some(255));
    let error_stderr = String::from_utf8(error_execution.stderr).unwrap();
    assert!(
        error_stderr.contains(
            "Fatal error: safe_to_string(): Argument #1 ($number) must be of type int|float, array given, called in "
        ),
        "{error_stderr}"
    );
    assert!(
        error_stderr.contains("user-function-union-type-error.php on line 1\n"),
        "{error_stderr}"
    );
}

