#[test]
fn compile_xmlwriter_resources_and_invalid_targets_to_native_binary() {
    let root = temp_dir("ptn-native-xmlwriter-resources-invalid-targets");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("xmlwriter-resources-invalid-targets.php");
    let output = root.join("xmlwriter-resources-invalid-targets-bin");
    let missing = root.join("missing-parent").join("out.xml");
    let writer_path = root.join("writer.xml");
    let reader_path = root.join("reader.xml");
    fs::write(
        &input,
        format!(
            "<?php\n\
var_dump(function_exists('get_resources'));\n\
var_dump(xmlwriter_open_uri('{}'));\n\
\n\
$h = fopen('php://temp', 'w');\n\
$writer = XMLWriter::toStream($h);\n\
$writer->startElement('root');\n\
fclose($h);\n\
var_dump($writer->flush());\n\
try {{\n\
    XMLWriter::toStream($h);\n\
}} catch (TypeError $e) {{\n\
    echo $e->getMessage(), \"\\n\";\n\
}}\n\
\n\
$uriWriter = XMLWriter::toUri('{}');\n\
var_dump($uriWriter instanceof XMLWriter);\n\
$last = end(get_resources());\n\
var_dump(get_resource_type($last));\n\
var_dump(fclose($last));\n\
\n\
file_put_contents('{}', 'a');\n\
$reader = new XMLReader();\n\
var_dump($reader->open('{}'));\n\
$last = end(get_resources());\n\
var_dump(get_resource_type($last));\n\
var_dump(fclose($last));\n",
            missing.display(),
            writer_path.display(),
            reader_path.display(),
            reader_path.display()
        ),
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    let stdout = String::from_utf8(execution.stdout).unwrap();
    assert!(stdout.contains("bool(true)\n"));
    assert!(stdout.contains("Warning: xmlwriter_open_uri(): Unable to resolve file path"));
    assert!(stdout.contains("bool(false)\nint(-1)\n"));
    assert!(stdout
        .contains("XMLWriter::toStream(): supplied resource is not a valid stream resource\n"));
    assert_eq!(
        stdout.matches("Warning: fclose(): cannot close the provided stream, as it must not be manually closed").count(),
        2
    );
    assert!(stdout.contains("string(6) \"stream\"\n"));
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_internal_get_resources"));
    assert!(c_source.contains("ptn_xmlwriter_prepare_uri_target"));
}

#[test]
fn compile_xml_parser_object_swap_and_reader_expand_to_native_binary() {
    let root = temp_dir("ptn-native-xml-parser-object-swap-reader-expand");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("xml-parser-object-swap-reader-expand.php");
    let output = root.join("xml-parser-object-swap-reader-expand-bin");
    fs::write(
        &input,
        "<?php
class A {
    public function start_element($parser, $name, $attributes) {
        echo \"A::start_element($name)\\n\";
    }
    public function end_element($parser, $name) {
        echo \"A::end_element($name)\\n\";
    }
}

class B {
    public function start_element($parser, $name, $attributes) {
        echo \"B::start_element($name)\\n\";
    }
}

$parser = xml_parser_create();
xml_set_object($parser, new A());
xml_set_element_handler($parser, \"start_element\", \"end_element\");
try {
    xml_set_object($parser, new B());
} catch (Throwable $exception) {
    echo $exception::class, ': ', $exception->getMessage(), \"\\n\";
}

$delayed = xml_parser_create();
xml_set_object($delayed, new A());
xml_set_element_handler($delayed, \"start_element\", \"end_element\");
xml_parse($delayed, \"<delayed/>\");

try {
    serialize(xml_parser_create());
} catch (Throwable $exception) {
    echo $exception->getMessage(), \"\\n\";
}

function ptn_recursive_start($parser, $name) {
    xml_parse($parser, '<nested/>');
}
function ptn_recursive_end($parser, $name) {}
$recursive = xml_parser_create();
xml_set_element_handler($recursive, 'ptn_recursive_start', 'ptn_recursive_end');
try {
    xml_parse($recursive, '<root/>');
} catch (Throwable $exception) {
    echo $exception::class, ': ', $exception->getMessage(), \"\\n\";
}

$badBase = new DOMCharacterData();
$badReader = new XMLReader();
$badReader->XML('<books><book>bad base</book></books>');
while ($badReader->read()) {
    if ($badReader->localName === 'book') {
        var_dump($badReader->expand($badBase));
        break;
    }
}

$dom = new DOMDocument();
$dom->loadXML('<books><book>base book</book></books>');
$reader = new XMLReader();
$reader->XML('<books><book>new book</book></books>');
while ($reader->read()) {
    if ($reader->localName === 'book') {
        $node = $reader->expand($dom);
        echo $node->ownerDocument->documentElement->firstChild->textContent, \"\\n\";
        break;
    }
}
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    let stdout = String::from_utf8(execution.stdout).unwrap();
    assert!(stdout.contains(
        "ValueError: xml_set_object(): Argument #2 ($object) cannot safely swap to object of class B as method \"end_element\" does not exist, which was set via xml_set_element_handler()\n"
    ));
    assert!(stdout.contains("A::start_element(DELAYED)\n"));
    assert!(stdout.contains("A::end_element(DELAYED)\n"));
    assert!(stdout.contains("Serialization of 'XMLParser' is not allowed\n"));
    assert!(stdout.contains("Error: Parser must not be called recursively\n"));
    assert!(stdout.contains("Warning: XMLReader::expand(): Couldn't fetch DOMCharacterData"));
    assert!(stdout.contains("bool(false)\n"));
    assert!(stdout.ends_with("base book\n"));
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("XMLParser"));
    assert!(c_source.contains("ptn_xml_reader_call_method"));
}

#[test]
fn compile_xml_parser_element_handler_validation_to_native_binary() {
    let root = temp_dir("ptn-native-xml-parser-element-handler-validation");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("xml-parser-element-handler-validation.php");
    let output = root.join("xml-parser-element-handler-validation-bin");
    fs::write(
        &input,
        "<?php
class TrampolineTest {
    public function __call(string $name, array $arguments) {}
}

$object = new TrampolineTest();
$parser = xml_parser_create();
foreach ([[[], [$object, 'end_handler']], [[$object, 'start_handler'], []]] as $handlers) {
    try {
        xml_set_element_handler($parser, $handlers[0], $handlers[1]);
    } catch (Throwable $exception) {
        echo $exception::class, ': ', $exception->getMessage(), \"\\n\";
    }
}
foreach ([['missing_start', null], [null, 'missing_end']] as $handlers) {
    try {
        xml_set_element_handler($parser, $handlers[0], $handlers[1]);
    } catch (Throwable $exception) {
        echo $exception::class, ': ', $exception->getMessage(), \"\\n\";
    }
}
xml_set_object($parser, new stdClass());
foreach ([['missing_start', null], [null, 'missing_end']] as $handlers) {
    try {
        xml_set_element_handler($parser, $handlers[0], $handlers[1]);
    } catch (Throwable $exception) {
        echo $exception::class, ': ', $exception->getMessage(), \"\\n\";
    }
}
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    let stdout = String::from_utf8(execution.stdout).unwrap();
    assert!(stdout.contains(
        "TypeError: xml_set_element_handler(): Argument #2 ($start_handler) must be of type callable|string|null\n"
    ));
    assert!(stdout.contains(
        "TypeError: xml_set_element_handler(): Argument #3 ($end_handler) must be of type callable|string|null\n"
    ));
    assert_eq!(
        stdout
            .matches("Deprecated: xml_set_element_handler(): Passing non-callable strings is deprecated since 8.4")
            .count(),
        4
    );
    assert_eq!(
        stdout
            .matches("Deprecated: Function xml_set_object() is deprecated since 8.4")
            .count(),
        1
    );
    assert!(stdout.contains(
        "ValueError: xml_set_element_handler(): Argument #2 ($start_handler) an object must be set via xml_set_object() to be able to lookup method\n"
    ));
    assert!(stdout.contains(
        "ValueError: xml_set_element_handler(): Argument #3 ($end_handler) an object must be set via xml_set_object() to be able to lookup method\n"
    ));
    assert!(stdout.contains(
        "ValueError: xml_set_element_handler(): Argument #2 ($start_handler) method stdClass::missing_start() does not exist\n"
    ));
    assert!(stdout.contains(
        "ValueError: xml_set_element_handler(): Argument #3 ($end_handler) method stdClass::missing_end() does not exist\n"
    ));
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_internal_xml_set_element_handler"));
}

