#[test]
fn compile_dom_current_red_schema_and_reconstructed_element_to_native_binary() {
    let root = temp_dir("ptn-native-dom-current-red-schema-reconstructed-element");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("dom-current-red-schema-reconstructed-element.php");
    let output = root.join("dom-current-red-schema-reconstructed-element-bin");
    fs::write(
        &input,
        r#"<?php
$doc = new DOMDocument();
$doc->loadXML(<<<'XML'
<books>
    <book><title>First</title></book>
    <book is-hardback="true"><title>Second</title></book>
</books>
XML);
$xsd = <<<'XSD'
<xs:schema xmlns:xs="http://www.w3.org/2001/XMLSchema">
  <xs:element name="books">
    <xs:complexType>
      <xs:sequence>
        <xs:element name="book" maxOccurs="unbounded">
          <xs:complexType>
            <xs:sequence>
              <xs:element name="title" type="xs:string"/>
            </xs:sequence>
            <xs:attribute name="is-hardback" type="xs:boolean" default="false" use="optional"/>
          </xs:complexType>
        </xs:element>
      </xs:sequence>
    </xs:complexType>
  </xs:element>
</xs:schema>
XSD;
var_dump($doc->schemaValidateSource($xsd, LIBXML_SCHEMA_CREATE));
foreach ($doc->getElementsByTagName('book') as $book) {
    var_dump($book->getAttribute('is-hardback'));
}

$el = new DOMElement('name');
$el->append($child = new DOMElement('child'));
$container = new DOMDocument();
$container->appendChild($el);
$el->__construct('newname');
$container->appendChild($el);
echo $container->saveXML();
$other = new DOMDocument();
try {
    $other->appendChild($el);
} catch (DOMException $e) {
    echo $e->getMessage(), "\n";
}
var_dump($child->ownerDocument === $container);
"#,
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "bool(true)\n",
            "string(5) \"false\"\n",
            "string(4) \"true\"\n",
            "<?xml version=\"1.0\"?>\n",
            "<name><child/></name>\n",
            "<newname/>\n",
            "Wrong Document Error\n",
            "bool(true)\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_dom_schema_validate_source_with_libxml"));
    assert!(c_source.contains("allow_reconstructed_document_element_sibling"));
}

#[test]
fn compile_dom_relaxng_validation_to_native_binary() {
    let root = temp_dir("ptn-native-dom-relaxng-validation");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("dom-relaxng-validation.php");
    let output = root.join("dom-relaxng-validation-bin");
    let rng_path = root.join("apple.rng");
    fs::write(
        &rng_path,
        r#"<element name="apple" xmlns="http://relaxng.org/ns/structure/1.0">
  <element name="pear"><empty/></element>
</element>
"#,
    )
    .unwrap();
    fs::write(
        &input,
        r#"<?php
$invalid = new DOMDocument();
$invalid->loadXML('<apple><pear/><pear/></apple>');
$validRng = <<<'RNG'
<element name="apple" xmlns="http://relaxng.org/ns/structure/1.0">
  <element name="pear"><empty/></element>
</element>
RNG;
$invalidRng = <<<'RNG'
<element name="apple" xmlns="http://relaxng.org/ns/structure/1.0"></element>
RNG;
var_dump($invalid->relaxNGValidateSource($validRng));
var_dump($invalid->relaxNGValidateSource($invalidRng));
var_dump($invalid->relaxNGValidate('__RNG_PATH__'));
$valid = new DOMDocument();
$valid->loadXML('<apple><pear/></apple>');
var_dump($valid->relaxNGValidateSource($validRng));
"#
        .replace("__RNG_PATH__", &rng_path.to_string_lossy()),
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    let stdout = String::from_utf8(execution.stdout).unwrap();
    assert!(
        stdout.matches("bool(false)\n").count() >= 3,
        "unexpected stdout:\n{stdout}"
    );
    assert!(
        stdout.ends_with("bool(true)\n"),
        "unexpected stdout:\n{stdout}"
    );
    assert!(
        stdout.contains("DOMDocument::relaxNGValidateSource(): Did not expect element pear there"),
        "unexpected stdout:\n{stdout}"
    );
    assert!(
        stdout.contains(
            "DOMDocument::relaxNGValidateSource(): xmlRelaxNGParseElement: element has no content"
        ),
        "unexpected stdout:\n{stdout}"
    );
    assert!(
        stdout.contains("DOMDocument::relaxNGValidateSource(): Invalid RelaxNG"),
        "unexpected stdout:\n{stdout}"
    );
    assert!(
        stdout.contains("DOMDocument::relaxNGValidate(): Did not expect element pear there"),
        "unexpected stdout:\n{stdout}"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_dom_relaxng_validate_with_libxml"));
    assert!(c_source.contains("xmlRelaxNGValidateDoc"));
}

#[test]
fn compile_dom_element_attribute_map_and_parent_mutators_to_native_binary() {
    let root = temp_dir("ptn-native-dom-element-attribute-map-parent-mutators");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("dom-element-attribute-map-parent-mutators.php");
    let output = root.join("dom-element-attribute-map-parent-mutators-bin");
    fs::write(
        &input,
        "<?php
$doc = new DOMDocument();
$doc->loadXML('<root xmlns:a=\"urn:a\"><item id=\"one\">text</item></root>');
$root = $doc->documentElement;
$root->setAttributeNS('urn:b', 'b:flag', 'v');
$attr = $root->getAttributeNodeNS('urn:b', 'flag');
var_dump($attr->namespaceURI, $attr->prefix, $attr->localName, $attr->nodeValue);

$attributes = $root->attributes;
var_dump($attributes instanceof DOMNamedNodeMap, $attributes->length);
foreach ($attributes as $attribute) {
    echo $attribute->nodeName, '=', $attribute->nodeValue, '|', ($attribute->namespaceURI === NULL ? 'NULL' : $attribute->namespaceURI), \"\\n\";
}
var_dump(
    $attributes->item(0)->nodeName,
    $attributes->getNamedItem('b:flag')->nodeValue,
    $attributes->getNamedItemNS('urn:b', 'flag')->nodeName
);

$copy = clone $doc;
$copyItem = $copy->documentElement->firstElementChild;
$copyItem->insertAdjacentText('afterbegin', 'C');
var_dump($copyItem->nodeValue);
echo $copy->saveXML();

$item = $root->firstElementChild;
var_dump($item->toggleAttribute('data-x'), $item->toggleAttribute('data-x', false));
$item->insertAdjacentText('afterbegin', 'A');
$item->insertAdjacentElement('beforeend', $doc->createElement('tail'));
$item->insertAdjacentElement('afterend', $doc->createElement('sibling'));
echo $doc->saveXML();

$root->replaceChildren('reset', $doc->createElement('done'));
echo $doc->saveXML();

$other = new DOMDocument();
$other->loadXML('<other><m/></other>');
$root->lastElementChild->insertAdjacentElement('afterbegin', $other->documentElement->firstChild);
echo $doc->saveXML();
echo $other->saveXML();

$detachedDoc = new DOMDocument();
$detachedRoot = $detachedDoc->createElement('root');
$detachedDoc->appendChild($detachedRoot);
$detachedAttr = $detachedRoot->setAttribute('category', 'books');
$detachedDoc->removeChild($detachedRoot);
var_dump($detachedAttr->ownerElement);
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "string(5) \"urn:b\"\n",
            "string(1) \"b\"\n",
            "string(4) \"flag\"\n",
            "string(1) \"v\"\n",
            "bool(true)\n",
            "int(1)\n",
            "b:flag=v|urn:b\n",
            "string(6) \"b:flag\"\n",
            "string(1) \"v\"\n",
            "string(6) \"b:flag\"\n",
            "string(5) \"Ctext\"\n",
            "<?xml version=\"1.0\"?>\n",
            "<root xmlns:a=\"urn:a\" xmlns:b=\"urn:b\" b:flag=\"v\"><item id=\"one\">Ctext</item></root>\n",
            "bool(true)\n",
            "bool(false)\n",
            "<?xml version=\"1.0\"?>\n",
            "<root xmlns:a=\"urn:a\" xmlns:b=\"urn:b\" b:flag=\"v\"><item id=\"one\">Atext<tail/></item><sibling/></root>\n",
            "<?xml version=\"1.0\"?>\n",
            "<root xmlns:a=\"urn:a\" xmlns:b=\"urn:b\" b:flag=\"v\">reset<done/></root>\n",
            "<?xml version=\"1.0\"?>\n",
            "<root xmlns:a=\"urn:a\" xmlns:b=\"urn:b\" b:flag=\"v\">reset<done><m/></done></root>\n",
            "<?xml version=\"1.0\"?>\n",
            "<other/>\n",
            "NULL\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("DOMNamedNodeMap"));
    assert!(c_source.contains("ptn_dom_insert_adjacent_element_method"));
    assert!(c_source.contains("ptn_dom_replace_children_method"));
}

