#[test]
fn compile_dom_html_document_encoding_bom_override_and_eof_to_native_binary() {
    let root = temp_dir("ptn-native-dom-html-document-encoding-bom-override-eof");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("dom-html-document-encoding-bom-override-eof.php");
    let output = root.join("dom-html-document-encoding-bom-override-eof-bin");
    fs::write(
        &input,
        r#"<?php
try {
    Dom\HTMLDocument::createFromString("<p>x</p>", overrideEncoding: "nonexistent");
} catch (ValueError $exception) {
    echo $exception->getMessage(), "\n";
}

$gb18030 = "<!doctype html><html><head><title>No charset!</title></head><body>\n    H" . hex2bin("a8a6") . "llo, world!\n</body>";
$decoded = Dom\HTMLDocument::createFromString($gb18030, overrideEncoding: "GB18030");
echo bin2hex($decoded->documentElement->lastChild->textContent), "\n";
var_dump($decoded->charset);

$empty = Dom\HTMLDocument::createEmpty("GB18030");
$container = $empty->createElement("container");
$empty->append($container);
$container->append(hex2bin("f0908d88"));
echo bin2hex($empty->saveHtml()), "\n";

$invalid = Dom\HTMLDocument::createEmpty();
$invalidContainer = $invalid->createElement("container");
$invalid->append($invalidContainer);
$invalidContainer->append(hex2bin("ff"));
echo bin2hex($invalid->saveHtml()), "\n";

$brokenGb18030 = Dom\HTMLDocument::createFromString("<!doctype html><html><head><meta charset=\"gb18030\"></head><body>" . hex2bin("9030"));
$brokenGb18030->charset = "UTF-8";
echo bin2hex($brokenGb18030->body->textContent), "\n";

$bom = Dom\HTMLDocument::createFromString("\xEF\xBB\xBF<!doctype html><html><head><meta charset=\"utf-16\"></head><body></body></html>");
var_dump($bom->characterSet);
$bom->body->textContent = hex2bin("c3a9");
echo bin2hex($bom->saveHtml()), "\n";

$text = str_repeat(hex2bin("e28093"), 1359);
$doc = Dom\HTMLDocument::createFromString("<!DOCTYPE HTML><html>" . $text, 0, "UTF-8");
var_dump($doc->body->textContent === $text);
"#,
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "Dom\\HTMLDocument::createFromString(): Argument #3 ($overrideEncoding) must be a valid document encoding\n",
            "0a2020202048c3a96c6c6f2c20776f726c64210a\n",
            "string(7) \"gb18030\"\n",
            "3c636f6e7461696e65723e9030d5303c2f636f6e7461696e65723e\n",
            "3c636f6e7461696e65723eefbfbd3c2f636f6e7461696e65723e\n",
            "efbfbd\n",
            "string(5) \"UTF-8\"\n",
            "3c21444f43545950452068746d6c3e3c68746d6c3e3c686561643e3c6d65746120636861727365743d227574662d3136223e3c2f686561643e3c626f64793ec3a93c2f626f64793e3c2f68746d6c3e\n",
            "bool(true)\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_dom_html_canonical_encoding_from_operand_alloc"));
    assert!(c_source.contains("ptn_dom_html_prepare_source_for_parse"));
}

#[test]
fn compile_dom_html_document_noimplied_and_import_void_serialization_to_native_binary() {
    let root = temp_dir("ptn-native-dom-html-noimplied-import-void");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("dom-html-noimplied-import-void.php");
    let output = root.join("dom-html-noimplied-import-void-bin");
    let noimplied_file = root.join("noimplied-input.html");
    fs::write(
        &input,
        format!(
            r#"<?php
function show_noimplied(string $html, string $file): void {{
    file_put_contents($file, $html);
    $fromString = Dom\HTMLDocument::createFromString($html, LIBXML_HTML_NOIMPLIED | LIBXML_NOERROR);
    $output = $fromString->saveHtml();
    echo $output, "\n";
    $fromFile = Dom\HTMLDocument::createFromFile($file, LIBXML_HTML_NOIMPLIED | LIBXML_NOERROR);
    var_dump($output === $fromFile->saveHtml());
}}

show_noimplied("", {});
show_noimplied("<!-- start --><body><head><html>foo</html></head></body><!-- end -->", {});

$xml = Dom\XMLDocument::createFromString('<html><body xmlns="http://www.w3.org/1999/xhtml"><br/><default:p xmlns:default="http://www.w3.org/1999/xhtml" id="import">x</default:p></body></html>');
$html = Dom\HTMLDocument::createEmpty();
$html->appendChild($html->importNode($xml->documentElement, true));
echo $html->saveXml();
"#,
            php_string_literal(&noimplied_file),
            php_string_literal(&noimplied_file)
        ),
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    let stdout = String::from_utf8(execution.stdout).unwrap();
    assert!(stdout.starts_with("\nbool(true)\n"));
    assert!(stdout.contains("<!-- start --><body>foo</body><!-- end -->\nbool(true)\n"));
    assert!(stdout.contains("<br />"));
    assert!(
        stdout.contains("<p xmlns:default=\"http://www.w3.org/1999/xhtml\" id=\"import\">x</p>")
    );
    assert!(!stdout.contains("<html><head></head><body></body></html>"));
    assert!(!stdout.contains("<br></br>"));
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_dom_html_normalize_body_misnested_wrappers"));
    assert!(c_source.contains("PTN_LIBXML_HTML_NOIMPLIED"));
}

#[test]
fn compile_dom_attribute_node_namespace_conflicts_to_native_binary() {
    let root = temp_dir("ptn-native-dom-attribute-node-namespace-conflicts");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("dom-attribute-node-namespace-conflicts.php");
    let output = root.join("dom-attribute-node-namespace-conflicts-bin");
    fs::write(
        &input,
        "<?php
$doc = new DOMDocument();
$doc->appendChild($doc->createElement('container'));
var_dump($doc->documentElement->setAttributeNode($doc->createAttributeNS('http://php.net/ns1', 'hello'))?->namespaceURI);
echo $doc->saveXML();
var_dump($doc->documentElement->setAttributeNode($doc->createAttributeNS('http://php.net/ns2', 'hello'))?->namespaceURI);
echo $doc->saveXML();

$doc = new DOMDocument();
$doc->appendChild($doc->createElement('container'));
$attr = $doc->createAttributeNS('http://php.net/ns1', 'foo:hello');
$attr->nodeValue = '1';
var_dump($doc->documentElement->setAttributeNodeNS($attr)?->nodeValue);
$attr = $doc->createAttributeNS('http://php.net/ns1', 'bar:hello');
$attr->nodeValue = '2';
var_dump($doc->documentElement->setAttributeNodeNS($attr)?->nodeValue);
echo $doc->saveXML();

$dom = new DOMDocument();
$dom->loadXML('<?xml version=\"1.0\"?><container xmlns:foo=\"http://php.net\" foo:bar=\"yes\"/>');
$dom->documentElement->setAttributeNS('http://php.net/2', 'foo:bar', 'no1');
$dom->documentElement->setAttributeNS('http://php.net/2', 'bar', 'no2');
echo $dom->saveXML();

$source = new DOMDocument();
$dest = new DOMDocument();
$source->loadXML('<?xml version=\"1.0\"?><container xmlns:foo=\"http://php.net\" foo:bar=\"yes\"/>');
$dest->loadXML('<?xml version=\"1.0\"?><container xmlns=\"http://php.net\" xmlns:foo=\"http://php.net/2\"/>');
$imported = $dest->importNode($source->documentElement->getAttributeNode('foo:bar'));
var_dump($imported->prefix, $imported->namespaceURI);
$dest->documentElement->setAttributeNodeNS($imported);
echo $dest->saveXML();
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "NULL\n",
            "<?xml version=\"1.0\"?>\n",
            "<container xmlns:default=\"http://php.net/ns1\" default:hello=\"\"/>\n",
            "string(18) \"http://php.net/ns1\"\n",
            "<?xml version=\"1.0\"?>\n",
            "<container xmlns:default=\"http://php.net/ns1\" xmlns:default1=\"http://php.net/ns2\" default1:hello=\"\"/>\n",
            "NULL\n",
            "string(1) \"1\"\n",
            "<?xml version=\"1.0\"?>\n",
            "<container xmlns:foo=\"http://php.net/ns1\" foo:hello=\"2\"/>\n",
            "<?xml version=\"1.0\"?>\n",
            "<container xmlns:foo=\"http://php.net\" xmlns:default=\"http://php.net/2\" foo:bar=\"yes\" default:bar=\"no2\"/>\n",
            "string(7) \"default\"\n",
            "string(14) \"http://php.net\"\n",
            "<?xml version=\"1.0\"?>\n",
            "<container xmlns=\"http://php.net\" xmlns:foo=\"http://php.net/2\" xmlns:default=\"http://php.net\" default:bar=\"yes\"/>\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_dom_set_attribute_node_method"));
    assert!(c_source.contains("ptn_dom_element_attach_attribute"));
}

#[test]
fn compile_dom_modern_attribute_metadata_pack_to_native_binary() {
    let root = temp_dir("ptn-native-dom-modern-attribute-metadata-pack");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("dom-modern-attribute-metadata-pack.php");
    let output = root.join("dom-modern-attribute-metadata-pack-bin");
    fs::write(
        &input,
        r#"<?php
$ids = Dom\HTMLDocument::createFromString('<main><em id="x"></em></main>', LIBXML_NOERROR);
$em = $ids->getElementById('x');
$em->setAttribute('ID', 'y');
var_dump($ids->getElementById('x')?->nodeName);
var_dump($ids->getElementById('y')?->nodeName);

$created = Dom\HTMLDocument::createEmpty();
$foo = $created->appendChild($created->createElement('foo'));
$foo->setAttribute('id', 'made');
var_dump($created->getElementById('made')?->nodeName);

$xmlIds = Dom\XMLDocument::createFromString('<root><test1 xml:id="x"/><test2 xml:id="y"/></root>');
$test1 = $xmlIds->getElementById('x');
$test2 = $xmlIds->getElementById('y');
var_dump($test1?->nodeName, $test2?->nodeName);
$test1->getAttributeNode('xml:id')->value = 'y';
var_dump($xmlIds->getElementById('x')?->nodeName, $xmlIds->getElementById('y')?->nodeName);
$test1->setIdAttribute('xml:id', false);
var_dump($xmlIds->getElementById('y')?->nodeName);
$test1->setIdAttribute('xml:id', true);
var_dump($xmlIds->getElementById('y')?->nodeName);

$html = Dom\HTMLDocument::createEmpty();
$container = $html->appendChild($html->createElement('container'));

$other = Dom\HTMLDocument::createEmpty();
$plain = $other->createAttribute('my-attribute');
$plain->value = '1';
$container->setAttributeNode($plain);
var_dump($plain->ownerDocument === $html);

$other = Dom\HTMLDocument::createEmpty();
$first = $other->createAttributeNS('urn:a', 'a:my-attribute');
$first->value = '2';
$container->setAttributeNode($first);

$other = Dom\HTMLDocument::createEmpty();
$second = $other->createAttributeNS('urn:b', 'a:my-attribute');
$second->value = '3';
$container->setAttributeNode($second);
echo $html->saveHtml($container), "\n";

$plain = $container->getAttributeNode('MY-ATTRIBUTE');
$plain->value = '&amp;';
var_dump($plain->firstChild->nodeValue);
$plain->removeChild($plain->firstChild);
var_dump($plain->value);
echo $html->saveHtml($container), "\n";

$defaultXmlns = $html->createAttributeNS('http://www.w3.org/2000/xmlns/', 'xmlns');
$container->setAttributeNodeNS($defaultXmlns);
$prefixedXmlns = $html->createAttributeNS('http://www.w3.org/2000/xmlns/', 'xmlns:f');
$container->setAttributeNodeNS($prefixedXmlns);
echo $html->saveHtml($container), "\n";

$xml = Dom\XMLDocument::createFromString('<container xmlns="some:ns" xmlns:bar="another:ns"><test xmlns="x:y"/></container>');
$imported = $html->importNode($xml->documentElement, true);
echo $html->saveHtml($imported), "\n";

try {
    $container->prefix = 'x';
} catch (Error $e) {
    echo $e->getMessage(), "\n";
}

$xml = Dom\XMLDocument::createEmpty();
$renamed = $xml->createElementNS('http://www.w3.org/1999/xhtml', 'foo:bar');
$renamed->rename('urn:x', 'foo:baz');
var_dump($renamed->nodeName, $renamed->namespaceURI, $renamed->prefix);

try {
    $container->attributes[][0] = 1;
} catch (Error $e) {
    echo $e->getMessage(), "\n";
}
"#,
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "NULL\n",
            "string(2) \"EM\"\n",
            "string(3) \"FOO\"\n",
            "string(5) \"test1\"\n",
            "string(5) \"test2\"\n",
            "NULL\n",
            "string(5) \"test1\"\n",
            "string(5) \"test2\"\n",
            "string(5) \"test1\"\n",
            "bool(true)\n",
            "<container my-attribute=\"1\" a:my-attribute=\"2\" a:my-attribute=\"3\"></container>\n",
            "string(5) \"&amp;\"\n",
            "string(0) \"\"\n",
            "<container my-attribute=\"\" a:my-attribute=\"2\" a:my-attribute=\"3\"></container>\n",
            "<container my-attribute=\"\" a:my-attribute=\"2\" a:my-attribute=\"3\" xmlns=\"\" xmlns:f=\"\"></container>\n",
            "<container xmlns=\"some:ns\" xmlns:bar=\"another:ns\"><test xmlns=\"x:y\"></test></container>\n",
            "Cannot modify private(set) property Dom\\Element::$prefix from global scope\n",
            "string(7) \"foo:baz\"\n",
            "string(5) \"urn:x\"\n",
            "string(3) \"foo\"\n",
            "Cannot append to Dom\\NamedNodeMap\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_dom_element_rename_method"));
    assert!(c_source.contains("ptn_xml_attribute_ensure_text_child"));
    assert!(c_source.contains("ptn_xml_attribute_is_synthetic_namespace_declaration"));
    assert!(c_source.contains("Cannot append to %s"));
}

#[test]
fn compile_dom_modern_node_document_residual_semantics_to_native_binary() {
    let root = temp_dir("ptn-native-dom-modern-node-document-residual-semantics");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("dom-modern-node-document-residual-semantics.php");
    let output = root.join("dom-modern-node-document-residual-semantics-bin");
    fs::write(
        &input,
        r#"<?php
$xml = Dom\XMLDocument::createEmpty();
$root = $xml->appendChild($xml->createElement('root'));
$attr = $xml->createAttributeNS('http://www.w3.org/2000/xmlns/', 'xmlns:p');
$root->setAttributeNodeNS($attr);
var_dump($root->attributes->length);
var_dump($attr->namespaceURI);
var_dump($attr->prefix);

$html = Dom\HTMLDocument::createEmpty();
try {
    $html->createCDATASection('foo');
} catch (DOMException $e) {
    var_dump($e->getCode());
    echo $e->getMessage(), "\n";
}

try {
    $xml->createCDATASection(']]>');
} catch (DOMException $e) {
    var_dump($e->getCode());
    echo $e->getMessage(), "\n";
}

$legacy = new DOMDocument();
try {
    $legacy->nodeValue = [];
} catch (TypeError $e) {
    echo $e->getMessage(), "\n";
}
try {
    $legacy->nodeType += 1;
} catch (Error $e) {
    echo $e->getMessage(), "\n";
}
try {
    $legacy->xmlEncoding = null;
} catch (Error $e) {
    echo $e->getMessage(), "\n";
}
$entity = new DOMEntity();
foreach (['actualEncoding', 'encoding', 'version'] as $property) {
    try {
        $entity->{$property} = null;
    } catch (Error $e) {
        echo $e->getMessage(), "\n";
    }
}

$document = new DOMDocument();
$xpath = new DOMXPath($document);
$xpath->registerNamespace('my', 'my.ns');
$xpath->registerPHPFunctionNS('my.ns', 'include', function(): DOMElement {
    $includedDocument = new DOMDocument();
    $includedDocument->loadXML('<root><uaf/><node/><uaf/></root>');
    return $includedDocument->documentElement;
});
$nodes = $xpath->query('my:include()/uaf');
var_dump($nodes->length);
var_dump($nodes->item(0)->ownerDocument->saveXML($nodes->item(0)));
"#,
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "int(1)\n",
            "string(29) \"http://www.w3.org/2000/xmlns/\"\n",
            "string(5) \"xmlns\"\n",
            "int(9)\n",
            "This operation is not supported for HTML documents\n",
            "int(5)\n",
            "Invalid character sequence \"]]>\" in CDATA section\n",
            "Cannot assign array to property DOMNode::$nodeValue of type ?string\n",
            "Cannot modify private(set) property DOMNode::$nodeType from global scope\n",
            "Cannot modify private(set) property DOMDocument::$xmlEncoding from global scope\n",
            "Cannot modify private(set) property DOMEntity::$actualEncoding from global scope\n",
            "Cannot modify private(set) property DOMEntity::$encoding from global scope\n",
            "Cannot modify private(set) property DOMEntity::$version from global scope\n",
            "int(2)\n",
            "string(6) \"<uaf/>\"\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_dom_xpath_register_php_function_ns_method"));
    assert!(c_source.contains("PTN_DOM_NOT_SUPPORTED_ERR"));
    assert!(c_source.contains("Cannot assign array to property DOMNode::$nodeValue"));
}

#[test]
fn compile_dom_node_document_current_red_pack_to_native_binary() {
    let root = temp_dir("ptn-native-dom-node-document-current-red-pack");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("dom-node-document-current-red-pack.php");
    let output = root.join("dom-node-document-current-red-pack-bin");
    fs::write(
        &input,
        r#"<?php
echo "--xml-version--\n";
$xml = Dom\XMLDocument::createFromString('<root><child/></root>');
var_dump($xml->xmlVersion);
foreach (['0.1', '1.0', '1.1', '', 'foo'] as $version) {
    try {
        $xml->xmlVersion = $version;
    } catch (ValueError $e) {
        echo $e->getMessage(), "\n";
    }
    var_dump($xml->xmlVersion);
}

echo "--type-checks--\n";
$doc = new DOMDocument;
$doc->loadXML('<?xml version="1.0"?><container><test/><child><testelement/></child></container>');
$testElement = $doc->documentElement->firstElementChild->nextElementSibling->firstElementChild;
try {
    $doc->documentElement->firstElementChild->prepend($testElement, 0);
} catch (TypeError $e) {
    echo $e->getMessage(), "\n";
}
try {
    $doc->documentElement->firstElementChild->append($testElement, true);
} catch (TypeError $e) {
    echo $e->getMessage(), "\n";
}
try {
    $doc->documentElement->firstElementChild->before($testElement, null);
} catch (TypeError $e) {
    echo $e->getMessage(), "\n";
}
try {
    $doc->documentElement->firstElementChild->after($testElement, new stdClass);
} catch (TypeError $e) {
    echo $e->getMessage(), "\n";
}
try {
    $doc->documentElement->firstElementChild->replaceWith($testElement, []);
} catch (TypeError $e) {
    echo $e->getMessage(), "\n";
}
echo $doc->saveXML();

echo "--before-prefix--\n";
$doc = new DOMDocument();
$doc->loadXML('<a>foo<last/></a>');
$target = $doc->documentElement->lastChild;
$target->before('bar', $doc->documentElement->firstChild, 'baz');
echo $doc->saveXML($doc->documentElement), "\n";
var_dump($target->prefix);

echo "--replace-with--\n";
$doc = new DOMDocument();
$doc->appendChild($target = $doc->createElement('test'));
$target->replaceWith($target, $doc->createElement('foo'));
var_dump($doc->saveXML());
$doc = new DOMDocument();
$doc->appendChild($target = $doc->createElement('test'));
$target->replaceWith('bar', $target, 'foo');
var_dump($doc->saveXML());

echo "--import-document--\n";
$legacy = new DOMDocument();
var_dump($legacy->importNode($legacy));
$modern = Dom\HTMLDocument::createEmpty();
try {
    $modern->importNode($modern);
} catch (DOMException $e) {
    echo $e->getMessage(), "\n";
}

echo "--element-constructor--\n";
$v0 = new DOMElement("jg");
$v1 = new DOMDocument("Zb");
$v2 = new DOMElement("IU");
$v7 = new DOMElement("L", null, "df");
$v0->replaceChildren($v7);
$v7->before($v2);
$v1->insertBefore($v0);
echo $v1->saveXML();

echo "--rename--\n";
$dom = Dom\XMLDocument::createFromString('<root xmlns:a="urn:a"><a:child attrib="value"/></root>');
$dom->documentElement->rename("urn:x", "x:foo");
echo $dom->saveXML(), "\n";
var_dump($dom->documentElement->namespaceURI, $dom->documentElement->prefix);
$dom->documentElement->rename("urn:x", "a:foo");
echo $dom->saveXML(), "\n";
var_dump($dom->documentElement->namespaceURI, $dom->documentElement->prefix);
$dom->documentElement->rename("", "bar");
$attr = $dom->documentElement->firstElementChild->attributes[0];
$attr->rename("urn:x", "x:foo");
echo $dom->saveXML(), "\n";
$attr->rename("urn:x", "a:foo");
echo $dom->saveXML(), "\n";
var_dump($attr->namespaceURI, $attr->prefix);
$attr->rename(null, "bar");
echo $dom->saveXML(), "\n";
var_dump($attr->namespaceURI, $attr->prefix);

echo "--namespace-print--\n";
$dom = new DOMDocument();
$dom->loadXML('<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xsi="foo"/>');
print_r($dom->documentElement->getAttributeNode('xmlns'));

echo "--xinclude--\n";
function ptn_count_dom_elements($nodes) {
    $count = 0;
    foreach ($nodes as $node) {
        if ($node instanceof DOMElement) {
            $count++;
            if ($node->childNodes->length > 0) {
                $count += ptn_count_dom_elements($node->childNodes);
            }
        }
    }
    return $count;
}
$doc = new DOMDocument();
$doc->loadXML('<?xml version="1.0" encoding="UTF-8"?><root xmlns:xi="http://www.w3.org/2001/XInclude"><a><a_child1>ac1</a_child1><a_child2>ac2</a_child2></a><b><xi:include xpointer="xpointer(/root/a)" /></b><c><xi:include xpointer="xpointer(/root/b)" /></c></root>');
$doc->xinclude();
var_dump(ptn_count_dom_elements([$doc->documentElement]));

echo "--detached-attributes--\n";
$dom = new DOMDocument();
$dom->loadXML('<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><url xmlns:xsi="foo" myattrib="bar"/></urlset>');
$attr = $dom->documentElement->firstElementChild->getAttributeNode('myattrib');
$dom->documentElement->firstElementChild->remove();
var_dump($attr->parentNode);
$dom = new DOMDocument();
$dom->loadXML('<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><url xmlns:xsi="foo" myattrib="bar"/></urlset>');
$ns = $dom->documentElement->firstElementChild->getAttributeNode('xmlns:xsi');
$dom->documentElement->firstElementChild->remove();
var_dump($ns->parentNode->nodeName);
"#,
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    let stdout = String::from_utf8(execution.stdout).unwrap();
    assert!(stdout.contains(
        "--xml-version--\nstring(3) \"1.0\"\nInvalid XML version\nstring(3) \"1.0\"\nstring(3) \"1.0\"\nstring(3) \"1.1\"\nInvalid XML version\nstring(3) \"1.1\"\nInvalid XML version\nstring(3) \"1.1\"\n"
    ));
    assert!(stdout.contains(
        "DOMElement::prepend(): Argument #2 must be of type DOMNode|string, int given\n"
    ));
    assert!(stdout.contains(
        "DOMElement::append(): Argument #2 must be of type DOMNode|string, bool given\n"
    ));
    assert!(stdout.contains(
        "DOMElement::before(): Argument #2 must be of type DOMNode|string, null given\n"
    ));
    assert!(stdout.contains(
        "DOMElement::after(): Argument #2 must be of type DOMNode|string, stdClass given\n"
    ));
    assert!(stdout.contains(
        "DOMElement::replaceWith(): Argument #2 must be of type DOMNode|string, array given\n"
    ));
    assert!(stdout.contains("<container><test/><child><testelement/></child></container>"));
    assert!(stdout.contains("--before-prefix--\n<a>barfoobaz<last/></a>\nstring(0) \"\"\n"));
    assert!(stdout.contains("<test/>\n<foo/>\n"));
    assert!(stdout.contains("bar\n<test/>\nfoo\n"));
    assert!(stdout
        .contains("Warning: DOMDocument::importNode(): Cannot import: Node Type Not Supported"));
    assert!(stdout.contains("bool(false)\nNot Supported Error\n"));
    assert!(stdout.contains(
        "<?xml version=\"Zb\"?>\n<jg xmlns:default=\"df\"><IU/><default:L xmlns=\"df\"/></jg>\n"
    ));
    assert!(stdout.contains("<x:foo xmlns:x=\"urn:x\" xmlns:a=\"urn:a\">"));
    assert!(stdout.contains("<ns1:foo xmlns:ns1=\"urn:x\" xmlns:a=\"urn:a\">"));
    assert!(stdout.contains("string(5) \"urn:x\"\nstring(1) \"a\"\n"));
    assert!(stdout.contains("<a:child xmlns:x=\"urn:x\" x:foo=\"value\"/>"));
    assert!(stdout.contains("<a:child xmlns:a=\"urn:x\" a:foo=\"value\"/>"));
    assert!(stdout.contains("NULL\nNULL\n"));
    assert!(stdout.contains(
        "--namespace-print--\nDOMNameSpaceNode Object\n(\n    [nodeName] => xmlns\n    [nodeValue] => http://www.sitemaps.org/schemas/sitemap/0.9\n    [nodeType] => 18\n"
    ));
    assert!(stdout.contains("    [ownerDocument] => (object value omitted)\n"));
    assert!(stdout.contains("--xinclude--\nint(13)\n"));
    assert!(stdout.contains("--detached-attributes--\nNULL\nstring(3) \"url\"\n"));
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_dom_xml_version_is_valid"));
    assert!(c_source.contains("ptn_xml_check_document_text_insertion"));
    assert!(c_source.contains("ptn_dom_attr_rename_method"));
    assert!(c_source.contains("ptn_xml_mark_detached_transient_parents"));
}

#[test]
fn compile_dom_get_element_by_id_marker_mutations_to_native_binary() {
    let root = temp_dir("ptn-native-dom-get-element-by-id-marker-mutations");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("dom-get-element-by-id-marker-mutations.php");
    let output = root.join("dom-get-element-by-id-marker-mutations-bin");
    fs::write(
        &input,
        r#"<?php
$xml = Dom\XMLDocument::createFromString('<root><test1 xml:id="x"/><test2 xml:id="y"/><test3 attr="x"/></root>');
$test1 = $xml->documentElement->firstElementChild;
$test3 = $xml->documentElement->lastElementChild;
var_dump($xml->getElementById('x')?->nodeName);
$test1->setAttribute('xml:id', 'y');
var_dump($xml->getElementById('x')?->nodeName);
var_dump($xml->getElementById('y')?->nodeName);
$test3->setIdAttribute('attr', true);
var_dump($test3->getAttributeNode('attr')->isId());
var_dump($xml->getElementById('x')?->nodeName);
$test3->setIdAttributeNode($test3->getAttributeNode('attr'), false);
var_dump($test3->getAttributeNode('attr')->isId());
var_dump($xml->getElementById('x')?->nodeName);

$plain = Dom\XMLDocument::createFromString('<root><test1/><test2/></root>');
$p1 = $plain->documentElement->firstElementChild;
$p2 = $p1->nextElementSibling;
$p2->id = 'p';
$p1->id = 'p';
var_dump($plain->getElementById('p')?->nodeName);
$p1->setIdAttribute('id', false);
var_dump($p1->getAttributeNode('id')->isId());
var_dump($plain->getElementById('p')?->nodeName);

$html = Dom\HTMLDocument::createFromString('<p><em id="x"></em><strong id="y"></strong></p>', LIBXML_NOERROR);
$em = $html->getElementById('x');
$em->setAttributeNS('urn:x', 'id', 'z');
var_dump($html->getElementById('x')?->nodeName);
var_dump($html->getElementById('z')?->nodeName);
$em->setAttribute('ID', 'z');
var_dump($html->getElementById('x')?->nodeName);
var_dump($html->getElementById('z')?->nodeName);
"#,
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "string(5) \"test1\"\n",
            "NULL\n",
            "string(5) \"test1\"\n",
            "bool(true)\n",
            "string(5) \"test3\"\n",
            "bool(false)\n",
            "NULL\n",
            "string(5) \"test1\"\n",
            "bool(false)\n",
            "string(5) \"test2\"\n",
            "string(2) \"EM\"\n",
            "NULL\n",
            "NULL\n",
            "string(2) \"EM\"\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_xml_find_element_by_id"));
    assert!(c_source.contains("ptn_dom_set_id_attribute_method"));
    assert!(c_source.contains("ptn_dom_attribute_is_active_id"));
}

#[test]
fn compile_dom_clone_import_namespace_residual_pack_to_native_binary() {
    let root = temp_dir("ptn-native-dom-clone-import-namespace-residual-pack");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("dom-clone-import-namespace-residual-pack.php");
    let output = root.join("dom-clone-import-namespace-residual-pack-bin");
    fs::write(
        &input,
        r#"<?php
$dom = new DOMDocument();
$dom->loadXML('<?xml version="1.0"?><container/>');
$dom->documentElement->setAttributeNS("some:ns", "foo:bar", "value");
$clone = $dom->documentElement->getAttributeNodeNS("some:ns", "bar")->cloneNode(true);
var_dump($clone->prefix, $clone->namespaceURI);
$dom->documentElement->removeAttributeNS("some:ns", "bar");
$dom->documentElement->removeAttribute("xmlns:foo");
$child = $dom->documentElement->appendChild($dom->createElement("child"));
$child->appendChild($clone);
echo $dom->saveXML();

$dom = new DOMDocument();
$dom->loadXML('<?xml version="1.0"?><container xmlns:foo="some:ns" foo:bar="1"><child xmlns:foo="some:other"/></container>');
$clone = $dom->documentElement->getAttributeNodeNS("some:ns", "bar")->cloneNode(true);
$dom->documentElement->firstElementChild->setAttributeNodeNS($clone);
echo $dom->saveXML();

$modern = Dom\XMLDocument::createFromString('<?xml version="1.0"?><root><a:item xmlns:a="urn:a"/></root>');
$item = $modern->documentElement->firstElementChild;
$item->setAttributeNS("urn:y", "a:foo", "bar");
$copy = clone $item;
foreach ($copy->attributes as $attr) {
    var_dump($attr->name, $attr->namespaceURI);
}
echo $modern->saveXml($copy), "\n";

$xml = Dom\XMLDocument::createFromString('<html><body xmlns="http://www.w3.org/1999/xhtml"><br/><default:p xmlns:default="http://www.w3.org/1999/xhtml" id="import">x</default:p></body></html>');
$html = Dom\HTMLDocument::createEmpty();
$imported = $html->importNode($xml->documentElement, true);
$html->appendChild($imported);
$p = $html->getElementsByTagName("body")[0]->lastElementChild;
var_dump($p->prefix, $p->namespaceURI);
echo $html->saveXml();
"#,
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    let stdout = String::from_utf8(execution.stdout).unwrap();
    assert!(stdout.contains("string(3) \"foo\"\nstring(7) \"some:ns\"\n"));
    assert!(stdout
        .contains("<container><child xmlns:foo=\"some:ns\" foo:bar=\"value\"/></container>\n"));
    assert!(
        stdout.contains("<child xmlns:foo=\"some:other\" xmlns:foo1=\"some:ns\" foo1:bar=\"1\"/>")
    );
    assert!(
        stdout.contains("string(7) \"xmlns:a\"\nstring(29) \"http://www.w3.org/2000/xmlns/\"\n")
    );
    assert!(stdout.contains("string(5) \"a:foo\"\nstring(5) \"urn:y\"\n"));
    assert!(stdout.contains("<a:item xmlns:a=\"urn:a\" xmlns:ns1=\"urn:y\" ns1:foo=\"bar\"/>"));
    assert!(stdout.contains("string(7) \"default\"\nstring(28) \"http://www.w3.org/1999/xhtml\"\n"));
    assert!(stdout.contains("<br />"));
    assert!(
        stdout.contains("<p xmlns:default=\"http://www.w3.org/1999/xhtml\" id=\"import\">x</p>")
    );
    assert!(!stdout.contains("<default:p"));
    assert!(!stdout.contains("<br></br>"));
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("serialized_name"));
    assert!(c_source.contains("ptn_dom_attribute_set_serialized_prefix"));
    assert!(c_source.contains("ptn_dom_remove_attribute_method"));
}

#[test]
fn compile_dom_namespace_lookup_and_xmlns_serialization_to_native_binary() {
    let root = temp_dir("ptn-native-dom-namespace-lookup-xmlns-serialization");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("dom-namespace-lookup-xmlns-serialization.php");
    let output = root.join("dom-namespace-lookup-xmlns-serialization-bin");
    fs::write(
        &input,
        "<?php
$doc = new DOMDocument;
$doc->loadXML('<?xml version=\"1.0\"?><container xmlns=\"http://php.net\"/>');
$doc->documentElement->appendChild($doc->createElementNS('http://php.net', 'example'));
echo $doc->saveXML(), \"\\n\";

$dom = Dom\\XMLDocument::createFromString('<?xml version=\"1.0\"?><!DOCTYPE html><html xmlns=\"http://www.w3.org/1999/xhtml\" xmlns:x=\"test\"><body><svg:svg xmlns:svg=\"http://www.w3.org/2000/svg\" height=\"1\"/><p xmlns:y=\"test\"><x/></p></body></html>');
$body = $dom->getElementsByTagName('body')[0];
$body->setAttribute('xmlns:a', 'urn:a');
var_dump($dom->doctype->lookupPrefix(''));
var_dump($body->lookupPrefix('urn:a'));
$svg = $dom->getElementsByTagNameNS('*', 'svg')[0];
var_dump($svg->lookupPrefix('http://www.w3.org/2000/svg'));
foreach (['x', 'p', 'html'] as $name) {
    $node = $dom->getElementsByTagNameNS('*', $name)[0];
    var_dump($node->lookupPrefix('test'));
}

$dom = Dom\\XMLDocument::createEmpty();
$rootElement = $dom->appendChild($dom->createElementNS('http://www.w3.org/XML/1998/namespace', 'xml:test'));
$rootElement->appendChild($dom->createElementNS('http://www.w3.org/XML/1998/namespace', 'xml:child'));
echo $dom->saveXml(), \"\\n\";

$dom = Dom\\XMLDocument::createFromString('<root/>');
$dom->documentElement->setAttributeNS('http://www.w3.org/2000/xmlns/', 'xmlns:xml', 'http://www.w3.org/XML/1998/namespace');
echo $dom->saveXml(), \"\\n\";

$dom = Dom\\XMLDocument::createFromString('<root><x xmlns=\"\"/></root>');
var_dump($dom->documentElement->innerHTML);

$dom = Dom\\XMLDocument::createFromString('<root><x/></root>');
$x = $dom->documentElement->firstChild;
$x->setAttributeNS('http://www.w3.org/2000/xmlns/', 'xmlns:a', '');
try {
    var_dump($dom->documentElement->innerHTML);
} catch (DOMException $e) {
    echo $e->getMessage(), \"\\n\";
}
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "<?xml version=\"1.0\"?>\n",
            "<container xmlns=\"http://php.net\"><example/></container>\n",
            "\n",
            "NULL\n",
            "NULL\n",
            "string(3) \"svg\"\n",
            "string(1) \"y\"\n",
            "string(1) \"y\"\n",
            "string(1) \"x\"\n",
            "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n",
            "<xml:test><xml:child/></xml:test>\n",
            "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n",
            "<root/>\n",
            "string(13) \"<x xmlns=\"\"/>\"\n",
            "The resulting XML serialization is not well-formed\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_dom_lookup_prefix_method"));
    assert!(c_source.contains("ptn_dom_element_inner_html_value"));
}

#[test]
fn compile_dom_xpath_node_class_and_html_edges_to_native_binary() {
    let root = temp_dir("ptn-native-dom-xpath-node-class-html-edges");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("dom-xpath-node-class-html-edges.php");
    let output = root.join("dom-xpath-node-class-html-edges-bin");
    fs::write(
        &input,
        "<?php
echo \"--xpath-query--\\n\";
class MyXPathCallback {
    public static function dump(string $var) {
        var_dump($var);
        return true;
    }
}
$doc = new DOMDocument();
$doc->loadHTML('<a href=\"https://php.net\">hello</a>');
$xpath = new DOMXpath($doc);
$xpath->registerNamespace('php', 'http://php.net/xpath');
$xpath->registerPHPFunctions();
$xpath->query(\"//a[php:function('MyXPathCallback::dump', string(@href))]\");
echo \"Done\\n\";

echo \"--node-class--\\n\";
class myElement extends DOMElement {
    public function testit() { echo \"HELLO Element\\n\"; }
}
class myAttribute extends DOMAttr {
    public function testit() { echo \"HELLO Attribute\\n\"; }
}
$doc = new DOMDocument();
$doc->registerNodeClass('DOMElement', 'myElement');
$doc->registerNodeClass('DOMAttr', 'myAttribute');
$doc->appendChild(new DOMElement('root'));
$attr = $doc->createAttribute('a');
$doc->documentElement->setAttributeNode($attr);
echo get_class($doc->documentElement), \"\\n\";
$doc->documentElement->testit();
$attr = $doc->documentElement->getAttributeNode('a');
echo get_class($attr), \"\\n\";
$attr->testit();
unset($attr);
$doc->registerNodeClass('DOMAttr', null);
$attr = $doc->documentElement->getAttributeNode('a');
echo get_class($attr), \"\\n\";
try {
    $attr->testit();
} catch (Throwable $e) {
    echo $e->getMessage(), \"\\n\";
}

echo \"--xpath-state--\\n\";
class DemoXPath extends DOMXPath {
    public function __construct() {}
}
$demo = new DemoXPath();
try {
    var_dump($demo);
} catch (DOMException $e) {
    echo $e->getMessage(), \"\\n\";
}
try {
    var_dump($demo->document);
} catch (DOMException $e) {
    echo $e->getMessage(), \"\\n\";
}

echo \"--html-nul--\\n\";
$doc = new DOMDocument();
$html = '<!DOCTYPE html><html><head><meta charset=\"UTF-8\"></head><body>U+0000 <span>' . chr(0) . '</span></body></html>';
$doc->loadHTML($html);
echo $doc->saveHTML();
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    let stdout = String::from_utf8(execution.stdout).unwrap();
    assert!(stdout.contains("--xpath-query--\nstring(15) \"https://php.net\"\nDone\n"));
    assert!(stdout.contains(
        "--node-class--\nmyElement\nHELLO Element\nmyAttribute\nHELLO Attribute\nDOMAttr\nCall to undefined method DOMAttr::testit()\n"
    ));
    assert!(stdout.contains("--xpath-state--\nobject(DemoXPath)#"));
    assert!(
        stdout.contains(
            "[\"registerNodeNamespaces\"]=>\n  bool(true)\n}\nInvalid State Error\nInvalid State Error\n"
        )
    );
    assert!(stdout.contains(
        "--html-nul--\n<!DOCTYPE html>\n<html><head><meta charset=\"UTF-8\"></head><body>U+0000 <span>&#65533;</span></body></html>\n"
    ));
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_dom_register_node_class_method"));
    assert!(c_source.contains("ptn_dom_xpath_query_method"));
    assert!(c_source.contains("ptn_dom_html_replace_nuls_with_replacement_alloc"));
}

#[test]
fn compile_curl_setopt_callback_option_surface_to_native_binary() {
    let root = temp_dir("ptn-native-curl-setopt-callback-option");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("curl-setopt-callback-option.php");
    let output = root.join("curl-setopt-callback-option-bin");
    fs::write(
        &input,
        "<?php\n\
class CurlHeaderHandler {\n\
    public static function handle($handle, $line) {\n\
        return strlen($line);\n\
    }\n\
}\n\
$callback = ['CurlHeaderHandler', 'handle'];\n\
$handle = curl_init();\n\
var_dump(function_exists('curl_setopt'));\n\
var_dump(CURLOPT_HEADERFUNCTION);\n\
var_dump(curl_setopt($handle, CURLOPT_HEADERFUNCTION, $callback));\n\
$constants = get_defined_constants(true);\n\
var_dump(isset($constants['curl']['CURLOPT_HEADERFUNCTION']));\n\
$extension = new ReflectionExtension('curl');\n\
var_dump($extension->getConstants()['CURLOPT_HEADERFUNCTION']);\n\
var_dump(isset($extension->getFunctions()['curl_setopt']));\n\
set_error_handler($callback);\n\
set_error_handler(function () use ($handle) {});\n\
echo \"ok\\n\";\n",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        "bool(true)\nint(20079)\nbool(true)\nbool(true)\nint(20079)\nbool(true)\nok\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_internal_curl_setopt"));
    assert!(c_source.contains("CURLOPT_HEADERFUNCTION"));
}

