#[test]
fn compile_curl_file_read_and_write_callbacks_to_native_binary() {
    let root = temp_dir("ptn-native-curl-file-read-write-callbacks");
    fs::create_dir_all(&root).unwrap();
    fs::write(root.join("payload.txt"), "payload").unwrap();
    fs::write(root.join("upload-in.txt"), "contents of tempfile").unwrap();
    fs::write(root.join("download.txt"), "test").unwrap();
    let input = root.join("curl-file-read-write-callbacks.php");
    let output = root.join("curl-file-read-write-callbacks-bin");
    fs::write(
        &input,
        "<?php\n\
function ptn_curl_read($handle, $stream, $max) {\n\
    $data = fread($stream, $max - 10);\n\
    return $data === '' ? '' : 'custom:' . $data;\n\
}\n\
function ptn_curl_write($handle, $data) {\n\
    echo $data;\n\
    return strlen($data);\n\
}\n\
$file = new CURLFile(__DIR__ . '/payload.txt');\n\
try {\n\
    serialize($file);\n\
} catch (Exception $e) {\n\
    echo $e->getMessage(), \"\\n\";\n\
}\n\
$read = fopen(__DIR__ . '/upload-in.txt', 'r');\n\
$upload = curl_init();\n\
curl_setopt($upload, CURLOPT_URL, 'file://' . __DIR__ . '/upload-out.txt');\n\
curl_setopt($upload, CURLOPT_UPLOAD, 1);\n\
curl_setopt($upload, CURLOPT_READFUNCTION, 'ptn_curl_read');\n\
curl_setopt($upload, CURLOPT_INFILE, $read);\n\
var_dump(curl_exec($upload));\n\
fclose($read);\n\
echo file_get_contents(__DIR__ . '/upload-out.txt'), \"\\n\";\n\
$download = curl_init('file://' . __DIR__ . '/download.txt');\n\
curl_setopt($download, CURLOPT_WRITEFUNCTION, 'ptn_curl_write');\n\
var_dump(curl_exec($download));\n",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "Serialization of 'CURLFile' is not allowed\n",
            "bool(true)\n",
            "custom:contents of tempfile\n",
            "testbool(true)\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_curl_read_upload_payload"));
    assert!(c_source.contains("CURLOPT_READFUNCTION"));
    assert!(c_source.contains("CURLFile"));
}

#[test]
fn compile_archive_network_extension_surface_to_native_binary() {
    let root = temp_dir("ptn-native-archive-network-extension-surface");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("archive-network-extension-surface.php");
    let output = root.join("archive-network-extension-surface-bin");
    fs::write(
        &input,
        "<?php
class ExtendedSoapClient extends SoapClient {}

var_dump(
    extension_loaded('phar'),
    extension_loaded('Phar'),
    extension_loaded('zip'),
    extension_loaded('sockets'),
    extension_loaded('soap'),
    extension_loaded('zlib'),
    extension_loaded('openssl'),
    extension_loaded('curl'),
    extension_loaded('SPL')
);
var_dump(
    Phar::apiVersion(),
    Phar::canCompress(),
    Phar::canCompress(Phar::GZ),
    Phar::canCompress(Phar::BZ2),
    Phar::PHP,
    Phar::PHPS,
    Phar::GZ,
    Phar::BZ2,
    ZipArchive::CREATE
);
var_dump(TCP_NODELAY, socket_strerror(1), SOAP_1_1, SOAP_1_2);

$phar = new ReflectionExtension('phar');
$soap = new ReflectionExtension('soap');
$sockets = new ReflectionExtension('sockets');
var_dump(
    $phar->getName(),
    in_array('Phar', $phar->getClassNames(), true),
    $soap->getConstants()['SOAP_1_1'],
    in_array('SoapClient', $soap->getClassNames(), true),
    $sockets->getConstants()['TCP_NODELAY'],
    isset($sockets->getFunctions()['socket_strerror'])
);

$rc = new ReflectionClass('SoapClient');
$pharClass = new ReflectionClass('Phar');
$pharDataClass = new ReflectionClass('PharData');
$pharConstants = $pharClass->getConstants();
$pharDataConstants = $pharDataClass->getConstants();
var_dump(
    $rc->getExtensionName(),
    method_exists('SoapClient', '__construct'),
    class_exists('ZipArchive'),
    method_exists('ZipArchive', 'registerCancelCallback'),
    method_exists('Phar', 'apiVersion'),
    $pharConstants['PHP'],
    $pharConstants['PHPS'],
    array_key_exists('PHP', $pharDataConstants)
);

function &zip_cancel_ref_notice() {}
$zip = new ZipArchive;
var_dump(
    $zip->open(__DIR__ . '/archive.zip', ZipArchive::CREATE),
    $zip->registerCancelCallback(zip_cancel_ref_notice(...)),
    $zip->addFromString('name.txt', 'contents'),
    $zip->close()
);

try {
    new SoapClient('irrelevant', ['encoding' => 'non-sense']);
} catch (Throwable $e) {
    echo get_class($e), ': ', $e->getMessage(), \"\\n\";
}
try {
    new ExtendedSoapClient(null, ['uri' => 'https://example.com']);
} catch (Throwable $e) {
    echo get_class($e), ': ', $e->getMessage(), \"\\n\";
}

$sf = new SoapFault(null, 'x');
$sf->__construct(null, 'x', headerFault: []);
var_dump(
    class_exists('SoapHeader'),
    in_array('SoapHeader', $soap->getClassNames(), true),
    method_exists('SoapClient', '__setSoapHeaders'),
    method_exists('SoapClient', '__soapCall'),
    $sf->headerfault
);
$sf->__construct(null, 'x');
var_dump($sf->headerfault);
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    let expected_notice_61 = format!(
        "\nNotice: Only variable references should be returned by reference in {} on line 61\n",
        input.display()
    );
    let expected_notice_62 = format!(
        "\nNotice: Only variable references should be returned by reference in {} on line 62\n",
        input.display()
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        format!(
            "{}{}{}{}{}",
            concat!(
                "bool(true)\n",
                "bool(true)\n",
                "bool(true)\n",
                "bool(true)\n",
                "bool(true)\n",
                "bool(true)\n",
                "bool(true)\n",
                "bool(true)\n",
                "bool(true)\n",
                "string(5) \"1.1.1\"\n",
                "bool(true)\n",
                "bool(true)\n",
                "bool(false)\n",
                "int(0)\n",
                "int(1)\n",
                "int(4096)\n",
                "int(8192)\n",
                "int(1)\n",
                "int(1)\n",
                "string(23) \"Operation not permitted\"\n",
                "int(1)\n",
                "int(2)\n",
                "string(4) \"Phar\"\n",
                "bool(true)\n",
                "int(1)\n",
                "bool(true)\n",
                "int(1)\n",
                "bool(true)\n",
                "string(4) \"soap\"\n",
                "bool(true)\n",
                "bool(true)\n",
                "bool(true)\n",
                "bool(true)\n",
                "int(0)\n",
                "int(1)\n",
                "bool(false)\n",
            ),
            expected_notice_61,
            expected_notice_61,
            expected_notice_62,
            concat!(
                "bool(true)\n",
                "bool(true)\n",
                "bool(true)\n",
                "bool(true)\n",
                "SoapFault: SoapClient::__construct(): Invalid 'encoding' option - 'non-sense'\n",
                "SoapFault: SoapClient::__construct(): 'location' option is required in nonWSDL mode\n",
                "bool(true)\n",
                "bool(true)\n",
                "bool(true)\n",
                "bool(true)\n",
                "array(0) {\n",
                "}\n",
                "NULL\n",
            ),
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_internal_phar_can_compress"));
    assert!(c_source.contains("ptn_soap_client_new"));
    assert!(c_source.contains("ptn_soap_header_new"));
    assert!(c_source.contains("ptn_soap_call_method"));
    assert!(c_source.contains("ptn_internal_socket_strerror"));
    assert!(c_source.contains("ptn_zip_archive_call_method"));
}

