#[test]
fn compile_phar_manifest_cow_cache_list_state_to_native_binary() {
    fn push_u16(bytes: &mut Vec<u8>, value: u16) {
        bytes.extend_from_slice(&value.to_le_bytes());
    }

    fn push_u32(bytes: &mut Vec<u8>, value: u32) {
        bytes.extend_from_slice(&value.to_le_bytes());
    }

    let root = temp_dir("ptn-native-phar-manifest-cow-cache-list-state");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("manifest-cow-cache-list.phar.php");
    let output = root.join("manifest-cow-cache-list-bin");

    let text_entry = b"hi\n";
    let script_entry = b"<?php echo \"from phar include\\n\"; ?>";
    let mut manifest = Vec::new();
    push_u32(&mut manifest, 2);
    push_u16(&mut manifest, 0x0011);
    push_u32(&mut manifest, 0x00010000);
    push_u32(&mut manifest, 0);
    push_u32(&mut manifest, 9);
    manifest.extend_from_slice(b"s:2:\"hi\";");
    push_u32(&mut manifest, 8);
    manifest.extend_from_slice(b"test.txt");
    push_u32(&mut manifest, text_entry.len() as u32);
    push_u32(&mut manifest, 0);
    push_u32(&mut manifest, text_entry.len() as u32);
    push_u32(&mut manifest, 0);
    push_u32(&mut manifest, 0);
    push_u32(&mut manifest, 0);
    push_u32(&mut manifest, 10);
    manifest.extend_from_slice(b"script.php");
    push_u32(&mut manifest, script_entry.len() as u32);
    push_u32(&mut manifest, 0);
    push_u32(&mut manifest, script_entry.len() as u32);
    push_u32(&mut manifest, 0);
    push_u32(&mut manifest, 0);
    push_u32(&mut manifest, 0);

    let mut source = Vec::new();
    source.extend_from_slice(
        b"<?php\n\
$phar = new Phar(__FILE__);\n\
var_dump($phar->getMetadata());\n\
echo $phar[\"test.txt\"]->getContent();\n\
include \"phar://\" . __FILE__ . \"/script.php\";\n\
$phar[\"test.txt\"] = \"changed\\n\";\n\
echo $phar[\"test.txt\"]->getContent();\n\
mkdir(\"phar://\" . __FILE__ . \"/dir\");\n\
var_dump(is_dir(\"phar://\" . __FILE__ . \"/dir\"), isset($phar[\"dir\"]));\n\
Phar::mount(\"mounted.txt\", \"phar://\" . __FILE__ . \"/test.txt\");\n\
echo file_get_contents(\"phar://\" . __FILE__ . \"/mounted.txt\");\n\
rmdir(\"phar://\" . __FILE__ . \"/dir\");\n\
var_dump(file_exists(\"phar://\" . __FILE__ . \"/dir\"));\n\
ini_set(\"phar.readonly\", \"1\");\n\
var_dump(@fopen(\"phar://\" . __FILE__ . \"/blocked.php\", \"wb\"));\n\
__HALT_COMPILER(); ?>\r\n",
    );
    push_u32(&mut source, manifest.len() as u32);
    source.extend_from_slice(&manifest);
    source.extend_from_slice(text_entry);
    source.extend_from_slice(script_entry);
    fs::write(&input, source).unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        "string(2) \"hi\"\nhi\nfrom phar include\nchanged\nbool(true)\nbool(true)\nchanged\nbool(false)\nbool(false)\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_phar_manifest_read_u16"));
    assert!(c_source.contains("ptn_phar_uri_read_entry"));
    assert!(c_source.contains("ptn_internal_phar_mount"));
}

#[test]
fn compile_phar_manifest_corruption_diagnostics_to_native_binary() {
    fn push_u16(bytes: &mut Vec<u8>, value: u16) {
        bytes.extend_from_slice(&value.to_le_bytes());
    }

    fn push_u32(bytes: &mut Vec<u8>, value: u32) {
        bytes.extend_from_slice(&value.to_le_bytes());
    }

    let root = temp_dir("ptn-native-phar-manifest-corruption");
    fs::create_dir_all(&root).unwrap();

    let truncated_input = root.join("truncated.phar.php");
    let truncated_output = root.join("truncated-phar-bin");
    fs::write(
        &truncated_input,
        "<?php\n\
try {\n\
    Phar::mapPhar();\n\
} catch (Exception $e) {\n\
    echo $e->getMessage(), \"\\n\";\n\
}\n\
__HALT_COMPILER(); ?>",
    )
    .unwrap();

    let compiled = compile_file(
        &truncated_input,
        &truncated_output,
        CompileOptions { emit_c: true },
    )
    .unwrap();
    let execution = Command::new(&truncated_output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        format!(
            "internal corruption of phar \"{}\" (truncated manifest at manifest length)\n",
            truncated_input.display()
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_phar_archive_set_internal_corruption"));

    let reader_input = root.join("phar-corrupt-entry-reader.php");
    let reader_output = root.join("phar-corrupt-entry-reader-bin");
    let archive = root.join("bad-entry.phar.php");

    let wrong_crc_entry = b"a";
    let compressed_entry = [0xcb, 0xc8, 0x04, 0x00];
    let mut manifest = Vec::new();
    push_u32(&mut manifest, 2);
    push_u16(&mut manifest, 0x1000);
    push_u32(&mut manifest, 0x1000);
    push_u32(&mut manifest, 0);
    push_u32(&mut manifest, 0);
    push_u32(&mut manifest, 1);
    manifest.extend_from_slice(b"a");
    push_u32(&mut manifest, wrong_crc_entry.len() as u32);
    push_u32(&mut manifest, 0);
    push_u32(&mut manifest, wrong_crc_entry.len() as u32);
    push_u32(&mut manifest, 0x12345678);
    push_u32(&mut manifest, 0);
    push_u32(&mut manifest, 0);
    push_u32(&mut manifest, 1);
    manifest.extend_from_slice(b"b");
    push_u32(&mut manifest, 1);
    push_u32(&mut manifest, 0);
    push_u32(&mut manifest, compressed_entry.len() as u32);
    push_u32(&mut manifest, 0);
    push_u32(&mut manifest, 0x1000);
    push_u32(&mut manifest, 0);

    let mut source = Vec::new();
    source.extend_from_slice(b"<?php __HALT_COMPILER(); ?>");
    push_u32(&mut source, manifest.len() as u32);
    source.extend_from_slice(&manifest);
    source.extend_from_slice(wrong_crc_entry);
    source.extend_from_slice(&compressed_entry);
    fs::write(&archive, source).unwrap();

    fs::write(
        &reader_input,
        format!(
            "<?php\n\
var_dump(file_get_contents('phar://{}/a'));\n\
var_dump(file_get_contents('phar://{}/b'));\n",
            archive.display(),
            archive.display()
        ),
    )
    .unwrap();
    let compiled = compile_file(
        &reader_input,
        &reader_output,
        CompileOptions { emit_c: true },
    )
    .unwrap();
    let execution = Command::new(&reader_output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        format!(
            "\nWarning: file_get_contents(phar://{}/a): Failed to open stream: phar error: internal corruption of phar \"{}\" (crc32 mismatch on file \"a\") in {} on line 2\n\
bool(false)\n\
\nWarning: file_get_contents(phar://{}/b): Failed to open stream: phar error: internal corruption of phar \"{}\" (actual filesize mismatch on file \"b\") in {} on line 3\n\
bool(false)\n",
            archive.display(),
            archive.display(),
            reader_input.display(),
            archive.display(),
            archive.display(),
            reader_input.display()
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_phar_archive_entry_stream_error"));
}

#[test]
fn compile_phar_alias_lifecycle_conflicts_to_native_binary() {
    let root = temp_dir("ptn-native-phar-alias-lifecycle-conflicts");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("phar-alias-lifecycle.php");
    let output = root.join("phar-alias-lifecycle-bin");
    fs::write(
        &input,
        r#"<?php
$fname = __DIR__ . '/alias-unset.phar.php';
$fname2 = __DIR__ . '/alias-unset.2.phar.php';

$phar = new Phar($fname);
$phar->setAlias('first');
$phar['file1.txt'] = 'hi';
unset($phar);

$phar2 = new Phar($fname2);
var_dump($phar2->setAlias('first'));
$phar2['file1.txt'] = 'hi';
unset($phar2);

$handle = fopen('phar://' . $fname . '/file1.txt', 'r');
try {
    new Phar($fname2);
} catch (Throwable $e) {
    echo "open-conflict:", $e->getMessage(), "\n";
}
fclose($handle);

$phar2 = new Phar($fname2);
echo "alias:", $phar2->getAlias(), "\n";
unset($phar2);

$tar = __DIR__ . '/alias-acrobatics.phar.tar';
$tar2 = __DIR__ . '/alias-acrobatics.2.phar.tar';
$archive = new Phar($tar);
$archive->setAlias('foo');
$archive['unused'] = 'hi';
copy($tar, $tar2);

try {
    new Phar($tar2);
} catch (Throwable $e) {
    echo "tar-conflict:", $e->getMessage(), "\n";
}
"#,
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        format!(
            "bool(true)\nopen-conflict:Cannot open archive \"{}\", alias is already in use by existing archive\nalias:first\ntar-conflict:phar error: Unable to add tar-based phar \"{}\", alias is already in use\n",
            root.join("alias-unset.2.phar.php").display(),
            root.join("alias-acrobatics.2.phar.tar").display()
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_phar_archive_find_active_alias_excluding"));
    assert!(c_source.contains("ptn_phar_archive_has_open_entries"));
}

