#[test]
fn compile_soap_wsdl_backed_enum_field_encoding_to_native_binary() {
    let root = temp_dir("ptn-native-soap-wsdl-backed-enum-field-encoding");
    fs::create_dir_all(&root).unwrap();
    fs::write(
        root.join("gh15711.wsdl"),
        r#"<wsdl:definitions xmlns="http://schemas.xmlsoap.org/wsdl/" xmlns:soap="http://schemas.xmlsoap.org/wsdl/soap/" xmlns:SOAP-ENC="http://schemas.xmlsoap.org/soap/encoding/" xmlns:wsdl="http://schemas.xmlsoap.org/wsdl/" xmlns:xsd="http://www.w3.org/2001/XMLSchema" xmlns:tns="http://schemas.nothing.com" targetNamespace="http://schemas.nothing.com">
  <wsdl:types>
    <xsd:schema targetNamespace="http://schemas.nothing.com">
      <xsd:complexType name="book">
        <xsd:all>
          <xsd:element name="base64" type="xsd:base64Binary"/>
          <xsd:element name="string" type="xsd:string"/>
          <xsd:element name="any" type="xsd:any"/>
          <xsd:element name="hexbin" type="xsd:hexBinary"/>
          <xsd:element name="nmtokens" type="xsd:NMTOKENS"/>
          <xsd:element name="integer" type="xsd:integer"/>
          <xsd:element name="short" type="xsd:short"/>
        </xsd:all>
      </xsd:complexType>
    </xsd:schema>
  </wsdl:types>
  <message name="dotestRequest">
    <part name="dotestReturn" type="tns:book"/>
  </message>
  <portType name="testPortType">
    <operation name="dotest">
      <input message="tns:dotestRequest"/>
    </operation>
  </portType>
  <binding name="testBinding" type="tns:testPortType">
    <soap:binding style="rpc" transport="http://schemas.xmlsoap.org/soap/http"/>
    <operation name="dotest">
      <soap:operation soapAction="http://localhost:81/test/interface.php?class=test/dotest" style="rpc"/>
      <input>
        <soap:body use="encoded" encodingStyle="http://schemas.xmlsoap.org/soap/encoding/" namespace="http://schemas.nothing.com"/>
      </input>
    </operation>
  </binding>
  <service name="test">
    <port name="testPort" binding="tns:testBinding">
      <soap:address location="test://" />
    </port>
  </service>
</wsdl:definitions>
"#,
    )
    .unwrap();
    let input = root.join("soap-wsdl-backed-enum-field-encoding.php");
    let output = root.join("soap-wsdl-backed-enum-field-encoding-bin");
    fs::write(
        &input,
        r#"<?php
enum StringBackedEnum: string {
    case First = 'BackingValue1';
    case Second = 'BackingValue2';
    case Third = 'BackingValue3';
    case Fourth = 'BackingValue4';
    case Fifth = 'BackingValue5';
}

enum IntBackedEnum: int {
    case First = 1;
    case Second = 2;
}

enum NonBackedEnum {
    case First;
}

class TestSoapClient extends SoapClient {
    function __doRequest($request, $location, $action, $version, $one_way = false, ?string $uriParserClass = null): ?string {
        echo $request;
    }
}

$client = new TestSoapClient(__DIR__ . '/gh15711.wsdl', ['classmap' => ['book' => 'book']]);

echo "--- Test with backed enum ---\n";
$book = new stdClass();
$book->base64 = StringBackedEnum::First;
$book->string = StringBackedEnum::Second;
$book->any = StringBackedEnum::Third;
$book->hexbin = StringBackedEnum::Fourth;
$book->nmtokens = StringBackedEnum::Fifth;
$book->integer = IntBackedEnum::First;
$book->short = IntBackedEnum::Second;
try {
    $client->dotest($book);
} catch (Throwable) {}

echo "--- Test with non-backed enum ---\n";
$book = new stdClass();
$book->base64 = NonBackedEnum::First;
$book->string = NonBackedEnum::First;
$book->any = NonBackedEnum::First;
$book->hexbin = NonBackedEnum::First;
$book->nmtokens = NonBackedEnum::First;
$book->integer = NonBackedEnum::First;
$book->short = NonBackedEnum::First;
try {
    $client->dotest($book);
} catch (ValueError $e) {
    echo "ValueError: ", $e->getMessage(), "\n";
}

echo "--- Test with mismatched enum backing type ---\n";
$book->integer = StringBackedEnum::First;
$book->short = StringBackedEnum::First;
try {
    $client->dotest($book);
} catch (ValueError $e) {
    echo "ValueError: ", $e->getMessage(), "\n";
}
"#,
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();
    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    let stdout = String::from_utf8(execution.stdout).unwrap();
    assert!(
        stdout.contains("<any xsi:type=\"xsd:any\"><name xsi:type=\"xsd:string\">Third</name><value xsi:type=\"xsd:string\">BackingValue3</value></any>"),
        "{stdout}"
    );
    assert!(
        stdout.contains("ValueError: Non-backed enums have no default serialization\n"),
        "{stdout}"
    );
    assert!(
        stdout.contains("ValueError: String-backed enum cannot be serialized as int\n"),
        "{stdout}"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_soap_append_any_value"));
    assert!(c_source.contains("ptn_soap_validate_enum_for_type"));
}

#[test]
fn compile_soap_client_invalid_headers_fatal_to_native_binary() {
    let root = temp_dir("ptn-native-soap-client-invalid-headers-fatal");
    fs::create_dir_all(&root).unwrap();
    let cases = [
        (
            "soap-set-headers-invalid.php",
            "__setSoapHeaders",
            "$client->__setSoapHeaders($headers);",
        ),
        (
            "soap-call-invalid-headers.php",
            "__soapCall",
            "$client->__soapCall('function', ['arg'], ['options'], $headers);",
        ),
    ];

    for (file_name, method_name, call_source) in cases {
        let input = root.join(file_name);
        let output = root.join(format!("{file_name}-bin"));
        fs::write(
            &input,
            format!(
                "<?php
class ExtendedSoapClient extends SoapClient {{
    public function __construct() {{}}
}}
$client = new ExtendedSoapClient();
$header = new SoapHeader('namespace', 'name');
$headers = [$header, 'giberrish'];
try {{
    {call_source}
    echo \"not reached\\n\";
}} catch (Throwable $e) {{
    echo \"caught\\n\";
}}
"
            ),
        )
        .unwrap();

        compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

        let execution = Command::new(&output).output().unwrap();
        assert!(!execution.status.success(), "{method_name}");
        assert_eq!(String::from_utf8(execution.stdout).unwrap(), "");
        let stderr = String::from_utf8(execution.stderr).unwrap();
        assert!(
            stderr.contains(&format!(
                "Fatal error: SoapClient::{method_name}(): Invalid SOAP header in {} on line ",
                input.display()
            )),
            "{stderr}"
        );
        assert!(!stderr.contains("caught"), "{stderr}");
    }
}

#[test]
fn compile_soap12_literal_array_size_schema_to_native_binary() {
    let root = temp_dir("ptn-native-soap12-literal-array-size-schema");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("soap12-literal-array-size-schema.php");
    let output = root.join("soap12-literal-array-size-schema-bin");
    fs::write(
        &input,
        r##"<?php
$seen = [];
function test($input) {
    global $seen;
    $seen[] = $input;
}

function run_schema_case($path, $schema, $param) {
    $wsdl = <<<WSDL
<definitions name="test"
    xmlns:xsd="http://www.w3.org/2001/XMLSchema"
    xmlns:SOAP-ENC="http://schemas.xmlsoap.org/soap/encoding/"
    xmlns:tns="http://test-uri/"
    xmlns:soap="http://schemas.xmlsoap.org/wsdl/soap/"
    xmlns:wsdl="http://schemas.xmlsoap.org/wsdl/"
    xmlns="http://schemas.xmlsoap.org/wsdl/"
    targetNamespace="http://test-uri/">
  <types>
    <schema xmlns="http://www.w3.org/2001/XMLSchema" targetNamespace="http://test-uri/">
      <xsd:import namespace="http://schemas.xmlsoap.org/soap/encoding/" />
      <xsd:import namespace="http://schemas.xmlsoap.org/wsdl/" />
$schema
    </schema>
  </types>
  <message name="testMessage">
    <part name="testParam" type="tns:testType"/>
  </message>
  <portType name="testPortType">
    <operation name="test">
      <input message="tns:testMessage"/>
    </operation>
  </portType>
  <binding name="testBinding" type="tns:testPortType">
    <soap:binding style="rpc" transport="http://schemas.xmlsoap.org/soap/http"/>
    <operation name="test">
      <soap:operation soapAction="#test" style="rpc"/>
      <input>
        <soap:body use="literal" namespace="http://test-uri/" encodingStyle="http://schemas.xmlsoap.org/soap/encoding/"/>
      </input>
    </operation>
  </binding>
  <service name="testService">
    <port name="testPort" binding="tns:testBinding">
      <soap:address location="test://" />
    </port>
  </service>
</definitions>
WSDL;
    file_put_contents($path, $wsdl);
    $client = new SoapClient($path, ['trace' => 1, 'exceptions' => 0]);
    $server = new SoapServer($path);
    $server->addFunction('test');
    $client->test($param);
    $request = $client->__getLastRequest();
    echo $request;
    ob_start();
    $server->handle($request);
    ob_end_clean();
}

$itemTypeSchema = <<<'XML'
      <complexType name="testType">
        <complexContent>
          <restriction base="enc12:Array" xmlns:enc12="http://www.w3.org/2003/05/soap-encoding">
            <attribute ref="enc12:itemType" wsdl:itemType="int"/>
            <attribute ref="enc12:arraySize" wsdl:arraySize="* 1"/>
          </restriction>
        </complexContent>
      </complexType>
XML;
run_schema_case(__DIR__ . '/item-type.wsdl', $itemTypeSchema, [[123], [123.5]]);

$elementSchema = <<<'XML'
      <complexType name="testType">
        <complexContent>
          <restriction base="enc12:Array" xmlns:enc12="http://www.w3.org/2003/05/soap-encoding">
            <all>
              <element name="x_item" type="int" maxOccurs="unbounded"/>
            </all>
            <attribute ref="enc12:arraySize" wsdl:arraySize="* 1"/>
          </restriction>
        </complexContent>
      </complexType>
XML;
run_schema_case(__DIR__ . '/element.wsdl', $elementSchema, [[123], [123.5]]);
var_dump($seen);
"##,
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    let stdout = String::from_utf8(execution.stdout).unwrap();
    assert!(
        stdout.contains("<testParam><xsd:int>123</xsd:int><xsd:int>123</xsd:int></testParam>"),
        "{stdout}"
    );
    assert!(
        stdout.contains("<testParam><x_item>123</x_item><x_item>123</x_item></testParam>"),
        "{stdout}"
    );
    assert!(
        stdout.contains("array(1) {\n      [0]=>\n      int(123)\n    }"),
        "{stdout}"
    );
    assert!(
        stdout.contains("array(1) {\n      [0]=>\n      int(123)\n    }\n  }\n  [1]=>\n  array(2)"),
        "{stdout}"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_soap_array_rank_from_wsdl_array_size"));
    assert!(c_source.contains("array_use_xsd_item_name"));
}

#[test]
fn compile_php_core_version_platform_constants_to_native_binary() {
    let root = temp_dir("ptn-native-core-version-platform-constants");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("core-version-platform-constants.php");
    let output = root.join("core-version-platform-constants-bin");
    fs::write(
        &input,
        "<?php\n\
var_dump(PHP_MAJOR_VERSION, PHP_MINOR_VERSION, PHP_RELEASE_VERSION, PHP_EXTRA_VERSION, PHP_VERSION_ID);\n\
var_dump(PHP_ZTS, PHP_DEBUG, PHP_OS_FAMILY);\n\
var_dump(defined('PHP_VERSION_ID'), defined('PHP_OS_FAMILY'));\n\
var_dump(constant('PHP_EXTRA_VERSION'), constant('PHP_OS_FAMILY'));\n",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    let php_os_family = if cfg!(windows) {
        "Windows"
    } else if cfg!(target_os = "macos") {
        "Darwin"
    } else if cfg!(target_os = "freebsd") {
        "BSD"
    } else if cfg!(target_os = "linux") {
        "Linux"
    } else {
        "Unknown"
    };
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        format!(
            "int(8)\nint(4)\nint(0)\nstring(0) \"\"\nint(80400)\nint(0)\nint(0)\nstring({}) \"{}\"\nbool(true)\nbool(true)\nstring(0) \"\"\nstring({}) \"{}\"\n",
            php_os_family.len(),
            php_os_family,
            php_os_family.len(),
            php_os_family
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

