#[test]
fn compile_assert_internal_to_native_binary() {
    let root = temp_dir("ptn-native-assert-internal");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("assert-internal.php");
    let output = root.join("assert-internal-bin");
    fs::write(
        &input,
        "<?php
var_dump(function_exists(\"assert\"));
var_dump(assert(true));
try {
    assert(false && ($a **= 2));
} catch (AssertionError $e) {
    echo 'assert(): ', $e->getMessage(), ' failed', \"\\n\";
}
try {
    assert(0.0);
} catch (AssertionError $e) {
    echo $e->getMessage(), \"\\n\";
}
try {
    assert(false && `echo -n \"\"`);
} catch (AssertionError $e) {
    echo 'assert(): ', $e->getMessage(), ' failed', \"\\n\";
}
if (isset($a)) {
    echo \"bad\\n\";
} else {
    echo \"short\\n\";
}
try {
    assert(false, \"custom failure\");
} catch (\\Error $e) {
    echo $e->getMessage(), \"\\n\";
}
class CustomAssertionReason extends AssertionError {}
$assertionException = new CustomAssertionReason(\"assert exception\");
try {
    assert(false, $assertionException);
} catch (CustomAssertionReason $e) {
    echo get_class($e), \":\", $e->getMessage(), \"\\n\";
}
try {
    call_user_func(\"assert\", false);
} catch (AssertionError $e) {
    var_dump($e->getMessage());
}
try {
    assert(false && `echo skipped`);
} catch (AssertionError $e) {
    echo $e->getMessage(), \"\\n\";
}
try {
    assert(!is_float(0.0));
} catch (AssertionError $e) {
    echo $e->getMessage(), \"\\n\";
}
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        "bool(true)\nbool(true)\nassert(): assert(false && ($a **= 2)) failed\nassert(0.0)\nassert(): assert(false && `echo -n \"\"`) failed\nshort\ncustom failure\nCustomAssertionReason:assert exception\nstring(0) \"\"\nassert(false && `echo skipped`)\nassert(!is_float(0.0))\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_initialize_declared_exception_object"));
}

