    fs::write(
        &input,
        "<?php\n\
$foo = 42;\n\
$array1 = [&$foo];\n\
$array2 = [$foo];\n\
var_dump($array1 === $array2);\n\
$n = \"10\";\n\
$n .= \"0\";\n\
$nums = [&$n, 100];\n\
var_dump(array_sum($nums));\n\
var_dump($n);\n\
$word = \"foo\";\n\
$map = [\"bar\" => &$word];\n\
var_dump(strtr(\"foobar\", $map));\n\
$r = 1;\n\
$a = [&$r];\n\
debug_zval_dump($a);\n\
$a[] =& $r;\n\
debug_zval_dump($a);\n\
unset($a[1]);\n\
debug_zval_dump($a);\n\
unset($r);\n\
debug_zval_dump($a);",
    )
