#[test]
fn compile_by_reference_return_call_result_chains_to_native_binary() {
    let root = temp_dir("ptn-native-by-reference-return-call-result-chains");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("by-reference-return-call-result-chains.php");
    let output = root.join("by-reference-return-call-result-chains-bin");
    fs::write(
        &input,
        "<?php\n\
function &id(&$value) {\n\
    return $value;\n\
}\n\
function &chain(&$value) {\n\
    return id($value);\n\
}\n\
function make_value() {\n\
    return 9;\n\
}\n\
function &value_chain() {\n\
    return make_value();\n\
}\n\
function &typed_value_chain(): string {\n\
    return make_value();\n\
}\n\
$value = 1;\n\
$alias =& chain($value);\n\
$alias = 2;\n\
echo $value, \"|\", $alias, \"\\n\";\n\
$copy = chain($value);\n\
$copy = 3;\n\
echo $value, \"|\", $copy, \"\\n\";\n\
$fallback =& value_chain();\n\
echo $fallback, \"\\n\";\n\
$typed =& typed_value_chain();\n\
echo gettype($typed), \":\", $typed, \"\\n\";\n",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        format!(
            "2|2\n\
2|3\n\
\n\
Notice: Only variable references should be returned by reference in {} on line 12\n\
9\n\
\n\
Notice: Only variable references should be returned by reference in {} on line 15\n\
string:9\n",
            input.display(),
            input.display()
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_return_reference_source_or_value(&runtime, "));
}

