#[test]
fn compile_array_predicate_find_helpers_to_native_binary() {
    let root = temp_dir("ptn-native-array-predicate-find");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("array-predicate-find.php");
    let output = root.join("array-predicate-find-bin");
    fs::write(
        &input,
        "<?php\n\
function even($value) { return $value % 2 === 0; }\n\
class BiggerThanThree { public static function test($value) { return $value > 3; } }\n\
$items = array(\"a\" => 1, \"b\" => 2, \"c\" => 3, \"d\" => 4);\n\
var_dump(array_all($items, fn($value) => $value > 0));\n\
var_dump(array_all($items, fn($value, $key) => $key !== \"c\"));\n\
var_dump(array_any($items, fn($value) => $value > 3));\n\
var_dump(array_any($items, fn($value, $key) => $key === \"c\"));\n\
var_dump(array_find($items, \"even\"));\n\
var_dump(array_find_key($items, \"even\"));\n\
var_dump(array_find($items, array(\"BiggerThanThree\", \"test\")));\n\
var_dump(array_find_key($items, \"BiggerThanThree::test\"));\n\
var_dump(array_find(array(), fn() => true));\n\
var_dump(array_any(array(), fn() => true));\n\
var_dump(array_all(array(), fn() => false));\n\
try {\n\
    var_dump(array_any($items, function($value) {\n\
        if ($value === 2) { throw new Exception(\"stop\"); }\n\
        return false;\n\
    }));\n\
} catch (Exception $e) {\n\
    echo $e->getMessage(), \"\\n\";\n\
}\n\
var_dump(function_exists(\"array_all\"), function_exists(\"ARRAY_ANY\"), function_exists(\"array_find\"), function_exists(\"ARRAY_FIND_KEY\"));",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        "bool(true)\nbool(false)\nbool(true)\nbool(true)\nint(2)\nstring(1) \"b\"\nint(4)\nstring(1) \"d\"\nNULL\nbool(false)\nbool(true)\nstop\nbool(true)\nbool(true)\nbool(true)\nbool(true)\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_internal_array_all"));
    assert!(c_source.contains("ptn_internal_array_any"));
    assert!(c_source.contains("ptn_internal_array_find"));
    assert!(c_source.contains("ptn_internal_array_find_key"));
    assert!(c_source.contains("ptn_array_callback_predicate_matches"));
}

#[test]
fn compile_array_filter_to_native_binary() {
    let root = temp_dir("ptn-native-array-filter");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("array-filter.php");
    let output = root.join("array-filter-bin");
    fs::write(
        &input,
        "<?php\n\
function even($input) { return ($input % 2 == 0); }\n\
function key_is_keep($key) { return str_contains($key, \"keep\"); }\n\
function both_large($value, $key) { return $value > 1 && $key != \"skip\"; }\n\
$input = array(1, 2, 3, 0, -1);\n\
var_dump(array_filter($input, \"even\"));\n\
var_dump(array_filter($input));\n\
var_dump(array_filter($input, null));\n\
$assoc = array(\"keep1\" => 1, \"drop\" => 2, \"keep0\" => 0, \"skip\" => 3);\n\
var_dump(array_filter($assoc, \"key_is_keep\", ARRAY_FILTER_USE_KEY));\n\
var_dump(array_filter($assoc, \"both_large\", ARRAY_FILTER_USE_BOTH));\n\
$value = array(\"seed\");\n\
$source = array(\"x\" => $value, \"empty\" => array());\n\
$filtered = array_filter($source);\n\
$filtered[\"x\"][] = \"copy\";\n\
var_dump($filtered, $source[\"x\"]);\n\
try { array_filter($input, null, 999); } catch (ValueError $e) { echo $e->getMessage(), \"\\n\"; }\n\
try { array_filter($input, mode: 999); } catch (ValueError $e) { echo $e->getMessage(), \"\\n\"; }\n\
var_dump(ARRAY_FILTER_USE_BOTH, ARRAY_FILTER_USE_KEY, function_exists('array_filter'), function_exists('ARRAY_FILTER'));",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        "array(2) {\n  [1]=>\n  int(2)\n  [3]=>\n  int(0)\n}\narray(4) {\n  [0]=>\n  int(1)\n  [1]=>\n  int(2)\n  [2]=>\n  int(3)\n  [4]=>\n  int(-1)\n}\narray(4) {\n  [0]=>\n  int(1)\n  [1]=>\n  int(2)\n  [2]=>\n  int(3)\n  [4]=>\n  int(-1)\n}\narray(2) {\n  [\"keep1\"]=>\n  int(1)\n  [\"keep0\"]=>\n  int(0)\n}\narray(1) {\n  [\"drop\"]=>\n  int(2)\n}\narray(1) {\n  [\"x\"]=>\n  array(2) {\n    [0]=>\n    string(4) \"seed\"\n    [1]=>\n    string(4) \"copy\"\n  }\n}\narray(1) {\n  [0]=>\n  string(4) \"seed\"\n}\narray_filter(): Argument #3 ($mode) must be one of ARRAY_FILTER_USE_VALUE, ARRAY_FILTER_USE_KEY, or ARRAY_FILTER_USE_BOTH\narray_filter(): Argument #3 ($mode) must be one of ARRAY_FILTER_USE_VALUE, ARRAY_FILTER_USE_KEY, or ARRAY_FILTER_USE_BOTH\nint(1)\nint(2)\nbool(true)\nbool(true)\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_internal_array_filter"));
    assert!(c_source.contains("ptn_internal_call_callback(runtime, callback, callback_argc"));
}

#[test]
fn compile_extract_refs_and_globals_to_native_binary() {
    let root = temp_dir("ptn-native-extract-refs-globals");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("extract-refs-globals.php");
    let output = root.join("extract-refs-globals-bin");
    fs::write(
        &input,
        "<?php\n\
$source = [\"a\" => 1, \"b\" => 2, 1 => \"skip\", \"bad-name\" => 3, \"GLOBALS\" => [\"no\"]];\n\
var_dump(extract($source));\n\
var_dump($a, $b);\n\
$refs = [\"r\" => 10];\n\
$other = $refs;\n\
var_dump(extract($refs, EXTR_REFS));\n\
$r = 20;\n\
var_dump($refs[\"r\"], $other[\"r\"], $r);\n\
$str = \"John\";\n\
var_dump(extract([\"GLOBALS\" => [\"str\" => \"bad\"]]));\n\
var_dump($GLOBALS[\"str\"]);\n\
function check_globals($ref) {\n\
    unset($GLOBALS[\"ga\"]);\n\
    $GLOBALS[\"ga\"] = 1;\n\
    if ($ref) {\n\
        global $ga;\n\
    } else {\n\
        $ga = NULL;\n\
    }\n\
    var_dump(is_int(extract($GLOBALS, EXTR_REFS)));\n\
    var_dump($ga, $GLOBALS[\"ga\"]);\n\
    $ga = 4;\n\
    var_dump($ga, $GLOBALS[\"ga\"]);\n\
}\n\
check_globals(false);\n\
check_globals(true);\n\
var_dump(EXTR_REFS, EXTR_OVERWRITE, function_exists(\"extract\"), function_exists(\"EXTRACT\"));",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        "int(3)\nint(1)\nint(2)\nint(1)\nint(20)\nint(10)\nint(20)\nint(1)\nstring(4) \"John\"\nbool(true)\nint(1)\nint(1)\nint(4)\nint(1)\nbool(true)\nint(1)\nint(1)\nint(4)\nint(4)\nint(256)\nint(0)\nbool(true)\nbool(true)\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_internal_extract"));
    assert!(c_source.contains("ptn_internal_extract_globals"));
}

#[test]
fn compile_extract_flags_and_prefix_modes_to_native_binary() {
    let root = temp_dir("ptn-native-extract-flags-prefix-modes");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("extract-flags-prefix-modes.php");
    let output = root.join("extract-flags-prefix-modes-bin");
    fs::write(
        &input,
        "<?php\n\
$numeric = [1, 2, 3];\n\
var_dump(extract($numeric, EXTR_SKIP));\n\
var_dump(extract($numeric, EXTR_PREFIX_INVALID, \"ssd\"));\n\
var_dump($ssd_0, $ssd_1, $ssd_2);\n\
var_dump(extract([\"x\" => 10, 1 => 20], EXTR_PREFIX_ALL, \"\"));\n\
var_dump($_x, $_1);\n\
$existing = \"keep\";\n\
var_dump(extract([\"existing\" => \"new\"], EXTR_PREFIX_SAME, \"p\"));\n\
var_dump($existing, $p_existing);\n\
var_dump(extract([\"\" => \"blank\", \"ok\" => \"yes\"], EXTR_PREFIX_ALL, \"same\"));\n\
var_dump(isset($same_), $same_ok);\n\
var_dump(extract([\"\" => \"blank\"], EXTR_PREFIX_INVALID, \"same\"));\n\
var_dump($same_);\n\
foreach ([[7, \"ok\"], [EXTR_PREFIX_ALL, \"1bad\"]] as [$flags, $prefix]) {\n\
    try { extract([\"x\" => 1], $flags, $prefix); } catch (Throwable $e) { echo get_class($e), \": \", $e->getMessage(), \"\\n\"; }\n\
}",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "int(0)\n",
            "int(3)\n",
            "int(1)\n",
            "int(2)\n",
            "int(3)\n",
            "int(2)\n",
            "int(10)\n",
            "int(20)\n",
            "int(1)\n",
            "string(4) \"keep\"\n",
            "string(3) \"new\"\n",
            "int(1)\n",
            "bool(false)\n",
            "string(3) \"yes\"\n",
            "int(1)\n",
            "string(5) \"blank\"\n",
            "ValueError: extract(): Argument #2 ($flags) must be a valid extract type\n",
            "ValueError: extract(): Argument #3 ($prefix) must be a valid identifier\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_extract_rejects_this_before_later_variables_to_native_binary() {
    let root = temp_dir("ptn-native-extract-this-reassignment");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("extract-this-reassignment.php");
    let output = root.join("extract-this-reassignment-bin");
    fs::write(
        &input,
        "<?php
function foo() {
    try {
        extract([\"this\" => 42, \"a\" => 24]);
    } catch (Error $e) {
        echo $e->getMessage(), \"\\n\";
    }
    var_dump($a);
}
foo();
",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        format!(
            "Cannot re-assign $this\n\nWarning: Undefined variable $a in {} on line 8\nNULL\n",
            input.display()
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

