#[test]
fn compile_extract_this_modes_to_native_binary() {
    let root = temp_dir("ptn-native-extract-this-modes");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("extract-this-modes.php");
    let output = root.join("extract-this-modes-bin");
    fs::write(
        &input,
        "<?php
class ExtractThisModes {
    public function run(): void {
        foreach ([
            'OVERWRITE' => EXTR_OVERWRITE,
            'SKIP' => EXTR_SKIP,
            'PREFIX_SAME' => EXTR_PREFIX_SAME,
            'PREFIX_ALL' => EXTR_PREFIX_ALL,
            'PREFIX_INVALID' => EXTR_PREFIX_INVALID,
            'IF_EXISTS' => EXTR_IF_EXISTS,
            'PREFIX_IF_EXISTS' => EXTR_PREFIX_IF_EXISTS,
        ] as $name => $flags) {
            unset($x_this);
            try {
                $result = extract(['this' => 'value'], $flags, 'x');
                echo $name, ':', $result, ':', (isset($x_this) ? $x_this : 'NULL'), \"\\n\";
            } catch (Throwable $e) {
                echo $name, ':E:', $e->getMessage(), \"\\n\";
            }
        }
    }
}
(new ExtractThisModes)->run();
",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "OVERWRITE:E:Cannot re-assign $this\n",
            "SKIP:0:NULL\n",
            "PREFIX_SAME:1:value\n",
            "PREFIX_ALL:1:value\n",
            "PREFIX_INVALID:1:value\n",
            "IF_EXISTS:0:NULL\n",
            "PREFIX_IF_EXISTS:0:NULL\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_forbidden_dynamic_scope_function_calls_to_native_binary() {
    let root = temp_dir("ptn-native-forbidden-dynamic-scope-calls");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("forbidden-dynamic-scope-calls.php");
    let output = root.join("forbidden-dynamic-scope-calls-bin");
    fs::write(
        &input,
        "<?php
function report($label, $callable, $args = []) {
    try {
        call_user_func_array($callable, $args);
        echo $label, \": ok\\n\";
    } catch (Error $e) {
        echo $label, \": \", $e->getMessage(), \"\\n\";
    }
}

foreach ([\"extract\", \"compact\", \"get_defined_vars\", \"func_get_args\", \"func_get_arg\", \"func_num_args\"] as $name) {
    report(\"direct \" . $name, $name, $name === \"func_get_arg\" ? [0] : [[]]);
}

report(\"array_map\", fn() => array_map(\"extract\", [[\"i\" => new stdClass]]));
report(\"call_user_func\", fn() => call_user_func(\"extract\", [\"i\" => new stdClass]));
report(\"call_user_func_eval\", fn() => call_user_func(\"eval\", \"echo 1;\"));
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "direct extract: Cannot call extract() dynamically\n",
            "direct compact: Cannot call compact() dynamically\n",
            "direct get_defined_vars: Cannot call get_defined_vars() dynamically\n",
            "direct func_get_args: Cannot call func_get_args() dynamically\n",
            "direct func_get_arg: Cannot call func_get_arg() dynamically\n",
            "direct func_num_args: Cannot call func_num_args() dynamically\n",
            "array_map: Cannot call extract() dynamically\n",
            "call_user_func: Cannot call extract() dynamically\n",
            "call_user_func_eval: call_user_func(): Argument #1 ($callback) must be a valid callback, function \"eval\" not found or invalid function name\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_dynamic_call_throw_if_forbidden"));
    assert!(c_source.contains("ptn_dynamic_call_forbidden_name"));
}

#[test]
fn compile_extract_into_typed_property_references_to_native_binary() {
    let root = temp_dir("ptn-native-extract-typed-property-refs");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("extract-typed-property-refs.php");
    let output = root.join("extract-typed-property-refs-bin");
    fs::write(
        &input,
        "<?php
class Test {
    public int $i = 0;
    public string $s = \"\";
}

$test = new Test;
$i =& $test->i;
$s =& $test->s;

try {
    extract(['i' => 'foo', 's' => 42]);
} catch (TypeError $e) {
    echo $e->getMessage(), \"\\n\";
}

var_dump($test->i, $test->s);
$i = '12';
$s = 42;
var_dump($test->i, $test->s);
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "Cannot assign string to reference held by property Test::$i of type int\n",
            "int(0)\n",
            "string(0) \"\"\n",
            "int(12)\n",
            "string(2) \"42\"\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("PTN_PROPERTY_TYPE_INT"));
    assert!(c_source.contains("PTN_PROPERTY_TYPE_STRING"));
    assert!(c_source.contains("reference held by property"));
}

