#[test]
fn compile_typed_property_reference_foreach_sources_to_native_binary() {
    let root = temp_dir("ptn-native-typed-property-reference-foreach-sources");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("typed-property-reference-foreach-sources.php");
    let output = root.join("typed-property-reference-foreach-sources-bin");
    fs::write(
        &input,
        "<?php
class RefBox {
    public int $i = 1;
    public string $s = \"ok\";
}

$box = new RefBox();
foreach ($box as $k => &$v) {
    try {
        $v = [];
    } catch (Throwable $e) {
        echo $k, \": \", $e->getMessage(), \"\\n\";
    }
}

class NeedsInit {
    public int $i;
    public ?string $s;
}

$needs = new NeedsInit();
try {
    $ref =& $needs->i;
} catch (Throwable $e) {
    echo $e->getMessage(), \"\\n\";
}
$nullable =& $needs->s;
var_dump($nullable);

class IteratorBox implements IteratorAggregate {
    public string $foo = \"bar\";

    public function getIterator(): Traversable {
        return new ArrayIterator($this);
    }
}

$iter = new IteratorBox();
foreach ($iter as $k => &$v) {
    try {
        $v = [];
    } catch (Throwable $e) {
        echo $k, \": \", $e->getMessage(), \"\\n\";
    }
}
var_dump($iter);

class ReadonlyIteratorBox implements IteratorAggregate {
    public readonly string $foo;

    public function __construct() {
        $this->foo = \"bar\";
    }

    public function getIterator(): Traversable {
        return new ArrayIterator($this);
    }
}

$readonly = new ReadonlyIteratorBox();
try {
    foreach ($readonly as $k => &$v) {}
} catch (Throwable $e) {
    echo $e->getMessage(), \"\\n\";
}
var_dump($readonly);
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    let stdout = String::from_utf8(execution.stdout).unwrap();
    assert!(stdout
        .contains("i: Cannot assign array to reference held by property RefBox::$i of type int"));
    assert!(stdout.contains(
        "s: Cannot assign array to reference held by property RefBox::$s of type string"
    ));
    assert!(stdout
        .contains("Cannot access uninitialized non-nullable property NeedsInit::$i by reference"));
    assert!(stdout.contains("NULL\n"));
    assert!(stdout.contains(
        "foo: Cannot assign array to reference held by property IteratorBox::$foo of type string"
    ));
    assert!(
        stdout.contains("Cannot acquire reference to readonly property ReadonlyIteratorBox::$foo")
    );
    assert!(stdout.contains("&string(3) \"bar\""));
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_object_reference_for_property"));
    assert!(c_source.contains("ptn_internal_array_iterator_current_reference"));
}

#[test]
fn compile_typed_property_reference_overflow_and_union_sources_to_native_binary() {
    let root = temp_dir("ptn-native-typed-property-reference-overflow-union");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("typed-property-reference-overflow-union.php");
    let output = root.join("typed-property-reference-overflow-union-bin");
    fs::write(
        &input,
        "<?php
class Box {
    public int $i;
    public int|string $x;
    public float|string $y;
}

$box = new Box();
$box->i = PHP_INT_MAX;
$ref =& $box->i;
try {
    $ref++;
} catch (TypeError $e) {
    echo $e->getMessage(), \"\\n\";
}
var_dump($box->i);
try {
    ++$box->i;
} catch (TypeError $e) {
    echo $e->getMessage(), \"\\n\";
}
var_dump($box->i);

$shared = \"foobar\";
$box->x =& $shared;
$box->y =& $shared;
try {
    $shared = 42;
} catch (TypeError $e) {
    echo $e->getMessage(), \"\\n\";
}
var_dump($shared);
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "Cannot increment a reference held by property Box::$i of type int past its maximal value\n",
            "int(9223372036854775807)\n",
            "Cannot increment a reference held by property Box::$i of type int past its maximal value\n",
            "int(9223372036854775807)\n",
            "Cannot assign int to reference held by property Box::$x of type string|int and property Box::$y of type string|float, as this would result in an inconsistent type conversion\n",
            "string(6) \"foobar\"\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_runtime_read_variable_for_increment"));
    assert!(c_source.contains("ptn_property_increment_value"));
    assert!(c_source.contains("string|int"));
}

#[test]
fn compile_array_callback_validation_to_native_binary() {
    let root = temp_dir("ptn-native-array-callback-validation");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("array-callback-validation.php");
    let output = root.join("array-callback-validation-bin");
    fs::write(
        &input,
        "<?php
function report($callback) {
    try {
        $callback();
    } catch (TypeError $e) {
        echo $e->getMessage(), \"\\n\";
    }
}
class CallbackTarget {
    public static function ok($value) { return $value; }
}
class PrivateCallbackTarget {
    private static function hide($value) { return $value; }
}
class ProtectedCallbackTarget {
    protected static function hide($value) { return $value; }
}

report(fn() => array_map(\"missing_map\", [1]));
report(fn() => array_map(\"eval\", [\"echo 1;\"]));
report(fn() => array_map(\"exit\", [1]));
report(fn() => array_map(\"die\", [1]));
report(fn() => array_map([\"MissingCallbackTarget\", \"ok\"], [1]));
report(fn() => array_map([\"CallbackTarget\", \"missing\"], [1]));
report(fn() => array_map([\"PrivateCallbackTarget\", \"hide\"], [1]));
report(fn() => array_map([\"ProtectedCallbackTarget\", \"hide\"], [1]));
report(fn() => array_map(123, [1]));
report(fn() => array_map([1, 2], [1]));
report(fn() => array_map(new CallbackTarget(), [1]));
report(fn() => array_filter([1], \"missing_filter\"));
report(fn() => array_reduce([1], \"missing_reduce\"));
report(fn() => array_diff_ukey([1], [2], \"missing_key\"));
report(fn() => array_udiff_uassoc([1], [2], \"missing_value\", \"strcmp\"));
report(fn() => array_uintersect_uassoc([1], [2], \"strcmp\", \"missing_key2\"));
report(fn() => array_map(123, [1]));
report(fn() => array_map([1, \"method\"], [1]));
report(fn() => array_map([\"CallbackTarget\", []], [1]));
echo \"done\\n\";
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "array_map(): Argument #1 ($callback) must be a valid callback or null, function \"missing_map\" not found or invalid function name\n",
            "array_map(): Argument #1 ($callback) must be a valid callback or null, function \"eval\" not found or invalid function name\n",
            "array_map(): Argument #1 ($callback) must be a valid callback or null, function \"exit\" not found or invalid function name\n",
            "array_map(): Argument #1 ($callback) must be a valid callback or null, function \"die\" not found or invalid function name\n",
            "array_map(): Argument #1 ($callback) must be a valid callback or null, class \"MissingCallbackTarget\" not found\n",
            "array_map(): Argument #1 ($callback) must be a valid callback or null, class CallbackTarget does not have a method \"missing\"\n",
            "array_map(): Argument #1 ($callback) must be a valid callback or null, cannot access private method PrivateCallbackTarget::hide()\n",
            "array_map(): Argument #1 ($callback) must be a valid callback or null, cannot access protected method ProtectedCallbackTarget::hide()\n",
            "array_map(): Argument #1 ($callback) must be a valid callback or null, no array or string given\n",
            "array_map(): Argument #1 ($callback) must be a valid callback or null, first array member is not a valid class name or object\n",
            "array_map(): Argument #1 ($callback) must be a valid callback or null, no array or string given\n",
            "array_filter(): Argument #2 ($callback) must be a valid callback or null, function \"missing_filter\" not found or invalid function name\n",
            "array_reduce(): Argument #2 ($callback) must be a valid callback, function \"missing_reduce\" not found or invalid function name\n",
            "array_diff_ukey(): Argument #3 must be a valid callback, function \"missing_key\" not found or invalid function name\n",
            "array_udiff_uassoc(): Argument #3 must be a valid callback, function \"missing_value\" not found or invalid function name\n",
            "array_uintersect_uassoc(): Argument #4 must be a valid callback, function \"missing_key2\" not found or invalid function name\n",
            "array_map(): Argument #1 ($callback) must be a valid callback or null, no array or string given\n",
            "array_map(): Argument #1 ($callback) must be a valid callback or null, first array member is not a valid class name or object\n",
            "array_map(): Argument #1 ($callback) must be a valid callback or null, second array member is not a valid method\n",
            "done\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_internal_expect_nullable_callback_arg"));
    assert!(c_source.contains("ptn_internal_expect_callback_arg"));
}

