#[test]
fn compile_array_merge_to_native_binary() {
    let root = temp_dir("ptn-native-array-merge");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("array-merge.php");
    let output = root.join("array-merge-bin");
    fs::write(
        &input,
        "<?php\n\
var_dump(array_merge());\n\
$left = [10 => \"ten\", \"keep\" => \"left\", 11 => \"eleven\"];\n\
$right = [\"keep\" => \"right\", 0 => \"zero\", \"new\" => \"new\"];\n\
$merged = array_merge($left, $right);\n\
$merged[\"keep\"] = \"changed\";\n\
var_dump($merged, $left, $right, function_exists(\"array_merge\"), function_exists(\"ARRAY_MERGE\"));\n\
try { array_merge(0, []); } catch (TypeError $e) { echo $e->getMessage(), \"\\n\"; }\n\
try { array_merge([], 0); } catch (TypeError $e) { echo $e->getMessage(), \"\\n\"; }",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "array(0) {\n",
            "}\n",
            "array(5) {\n",
            "  [0]=>\n",
            "  string(3) \"ten\"\n",
            "  [\"keep\"]=>\n",
            "  string(7) \"changed\"\n",
            "  [1]=>\n",
            "  string(6) \"eleven\"\n",
            "  [2]=>\n",
            "  string(4) \"zero\"\n",
            "  [\"new\"]=>\n",
            "  string(3) \"new\"\n",
            "}\n",
            "array(3) {\n",
            "  [10]=>\n",
            "  string(3) \"ten\"\n",
            "  [\"keep\"]=>\n",
            "  string(4) \"left\"\n",
            "  [11]=>\n",
            "  string(6) \"eleven\"\n",
            "}\n",
            "array(3) {\n",
            "  [\"keep\"]=>\n",
            "  string(5) \"right\"\n",
            "  [0]=>\n",
            "  string(4) \"zero\"\n",
            "  [\"new\"]=>\n",
            "  string(3) \"new\"\n",
            "}\n",
            "bool(true)\n",
            "bool(true)\n",
            "array_merge(): Argument #1 must be of type array, int given\n",
            "array_merge(): Argument #2 must be of type array, int given\n"
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_internal_array_merge"));
    assert!(c_source.contains("ptn_array_merge_into"));
}

