#[test]
fn compile_large_ordered_array_lookup_to_native_binary() {
    let root = temp_dir("ptn-native-large-array-lookup");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("large-array-lookup.php");
    let output = root.join("large-array-lookup-bin");
    let mut source = String::from("<?php\n$items = [\n");
    for index in 0..64 {
        source.push_str(&format!("\"k{index}\" => {index},\n"));
    }
    source.push_str("\"k10\" => 1000,\n");
    source.push_str("\"20\" => 2000,\n");
    source.push_str("65,\n");
    source.push_str("];\n");
    source.push_str("var_dump($items[\"k10\"]);\n");
    source.push_str("var_dump($items[20]);\n");
    source.push_str("var_dump($items[\"20\"]);\n");
    source.push_str("var_dump(count($items));\n");
    source.push_str("var_dump(array_key_exists(\"20\", $items));\n");
    source.push_str("var_dump(array_key_exists(\"missing\", $items));\n");
    source.push_str("var_dump(isset($items[\"k0\"]));\n");
    source.push_str("var_dump(empty($items[\"missing\"]));\n");
    source.push_str(
        "foreach ($items as $key => $value) { if ($key === \"k10\" || $key === 20 || $key === 21) echo $key, \"=\", $value, \"\\n\"; }\n",
    );
    fs::write(&input, source).unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        "int(1000)\nint(2000)\nint(2000)\nint(66)\nbool(true)\nbool(false)\nbool(true)\nbool(true)\nk10=1000\n20=2000\n21=65\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_string_offset_reads_to_native_binary() {
    let root = temp_dir("ptn-native-string-offset-reads");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("string-offset-reads.php");
    let output = root.join("string-offset-reads-bin");
    fs::write(
        &input,
        "<?php\n\
$str = \"abcd\";\n\
var_dump($str[0]);\n\
var_dump($str[\"2\"]);\n\
var_dump($str[-1]);\n\
var_dump($str[4]);\n\
var_dump($str[-5]);\n\
var_dump($str[1][0]);\n\
var_dump($str[2][-2]);\n\
var_dump($str[true]);\n\
var_dump($str[false]);\n\
var_dump($str[null]);\n\
var_dump($str[1.8]);\n\
var_dump($str[111111111111111111111]);\n\
var_dump($str[-11111111111111111111111]);",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    let stdout = String::from_utf8(execution.stdout).unwrap();
    let normalized_stdout = stdout.replace(input.to_str().unwrap(), "ptn");
    assert_eq!(
        normalized_stdout,
        "string(1) \"a\"\nstring(1) \"c\"\nstring(1) \"d\"\n\nWarning: Uninitialized string offset 4 in ptn on line 6\nstring(0) \"\"\n\nWarning: Uninitialized string offset -5 in ptn on line 7\nstring(0) \"\"\nstring(1) \"b\"\n\nWarning: Uninitialized string offset -2 in ptn on line 9\nstring(0) \"\"\n\nWarning: String offset cast occurred in ptn on line 10\nstring(1) \"b\"\n\nWarning: String offset cast occurred in ptn on line 11\nstring(1) \"a\"\n\nWarning: String offset cast occurred in ptn on line 12\nstring(1) \"a\"\n\nWarning: String offset cast occurred in ptn on line 13\nstring(1) \"b\"\n\nWarning: String offset cast occurred in ptn on line 14\n\nWarning: Uninitialized string offset 430646668853805056 in ptn on line 14\nstring(0) \"\"\n\nWarning: String offset cast occurred in ptn on line 15\n\nWarning: Uninitialized string offset -6171178737961271296 in ptn on line 15\nstring(0) \"\"\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

