#[test]
fn phpc_filter_validation_and_input_semantics() {
    let root = temp_dir("ptn-phpc-filter-validation-input");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("filter-validation-input.php");
    fs::write(
        &input,
        "<?php\n\
var_dump(filter_input(INPUT_ENV, 'PTN_FILTER_ENV_TEST'));\n\
var_dump(filter_input(INPUT_GET, 'missing', FILTER_VALIDATE_INT, ['options' => ['default' => 23]]));\n\
var_dump(filter_var('10.0.0.1', FILTER_VALIDATE_IP, FILTER_FLAG_IPV4 | FILTER_FLAG_NO_PRIV_RANGE));\n\
var_dump(filter_var('127.255.255.255', FILTER_VALIDATE_IP, FILTER_FLAG_IPV4 | FILTER_FLAG_NO_RES_RANGE));\n\
var_dump(filter_var('100.64.0.0', FILTER_VALIDATE_IP, FILTER_FLAG_IPV4 | FILTER_FLAG_NO_RES_RANGE));\n\
var_dump(filter_var('::ffff:192.168.1.1', FILTER_VALIDATE_IP, FILTER_FLAG_NO_PRIV_RANGE));\n\
var_dump(filter_var('0:0:0:0:0:0:0:1', FILTER_VALIDATE_IP, FILTER_FLAG_NO_RES_RANGE));\n\
var_dump(filter_var('foo@bar.com', FILTER_VALIDATE_DOMAIN));\n\
var_dump(filter_var('01-23-45-67-89-ab', FILTER_VALIDATE_MAC, ['options' => ['separator' => '.']]));\n\
var_dump(filter_var('0123.4567.89ab', FILTER_VALIDATE_MAC));\n\
try {\n\
    filter_var('01-23-45-67-89-ab', FILTER_VALIDATE_MAC, ['options' => ['separator' => '--']]);\n\
} catch (ValueError $e) {\n\
    echo $e->getMessage(), \"\\n\";\n\
}\n\
var_dump(filter_var(\"!@#$%^&*()><<>+_\\\"'<br><p /><li />\", 513));\n\
var_dump(filter_var('\"verî.uñusual.@.uñusual.com\"@example.com', FILTER_VALIDATE_EMAIL, FILTER_FLAG_EMAIL_UNICODE));\n\
var_dump(filter_input_array(INPUT_GET, ['c' => ['flags' => FILTER_NULL_ON_FAILURE]], true));\n\
try {\n\
    filter_var_array(['a' => true], ['a' => ['filter' => FILTER_VALIDATE_EMAIL, 'flags' => FILTER_THROW_ON_FAILURE]]);\n\
} catch (Filter\\FilterFailedException $e) {\n\
    echo get_class($e), ': ', $e->getMessage(), \"\\n\";\n\
}\n",
    )
    .unwrap();

    let execution = Command::new(env!("CARGO_BIN_EXE_phpc"))
        .arg("-d")
        .arg("variables_order=EGPCS")
        .arg("run")
        .arg(&input)
        .env("PTN_FILTER_ENV_TEST", "env-value")
        .env("QUERY_STRING", "")
        .env("PATH", "/")
        .output()
        .unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        "string(9) \"env-value\"\n\
int(23)\n\
bool(false)\n\
bool(false)\n\
string(10) \"100.64.0.0\"\n\
string(18) \"::ffff:192.168.1.1\"\n\
bool(false)\n\
string(11) \"foo@bar.com\"\n\
bool(false)\n\
string(14) \"0123.4567.89ab\"\n\
filter_var(): \"separator\" option must be one character long\n\
string(11) \"!@#$%^&*()>\"\n\
string(43) \"\"verî.uñusual.@.uñusual.com\"@example.com\"\n\
NULL\n\
Filter\\FilterFailedException: filter validation failed: filter validate_email not satisfied by '1'\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn phpc_filter_regexp_callback_and_array_option_edges() {
    let root = temp_dir("ptn-phpc-filter-regexp-callback-array-options");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("filter-regexp-callback-array-options.php");
    fs::write(
        &input,
        "<?php\n\
function test($var) { return strtoupper($var); }\n\
class test_class { static function test($var) { return strtolower($var); } }\n\
\n\
var_dump(filter_input(INPUT_GET, 'missing', FILTER_DEFAULT, FILTER_NULL_ON_FAILURE));\n\
var_dump(filter_var('data', FILTER_VALIDATE_REGEXP, ['options' => ['regexp' => '/.*/']]));\n\
var_dump(filter_var('data', FILTER_VALIDATE_REGEXP, ['options' => ['regexp' => '/^b(.*)/']]));\n\
var_dump(filter_var('data', FILTER_VALIDATE_REGEXP, ['options' => ['regexp' => '/^d(.*)/']]));\n\
try { filter_var('data', FILTER_VALIDATE_REGEXP); } catch (ValueError $e) { echo $e->getMessage(), \"\\n\"; }\n\
var_dump(filter_var('data', FILTER_CALLBACK, ['options' => 'test']));\n\
var_dump(filter_var('dAtA', FILTER_CALLBACK, ['options' => ['test_class', 'test']]));\n\
try { filter_var('qwe', FILTER_CALLBACK, ['options' => 'no such func']); } catch (TypeError $e) { echo $e->getMessage(), \"\\n\"; }\n\
try { filter_var('qwe', FILTER_CALLBACK); } catch (TypeError $e) { echo $e->getMessage(), \"\\n\"; }\n\
try { filter_var_array([], ''); } catch (TypeError $e) { echo $e->getMessage(), \"\\n\"; }\n\
try { filter_var_array([], new stdClass); } catch (TypeError $e) { echo $e->getMessage(), \"\\n\"; }\n",
    )
    .unwrap();

    let execution = Command::new(env!("CARGO_BIN_EXE_phpc"))
        .arg("-d")
        .arg("variables_order=EGPCS")
        .arg("run")
        .arg(&input)
        .env("QUERY_STRING", "")
        .env("PATH", "/")
        .output()
        .unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        "bool(false)\n\
string(4) \"data\"\n\
bool(false)\n\
string(4) \"data\"\n\
filter_var(): \"regexp\" option is missing\n\
string(4) \"DATA\"\n\
string(4) \"data\"\n\
filter_var(): Option must be a valid callback\n\
filter_var(): Option must be a valid callback\n\
filter_var_array(): Argument #2 ($options) must be of type array|int, string given\n\
filter_var_array(): Argument #2 ($options) must be of type array|int, stdClass given\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn phpc_cgi_php_input_fopen_streams_are_seekable_and_independent() {
    let root = temp_dir("ptn-phpc-cgi-php-input-stream");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("cgi-php-input-stream.php");
    fs::write(
        &input,
        "<?php\n\
$one = fopen('php://input', 'r');\n\
$two = fopen('php://input', 'w');\n\
$meta = stream_get_meta_data($one);\n\
var_dump($meta['wrapper_type'], $meta['stream_type'], $meta['mode'], $meta['seekable'], $meta['uri']);\n\
fseek($one, 3, SEEK_SET);\n\
echo fgetc($one);\n\
fseek($one, 1, SEEK_SET);\n\
echo fgetc($one);\n\
fseek($one, 3, SEEK_CUR);\n\
echo fgetc($one);\n\
fseek($one, -3, SEEK_CUR);\n\
echo fgetc($one);\n\
fseek($one, 3, SEEK_END);\n\
echo fgetc($one);\n\
fseek($one, -3, SEEK_END);\n\
fseek($two, 1, SEEK_SET);\n\
echo fgetc($one), fgetc($two), \"\\n\";\n\
",
    )
    .unwrap();

    let mut child = Command::new(env!("CARGO_BIN_EXE_phpc"))
        .arg("-C")
        .arg("run")
        .arg(&input)
        .env("REQUEST_METHOD", "POST")
        .env("CONTENT_TYPE", "application/unknown")
        .env("CONTENT_LENGTH", "10")
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .unwrap();
    child
        .stdin
        .as_mut()
        .unwrap()
        .write_all(b"0123456789")
        .unwrap();
    let execution = child.wait_with_output().unwrap();

    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        "string(3) \"PHP\"\n\
string(5) \"Input\"\n\
string(2) \"rb\"\n\
bool(true)\n\
string(11) \"php://input\"\n\
315371\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

