#[test]
fn phpc_string_ini_controls_default_charset_and_parse_str_separator() {
    let root = temp_dir("ptn-phpc-string-ini");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("string-ini.php");
    fs::write(
        &input,
        "<?php\n\
echo ini_get('default_charset'), \"\\n\";\n\
var_dump(htmlentities(\"\\xe4\\xf6\\xfc\", ENT_QUOTES, ''));\n\
parse_str('first=val1/second=val2/third=val3', $result);\n\
var_dump($result);\n\
var_dump(ini_get('output_handler'), ini_get('filter.default'), ini_get('internal_encoding'), ini_get('input_encoding'), ini_get('output_encoding'));\n\
var_dump(ini_set('arg_separator.input', '&'));\n\
parse_str('left=1&right=2', $next);\n\
var_dump($next);\n\
var_dump(ini_set('internal_encoding', 'ISO-8859-1'), ini_set('input_encoding', 'cp1252'), ini_set('output_encoding', 'EUC-JP'));\n\
var_dump(ini_get('internal_encoding'), ini_get('input_encoding'), ini_get('output_encoding'));\n\
ini_restore('internal_encoding');\n\
ini_restore('input_encoding');\n\
ini_restore('output_encoding');\n\
var_dump(ini_get('internal_encoding'), ini_get('input_encoding'), ini_get('output_encoding'));\n\
ini_restore('arg_separator.input');\n\
echo ini_get('arg_separator.input'), \"\\n\";",
    )
    .unwrap();

    let execution = Command::new(env!("CARGO_BIN_EXE_phpc"))
        .arg("-d")
        .arg("default_charset=ISO-8859-1")
        .arg("-d")
        .arg("arg_separator.input=/")
        .arg("-d")
        .arg("output_handler=")
        .arg("-d")
        .arg("filter.default=unsafe_raw")
        .arg("-d")
        .arg("internal_encoding=")
        .arg("-d")
        .arg("input_encoding=")
        .arg("-d")
        .arg("output_encoding=")
        .arg("-f")
        .arg(&input)
        .output()
        .unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "ISO-8859-1\n",
            "string(18) \"&auml;&ouml;&uuml;\"\n",
            "array(3) {\n",
            "  [\"first\"]=>\n",
            "  string(4) \"val1\"\n",
            "  [\"second\"]=>\n",
            "  string(4) \"val2\"\n",
            "  [\"third\"]=>\n",
            "  string(4) \"val3\"\n",
            "}\n",
            "string(0) \"\"\n",
            "string(10) \"unsafe_raw\"\n",
            "string(0) \"\"\n",
            "string(0) \"\"\n",
            "string(0) \"\"\n",
            "string(1) \"/\"\n",
            "array(2) {\n",
            "  [\"left\"]=>\n",
            "  string(1) \"1\"\n",
            "  [\"right\"]=>\n",
            "  string(1) \"2\"\n",
            "}\n",
            "string(0) \"\"\n",
            "string(0) \"\"\n",
            "string(0) \"\"\n",
            "string(10) \"ISO-8859-1\"\n",
            "string(6) \"cp1252\"\n",
            "string(6) \"EUC-JP\"\n",
            "string(0) \"\"\n",
            "string(0) \"\"\n",
            "string(0) \"\"\n",
            "&\n"
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn phpc_zend_multibyte_source_encoding_handles_boms_and_shift_jis() {
    let root = temp_dir("ptn-phpc-zend-multibyte-source-encoding");
    fs::create_dir_all(&root).unwrap();

    let utf8_bom = root.join("utf8-bom.php");
    let mut utf8_bom_source = vec![0xef, 0xbb, 0xbf];
    utf8_bom_source.extend_from_slice(b"<?php echo \"Hello World\\n\";");
    fs::write(&utf8_bom, utf8_bom_source).unwrap();
    let execution = Command::new(env!("CARGO_BIN_EXE_phpc"))
        .arg("-d")
        .arg("zend.multibyte=1")
        .arg("-d")
        .arg("internal_encoding=iso-8859-1")
        .arg("-f")
        .arg(&utf8_bom)
        .output()
        .unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        "Hello World\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let utf16_bom = root.join("utf16-bom.php");
    let utf16_body = "<?php\nprint \"Hello World\\n\";\n?>\n===DONE===\n";
    let mut utf16_source = vec![0xff, 0xfe];
    for word in utf16_body.encode_utf16() {
        utf16_source.extend_from_slice(&word.to_le_bytes());
    }
    utf16_source.push(0);
    fs::write(&utf16_bom, utf16_source).unwrap();
    let execution = Command::new(env!("CARGO_BIN_EXE_phpc"))
        .arg("-d")
        .arg("zend.multibyte=1")
        .arg("-d")
        .arg("internal_encoding=iso-8859-1")
        .arg("-f")
        .arg(&utf16_bom)
        .output()
        .unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        "Hello World\n===DONE===\n?"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let shift_jis = root.join("shift-jis.php");
    let mut shift_jis_source = b"<?php\ndeclare(encoding='Shift_JIS');\n$s = \"".to_vec();
    shift_jis_source.extend_from_slice(&[0x95, 0x5c]);
    shift_jis_source.extend_from_slice(b"\";\nprintf(\"%x:%x\", ord($s[0]), ord($s[1]));\n");
    fs::write(&shift_jis, shift_jis_source).unwrap();
    let execution = Command::new(env!("CARGO_BIN_EXE_phpc"))
        .arg("-d")
        .arg("zend.multibyte=1")
        .arg("-d")
        .arg("internal_encoding=SJIS")
        .arg("-f")
        .arg(&shift_jis)
        .output()
        .unwrap();
    assert!(execution.status.success());
    assert_eq!(String::from_utf8(execution.stdout).unwrap(), "95:5c");
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

