#[test]
fn compile_exit_construct_forms_to_native_binary() {
    let root = temp_dir("ptn-native-exit-construct-forms");
    fs::create_dir_all(&root).unwrap();
    let cases = [
        (
            "exit-string.php",
            "<?php echo \"before\\n\"; exit \"bye\\n\"; echo \"after\\n\";",
            Some(0),
            "before\nbye\n",
        ),
        (
            "exit-string-in-branch.php",
            "<?php if (false) { exit(\"failed\\n\"); } echo \"kept\\n\";",
            Some(0),
            "kept\n",
        ),
        (
            "exit-named-status.php",
            "<?php exit(status: \"named\\n\"); echo \"after\\n\";",
            Some(0),
            "named\n",
        ),
        (
            "die-without-status.php",
            "<?php echo \"before\\n\"; die; echo \"after\\n\";",
            Some(0),
            "before\n",
        ),
        (
            "die-parenthesized-string.php",
            "<?php if (false) { die(\"bad\\n\"); } echo \"ok\\n\";",
            Some(0),
            "ok\n",
        ),
        (
            "exit-int.php",
            "<?php echo \"before\\n\"; exit(7); echo \"after\\n\";",
            Some(7),
            "before\n",
        ),
    ];

    for (name, source, expected_status, expected_stdout) in cases {
        let input = root.join(name);
        let output = root.join(format!("{name}-bin"));
        fs::write(&input, source).unwrap();

        compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

        let execution = Command::new(&output).output().unwrap();
        assert_eq!(execution.status.code(), expected_status, "{name}");
        assert_eq!(
            String::from_utf8(execution.stdout).unwrap(),
            expected_stdout,
            "{name}"
        );
        assert_eq!(String::from_utf8(execution.stderr).unwrap(), "", "{name}");
    }

    let invalid_input = root.join("exit-array.php");
    let invalid_output = root.join("exit-array-bin");
    fs::write(&invalid_input, "<?php\nexit([]);\necho \"after\\n\";").unwrap();

    compile_file(
        &invalid_input,
        &invalid_output,
        CompileOptions { emit_c: false },
    )
    .unwrap();

    let execution = Command::new(&invalid_output).output().unwrap();
    assert!(!execution.status.success(), "exit-array.php should fail");
    assert_eq!(String::from_utf8(execution.stdout).unwrap(), "");
    let stderr = String::from_utf8(execution.stderr).unwrap();
    assert!(
        stderr.contains("exit(): Argument #1 ($status) must be of type string|int, array given"),
        "{stderr}"
    );
}

