#[test]
fn compile_included_function_body_uses_declaration_strict_types_to_native_binary() {
    let root = temp_dir("ptn-native-included-function-strict-types");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("main.php");
    let weak_include = root.join("weak.inc");
    let strict_include = root.join("strict.inc");
    let output = root.join("included-function-strict-types-bin");
    fs::write(
        &input,
        "<?php\n\
declare(strict_types=1);\n\
function test(int $i) { var_dump($i); }\n\
require __DIR__ . '/weak.inc';\n\
require __DIR__ . '/strict.inc';\n\
$fn = test(...);\n\
do_weak_call($fn);\n\
try { do_strict_call($fn); } catch (Error $e) { echo $e->getMessage(), \"\\n\"; }\n",
    )
    .unwrap();
    fs::write(
        &weak_include,
        "<?php\nfunction do_weak_call($fn) { $fn('42'); }\n",
    )
    .unwrap();
    fs::write(
        &strict_include,
        "<?php\ndeclare(strict_types=1);\nfunction do_strict_call($fn) { $fn('42'); }\n",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    let stdout = String::from_utf8(execution.stdout).unwrap();
    assert!(stdout.starts_with("int(42)\n"), "{stdout}");
    assert!(
        stdout.contains("test(): Argument #1 ($i) must be of type int, string given, called in "),
        "{stdout}"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_repeated_include_function_redeclaration_fatals_to_native_binary() {
    let root = temp_dir("ptn-native-repeated-include-function-redeclare");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("main.php");
    let included = root.join("functions.inc");
    let output = root.join("repeated-include-function-redeclare-bin");
    fs::write(
        &input,
        "<?php\n\
require __DIR__ . '/functions.inc';\n\
require __DIR__ . '/functions.inc';\n",
    )
    .unwrap();
    fs::write(
        &included,
        "<?php\n\
function repeated_include_function() {\n\
    return 42;\n\
}\n",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(!execution.status.success());
    assert_eq!(String::from_utf8(execution.stdout).unwrap(), "");
    assert_eq!(
        String::from_utf8(execution.stderr).unwrap(),
        format!(
            "Fatal error: Cannot redeclare function repeated_include_function() (previously declared in {}:2) in {} on line 2\n",
            included.display(),
            included.display()
        )
    );

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("Cannot redeclare function repeated_include_function"));
    assert!(c_source.contains("ptn_emit_fatal_error_at"));
}

