#[test]
fn compile_closure_invoke_method_suppresses_type_error_call_site_to_native_binary() {
    let root = temp_dir("ptn-native-closure-invoke-suppresses-type-error-call-site");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("closure-invoke-suppresses-type-error-call-site.php");
    let output = root.join("closure-invoke-suppresses-type-error-call-site-bin");
    fs::write(
        &input,
        "<?php
class InvokeTypeA {}
class InvokeTypeB {}

$closure = function (InvokeTypeA $value) {};
$bad = new InvokeTypeB();

foreach ([
    function () use ($closure, $bad) { $closure($bad); },
    function () use ($closure, $bad) { $closure->__invoke($bad); },
    function () use ($closure, $bad) { call_user_func([$closure, '__invoke'], $bad); },
] as $runner) {
    try {
        $runner();
    } catch (TypeError $error) {
        echo $error->getMessage(), \"\\n\";
    }
}
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    let stdout = String::from_utf8(execution.stdout).unwrap();
    let lines = stdout.lines().collect::<Vec<_>>();
    assert_eq!(lines.len(), 3, "{stdout}");
    assert!(lines[0].contains("called in"), "{stdout}");
    assert!(!lines[1].contains("called in"), "{stdout}");
    assert!(!lines[2].contains("called in"), "{stdout}");
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("previous_suppress_user_call_frame_location"));
}

#[test]
fn compile_closure_from_callable_invocation_and_metadata_to_native_binary() {
    let root = temp_dir("ptn-native-closure-from-callable-metadata");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("closure-from-callable-metadata.php");
    let output = root.join("closure-from-callable-metadata-bin");
    fs::write(
        &input,
        "<?php
function add($value, $extra = 1) {
    return $value + $extra;
}

class FromCallableWorker {
    public static function twice($value) {
        return $value * 2;
    }

    public function plus($value) {
        return $value + 3;
    }
}

$worker = new FromCallableWorker();
$named = Closure::fromCallable(\"add\");
$static = Closure::fromCallable(\"FromCallableWorker::twice\");
$method = Closure::fromCallable([$worker, \"plus\"]);
$same = function ($value) { return $value - 1; };
$sameResult = Closure::fromCallable($same);

var_dump($named(4));
var_dump($static(4));
var_dump($method(4));
var_dump($sameResult === $same);
var_dump($sameResult(4));

$namedReflection = new ReflectionFunction($named);
var_dump($namedReflection->getName());
var_dump($namedReflection->getNumberOfParameters());
var_dump($namedReflection->getNumberOfRequiredParameters());

$staticReflection = new ReflectionFunction($static);
var_dump($staticReflection->getName());
var_dump($staticReflection->getNumberOfParameters());

$sameReflection = new ReflectionFunction($sameResult);
var_dump($sameReflection->getName());
var_dump($sameReflection->getNumberOfParameters());
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    let same_display_name = format!("{{closure:{}:20}}", input.display());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        format!(
            concat!(
                "int(5)\n",
                "int(8)\n",
                "int(7)\n",
                "bool(true)\n",
                "int(3)\n",
                "string(3) \"add\"\n",
                "int(2)\n",
                "int(1)\n",
                "string(25) \"FromCallableWorker::twice\"\n",
                "int(1)\n",
                "string({}) \"{}\"\n",
                "int(1)\n",
            ),
            same_display_name.len(),
            same_display_name
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_internal_closure_from_callable"));
    assert!(c_source.contains("ptn_closure_wrap_callable"));
    assert!(c_source.contains("resolved.as.closure->has_wrapped_callable"));
}

#[test]
fn compile_closure_from_callable_parent_string_preserves_scope_to_native_binary() {
    let root = temp_dir("ptn-native-closure-from-callable-parent-string-scope");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("closure-from-callable-parent-string-scope.php");
    let output = root.join("closure-from-callable-parent-string-scope-bin");
    fs::write(
        &input,
        "<?php
class ParentCallableBase {
    public function label($suffix) {
        return static::class . ':' . $suffix;
    }
}

class ParentCallableChild extends ParentCallableBase {
    public function make() {
        return Closure::fromCallable('parent::label');
    }
}

$closure = (new ParentCallableChild())->make();
echo $closure('ok'), \"\\n\";
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    let stdout = String::from_utf8(execution.stdout).unwrap();
    assert!(stdout.contains("ParentCallableChild:ok\n"), "{stdout}");
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_closure_relative_scope_class_name"));
    assert!(c_source.contains("resolved.as.closure->scope_class_name"));
}

#[test]
fn compile_closure_from_callable_called_class_reflection_to_native_binary() {
    let root = temp_dir("ptn-native-closure-from-callable-called-class");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("closure-from-callable-called-class.php");
    let output = root.join("closure-from-callable-called-class-bin");
    fs::write(
        &input,
        r#"<?php
class ClosureCalledA {
    public static function __callStatic($name, $args) { echo static::class, "::", $name, "\n"; }
    public function __call($name, $args) { echo static::class, "->", $name, "\n"; }
    public static function b() { echo static::class, "::b\n"; }
    public function c() { echo static::class, "->c\n"; }
}

class ClosureCalledB extends ClosureCalledA {}

foreach ([
    ['ClosureCalledB', 'b'],
    [new ClosureCalledB(), 'c'],
    ['ClosureCalledB', 'd'],
    [new ClosureCalledB(), 'e'],
    ['ClosureCalledA', 'b'],
] as $callable) {
    $closure = Closure::fromCallable($callable);
    $class = (new ReflectionFunction($closure))->getClosureCalledClass();
    var_dump($class?->getName());
    $closure();
}
"#,
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "string(14) \"ClosureCalledB\"\n",
            "ClosureCalledB::b\n",
            "string(14) \"ClosureCalledB\"\n",
            "ClosureCalledB->c\n",
            "string(14) \"ClosureCalledB\"\n",
            "ClosureCalledB::d\n",
            "string(14) \"ClosureCalledB\"\n",
            "ClosureCalledB->e\n",
            "string(14) \"ClosureCalledA\"\n",
            "ClosureCalledA::b\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_closure_wrapped_callable_called_class_name"));
    assert!(c_source.contains(
        "ptn_call_declared_method_in_scope(runtime, receiver, ptn_object_callable_class"
    ));
}

#[test]
fn compile_bound_closure_reflection_parameters_declare_method_to_native_binary() {
    let root = temp_dir("ptn-native-bound-closure-reflection-parameter-method");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("bound-closure-reflection-parameter-method.php");
    let output = root.join("bound-closure-reflection-parameter-method-bin");
    fs::write(
        &input,
        r#"<?php
class BoundClosureBase {}
class BoundClosureChild extends BoundClosureBase {}

$closure = function ($left, $right = 0): self {};
$bound = $closure->bindTo(new BoundClosureChild(), BoundClosureChild::class);
$reflection = new ReflectionFunction($bound);
$parameter = $reflection->getParameters()[0];
$declaring = $parameter->getDeclaringFunction();

var_dump($declaring::class);
var_dump($declaring instanceof ReflectionMethod);
var_dump($declaring->getName() === $reflection->getName());
"#,
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "string(16) \"ReflectionMethod\"\n",
            "bool(true)\n",
            "bool(true)\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_closure_from_callable_object_method_call_rebinds_to_native_binary() {
    let root = temp_dir("ptn-native-closure-from-callable-object-method-rebind");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("closure-from-callable-object-method-rebind.php");
    let output = root.join("closure-from-callable-object-method-rebind-bin");
    fs::write(
        &input,
        r#"<?php
date_default_timezone_set('UTC');

class Counter {
    public $value;

    public function __construct($value) {
        $this->value = $value;
    }

    public function value() {
        return $this->value;
    }
}

$first = new Counter(10);
$second = new Counter(30);
$method = Closure::fromCallable([$first, 'value']);
var_dump($method());
var_dump($method->call($second));
var_dump($method());

$timestamp = Closure::fromCallable([new DateTime(), 'getTimestamp']);
var_dump($timestamp->call(new DateTime('@123')));
var_dump((new DateTime('@456'))->getTimestamp());
var_dump((new DateTimeImmutable('@789'))->getTimestamp());
"#,
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "int(10)\n",
            "int(30)\n",
            "int(10)\n",
            "int(123)\n",
            "int(456)\n",
            "int(789)\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_wrapped_callable_is_temporary"));
    assert!(c_source.contains("getTimestamp"));
}

#[test]
fn compile_closure_from_invokable_preserves_method_deprecated_metadata_to_native_binary() {
    let root = temp_dir("ptn-native-closure-invokable-deprecated-metadata");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("closure-invokable-deprecated-metadata.php");
    let output = root.join("closure-invokable-deprecated-metadata-bin");
    fs::write(
        &input,
        "<?php
class Foo {
    #[Deprecated(\"xyzzy\")]
    public function __invoke() {
        echo \"In __invoke\\n\";
    }
}

$foo = new Foo;
$closure = Closure::fromCallable($foo);
$test = $closure->__invoke(...);

$rc = new ReflectionMethod($test, '__invoke');
$attributes = $rc->getAttributes();
echo count($attributes), \"\\n\";
echo $attributes[0]->getName(), \"\\n\";
var_dump($rc->isDeprecated());

$test();
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    let stdout = String::from_utf8(execution.stdout).unwrap();
    assert!(stdout.contains("1\nDeprecated\nbool(true)\n"), "{stdout}");
    assert!(
        stdout.contains("Deprecated: Method Foo::__invoke() is deprecated, xyzzy in ptn on line "),
        "{stdout}"
    );
    assert!(stdout.ends_with("In __invoke\n"), "{stdout}");
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_find_callable_metadata"));
    assert!(c_source.contains("ptn_reflection_method_metadata_attributes"));
}

#[test]
fn compile_closure_from_callable_parameter_type_reflection_to_native_binary() {
    let root = temp_dir("ptn-native-closure-from-callable-parameter-types");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("closure-from-callable-parameter-types.php");
    let output = root.join("closure-from-callable-parameter-types-bin");
    fs::write(
        &input,
        "<?php
class Bar {
    public static function staticMethod(Bar $bar, int $int, $none): ?string {}
    public function instanceMethod(Bar $bar, int $int, $none): ?Bar {}
}

function foo(Bar $bar, int $int, $none): ?string {}

$fn = function (Bar $bar, int $x, $none): ?Bar {};
$bar = new Bar();

foreach (['foo', $fn, 'Bar::staticMethod', [$bar, 'instanceMethod']] as $callable) {
    $closure = Closure::fromCallable($callable);
    $refl = new ReflectionFunction($closure);
    foreach ($refl->getParameters() as $param) {
        var_dump($param->getName(), $param->getPosition(), $param->hasType());
        if ($param->hasType()) {
            $type = $param->getType();
            var_dump($type->getName(), (string) $type, $type->allowsNull(), $type->isBuiltin());
        }
    }
    $return = $refl->getReturnType();
    var_dump($return->getName(), (string) $return, $return->allowsNull());
}
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "string(3) \"bar\"\nint(0)\nbool(true)\nstring(3) \"Bar\"\nstring(3) \"Bar\"\nbool(false)\nbool(false)\n",
            "string(3) \"int\"\nint(1)\nbool(true)\nstring(3) \"int\"\nstring(3) \"int\"\nbool(false)\nbool(true)\n",
            "string(4) \"none\"\nint(2)\nbool(false)\nstring(6) \"string\"\nstring(7) \"?string\"\nbool(true)\n",
            "string(3) \"bar\"\nint(0)\nbool(true)\nstring(3) \"Bar\"\nstring(3) \"Bar\"\nbool(false)\nbool(false)\n",
            "string(1) \"x\"\nint(1)\nbool(true)\nstring(3) \"int\"\nstring(3) \"int\"\nbool(false)\nbool(true)\n",
            "string(4) \"none\"\nint(2)\nbool(false)\nstring(3) \"Bar\"\nstring(4) \"?Bar\"\nbool(true)\n",
            "string(3) \"bar\"\nint(0)\nbool(true)\nstring(3) \"Bar\"\nstring(3) \"Bar\"\nbool(false)\nbool(false)\n",
            "string(3) \"int\"\nint(1)\nbool(true)\nstring(3) \"int\"\nstring(3) \"int\"\nbool(false)\nbool(true)\n",
            "string(4) \"none\"\nint(2)\nbool(false)\nstring(6) \"string\"\nstring(7) \"?string\"\nbool(true)\n",
            "string(3) \"bar\"\nint(0)\nbool(true)\nstring(3) \"Bar\"\nstring(3) \"Bar\"\nbool(false)\nbool(false)\n",
            "string(3) \"int\"\nint(1)\nbool(true)\nstring(3) \"int\"\nstring(3) \"int\"\nbool(false)\nbool(true)\n",
            "string(4) \"none\"\nint(2)\nbool(false)\nstring(3) \"Bar\"\nstring(4) \"?Bar\"\nbool(true)\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("PtnParameterMetadata"));
    assert!(c_source.contains("ptn_reflection_parameter_object_from_metadata"));
    assert!(c_source.contains("ptn_reflection_named_type_object_from_metadata"));
}

