#[test]
fn compile_first_class_callable_syntax_and_metadata_to_native_binary() {
    let root = temp_dir("ptn-native-first-class-callable-syntax");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("first-class-callable-syntax.php");
    let output = root.join("first-class-callable-syntax-bin");
    fs::write(
        &input,
        "<?php
function fcc_add($value, $extra = 1) {
    return $value + $extra;
}

class FccWorker {
    public static function twice($value) {
        return $value * 2;
    }

    public static function selfTwice() {
        return self::twice(...);
    }

    public function plus($value) {
        return $value + 3;
    }
}

class FccConst {
    public const Twice = self::twice(...);

    public static function twice($value) {
        return $value * 2;
    }
}

function fcc_default($fn = strlen(...)) {
    var_dump($fn(\"hello\"));
}

const FCC_LEN = strlen(...);

$worker = new FccWorker();
$named = fcc_add(...);
$internal = strlen(...);
$static = FccWorker::twice(...);
$method = $worker->plus(...);
$same = function ($value) { return $value - 1; };
$sameResult = $same(...);
$name = \"fcc_add\";
$dynamic = $name(...);
$className = \"FccWorker\";
$methodName = \"twice\";
$dynamicStatic = $className::$methodName(...);
$directDynamicStatic = FccWorker::$methodName(...);

var_dump($named(4));
var_dump($internal(\"abcd\"));
var_dump($static(4));
var_dump($method(4));
var_dump($sameResult === $same);
var_dump($sameResult(4));
var_dump($dynamic(6, 7));
var_dump($dynamicStatic(8));
var_dump($directDynamicStatic(9));

$self = FccWorker::selfTwice();
var_dump($self(5));
var_dump((FCC_LEN)(\"abc\"));
var_dump((FccConst::Twice)(9));
fcc_default();
fcc_default(strrev(...));

$namedReflection = new ReflectionFunction($named);
var_dump($namedReflection->getName());
var_dump($namedReflection->getNumberOfParameters());
var_dump($namedReflection->getNumberOfRequiredParameters());

$staticReflection = new ReflectionFunction($static);
var_dump($staticReflection->getName());
var_dump($staticReflection->getNumberOfParameters());
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "int(5)\n",
            "int(4)\n",
            "int(8)\n",
            "int(7)\n",
            "bool(true)\n",
            "int(3)\n",
            "int(13)\n",
            "int(16)\n",
            "int(18)\n",
            "int(10)\n",
            "int(3)\n",
            "int(18)\n",
            "int(5)\n",
            "string(5) \"olleh\"\n",
            "string(7) \"fcc_add\"\n",
            "int(2)\n",
            "int(1)\n",
            "string(16) \"FccWorker::twice\"\n",
            "int(1)\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_first_class_callable_create"));
    assert!(c_source.contains("ptn_closure_wrap_callable"));
    assert!(c_source.contains("FccConst::twice"));
}

#[test]
fn compile_first_class_callable_static_trait_method_initializer_to_native_binary() {
    let root = temp_dir("ptn-native-first-class-callable-static-trait-method");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("first-class-callable-static-trait-method.php");
    let output = root.join("first-class-callable-static-trait-method-bin");
    fs::write(
        &input,
        "<?php
trait FccTraitCallable {
    public static function myMethod(string $foo) {
        echo \"Called \", __METHOD__, \"\\n\";
        var_dump($foo);
    }
}

const TRAIT_FCC = FccTraitCallable::myMethod(...);

var_dump(TRAIT_FCC);
(TRAIT_FCC)(\"abc\");

set_error_handler(function ($errno, $errstr, $errfile, $errline) {
    throw new ErrorException($errstr, 0, $errno, $errfile, $errline);
});

trait FccTraitCallableThrows {
    public static function myMethod(string $foo) {
        echo \"Called \", __METHOD__, \"\\n\";
        var_dump($foo);
    }
}

function fcc_trait_default(Closure $c = FccTraitCallableThrows::myMethod(...)) {
    var_dump($c);
    $c(\"abc\");
}

try {
    fcc_trait_default();
} catch (ErrorException $e) {
    echo \"Caught: \", $e->getMessage(), \"\\n\";
}
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    let stdout = String::from_utf8(execution.stdout).unwrap();
    assert_eq!(
        stdout
            .matches("Calling static trait method FccTraitCallable::myMethod")
            .count(),
        1,
        "{stdout}"
    );
    assert!(stdout.contains("object(Closure)#"), "{stdout}");
    assert!(stdout.contains(concat!(
        "  [\"function\"]=>\n",
        "  string(26) \"FccTraitCallable::myMethod\"\n",
        "  [\"parameter\"]=>\n",
        "  array(1) {\n",
        "    [\"$foo\"]=>\n",
        "    string(10) \"<required>\"\n",
        "  }\n",
    )));
    assert!(
        stdout.contains("Called FccTraitCallable::myMethod\nstring(3) \"abc\"\n"),
        "{stdout}"
    );
    assert!(stdout.contains(
        "Caught: Calling static trait method FccTraitCallableThrows::myMethod is deprecated"
    ));
    assert!(
        !stdout.contains("Called FccTraitCallableThrows::myMethod"),
        "{stdout}"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_runtime_emit_static_trait_method_deprecation"));
    assert!(c_source.contains("suppress_wrapped_callable_deprecation"));
    assert!(c_source.contains("FccTraitCallable::myMethod"));
}

