#[test]
fn compile_first_class_callable_diagnostics_to_native_binary() {
    let root = temp_dir("ptn-native-first-class-callable-diagnostics");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("first-class-callable-diagnostics.php");
    let output = root.join("first-class-callable-diagnostics-bin");
    fs::write(
        &input,
        "<?php
class FccErrorTest {
    private static function privateMethod() {}

    public function instanceMethod() {}
}

try {
    $fn = 123;
    $callable = $fn(...);
} catch (Error $e) {
    print $e->getMessage() . \"\\n\";
}
try {
    $callable = does_not_exist(...);
} catch (Error $e) {
    print $e->getMessage() . \"\\n\";
}
try {
    $callable = stdClass::doesNotExist(...);
} catch (Error $e) {
    print $e->getMessage() . \"\\n\";
}
try {
    $callable = (new stdClass)->doesNotExist(...);
} catch (Error $e) {
    print $e->getMessage() . \"\\n\";
}
try {
    $callable = [new stdClass, \"doesNotExist\"](...);
} catch (Error $e) {
    print $e->getMessage() . \"\\n\";
}
try {
    $callable = FccErrorTest::privateMethod(...);
} catch (Error $e) {
    print $e->getMessage() . \"\\n\";
}
try {
    $callable = FccErrorTest::instanceMethod(...);
} catch (Error $e) {
    print $e->getMessage() . \"\\n\";
}
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "Value of type int is not callable\n",
            "Call to undefined function does_not_exist()\n",
            "Call to undefined method stdClass::doesNotExist()\n",
            "Call to undefined method stdClass::doesNotExist()\n",
            "Call to undefined method stdClass::doesNotExist()\n",
            "Call to private method FccErrorTest::privateMethod() from global scope\n",
            "Non-static method FccErrorTest::instanceMethod() cannot be called statically\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_first_class_callable_create"));
    assert!(c_source.contains("ptn_first_class_callable_throw_error"));
}

#[test]
fn phpc_renders_first_class_callable_forbidden_context_fatals() {
    let cases = [
        (
            "first-class-callable-new",
            "<?php
class Foo {}
new Foo(...);
",
            "Cannot create Closure for new expression",
            3,
        ),
        (
            "first-class-callable-new-anonymous",
            "<?php
new class(...) {};
",
            "Cannot create Closure for new expression",
            2,
        ),
        (
            "first-class-callable-attribute",
            "<?php
#[Attribute(...)]
class Foo {}
",
            "Cannot create Closure as attribute argument",
            3,
        ),
        (
            "first-class-callable-nullsafe-chain",
            "<?php
$foo?->foo->bar(...);
",
            "Cannot combine nullsafe operator with Closure creation",
            2,
        ),
        (
            "first-class-callable-non-unary",
            "<?php
foo(1, ...);
",
            "Cannot create a Closure for call expression with more than one argument, or non-variadic placeholders",
            2,
        ),
        (
            "first-class-callable-non-variadic-placeholder",
            "<?php
foo(?);
",
            "Cannot create a Closure for call expression with more than one argument, or non-variadic placeholders",
            2,
        ),
        (
            "first-class-callable-constexpr-instance",
            "<?php
class Foo {
    public function method() {}
}
const C = (new Foo())->method(...);
",
            "Constant expression contains invalid operations",
            5,
        ),
        (
            "first-class-callable-constexpr-closure",
            "<?php
const C = (static function () {})(...);
",
            "Cannot use dynamic function name in constant expression",
            2,
        ),
        (
            "first-class-callable-constexpr-constant-name",
            "<?php
const Name = 'strrev';
const C = (Name)(...);
",
            "Cannot use dynamic function name in constant expression",
            3,
        ),
        (
            "first-class-callable-constexpr-static",
            "<?php
class Foo {
    public const C = static::method(...);
    public static function method() {}
}
",
            "\"static\" is not allowed in compile-time constants",
            3,
        ),
    ];

    for (name, source, message, line) in cases {
        let root_name = format!("ptn-phpc-{name}");
        let root = temp_dir(&root_name);
        fs::create_dir_all(&root).unwrap();
        let input = root.join(format!("{name}.php"));
        fs::write(&input, source).unwrap();

        let execution = Command::new(phpc_bin()).arg(&input).output().unwrap();
        assert!(!execution.status.success(), "{name}");
        assert_eq!(execution.status.code(), Some(255), "{name}");
        assert_eq!(String::from_utf8(execution.stdout).unwrap(), "", "{name}");
        assert_eq!(
            String::from_utf8(execution.stderr).unwrap(),
            format!(
                "Fatal error: {message} in {} on line {line}\n",
                input.display()
            ),
            "{name}"
        );
    }
}

#[test]
fn compile_first_class_callable_magic_trampoline_metadata_to_native_binary() {
    let root = temp_dir("ptn-native-first-class-callable-magic-trampoline");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("first-class-callable-magic-trampoline.php");
    let output = root.join("first-class-callable-magic-trampoline-bin");
    fs::write(
        &input,
        "<?php
class MagicFccRegression {
    public function __call($name, $args) {
        var_dump($name, $args);
    }

    public static function __callStatic($name, $args) {
        var_dump($name, $args);
    }
}

class MagicFccMetadataRegression {
    #[Deprecated]
    public function __call(string $name, array $params) {
    }

    #[Deprecated(\"due to some reason\")]
    public static function __callStatic(string $name, array $params) {
    }
}

function show_magic_fcc_metadata(Closure $closure) {
    $reflection = new ReflectionFunction($closure);
    $attributes = $reflection->getAttributes();
    echo count($attributes), \"\\n\";
    echo $attributes[0]->getName(), \"\\n\";
    $deprecated = $attributes[0]->newInstance();
    var_dump($deprecated->message);
    var_dump($reflection->isDeprecated());
}

$instance = new MagicFccRegression();
$instance->missing(...)(first: 11, second: \"ok\");
MagicFccRegression::missingStatic(...)(third: 33);

$reflection = new ReflectionFunction(MagicFccRegression::fail(...));
$parameters = $reflection->getParameters();
var_dump(count($parameters));
$argument = $parameters[0];
var_dump($argument->getName());
var_dump($argument->isVariadic());
$type = $argument->getType();
var_dump($type->getName());

$metadataInstance = new MagicFccMetadataRegression();
show_magic_fcc_metadata(Closure::fromCallable([$metadataInstance, 'test']));
show_magic_fcc_metadata($metadataInstance->test(...));
show_magic_fcc_metadata(Closure::fromCallable('MagicFccMetadataRegression::test'));
show_magic_fcc_metadata(MagicFccMetadataRegression::test(...));
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "string(7) \"missing\"\n",
            "array(2) {\n",
            "  [\"first\"]=>\n",
            "  int(11)\n",
            "  [\"second\"]=>\n",
            "  string(2) \"ok\"\n",
            "}\n",
            "string(13) \"missingStatic\"\n",
            "array(1) {\n",
            "  [\"third\"]=>\n",
            "  int(33)\n",
            "}\n",
            "int(1)\n",
            "string(9) \"arguments\"\n",
            "bool(true)\n",
            "string(5) \"mixed\"\n",
            "1\n",
            "Deprecated\n",
            "NULL\n",
            "bool(true)\n",
            "1\n",
            "Deprecated\n",
            "NULL\n",
            "bool(true)\n",
            "1\n",
            "Deprecated\n",
            "string(18) \"due to some reason\"\n",
            "bool(true)\n",
            "1\n",
            "Deprecated\n",
            "string(18) \"due to some reason\"\n",
            "bool(true)\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_magic_call_trampoline_metadata"));
    assert!(c_source.contains("ptn_function_metadata_with_attribute_method"));
    assert!(c_source.contains("ptn_find_callable_metadata"));
}

