#[test]
fn compile_array_walk_callback_diagnostics_to_native_binary() {
    let root = temp_dir("ptn-native-array-walk-callback-diagnostics");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("array-walk-callback-diagnostics.php");
    let output = root.join("array-walk-callback-diagnostics-bin");
    fs::write(
        &input,
        "<?php
function callback1($value, $key, $user_data) {}
function callback2($value, $key, $user_data1, $user_data2) {}
$input = [1];

try {
    var_dump(array_walk($input, \"callback1\"));
} catch (Throwable $e) {
    echo \"Exception: \" . $e->getMessage() . \"\\n\";
}
try {
    var_dump(array_walk($input, \"callback2\", 4));
} catch (Throwable $e) {
    echo \"Exception: \" . $e->getMessage() . \"\\n\";
}
try {
    var_dump(array_walk($input, \"echo\"));
} catch (TypeError $e) {
    echo $e->getMessage(), \"\\n\";
}
try {
    var_dump(array_walk($input, \"callback1\", 20, 10));
} catch (Throwable $e) {
    echo \"Exception: \" . $e->getMessage() . \"\\n\";
}
try {
    var_dump(array_walk_recursive($input, \"callback1\"));
} catch (Throwable $e) {
    echo \"Exception: \" . $e->getMessage() . \"\\n\";
}
try {
    var_dump(array_walk_recursive($input, \"callback2\", 4));
} catch (Throwable $e) {
    echo \"Exception: \" . $e->getMessage() . \"\\n\";
}
try {
    var_dump(array_walk_recursive($input, \"callback1\", 20, 10));
} catch (Throwable $e) {
    echo \"Exception: \" . $e->getMessage() . \"\\n\";
}
",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "Exception: Too few arguments to function callback1(), 2 passed and exactly 3 expected\n",
            "Exception: Too few arguments to function callback2(), 3 passed and exactly 4 expected\n",
            "array_walk(): Argument #2 ($callback) must be a valid callback, function \"echo\" not found or invalid function name\n",
            "Exception: array_walk() expects at most 3 arguments, 4 given\n",
            "Exception: Too few arguments to function callback1(), 2 passed and exactly 3 expected\n",
            "Exception: Too few arguments to function callback2(), 3 passed and exactly 4 expected\n",
            "Exception: array_walk_recursive() expects at most 3 arguments, 4 given\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_array_walk_user_type_error_uses_internal_callback_location_to_native_binary() {
    let root = temp_dir("ptn-native-array-walk-user-type-error-location");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("array-walk-user-type-error-location.php");
    let output = root.join("array-walk-user-type-error-location-bin");
    fs::write(
        &input,
        "<?php
class TypeHinted {}
function needs_type(TypeHinted $value) {
    var_dump($value);
}
$items = [new TypeHinted(), 1];
array_walk($items, \"needs_type\");
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(!execution.status.success());
    assert_eq!(execution.status.code(), Some(255));
    let stdout = String::from_utf8(execution.stdout).unwrap();
    assert!(stdout.contains("object(TypeHinted)#"), "{stdout}");
    let stderr = String::from_utf8(execution.stderr).unwrap();
    let message = format!(
        "Fatal error: Uncaught TypeError: needs_type(): Argument #1 ($value) must be of type TypeHinted, int given in {}:3",
        input.display()
    );
    assert!(stderr.contains(&message), "{stderr}");
    assert!(
        stderr.contains("\n#0 [internal function]: needs_type(1, 1)\n"),
        "{stderr}"
    );
    assert!(
        stderr.contains(&format!(
            "\n#1 {}(7): array_walk(Array, 'needs_type')\n",
            input.display()
        )),
        "{stderr}"
    );
    assert!(
        !stderr.contains("called in"),
        "internal callback type errors must not add a call-site suffix: {stderr}"
    );

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("include_definition && include_call_site"));
    assert!(c_source.contains("runtime->trace_frame->file"));
}

