#[test]
fn compile_reflection_promoted_and_dynamic_properties_to_native_binary() {
    let root = temp_dir("ptn-native-reflection-promoted-and-dynamic-properties");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("reflection-promoted-and-dynamic-properties.php");
    let output = root.join("reflection-promoted-and-dynamic-properties-bin");
    fs::write(
        &input,
        "<?php
class ReflectPromotedProperty {
    public $z;
    public function __construct(
        public int $x,
        /** @SomeAnnotation() */
        public string $y = \"123\",
        string $ignored = \"abc\",
    ) {}
}

$rc = new ReflectionClass(ReflectPromotedProperty::class);
$classText = (string) $rc;
var_dump(strpos($classText, \"    /** @SomeAnnotation() */\\n    Property [ public string \\$y ]\") !== false);
$y = $rc->getProperty('y');
var_dump(method_exists($y, 'isPromoted'));
var_dump($y->isPromoted());
var_dump($y->getDocComment());
var_dump($rc->getProperty('z')->isPromoted());
var_dump((new ReflectionParameter([ReflectPromotedProperty::class, '__construct'], 'y'))->isPromoted());
var_dump((new ReflectionParameter([ReflectPromotedProperty::class, '__construct'], 'ignored'))->isPromoted());

class ReflectPrivateDynamicBase {
    private $p = 1;
}

#[AllowDynamicProperties]
class ReflectPrivateDynamicChild extends ReflectPrivateDynamicBase {
}

$object = new ReflectPrivateDynamicChild();
$object->p = 'value';
$reflectionObject = new ReflectionObject($object);
var_dump(strpos((string) $reflectionObject, \"Dynamic properties [0]\") !== false);
var_dump(count($reflectionObject->getProperties()));

class ReflectIterableSameName {
    public iterable $iterable;
    public ?iterable $nullableIterable;
}

[$iterableProperty, $nullableIterableProperty] = (new ReflectionClass(ReflectIterableSameName::class))->getProperties();
$iterableType = $iterableProperty->getType();
$nullableIterableType = $nullableIterableProperty->getType();
var_dump($iterableType::class, $iterableType->getName(), (string) $iterableType, $iterableType->isBuiltin());
var_dump($nullableIterableType::class, $nullableIterableType->getName(), (string) $nullableIterableType, $nullableIterableType->isBuiltin());
",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "string(24) \"/** @SomeAnnotation() */\"\n",
            "bool(false)\n",
            "bool(true)\n",
            "bool(false)\n",
            "bool(true)\n",
            "int(0)\n",
            "string(19) \"ReflectionNamedType\"\n",
            "string(8) \"iterable\"\n",
            "string(8) \"iterable\"\n",
            "bool(true)\n",
            "string(19) \"ReflectionNamedType\"\n",
            "string(8) \"iterable\"\n",
            "string(9) \"?iterable\"\n",
            "bool(true)\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_parent_property_hook_fallback_diagnostics_to_native_binary() {
    let root = temp_dir("ptn-native-parent-property-hook-fallback-diagnostics");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("parent-property-hook-fallback-diagnostics.php");
    let output = root.join("parent-property-hook-fallback-diagnostics-bin");
    fs::write(
        &input,
        "<?php
class NoParentHookFallback {
    public $prop {
        get => parent::$prop::get();
    }
}

$noParent = new NoParentHookFallback();
try {
    var_dump($noParent->prop);
} catch (Error $e) {
    echo $e->getMessage(), \"\\n\";
}

class ParentWithoutHookProp {}

class ChildWithMissingParentHookProp extends ParentWithoutHookProp {
    public $prop {
        get {
            return parent::$prop::get();
        }
    }
}

$missing = new ChildWithMissingParentHookProp();
try {
    var_dump($missing->prop);
} catch (Error $e) {
    echo $e->getMessage(), \"\\n\";
}

class PrivateParentHookProp {
    private int $prop;
}

class ChildWithPrivateParentHookProp extends PrivateParentHookProp {
    public int $prop {
        get => parent::$prop::get();
    }
}

$private = new ChildWithPrivateParentHookProp();
try {
    var_dump($private->prop);
} catch (Error $e) {
    echo $e->getMessage(), \"\\n\";
}
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "Cannot use \"parent\" when current class scope has no parent\n",
            "Undefined property ParentWithoutHookProp::$prop\n",
            "Cannot access private property PrivateParentHookProp::$prop\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_declared_class_property_metadata"));
    assert!(c_source.contains("Cannot access %s property %s::$prop"));
}

#[test]
fn compile_braced_property_hook_getters_to_native_binary() {
    let root = temp_dir("ptn-native-braced-property-hook-getters");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("braced-property-hook-getters.php");
    let output = root.join("braced-property-hook-getters-bin");
    fs::write(
        &input,
        "<?php
class BracedHookBag {
    public $answer {
        get { return 42; }
    }

    public $upper {
        get { return strtoupper('ok'); }
    }

    public $backed = 'initial' {
        get { return $this->backed; }
    }

    public int $coerced {
        get { return '42'; }
    }

    public int $bad {
        get { return 'nope'; }
    }
}

$bag = new BracedHookBag();
var_dump($bag->answer);
var_dump($bag->upper);
var_dump($bag->backed);
var_dump($bag->coerced);

try {
    $bag->answer = 100;
} catch (Error $e) {
    echo $e->getMessage(), \"\\n\";
}

try {
    var_dump($bag->bad);
} catch (TypeError $e) {
    echo $e->getMessage(), \"\\n\";
}

$bag->backed = 'updated';
var_dump($bag->backed);
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "int(42)\n",
            "string(2) \"OK\"\n",
            "string(7) \"initial\"\n",
            "int(42)\n",
            "Cannot write to get-only virtual property BracedHookBag::$answer\n",
            "BracedHookBag::$bad::get(): Return value must be of type int, string returned\n",
            "string(7) \"updated\"\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_declared_class_property_hook_get"));
}

#[test]
fn compile_property_hook_get_by_reference_to_native_binary() {
    let root = temp_dir("ptn-native-property-hook-get-by-reference");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("property-hook-get-by-reference.php");
    let output = root.join("property-hook-get-by-reference-bin");
    fs::write(
        &input,
        "<?php
interface HasProp {
    public $prop { &get; }
}

class RefBag implements HasProp {
    private $_prop;
    public $prop {
        &get => $this->_prop;
        set { $this->_prop = $value; }
    }
}

function write_ref(HasProp $bag) {
    $ref = &$bag->prop;
    $ref = 42;
}

$bag = new RefBag();
$bag->prop = 41;
$alias = &$bag->prop;
$alias++;
var_dump($bag->prop);
write_ref($bag);
var_dump($bag);
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "int(42)\n",
            "object(RefBag)#1 (1) {\n",
            "  [\"_prop\":\"RefBag\":private]=>\n",
            "  &int(42)\n",
            "}\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_declared_class_property_hook_get"));
}

