#[test]
fn compile_property_array_dimension_assignments_to_native_binary() {
    let root = temp_dir("ptn-native-property-array-dimension-assignments");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("property-array-dimension-assignments.php");
    let output = root.join("property-array-dimension-assignments-bin");
    fs::write(
        &input,
        "<?php
class Bag {
    private $items = [];

    public function put($key, $value) {
        $this->items[$key] = $value;
    }

    public function add($key, $value) {
        return $this->items[$key] += $value;
    }

    public function append($value) {
        $this->items[] = $value;
    }

    public function drop($key) {
        unset($this->items[$key]);
    }

    public function all() {
        return $this->items;
    }
}

class OffsetBox implements ArrayAccess {
    public $value = 100;

    public function offsetGet($offset) {
        var_dump($offset);
        return $this->value;
    }

    public function offsetSet($offset, $value) {
        var_dump($offset);
        $this->value = $value;
    }

    public function offsetExists($offset) {
        return true;
    }

    public function offsetUnset($offset) {
    }
}

$bag = new Bag();
$bag->put(\"a\", 2);
var_dump($bag->add(\"a\", 3));
$bag->append(9);
var_dump($bag->all());
$bag->drop(\"a\");
var_dump($bag->all());

$box = new OffsetBox();
var_dump($box[] += 5);
var_dump($box->value);
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "int(5)\n",
            "array(2) {\n",
            "  [\"a\"]=>\n",
            "  int(5)\n",
            "  [0]=>\n",
            "  int(9)\n",
            "}\n",
            "array(1) {\n",
            "  [0]=>\n",
            "  int(9)\n",
            "}\n",
            "NULL\n",
            "NULL\n",
            "int(105)\n",
            "int(105)\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_value_array_path_set(&runtime"));
    assert!(c_source.contains("ptn_value_array_path_set_from_assign_op(&runtime"));
    assert!(c_source.contains("ptn_value_array_path_read_for_assign_op(&runtime"));
    assert!(c_source.contains("ptn_value_array_path_unset("));
}

#[test]
fn compile_arrayaccess_by_value_indirect_writes_to_native_binary() {
    let root = temp_dir("ptn-native-arrayaccess-by-value-indirect-writes");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("arrayaccess-by-value-indirect-writes.php");
    let output = root.join("arrayaccess-by-value-indirect-writes-bin");
    fs::write(
        &input,
        "<?php
class Box implements ArrayAccess {
    public $items = [
        0 => ['name' => 'Foo'],
        1 => 1,
    ];

    public function offsetExists($offset): bool {
        return array_key_exists($offset, $this->items);
    }

    public function offsetGet($offset): mixed {
        return $this->items[$offset];
    }

    public function offsetSet($offset, $value): void {
        echo \"offsetSet($offset)\\n\";
        $this->items[$offset] = $value;
    }

    public function offsetUnset($offset): void {
        echo \"offsetUnset($offset)\\n\";
        unset($this->items[$offset]);
    }
}

$box = new Box();
$box[0]['name'] = 'Bar';
$box[0]['name'] .= 'Baz';
var_dump($box[0]['name']);
$box[1]++;
var_dump($box[1]);
$ref = 'ref';
try {
    $box[0]['name'] =& $ref;
} catch (Error $e) {
    echo $e->getMessage(), \"\\n\";
}
var_dump($box[0]['name']);
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    let stdout = String::from_utf8(execution.stdout).unwrap();
    assert_eq!(
        stdout
            .matches("Indirect modification of overloaded element of Box has no effect")
            .count(),
        4,
        "{stdout}"
    );
    assert!(
        stdout.contains("Cannot assign by reference to an array dimension of an object"),
        "{stdout}"
    );
    assert_eq!(stdout.matches("string(3) \"Foo\"").count(), 2, "{stdout}");
    assert!(stdout.contains("int(1)"), "{stdout}");
    assert!(!stdout.contains("offsetSet"), "{stdout}");
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_runtime_array_path_set_from_inc_dec"));
    assert!(c_source.contains("ptn_runtime_bind_array_path_reference"));
    assert!(c_source.contains("ptn_arrayaccess_nested_write_should_apply"));
}

