#[test]
fn compile_dynamic_variable_null_coalescing_assignments_to_native_binary() {
    let root = temp_dir("ptn-native-dynamic-variable-null-coalescing-assignment");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("dynamic-variable-null-coalescing-assignment.php");
    let output = root.join("dynamic-variable-null-coalescing-assignment-bin");
    fs::write(
        &input,
        "<?php\n\
function mark($value) { echo $value, \"\\n\"; return $value; }\n\
function rhs($label) { echo \"rhs:$label\\n\"; return $label; }\n\
$name = \"slot\";\n\
var_dump($$name ??= rhs(\"missing\"));\n\
var_dump($slot);\n\
var_dump($$name ??= rhs(\"hit\"));\n\
$slot = null;\n\
var_dump($$name ??= rhs(\"null\"));\n\
$slot = false;\n\
var_dump($$name ??= rhs(\"false\"));\n\
${mark(\"ordered\")} ??= mark(\"created\");\n\
var_dump($ordered);\n\
$itemsName = \"items\";\n\
$items = [\"hit\" => \"kept\", \"nullish\" => null, \"nested\" => [\"leaf\" => null]];\n\
var_dump(${$itemsName}[\"hit\"] ??= rhs(\"array-hit\"));\n\
var_dump(${$itemsName}[\"nullish\"] ??= rhs(\"array-null\"));\n\
var_dump(${$itemsName}[\"missing\"] ??= rhs(\"array-missing\"));\n\
var_dump(${$itemsName}[\"nested\"][\"leaf\"] ??= rhs(\"nested\"));\n\
$undefName = \"undef\";\n\
var_dump(${$undefName}[\"key\"] ??= rhs(\"undef\"));\n\
$textName = \"text\";\n\
$text = \"abc\";\n\
var_dump(${$textName}[1] ??= rhs(\"string-hit\"));\n\
${mark(\"items\")}[mark(\"ordered\")] ??= mark(\"ordered-value\");\n\
var_dump($items[\"ordered\"]);\n\
var_dump($items[\"hit\"], $items[\"nullish\"], $items[\"missing\"], $items[\"nested\"][\"leaf\"], $undef[\"key\"], $text);\n",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        "rhs:missing\n\
string(7) \"missing\"\n\
string(7) \"missing\"\n\
string(7) \"missing\"\n\
rhs:null\n\
string(4) \"null\"\n\
bool(false)\n\
ordered\n\
created\n\
string(7) \"created\"\n\
string(4) \"kept\"\n\
rhs:array-null\n\
string(10) \"array-null\"\n\
rhs:array-missing\n\
string(13) \"array-missing\"\n\
rhs:nested\n\
string(6) \"nested\"\n\
rhs:undef\n\
string(5) \"undef\"\n\
string(1) \"b\"\n\
items\n\
ordered\n\
ordered-value\n\
string(13) \"ordered-value\"\n\
string(4) \"kept\"\n\
string(10) \"array-null\"\n\
string(13) \"array-missing\"\n\
string(6) \"nested\"\n\
string(5) \"undef\"\n\
string(3) \"abc\"\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_runtime_read_variable_quiet(&runtime, ptn_tmp_"));
    assert!(c_source.contains("ptn_runtime_array_path_lookup_quiet(&runtime, ptn_tmp_"));
    assert!(c_source.contains("ptn_runtime_array_path_set(&runtime, ptn_tmp_"));
}

#[test]
fn compile_dynamic_symbol_reference_fallbacks_to_native_binary() {
    let root = temp_dir("ptn-native-dynamic-symbol-references");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("dynamic-symbol-references.php");
    let output = root.join("dynamic-symbol-references-bin");
    fs::write(
        &input,
        "<?php\n\
$name = \"target\";\n\
$source = \"seed\";\n\
$$name =& $source;\n\
$target = \"changed\";\n\
echo $source, \"\\n\";\n\
$source = \"again\";\n\
echo $target, \"\\n\";\n\
\n\
$items = [1, 2];\n\
$slot = \"current\";\n\
foreach ($items as &$$slot) {\n\
    $$slot *= 10;\n\
}\n\
unset($current);\n\
var_dump($items);\n\
\n\
$GLOBALS[\"shared\"] = \"before\";\n\
function bind_dynamic_global() {\n\
    $name = \"shared\";\n\
    global $$name;\n\
    $shared = \"after\";\n\
}\n\
bind_dynamic_global();\n\
echo $GLOBALS[\"shared\"], \"\\n\";\n\
\n\
$ref = \"linked\";\n\
$GLOBALS[\"via_ref\"] =& $ref;\n\
$GLOBALS[\"via_ref\"] = \"mutated\";\n\
echo $ref, \"\\n\";\n\
\n\
$rootName = \"GLOBALS\";\n\
$ref2 = \"dyn\";\n\
${$rootName}[\"dyn_ref\"] =& $ref2;\n\
$GLOBALS[\"dyn_ref\"] = \"dyn-mutated\";\n\
echo $ref2, \"\\n\";\n\
\n\
$arrayName = \"box\";\n\
$box = [\"x\" => \"old\"];\n\
$ref3 = \"new\";\n\
${$arrayName}[\"x\"] =& $ref3;\n\
$box[\"x\"] = \"written\";\n\
echo $ref3, \"\\n\";\n",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "changed\n",
            "again\n",
            "array(2) {\n",
            "  [0]=>\n",
            "  int(10)\n",
            "  [1]=>\n",
            "  int(20)\n",
            "}\n",
            "after\n",
            "mutated\n",
            "dyn-mutated\n",
            "written\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_runtime_bind_global_variable(&runtime, ptn_tmp_"));
    assert!(c_source.contains("ptn_runtime_bind_array_path_reference(&runtime, ptn_tmp_"));
}

