#[test]
fn compile_clone_with_property_updates_to_native_binary() {
    let root = temp_dir("ptn-native-clone-with-property-updates");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("clone-with-property-updates.php");
    let output = root.join("clone-with-property-updates-bin");
    fs::write(
        &input,
        "<?php
class CloneWithBox {
    public string $hooked = 'default' {
        set {
            $this->hooked = strtoupper($value);
        }
    }
    public string $plain = 'plain';

    public function __clone() {
        echo \"__clone\\n\";
        $this->plain = 'from clone';
    }
}

$box = new CloneWithBox();
$copy = clone($box, ['hooked' => 'updated']);
echo $copy->hooked, \"\\n\";
echo $copy->plain, \"\\n\";

try {
    clone($box, 1);
} catch (TypeError $e) {
    echo \"TypeError: \", $e->getMessage(), \"\\n\";
}

$ref = 'reference';
$with = ['x' => &$ref];
try {
    clone(new stdClass(), $with);
} catch (Error $e) {
    echo \"Error: \", $e->getMessage(), \"\\n\";
}
unset($ref);
$copy = clone(new stdClass(), $with);
echo $copy->x, \"\\n\";
",
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "__clone\n",
            "UPDATED\n",
            "from clone\n",
            "TypeError: clone(): Argument #2 ($withProperties) must be of type array, int given\n",
            "Error: Cannot assign by reference when cloning with updated properties\n",
            "reference\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_clone_value_with_properties(&runtime"));
}

#[test]
fn compile_clone_preserves_live_property_references_to_native_binary() {
    let root = temp_dir("ptn-native-clone-live-property-references");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("clone-live-property-references.php");
    let output = root.join("clone-live-property-references-bin");
    fs::write(
        &input,
        r#"<?php
class Plain {
    public $p;
}

$first = new Plain();
$first->p = "init";
$ref =& $first->p;
$clone = clone $first;
$clone->p = "foo";
var_dump($first->p);

$second = new Plain();
$second->p = "init";
$ref2 =& $second->p;
unset($ref2);
$clone2 = clone $second;
$clone2->p = "bar";
var_dump($second->p);

class Typed {
    public int $x = 42;
}

$typed = new Typed();
$x =& $typed->x;
$typed2 = clone $typed;
unset($typed);
try {
    $x = "foo";
} catch (TypeError $e) {
    echo $e->getMessage(), "\n";
}
var_dump($typed2->x);
"#,
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();
    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstdout:\n{}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stdout),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "string(3) \"foo\"\n",
            "string(4) \"init\"\n",
            "Cannot assign string to reference held by property Typed::$x of type int\n",
            "int(42)\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

