#[test]
fn compile_catch_binding_typed_reference_error_to_native_binary() {
    let root = temp_dir("ptn-native-catch-binding-typed-reference");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("catch-binding-typed-reference.php");
    let output = root.join("catch-binding-typed-reference-bin");
    fs::write(
        &input,
        r#"<?php
class Test {
    public int $i = 42;
}

$test = new Test();
$ref =& $test->i;

try {
    try {
        throw new Exception("ex");
    } catch (Exception $ref) {
        echo "unreachable\n";
    } catch (TypeError $e) {
        echo "same catch\n";
    } finally {
        echo "inner finally\n";
    }
} catch (TypeError $e) {
    echo $test->i, "\n";
    echo $e->getMessage(), "\n";
    echo $e->getPrevious() === null ? "no previous\n" : "has previous\n";
}
"#,
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();
    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstdout:\n{}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stdout),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "inner finally\n",
            "42\n",
            "Cannot assign Exception to reference held by property Test::$i of type int\n",
            "no previous\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_readonly_object_incdec_preserves_previous_exception_identity_to_native_binary() {
    let root = temp_dir("ptn-native-readonly-object-incdec-previous");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("readonly-object-incdec-previous.php");
    let output = root.join("readonly-object-incdec-previous-bin");
    fs::write(
        &input,
        r#"<?php
class Test {
    public readonly object $prop;

    public function __construct(object $prop) {
        $this->prop = $prop;
    }
}

$test = new Test(new stdClass);
$test->prop->foo = 1;
$test->prop->foo += 1;
$test->prop->foo++;
try {
    $test->prop += 1;
} catch (Error $e) {
    echo $e->getMessage(), "\n";
}
try {
    $test->prop++;
} catch (Error $e) {
    echo $e->getMessage(), "\n";
}
try {
    --$test->prop;
} catch (Error $e) {
    echo $e->getMessage(), "\n";
}
var_dump($test->prop);

$ref =& $test->prop;
$ref = new stdClass;
var_dump($test->prop);

$test = new Test(new ArrayObject());
$test->prop[] = [];
$test->prop[0][] = 1;
var_dump($test->prop);
"#,
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();
    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstdout:\n{}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stdout),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "Unsupported operand types: stdClass + int\n",
            "Cannot modify readonly property Test::$prop\n",
            "Cannot modify readonly property Test::$prop\n",
            "object(stdClass)#2 (1) {\n",
            "  [\"foo\"]=>\n",
            "  int(3)\n",
            "}\n",
            "object(stdClass)#2 (1) {\n",
            "  [\"foo\"]=>\n",
            "  int(3)\n",
            "}\n",
            "object(ArrayObject)#7 (1) {\n",
            "  [\"storage\":\"ArrayObject\":private]=>\n",
            "  array(1) {\n",
            "    [0]=>\n",
            "    array(1) {\n",
            "      [0]=>\n",
            "      int(1)\n",
            "    }\n",
            "  }\n",
            "}\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_readonly_indirect_reference_and_unset_precedence_to_native_binary() {
    let root = temp_dir("ptn-native-readonly-indirect-reference-unset");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("readonly-indirect-reference-unset.php");
    let output = root.join("readonly-indirect-reference-unset-bin");
    fs::write(
        &input,
        "<?php
class Box {
    public readonly int $value;

    public function init() {
        $this->value = 1;
    }

    public function appendInside() {
        $this->value[] = 1;
    }

    public function bindInside(int &$value) {
        $this->value = &$value;
    }

    public function unsetInside() {
        unset($this->value);
    }
}

function show(callable $callback) {
    try {
        $callback();
    } catch (Error $e) {
        echo $e->getMessage(), \"\\n\";
    }
}

$box = new Box();
show(fn() => $box->appendInside());
$box->init();
show(fn() => $box->appendInside());
show(fn() => $box->value[] = 2);
show(function () use ($box) { unset($box->value); });

$other = new Box();
$i = 42;
show(fn() => $other->bindInside($i));
show(function () use ($other) { unset($other->value); });
",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();
    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "Cannot indirectly modify readonly property Box::$value\n",
            "Cannot indirectly modify readonly property Box::$value\n",
            "Cannot indirectly modify readonly property Box::$value\n",
            "Cannot unset readonly property Box::$value\n",
            "Cannot indirectly modify readonly property Box::$value\n",
            "Cannot unset protected(set) readonly property Box::$value from global scope\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

