#[test]
fn compile_stream_get_meta_data_to_native_binary() {
    let root = temp_dir("ptn-native-stream-get-meta-data");
    fs::create_dir_all(&root).unwrap();
    let data = root.join("payload.txt");
    fs::write(&data, "payload").unwrap();
    let input = root.join("stream-get-meta-data.php");
    let output = root.join("stream-get-meta-data-bin");
    let data_path = data.to_string_lossy();
    fs::write(
        &input,
        format!(
            "<?php\n\
$fp = fopen(\"{}\", \"r\");\n\
$meta = stream_get_meta_data($fp);\n\
var_dump(function_exists(\"stream_get_meta_data\"));\n\
var_dump($meta[\"timed_out\"], $meta[\"blocked\"], $meta[\"eof\"]);\n\
var_dump($meta[\"wrapper_type\"], $meta[\"stream_type\"], $meta[\"mode\"]);\n\
var_dump($meta[\"unread_bytes\"], $meta[\"seekable\"], str_contains($meta[\"uri\"], \"payload.txt\"));\n\
fread($fp, 2);\n\
$afterRead = stream_get_meta_data($fp);\n\
var_dump($afterRead[\"unread_bytes\"] > 0);\n\
var_dump(fclose($fp));\n\
$fileUri = \"File://{}\";\n\
$caseFp = fopen($fileUri, \"r\");\n\
$caseMeta = stream_get_meta_data($caseFp);\n\
var_dump($caseFp !== false, $caseMeta[\"uri\"] === $fileUri);\n\
fclose($caseFp);\n\
try {{\n\
    stream_get_meta_data($fp);\n\
}} catch (TypeError $e) {{\n\
    echo $e->getMessage(), \"\\n\";\n\
}}",
            data_path, data_path
        ),
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        "bool(true)\n\
bool(false)\n\
bool(true)\n\
bool(false)\n\
string(9) \"plainfile\"\n\
string(5) \"STDIO\"\n\
string(1) \"r\"\n\
int(0)\n\
bool(true)\n\
bool(true)\n\
bool(true)\n\
bool(true)\n\
bool(true)\n\
bool(true)\n\
stream_get_meta_data(): Argument #1 ($stream) must be an open stream resource\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_source_snapshot_file_reads_survive_deleted_source_to_native_binary() {
    let root = temp_dir("ptn-native-source-snapshot-file-reads");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("source-snapshot-file-reads.php");
    let output = root.join("source-snapshot-file-reads-bin");
    fs::write(
        &input,
        "<?php
$path = __FILE__;
var_dump(file_exists($path));
var_dump(is_file($path));
var_dump(is_readable($path));
$contents = file_get_contents($path);
echo substr($contents, 0, 5), \"\\n\";
echo filesize($path) === strlen($contents) ? \"size-ok\\n\" : \"size-bad\\n\";
$handle = fopen($path, \"r\");
echo fread($handle, 5), \"\\n\";
$stat = fstat($handle);
echo $stat[\"size\"] === strlen($contents) ? \"fstat-ok\\n\" : \"fstat-bad\\n\";
",
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();
    fs::remove_file(&input).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "<?php\n",
            "size-ok\n",
            "<?php\n",
            "fstat-ok\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_scandir_sort_constants_and_file_flag_validation_to_native_binary() {
    let root = temp_dir("ptn-native-scandir-and-file-flags");
    let directory = root.join("scan");
    fs::create_dir_all(&directory).unwrap();
    fs::write(directory.join("a.txt"), "").unwrap();
    fs::write(directory.join("b.txt"), "").unwrap();
    let lines = root.join("lines.txt");
    fs::write(&lines, "Line 1\nLine 2").unwrap();
    let input = root.join("scandir-and-file-flags.php");
    let output = root.join("scandir-and-file-flags-bin");
    let directory_path = directory.to_string_lossy();
    let lines_path = lines.to_string_lossy();
    fs::write(
        &input,
        format!(
            "<?php\n\
echo SCANDIR_SORT_ASCENDING, ':', SCANDIR_SORT_DESCENDING, ':', SCANDIR_SORT_NONE, \"\\n\";\n\
echo implode('|', scandir(\"{}\", SCANDIR_SORT_DESCENDING)), \"\\n\";\n\
try {{\n\
    scandir('');\n\
}} catch (ValueError $e) {{\n\
    echo $e->getMessage(), \"\\n\";\n\
}}\n\
foreach ([0, 2, 8, 16, 18, 24] as $flags) {{\n\
    try {{\n\
        $rows = file(\"{}\", $flags);\n\
        echo $flags, ':', strlen($rows[0]), ':', strlen($rows[1]), \"\\n\";\n\
    }} catch (ValueError $e) {{\n\
        echo $flags, ':', $e->getMessage(), \"\\n\";\n\
    }}\n\
}}\n",
            directory_path, lines_path
        ),
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(execution.status.success());
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        "0:1:2\n\
b.txt|a.txt|..|.\n\
scandir(): Argument #1 ($directory) must not be empty\n\
0:7:6\n\
2:6:6\n\
8:file(): Argument #2 ($flags) must be a valid flag value\n\
16:7:6\n\
18:6:6\n\
24:file(): Argument #2 ($flags) must be a valid flag value\n"
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

