#[test]
fn parser_reports_namespace_qualified_declarations_colliding_with_imports() {
    let cases = [
        (
            "<?php namespace Foo { class Bar {} } namespace Bazzle { use Foo\\Bar; class Bar {} }",
            "Cannot redeclare class Bazzle\\Bar (previously declared as local import)",
        ),
        (
            "<?php namespace Foo { function bar() {} } namespace Bazzle { use function Foo\\bar; function bar() {} }",
            "Cannot redeclare function Bazzle\\bar() (previously declared as local import)",
        ),
        (
            "<?php namespace Foo { const BAR = 42; } namespace Bazzle { use const Foo\\BAR; const BAR = 24; }",
            "Cannot declare const Bazzle\\BAR because the name is already in use",
        ),
    ];
    for (source, expected) in cases {
        let error = parser::parse(source).unwrap_err();
        assert_eq!(error.message, expected);
    }
}

#[test]
fn parser_keeps_namespace_import_symbols_block_local() {
    parser::parse("<?php namespace { class C {} } namespace { use Ns\\C; }").unwrap();
    parser::parse("<?php namespace { function f() {} } namespace { use function Ns\\f; }").unwrap();
    parser::parse("<?php namespace { const C = 1; } namespace { use const Ns\\C; }").unwrap();
    parser::parse("<?php use const foo\\bar; use const foo\\BAR;").unwrap();

    let program =
        parser::parse("<?php namespace { function f() {} } namespace { use function f; }").unwrap();
    assert_eq!(program.compile_warnings.len(), 1);
    assert_eq!(
        program.compile_warnings[0].message,
        "The use statement with non-compound name 'f' has no effect"
    );

    let error = parser::parse("<?php namespace { class C {} use Ns\\C; }").unwrap_err();
    assert_eq!(
        error.message,
        "Cannot use Ns\\C as C because the name is already in use"
    );
}

#[test]
fn parser_rejects_namespace_after_function_declaration() {
    let error = parser::parse("<?php function foo() {} namespace Bar;").unwrap_err();
    assert_eq!(
        error.message,
        "Namespace declaration statement has to be the very first statement or after any declare call in the script"
    );
}

#[test]
fn parser_rejects_mixed_namespace_declaration_styles() {
    let error = parser::parse("<?php namespace A; namespace B {}").unwrap_err();
    assert_eq!(
        error.message,
        "Cannot mix bracketed namespace declarations with unbracketed namespace declarations"
    );

    let error = parser::parse("<?php namespace A { namespace B; }").unwrap_err();
    assert_eq!(
        error.message,
        "Cannot mix bracketed namespace declarations with unbracketed namespace declarations"
    );
}

#[test]
fn parser_rejects_code_outside_bracketed_namespace_blocks() {
    let error = parser::parse("<?php namespace A {} echo \"outside\";").unwrap_err();
    assert_eq!(error.message, "No code may exist outside of namespace {}");
}

