#[test]
fn compile_random_randomizer_default_engine_serialize_to_native_binary() {
    let root = temp_dir("ptn-native-random-randomizer-default-engine-serialize");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("random-randomizer-default-engine-serialize.php");
    let output = root.join("random-randomizer-default-engine-serialize-bin");
    fs::write(
        &input,
        r#"<?php
use Random\Randomizer;

$default = new Randomizer();
$explicit = new Randomizer(null);
$payload = $explicit->__serialize();

var_dump($default->__serialize()[0]['engine'] instanceof Random\Engine\Secure);
var_dump($payload[0]['engine'] instanceof Random\Engine\Secure);
var_dump($payload[0]['engine'] instanceof Random\Engine);
var_dump(get_class($payload[0]['engine']));
var_dump(method_exists($explicit, '__serialize'));
var_dump(strlen($explicit->getBytes(4)));

try {
    $explicit->__serialize(1);
} catch (ArgumentCountError $e) {
    echo $e->getMessage(), "\n";
}
"#,
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "string(20) \"Random\\Engine\\Secure\"\n",
            "bool(true)\n",
            "int(4)\n",
            "Random\\Randomizer::__serialize() expects exactly 0 arguments, 1 given\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_random_randomizer_serialize"));
    assert!(c_source.contains("ptn_random_secure_engine_new"));
}

#[test]
fn compile_random_randomizer_array_methods_and_mt19937_to_native_binary() {
    let root = temp_dir("ptn-native-random-randomizer-array-methods");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("random-randomizer-array-methods.php");
    let output = root.join("random-randomizer-array-methods-bin");
    fs::write(
        &input,
        r#"<?php
use Random\Engine\Mt19937;
use Random\Engine\Secure;
use Random\Randomizer;

error_reporting(E_ALL & ~E_DEPRECATED);

$items = ['foo', 'bar', 'baz'];
mt_srand(1, MT_RAND_PHP);
var_dump(array_rand($items), array_rand($items), array_rand($items));

$map = ['foo' => 0, 'bar' => 1, 'baz' => 2];
mt_srand(1234);
$one = array_rand($map, 1);
$two = array_rand($map, 2);

$randomizer = new Randomizer(new Mt19937(1234));
[$methodOne] = $randomizer->pickArrayKeys($map, 1);
$methodTwo = $randomizer->pickArrayKeys($map, 2);
var_dump($one === $methodOne, $two === $methodTwo);
var_dump(strlen($randomizer->getBytes(8)));
$sample = $randomizer->getBytesFromString('az', 32);
var_dump(strlen($sample), strspn($sample, 'az') === 32);
$bounded = $randomizer->getInt(-10, 10);
var_dump($bounded >= -10 && $bounded <= 10);
$float = $randomizer->nextFloat();
var_dump($float >= 0 && $float < 1);

$engine = new Secure();
var_dump(
    $engine instanceof Random\Engine,
    class_exists(Random\Engine\PcgOneseq128XslRr64::class),
    method_exists($randomizer, 'pickArrayKeys'),
    method_exists($randomizer, 'shuffleArray'),
    method_exists($randomizer, 'getBytesFromString'),
    method_exists($randomizer, 'getInt'),
    method_exists($randomizer, 'nextFloat')
);

$keys = $randomizer->pickArrayKeys(['x' => 1, 'y' => 2, 'z' => 3], 2);
$keysOk = count($keys) === 2
    && count(array_unique($keys)) === 2
    && array_diff($keys, ['x', 'y', 'z']) === [];

$input = [3 => 'a', 1 => 'b', 2 => 'c'];
$shuffled = $randomizer->shuffleArray($input);
sort($shuffled);
var_dump($keysOk, $shuffled === ['a', 'b', 'c'], array_key_exists(3, $input) && !array_key_exists(0, $input));

try {
    $randomizer->pickArrayKeys('foo', 2);
} catch (TypeError $e) {
    echo $e->getMessage(), "\n";
}
try {
    $randomizer->pickArrayKeys([], 1);
} catch (ValueError $e) {
    echo $e->getMessage(), "\n";
}
try {
    $randomizer->pickArrayKeys([1, 2, 3], 10);
} catch (ValueError $e) {
    echo $e->getMessage(), "\n";
}
"#,
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "int(0)\n",
            "int(1)\n",
            "int(0)\n",
            "bool(true)\n",
            "bool(true)\n",
            "int(8)\n",
            "int(32)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "bool(true)\n",
            "Random\\Randomizer::pickArrayKeys(): Argument #1 ($array) must be of type array, string given\n",
            "Random\\Randomizer::pickArrayKeys(): Argument #1 ($array) must not be empty\n",
            "Random\\Randomizer::pickArrayKeys(): Argument #2 ($num) must be between 1 and the number of elements in argument #1 ($array)\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_random_engine_new"));
    assert!(c_source.contains("ptn_random_engine_call_method"));
    assert!(c_source.contains("ptn_random_randomizer_get_bytes_from_string"));
    assert!(c_source.contains("ptn_random_randomizer_get_int"));
    assert!(c_source.contains("ptn_random_randomizer_next_float"));
    assert!(c_source.contains("ptn_random_randomizer_pick_array_keys"));
    assert!(c_source.contains("ptn_random_randomizer_shuffle_array"));
}

#[test]
fn compile_random_engine_serialization_and_validation_to_native_binary() {
    let root = temp_dir("ptn-native-random-engine-serialization-validation");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("random-engine-serialization-validation.php");
    let output = root.join("random-engine-serialization-validation-bin");
    fs::write(
        &input,
        r#"<?php
use Random\Engine\PcgOneseq128XslRr64;
use Random\Engine\Xoshiro256StarStar;

echo serialize(new PcgOneseq128XslRr64(1234)), "\n";

try {
    unserialize('O:32:"Random\Engine\Xoshiro256StarStar":2:{i:0;a:0:{}i:1;a:4:{i:0;s:16:"0000000000000000";i:1;s:16:"0000000000000000";i:2;s:16:"0000000000000000";i:3;s:16:"0000000000000000";}}');
} catch (Exception $e) {
    echo $e->getMessage(), "\n";
}

try {
    unserialize('O:17:"Random\Randomizer":1:{i:0;a:2:{s:3:"foo";N;s:6:"engine";O:32:"Random\Engine\Xoshiro256StarStar":2:{i:0;a:0:{}i:1;a:4:{i:0;s:16:"7520fbc2d6f8de46";i:1;s:16:"84d2d2b9d7ba0a34";i:2;s:16:"d975f36db6490b32";i:3;s:16:"c19991ee16785b94";}}}}');
} catch (Exception $e) {
    echo $e->getMessage(), "\n";
}
"#,
    )
    .unwrap();

    let compiled = compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(
        String::from_utf8(execution.stdout).unwrap(),
        concat!(
            "O:33:\"Random\\Engine\\PcgOneseq128XslRr64\":2:{i:0;a:0:{}i:1;a:2:{i:0;s:16:\"c6d571c37c41a8d1\";i:1;s:16:\"345e7e82265d6e27\";}}\n",
            "Invalid serialization data for Random\\Engine\\Xoshiro256StarStar object\n",
            "Invalid serialization data for Random\\Randomizer object\n",
        )
    );
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");

    let c_source = fs::read_to_string(compiled.c_source.unwrap()).unwrap();
    assert!(c_source.contains("ptn_random_engine_serialize"));
    assert!(c_source.contains("ptn_random_engine_unserialize"));
    assert!(c_source.contains("ptn_random_randomizer_unserialize"));
}

#[test]
fn compile_intersection_type_variance_to_native_binary() {
    let root = temp_dir("ptn-native-intersection-type-variance");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("intersection-type-variance.php");
    let output = root.join("intersection-type-variance-bin");
    fs::write(
        &input,
        r#"<?php
interface A {}
interface B {}
interface C {}
interface X {}
interface Y {}
interface Z {}

class Test implements A, B, C, X, Y, Z {}

class CovariantParent {
    public function foo(): A { return new Test(); }
}
class CovariantChild extends CovariantParent {
    public function foo(): A&B { return new Test(); }
}
class CovariantGrandChild extends CovariantChild {
    public function foo(): A&B&C { return new Test(); }
}

class CommutativeParent {
    public A&B $prop;
    public function foo(A&B $v): A&B { return $v; }
}
class CommutativeChild extends CommutativeParent {
    public B&A $prop;
    public function foo(B&A $v): B&A { return $v; }
}

class VarianceParent {
    public function method1(X&Y&Z $a): X&Y { return $a; }
    public function method2(X&Y $a): X { return $a; }
}
class VarianceChild extends VarianceParent {
    public function method1(X&Y $a): X&Y&Z { return $a; }
    public function method2(X $a): X&Y { return $a; }
}

class UnionParent {
    public function test(): X|Z { return new Test(); }
}
class UnionChild extends UnionParent {
    public function test(): X&Y { return new Test(); }
}

class ObjectParent {
    public function method(): object {}
    public function method2(): object|int {}
    public function method3(): Y|int {}
}
class ObjectChild extends ObjectParent {
    public function method(): MissingX&Y {}
    public function method2(): MissingX&Y {}
    public function method3(): MissingX&Y {}
}

class IterableVarianceParent {
    public function method1(): mixed {}
    public function method2(): array|object {}
    public function method3(iterable $x) {}
    public function method4(iterable $x) {}
}
class IterableVarianceChild extends IterableVarianceParent {
    public function method1(): iterable {}
    public function method2(): iterable {}
    public function method3(mixed $x) {}
    public function method4(array|object $x) {}
}

class ObjectDnfUnionParent {
    public function method1(): object {}
    public function method2(): object|int {}
    public function method3(): Y|int {}
}
class ObjectDnfUnionChild extends ObjectDnfUnionParent {
    public function method1(): (MissingValidX&Y)|Countable {}
    public function method2(): (MissingValidX&Y)|int {}
    public function method3(): (MissingValidX&Y)|int {}
}

abstract class MyIterator implements Traversable {}
class IterableParent {
    public function method(): iterable {}
    public function method2(): iterable|int {}
    public function method3(): iterable|MissingZ {}
}
class IterableChild extends IterableParent {
    public function method(): MissingX&Traversable {}
    public function method2(): MissingX&MyIterator {}
    public function method3(): MissingX&MissingZ {}
}

echo "===DONE===\n";
"#,
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: true }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(
        execution.status.success(),
        "native exited with {:?}\nstderr:\n{}",
        execution.status.code(),
        String::from_utf8_lossy(&execution.stderr)
    );
    assert_eq!(String::from_utf8(execution.stdout).unwrap(), "===DONE===\n");
    assert_eq!(String::from_utf8(execution.stderr).unwrap(), "");
}

#[test]
fn compile_literal_eval_static_return_incompatibility_to_native_binary() {
    let root = temp_dir("ptn-native-literal-eval-static-return-lsp");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("literal-eval-static-return-lsp.php");
    let output = root.join("literal-eval-static-return-lsp-bin");
    fs::write(
        &input,
        r#"<?php
class A {
    public function duplicate(): static {}
}

class C {
    public static function generate() {
        eval('class B extends A { public function duplicate(): A {} }');
    }
}

C::generate();
echo "unreached\n";
"#,
    )
    .unwrap();

    compile_file(&input, &output, CompileOptions { emit_c: false }).unwrap();

    let execution = Command::new(&output).output().unwrap();
    assert!(!execution.status.success());
    assert_eq!(String::from_utf8(execution.stdout).unwrap(), "");
    let stderr = String::from_utf8(execution.stderr).unwrap();
    assert!(
        stderr.contains("Fatal error: Declaration of B::duplicate(): A must be compatible with A::duplicate(): static"),
        "{stderr}"
    );
    assert!(stderr.contains("eval()'d code on line "), "{stderr}");
}

